    const VIDEN = Component._viden || (Component._viden = [
      { id: 'E157', title: 'Driftsrapport for genbrugsstationer 2025', org: 'Reno Djurs', year: 2026, type: 'Statistik', temaer: ['Genbrugspladser', 'Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/6d3acd8e2cb25d88eb53ca0a57cfa424.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-06/Driftsrapport%20for%20genbrugsstationer%202025.pdf', res: 'Driften af ni genbrugsstationer på Djursland i 2025: mængder pr. fraktion og station, besøgstal, kg pr. besøg og hvor meget der går til genanvendelse, forbrænding og genbrug.', long: 'Driftsrapporten fra Reno Djurs for 2025 dækker de ni genbrugsstationer i Norddjurs og Syddjurs og er lavet efter vilkår i miljøgodkendelserne. Stationerne modtog 49.333 ton mod 54.987 ton i 2024, fordelt på 690.852 besøg med i gennemsnit 71 kg pr. besøg. Haveaffald var størst med 14.364 ton, fulgt af beton og tegl med 6.792 ton. Af affaldet gik 67 % til genanvendelse, 18 % til forbrænding, 8 % til deponering og 4 % til direkte genbrug, som skønnes til ca. 2.000 ton. Med ca. 55.800 betalende husstande og sommerhuse svarer det til ca. 884 kg og 12 besøg pr. enhed, og ifølge en brugerundersøgelse fra 2024 kommer ca. 96 % af affaldet fra private.' },
      { id: 'E165', title: 'Byens genbrug: serviceniveau for nærgenbrugsstationer 2026-2036', org: 'Københavns Kommune', year: 2026, type: 'Strategi', temaer: ['Genbrugspladser', 'Affaldsplaner/regulativer og strategi', 'Direkte genbrug'], img: 'img/64d72455cbbe6ffdf8b62601352f670a.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/c70d2c0b-027c-452e-b1d2-29f35530ae99/53e4521f-cb53-4008-aa4e-062be726a165-bilag-2_0.pdf', res: 'Københavns plan for nærgenbrugsstationer frem til 2036 med et fast serviceniveau, fire typer stationer og principper for kort vej til genbrug og en stærkere genbrugskultur.', long: 'Besøgene på Københavns nærgenbrugsstationer er mere end fordoblet på tre år, og med denne plan fastlægger kommunen et serviceniveau frem til 2036. I dag betjener nogle stationer ca. 30.000 borgere og andre op til 80.000, og ikke alle bydele har en station. Fremover skal stationerne dække hele byen og hver betjene 20.000-40.000 indbyggere. Det ventes at kræve 12 nye stationer, 4-6 frem mod 2030 og 6-8 frem til 2036, i alt 26. Planen beskriver fire typologier, fra bygninger i byrum og stueetager til p-huse og midlertidige løsninger, og fire principper for genbrug, bl.a. kort vej til genbrug, fordi bekvemmelighed vejer tungest for københavnerne.' },
      { id: 'E158', title: 'Årsrapport Genbrugsservice 2025', org: 'Amager Ressourcecenter (ARC)', year: 2026, type: 'Statistik', temaer: ['Genbrugspladser', 'Data, statistikker og nøgletal', 'Direkte genbrug'], img: 'img/d4a4c5442127d36c799f31aa84f50bbf.jpg', url: 'https://a-r-c.dk/app/uploads/2026/06/Aarsrapport-Genbrugsservice-2025.pdf', res: 'ARC\'s rapport for genbrugspladser og nærgenbrugsstationer i 2025 med mængder pr. plads, besøgstal, behandling af affaldet og resultater for direkte genbrug.', long: 'ARC\'s årsrapport for Genbrugsservice gør status over 2025 på selskabets 10 genbrugspladser og nærgenbrugsstationerne i København. Pladserne modtog 92.830 ton affald, 3 % mere end året før, og havde 1.563.113 besøg. At besøgstallet steg 52 %, skyldes især nye kameraer, der også tæller gående og cyklister. 71 % af affaldet blev sendt til genanvendelse, men opgjort efter modtageanlæggenes faktiske behandling var genanvendelsen 46 %, blandt andet fordi betonen kun kan bruges som vejfyld. Direkte genbrug steg 21 % til 3.695 ton, mens affald til deponi faldt 30 %. Rapporten har mængder og besøgstal for hver plads.' },
      { id: 'E168', title: 'Afrapportering af pilotprojektet Genbrugsspotterne', org: 'Københavns Kommune', year: 2026, type: 'Evaluering', temaer: ['Direkte genbrug', 'Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/b2ca4e5378682111c05cb16b65fd6852.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/7b5b42e1-395a-468a-b8db-915ca1745e11/18e02d0f-7b32-4db7-a67a-04e3de7d46fd-bilag-9.pdf', res: 'Erfaringer fra et toårigt forsøg med genbrugsspottere på Københavns fem genbrugsstationer: hvad de samlede ind til genbrug, hvad borgerne syntes, og hvad kommunen anbefaler.', long: 'Københavns Kommune gør status på pilotprojektet Genbrugsspotterne, der i 2025-2026 har 5 fuldtids- og 10 deltidsansatte på de fem genbrugsstationer. Ordningen ligger hos ARC, og spotterne vejleder borgere og erhverv og samler ting ind til direkte genbrug. I 2025 blev der indsamlet 402 ton, og borgernes tilfredshed med at kunne aflevere til genbrug steg fra 2022 til 2025. Forvaltningen finder ordningen relativt dyr, men pengene godt givet ud, og indstiller fast drift fra 2027 med 6,15 mio. kr. om året. Det hæver affaldstaksten med 18,1 kr. årligt pr. gennemsnitlig husstand. Der ventes 590 ton i 2027 og 720 ton i 2030, i alt 2.665 ton i 2027-2030.' },
      { id: 'I273', title: 'Selvbetjente åbningstider på genbrugsstationerne', org: 'Reno Djurs', year: 2026, type: 'Notat', temaer: ['Genbrugspladser', 'Teknologi'], img: 'img/1f9c93695e464d2c6dde7547024f7534.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-09/Bilag%2023_Selvbetjente%20%C3%A5bningstider%20p%C3%A5%20genbrugsstationerne.pdf', res: 'Reno Djurs\' erfaringer med selvbetjente åbningstider, hvor private og erhverv kan aflevere affald kl. 6-21 med nummerpladeaflæsning, og besøgstal fra 2023 og frem.', long: 'I et notat fra september 2026 gør Reno Djurs status over de selvbetjente åbningstider i Grenaa og Feldballe. Her kan private og erhverv aflevere affald alle dage kl. 6-21 uden for den bemandede tid med nummerpladeaflæsning og overvågning. Ordningen startede som forsøg i Feldballe i 2021 og blev siden udvidet til Grenaa. I Grenaa ligger 70 % af besøgene i den bemandede tid, i Feldballe 65 %. Erhverv står for ca. 1 % af besøgene, men bruger i stigende grad de selvbetjente timer. Nye anlæg til adgangskontrol og kameraer koster ca. 1 mio. kr. pr. plads plus ca. 40.000 kr. årligt, og der går ekstra personaletid til oprydning og gennemsyn af video.' },
      { id: 'A043', title: 'Kortlægning og affaldsanalyser for elektronikaffald (WEEE)', org: 'Miljøstyrelsen', year: 2026, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Udvidet producentansvar', 'Sorteringskvalitet'], img: 'img/10b40936d385f09ea0fa9fcb9bf3db8f.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/04/978-87-7564-053-9.pdf', res: 'Hvor ender elektronikaffald i Danmark? Rapporten bygger på interviews på 16 genbrugspladser og analyser af fejlsorteret elektronik og beregner effekten af nye virkemidler.', long: 'COWI og JHN Processor har for Miljøstyrelsen undersøgt, hvorfor Danmark i ti år ikke har nået EU\'s mål for indsamling af elektronikaffald (WEEE). Grundlaget er interviews på 16 genbrugspladser, analyser af fejlsorteret WEEE og ADS-data. Den største, men usikre forklaring er solgt elektronik, der stadig er i brug, anslået til 86.000 ton i 2023. Samme år endte ca. 6.400 ton WEEE i genbrugspladsernes containere til jern og metal. Af seks virkemidler kan bedre data fra skrotpladser øge registreringen mest, med ca. 23.700 ton. Rapporten anbefaler et mål baseret på genereret WEEE, hvor der mangler 37.800 ton mod 64.200 ton med det nuværende mål.' },
      { id: 'M352', title: 'Black bag sorting at Forfar Recycling Centre', org: 'Zero Waste Scotland', year: 2026, type: 'Evaluering', temaer: ['Genbrugspladser', 'Sorteringskvalitet'], img: 'img/0fff26935a15eba40ecac7eeb1091288.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-k5c6ao72-1791887701d', res: 'Skotsk forsøg, hvor borgerne skulle sortere sække med blandet affald på genbrugspladsen. Genanvendelsesprocenten lå 4,8 procentpoint højere end ventet, og restaffaldet blev renere.', long: 'Zero Waste Scotland og Angus Council lod fra november 2025 til marts 2026 borgerne på genbrugspladsen Forfar Recycling Centre selv sortere det genanvendelige fra deres sække med blandet restaffald. Pladsens genanvendelsesprocent blev 58,5 % mod 53,7 % i en kontrolgruppe, altså 4,8 procentpoint mere. I marts 2026 var 20,6 % af restaffaldet på Forfar genanvendeligt mod 40,8 % i snit på tre pladser i 2023. Udbredt til alle Angus\' pladser anslås tiltaget at spare 835 ton CO2e og 164.955 pund om året, før opstartsudgifter og ekstra personale. Rapporten anbefaler sortering på alle kommunens pladser, så affaldet ikke flytter til nabopladserne.' },
      { id: 'C085', title: 'Opgørelse af omkostninger til batteriindsamling', org: 'KL og Brancheforeningen Cirkulær', year: 2026, type: 'Notat', temaer: ['Økonomi', 'Udvidet producentansvar'], img: 'img/0b9043f1e956bda52424e4c57f1bc162.jpg', url: 'https://www.kl.dk/media/asvit340/opgoerelse-af-omkostninger-for-batterier.pdf', res: 'Sådan opgør kommunen sine omkostninger til batteriindsamling, når udgifterne er spredt på flere ordninger. Omkostningen pr. kg skal bruges i kontrakten med de kollektive ordninger.', long: 'Brancheforeningen Cirkulær forklarer, hvordan kommunen kan samle sine udgifter til batteriindsamling og finde en pris pr. kg, så kontrakten med de kollektive ordninger bliver omkostningsægte. Notatet bygger på batteriforordningen og Eunomias retningslinjer og gennemgår ordningerne fra miljøkasse og pose-på-låg til viceværtsordninger og genbrugspladser. I miljøkassen bør batteriernes andel opgøres efter tid eller antal frem for vægt, fordi batterier er tunge, men nemme at sortere. I et datasæt gav andelsmetoden 8 % batterier og vægtmetoden over 30 %. Niras anslog i 2024 omkostningen til 19 kr./kg i miljøkasse og 13 kr./kg i pose-på-låg.' },
      { id: 'E171', title: 'Evaluering af miljøstationer på Nørrebro', org: 'Københavns Kommune', year: 2026, type: 'Evaluering', temaer: ['Hente- og bringeordninger', 'Etageboliger', 'Økonomi'], img: 'img/b8fbdfad007345e7bd29905ca657ea9e.jpg', url: '#', res: 'Evaluering af tre miljøstationer på Nørrebro, der erstattede beholdere i gårdene. Driften koster 75 procent mere end gårdløsningen, og effekten på sorteringen er ikke entydig.', long: 'Københavns Kommune har evalueret et forsøg på Nørrebro, hvor tre miljøstationer med nedgravede beholdere på gaden afløste gårdenes 660-liters beholdere fra oktober 2024 til november 2025. Evalueringen bygger på vejninger, sorteringsanalyser, interviews og et spørgeskema. Driften koster 714.000 kr. om året mod 409.000 kr. før, især pga. dyrere vedligehold. Sorteringen blev hverken klart bedre eller dårligere. To tredjedele af beboerne har fået længere til affaldet, men på Tikøbgade vil 86 % beholde miljøstationen mod 43 % på Sjællandsgade. Forvaltningen indstiller, at ejendommene betaler gebyret for restaffald i private nedgravede beholdere.' },
      { id: 'A039', title: 'Affaldsfremskrivning 2025', org: 'Energistyrelsen', year: 2026, type: 'Analyse', temaer: ['Data, statistikker og nøgletal', 'Analyser og undersøgelser'], img: 'img/d2a4d95e55ff737f39a2c3d4545b33e6.jpg', url: 'https://mst.dk/media/jruicwky/affaldsfremskrivning-2025-ens.pdf', res: 'Energistyrelsens fremskrivning af den forventede udvikling i Danmarks affaldsmængder og behandling. Den bygger på affaldsmodellen i GrønREFORM med data til og med 2023.', long: 'Affaldsfremskrivning 2025 er Energistyrelsens første publicerede fremskrivning fra affaldsmodellen i GrønREFORM, som afløser FRIDA-modellen. Den bygger på Affaldsdatasystemet, Nationalregnskabet og affaldsanalyser med 2023 som seneste dataår og dækker 2024-2050. Mængderne fordeles på husholdnings- og erhvervsaffald, 17 fraktioner og fire behandlingsformer fra genanvendelse til deponering. Modellen skelner mellem indsamlet og reelt genanvendt affald, medregner effekten af vedtagne, men ikke gennemførte tiltag og fremskriver elektronikaffald også inkl. skyggestrømme. Rapporten beskriver metoden, mens tallene ligger i et Excel-bilag.' },
      { id: 'A041', title: 'Nøgletal til betaling for ikke-emballageaffald og erhvervsemballage', org: 'Energistyrelsen', year: 2026, type: 'Statistik', temaer: ['Udvidet producentansvar', 'Data, statistikker og nøgletal', 'Økonomi'], img: 'img/e2e966be181a36cc9e9dc8b80d111381.jpg', url: 'https://mst.dk/media/hc4lmbe0/noegletal-01_10_2026.pdf', res: 'Energistyrelsens nøgletal for kommunernes betaling til de kollektive ordninger for ikke-emballageaffald og for kompensation for erhvervsemballage, gældende fra 1. oktober 2026.', long: 'Energistyrelsens nøgletal bruges af de kollektive ordninger til betalingerne efter emballagebekendtgørelsens bilag 8 og 9. Kommunerne betaler ordningerne for husholdningernes ikke-emballageaffald, og ordningerne kompenserer virksomheder for erhvervsemballage. Versionen gælder fra 1. oktober 2026, og tallene prisreguleres hvert kvartal. For husholdninger er behandlingsnøgletallet 2.450 kr. pr. ton for plast og 1.005 kr. for mad- og drikkekartoner (MDK), mens pap og metal er negative. Transportnøgletallet er 24,53 kr. pr. km og timeprisen for administration 349,61 kr. På erhvervssiden er indsamling af MDK dyrest med 7.974 kr. pr. ton.' },
      { id: 'A042', title: 'Minimering af gasemissioner fra kompostering af haveaffald', org: 'Miljøstyrelsen', year: 2026, type: 'Rapport', temaer: ['Klima', 'Afsætning og behandling', 'Analyser og undersøgelser'], img: 'img/66dbb984f13be0174f6fc28100867f1b.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/07/978-87-7564-123-9.pdf', res: 'Forsøg på tre komposteringsanlæg viser, at milestørrelsen betyder mest for udledningen af metan. Små, passivt beluftede miler med usorteret haveaffald gav de laveste emissioner.', long: 'DTU Sustain og Haugsted Consult har for Miljøstyrelsen målt metan og lattergas fra 10 varianter af fuldskala-kompostering af haveaffald på tre anlæg. Milestørrelsen betød mest, og 4,5 m høje miler udledte markant mere metan end 3 m høje, også pr. ton. Usorteret haveaffald modnede hurtigere og gav samlet mindre metan end sorteret, mens hyppigere vending og biocover ikke havde tydelig effekt. Små, passivt beluftede miler eller aktivt beluftede moduler med usorteret affald kan sænke metanudledningen ca. 68 % i forhold til den nationale emissionsfaktor, fra 2,57 til ca. 0,8 kg pr. ton. Lattergas lå i alle forsøg langt under den nationale faktor.' },
      { id: 'AA553', title: 'Emballageforbrug til madlevering og skolemad', org: 'Miljøstyrelsen', year: 2026, type: 'Analyse', temaer: ['Cirkulær økonomi', 'Analyser og undersøgelser', 'Udvidet producentansvar'], img: 'img/080925b64fc1b212b4ab9bf3c35cc902.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/07/978-87-7564-122-2.pdf', res: 'Emballageforbruget til madlevering og skolemad, opgjort for 2018 og fremskrevet til 2040, og en beregning af, hvornår genbrugsemballage er bedre for miljøet end engangsemballage.', long: 'Norion Consult, Menon Economics og Om Affald har for Miljøstyrelsen opgjort emballagen til madlevering og skolemad og regnet på nationale krav om 10, 20 og 30 % genbrug. Analysen bygger på interviews med ca. 50 aktører og affaldstal fra BEA-modellen. Forbruget var ca. 650 ton i 2018 og kan nå knap 1.500 ton i 2040 med flere ældre og mere skolemad. Genbrugsemballage skal bruges 6-15 gange for at slå engangsemballage på klima, og 10-30 % genbrug kan spare 51-140 ton affald i 2030. Nettonutidsværdien er -11 til -17 mio. kr. for madlevering og -4 til -5 mio. kr. for skolemad, og et generelt krav vurderes ikke samfundsøkonomisk fordelagtigt.' },
      { id: 'C090', title: 'Procedure for tildelingsordning: Emballage', org: 'Dansk Producentansvar', year: 2026, type: 'Vejledning', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser'], img: 'img/73cc75e9f0e5a5294f9a55c4f8e11549.jpg', url: '#', res: 'Reglerne for, hvilken kollektiv ordning der skal afhente eller betale for emballageaffaldet i den enkelte kommune, og forskellen på tildeling med og uden overdragelse af affaldet.', long: 'Dansk Producentansvar beskriver, hvordan emballageaffald i hver kommune fordeles mellem de kollektive ordninger. Ved tildelingstype 1 overdrager kommunen husholdningernes emballageaffald til en ordning. Ved type 2 betaler ordningen kommunens indsamling uden at overtage affaldet, og for træemballage, emballage i restaffald og farligt affald også behandlingen. Type 3 er betaling til virksomheder for erhvervsemballage. Andelene bygger på markedsførte mængder og en tilbagetagningsfaktor, reguleret for over- og underindsamling. Hver fraktion tildeles for hele kommunen ud fra tre års gennemsnitlig indsamling, så flere ordninger kan dele en kommune.' },
      { id: 'B068', title: 'Udkast til emballagebekendtgørelsen med maksimale gebyrer', org: 'Miljøstyrelsen', year: 2026, type: 'Høringsudkast', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/5bcc086c21a34fb9a8c5ad1535e0a8b5.jpg', url: '#', res: 'Udkastet sætter loft pr. ton over kommunernes gebyrer til producenterne for emballage fra henteordninger og kræver 20 % tillæg på gebyrerne fra oktober 2025 til april 2026.', long: 'Udkastet til ny emballagebekendtgørelse skal træde i kraft 1. juli 2026. Kommunernes gebyrer til producenterne for henteordninger med pap, papir, metal, glas, plast og mad- og drikkevarekartoner får et loft pr. ton, der afhænger af kommunegruppen. For plast er loftet 6.632 kr. i bykommuner, 7.725 kr. i oplandskommuner og 9.501 kr. i land- og ø-kommuner, for glas 2.547-2.908 kr. Gebyret beregnes som sidste års indsamlede tonnage gange emballageandelen, fx 51 % for plast, og det maksimale gebyr. Kommunerne skal også opkræve et tillæg på 20 % plus markedsrente af gebyrerne opkrævet fra oktober 2025 til april 2026, fordelt over fire år.' },
      { id: 'H223', title: 'Abonnementsordning for erhverv på genbrugspladserne', org: 'Nordfyns Kommune', year: 2025, type: 'Notat', temaer: ['Erhverv', 'Genbrugspladser', 'Økonomi'], img: 'img/953378baa500ec3ca0fbce8a76474ba4.jpg', url: 'https://dagsordener.nordfynskommune.dk/vis/pdf/bilag/9528fe7e-cd34-40a9-ac95-16316c6d554e', res: 'Nordfyns Kommune vurderer en abonnementsordning for virksomheder på genbrugspladserne efter skiftet til nummerpladescanning, med Kredsløbs ordning i Aarhus som eksempel.', long: 'Nordfyns Kommune har siden 2023 faktureret virksomheder og velgørende organisationer pr. besøg på genbrugspladserne via nummerpladescanning. Et notat fra april 2025 vurderer De Konservatives abonnementsforslag. Kredsløb i Aarhus tager 2.456-58.300 kr. årligt pr. P-nummer, men abonnenterne kommer 38 gange oftere end andre erhvervskunder, og Aarhus revurderer ordningen. En fast årlig pris gør det billigere for de største affaldsproducenter og dyrere for andre, og et ekstra system koster 40.000 kr. og 1.250 kr. månedligt. Loven tillader ikke at særbehandle velgørende organisationer, og administrationen foreslår en forundersøgelse til udgangen af 2026.' },
      { id: 'H252', title: 'Brugerundersøgelse af erhverv på genbrugspladserne i Brande og Ikast', org: 'Ikast-Brande Kommune', year: 2025, type: 'Analyse', temaer: ['Erhverv', 'Genbrugspladser', 'Økonomi'], img: 'img/1403c237972b5deb3d7b0802fa871699.jpg', url: 'https://dagsordener.ikast-brande.dk/vis/pdf/bilag/e84fad84-b590-4d34-b31d-842a96825500', res: 'Registrering af virksomheders besøg på genbrugspladserne i Brande og Ikast: besøg, læs, mængder og fraktioner som grundlag for kommunens gebyrer for erhverv fra 2026.', long: 'JHN Processor registrerede over syv hverdage i marts 2025 besøg og læs på genbrugspladserne i Brande og Ikast, så Ikast-Brande Kommune kan fastsætte gebyrer for erhverv i 2026. Af 1.657 registrerede besøg var 134 virksomheder. En virksomhed kom i gennemsnit med 316 kg affald mod 94 kg for en privat husstand, og håndværkere med abonnement havde 514 kg med. Opskaleret med kommunens tællertal på 178.461 besøg om året afleverer virksomhederne 5.544 ton årligt, heraf 1.674 ton blandet mursten og beton. Ifølge rapporten kan gennemsnitslæssene bruges til at prissætte transport og afsætning, mens fx personaleløn kan fordeles efter antal besøg.' },
      { id: 'I268', title: 'Tilfredshedsundersøgelse på genbrugsstationerne 2024', org: 'Reno Djurs', year: 2025, type: 'Analyse', temaer: ['Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/d7d8b1923833b74d1cf5d252294efdcf.jpg', url: 'https://renodjurs.dk/sites/default/files/2025-03/Bilag%206.3_Tilfredshedsunders%C3%B8gelse%20genbrugsstationer.pdf', res: 'Spørgeundersøgelse blandt 1.523 kunder på otte genbrugsstationer om tilfredshed med stationerne, personalets vejledning og åbningstiderne, med resultater for hver station.', long: 'JHN Processor har for Reno Djurs målt kundetilfredsheden på otte genbrugsstationer. Interviewere delte spørgeskemaer ud på stationerne mellem 23. november og 3. december 2024, og 1.523 kunder svarede, heraf 64 virksomheder. 98 % er alt i alt tilfredse eller meget tilfredse, og lige så mange er tilfredse med personalet. Åbningstiden og ordenen i Gi\' det videre-området får de laveste scorer med 88 % hver. For åbningstiden går spændet fra 68 % i Ryomgård til 98 % i Feldballe, der også har åbent uden bemanding. I de 548 kunders kommentarer går ønskerne især på længere eller ubemandede åbningstider og nedsænkede containere til tunge fraktioner.' },
      { id: 'A037', title: 'Vejledende udtalelse om belægninger og overdækning ved oplag af elektronikaffald', org: 'Miljøstyrelsen', year: 2025, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Genbrugspladser'], img: 'img/1338bc86c91d80efe70671ca6dd0c472.jpg', url: 'https://mst.dk/media/1orn2qpi/vejledende-udtalelse-om-belaegninger-og-overdaekning-af-elektronikaffald.pdf', res: 'Miljøstyrelsen vurderer, at udækket elektronikaffald udvasker problematiske stoffer. Kommunerne bør bruge den viden, når de vurderer krav om tæt belægning og overdækning.', long: 'Miljøstyrelsens vejledende udtalelse fra november 2025 giver kommunerne viden om udvaskning fra udækket elektronikaffald. Elektronikaffaldsbekendtgørelsens § 40 kræver tæt belægning og overdækning af relevante arealer, men definerer dem ikke, så kommunen har et skøn. Grundlaget er en rapport fra 2023 med udvaskningstest af udstyr til temperaturudveksling, skærme og småt udstyr. Udvaskning af bl.a. bly, cadmium, kobber og PFAS kan være problematisk ved udledning til vandmiljø eller kloak. Stort udstyr og solceller blev ikke testet, men kan også udvaske stoffer. Kommunerne bør bruge den viden, når de i tilsynet vurderer, hvilke arealer der er relevante.' },
      { id: 'M346', title: 'Household Waste Recycling Centre (HWRC) Guide', org: 'WRAP', year: 2025, type: 'Vejledning', temaer: ['Genbrugspladser', 'Direkte genbrug', 'Kommunikation'], img: 'img/6af2186942bc940a1f079652319302ed.jpg', url: 'https://www.wrap.ngo/sites/default/files/2026-06/WRAP-HWRC-REPORT-v2.pdf', res: 'WRAP\'s samlede vejledning om genbrugspladser: indretning, booking, direkte genbrug, skiltning, måling af resultater og modtagelse af affald fra små virksomheder.', long: 'WRAP samler i en vejledning fra marts 2025 britisk god praksis for genbrugspladser, lavet med input fra kommuner og branchen. Den dækker lovgivning, måling af resultater, driftsmodeller, direkte genbrug, booking, affald fra små virksomheder, skiltning og indretning. I England faldt mængden på pladserne med 23 % fra 5,1 mio. ton i 2016/17 til 3,9 mio. ton i 2022/23. Flere medarbejdere, flere fraktioner, organiseret genbrug og tydelig skiltning følger med højere genanvendelse. Da Vale of Glamorgan i 2019 begyndte at afvise usorterede sække, faldt restaffaldet med ca. 60 % på fem måneder, og på én plads steg genanvendelsen fra 69 % til 84 %.' },
      { id: 'NIR', title: 'Omkostninger ved indsamling af bærbare batterier', org: 'KL, udarbejdet af NIRAS', year: 2024, type: 'Analyse', temaer: ['Økonomi', 'Udvidet producentansvar', 'Hente- og bringeordninger'], img: '', url: 'https://www.kl.dk/media/bltjw21y/rapport-omkostninger-ved-indsamling-af-baerbare-batterier-okt-2024.pdf', res: 'NIRAS beregner for KL, hvad kommunerne bruger på at indsamle bærbare batterier, i kr. pr. kg for hver ordning. Baggrunden er EU\'s batteriforordning og det nye producentansvar.', long: 'NIRAS har for KL beregnet, hvad det koster kommunerne at indsamle bærbare batterier fra husstande, nu hvor EU\'s batteriforordning kræver, at kommunal indsamling aftales med producenterne. Analysen bygger på interviews og spørgeskemaer med brugbare omkostningsdata fra 58 kommuner samt data fra DPA og ADS. Miljøkassen koster 19 kr./kg, pose-på-låg og andre ordninger 11-13 kr./kg og genbrugspladsen ca. 1 kr./kg. Med et gennemsnit på 11 kr./kg anslås udgifterne til 26-27 mio. kr. om året i 2021-2022, hvoraf producenternes betaling via DUT kun dækkede 67-69 %. Skal kommunerne alene nå EU-målene for 2027 og 2030, koster det 34-39 mio. kr. om året.' },
      { id: 'N01', title: 'Beregning af skitseløsninger for afhentning af 10 affaldstyper ved husstande og sommerhuse', org: 'Reno Djurs', year: 2020, type: 'Analyse', temaer: ['Hente- og bringeordninger', 'Økonomi', 'Reel genanvendelse'], img: 'img/be314121fe632f23a64d9855b813b8f0.jpg', url: 'https://renodjurs.dk/sites/default/files/Bilag%2017.2_Beregning%20af%20skitsel%C3%B8sninger%20ved%20afhentning%20af%2010%20fraktioner.pdf', res: 'Econet regner på tre scenarier for ti affaldstyper hos Reno Djurs. Alle løfter den reelle genanvendelse fra ca. 33 til 49 %, og en gennemsnitsbolig betaler 3.057-3.129 kr. om året.', long: 'Econet lavede beregningerne for Reno Djurs i september 2020 efter klimaplanens krav om ti affaldstyper. Scenarie 1 har tre beholdere ved enfamiliehuse og sommerhuse, scenarie 2 fire og scenarie 3 to, fordi fire fraktioner lægges i farvede poser til optisk sortering. Modellen bruger Reno Djurs\' data for 2019-2020 og regner med, at alt materiel købes nyt. Scenarie 1 er billigst for en gennemsnitsbolig med et gebyr på 3.057 kr. om året inkl. moms, mens scenarie 3 kræver den mindste investering på 58 mio. kr. mod 93-100 mio. kr. Alle giver ca. 8.600 ton mere til genanvendelse og sparer ca. 2.100 ton CO2-ækv. om året, men klimatallene er usikre.' },
      { id: 'N02', title: 'Baggrundsnotat vedr. indsamling af miljøkasser og tekstiler', org: 'Fors A/S og Holbæk Kommune', year: 2024, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Tekstil', 'Storskraldsordning'], img: 'img/3a336de4138f9661fb5e491eedd8248c.jpg', url: 'https://dagsordener.holbaek.dk/vis/pdf/bilag/773855bd-4921-4e37-b4bb-b79cc23358cd', res: 'Rambøll vurderer fire måder at indsamle miljøkasser og tekstiler på i Holbæk Kommune før udbuddet og anbefaler en løsning med og en uden storskraldsordning.', long: 'Notatet er skrevet for Fors i april 2024 som forarbejde til en politisk beslutning før udbuddet af indsamlingen. I dag hentes miljøkasser og tekstiler to gange om året med storskraldet, og i 2023 blev der bestilt ombytning af 417 miljøkasser. Rambøll har spurgt Tønder, Sønderborg, Roskilde og Herning om erfaringer. Bevares storskraldsordningen, anbefales fire runder om året til ca. 1,2 mio. kr. mod knap 600.000 kr. i dag, suppleret med tøjcontainere i store boligselskaber. Nedlægges den, foreslås indsamling på skraldebilerne til ca. 456.000 kr. om året, hvis 30 % af husstandene bruger ordningen. Begge beløb er uden sortering og behandling.' },
      { id: 'N03', title: 'ARC’s evaluering af forsøg i indsats 8.2: Tilpasning af beholdervolumen til mere genanvendelse', org: 'Københavns Kommune og ARC', year: 2024, type: 'Evaluering', temaer: ['Etageboliger', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/7642c6c08d8f4311003a9d2746f34800.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/14d5dc58-bb61-468e-95db-55fcc1305a00/d7099b2a-854b-420a-b308-09fef9140a88-bilag-3.pdf', res: 'ARC testede i 2023 en restaffaldskapacitet på 52 liter pr. lejlighed om ugen i knap 5.000 lejligheder. Den passede i ca. halvdelen af ejendommene, og kommunen foreslår 62 liter.', long: 'Teknik- og Miljøforvaltningens svar fra januar 2024 har ARC’s evaluering fra september 2023 som bilag. Forsøgene kørte fra uge 15 til 37 i etageejendomme på Østerbro og Amager. ARC tog ca. 370.000 liter restaffaldskapacitet om ugen hjem, men satte kun ca. 114.000 liter ud til genanvendeligt affald. Overfyldningerne steg i alle tre forsøg, især i store ejendomme, ofte med genanvendeligt affald i beholderne. På Østerbro fik ca. 55 % af ejendommene ingen overfyldninger, på Amager 38 %. ARC anbefaler 57-62 liter og at få erhvervsandelene på plads før udrulningen. Skilte på beholderne og materiale omdelt af skraldemændene virkede bedst.' },
      { id: 'N04', title: 'Opgørelsesmetoder i Ressource- og Affaldsstrategi 2030', org: 'Københavns Kommune', year: 2025, type: 'Notat', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse', 'Affaldsplaner/regulativer og strategi'], img: 'img/324e07c13ed7e4476849acbd9ce2cca1.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/7b5b42e1-395a-468a-b8db-915ca1745e11/18e02d0f-7b32-4db7-a67a-04e3de7d46fd-bilag-6.pdf', res: 'Københavns Kommune beskriver, hvordan de fire mål i Ressource- og Affaldsstrategi 2030 måles. Metoderne følger EU, og genanvendelse opgøres anderledes end i tidligere planer.', long: 'Teknik- og Miljøforvaltningen gennemgår i november 2025 opgørelsen af målene om 10.000 ton genbrug, 60 % reel genanvendelse af husholdningslignende affald, 30.000 ton erhvervsaffald og 60.000 ton bygge- og anlægsaffald til genanvendelse. Genbrug beregnes ud fra stikprøver og besøgstal på genbrugs- og nærgenbrugsstationerne plus behandlingsaftaler. Reel genanvendelse følger EU\'s definition af municipal waste med data fra Miljøstyrelsen, som kommer to år forsinket og suppleres halvårligt med kommunens egne tal. Erhvervsmålet skønnes ud fra positive tilsyns- og vejledningsbesøg, mens metoden for bygge- og anlægsaffald er under udarbejdelse.' },
      { id: 'N05', title: 'Miljømæssig vurdering af bioplast som en del af den grønne omstilling', org: 'DTU Sustain', year: 2026, type: 'Rapport', temaer: ['Afsætning og behandling', 'Reel genanvendelse', 'Cirkulær økonomi'], img: 'img/92a25815d984d44aa88398592cf613e4.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/446201207/Bioplastrapport_DTUSustain_Marts26.pdf', res: 'DTU Sustain vurderer bioplast i affaldssystemet. BioPE og bioPP kan genanvendes som almindelig plast, mens PLA, PHA, PBAT og PBS typisk ender i rejekt eller til forbrænding.', long: 'Thomas Højlund Christensen og Marie Kampmann Eriksen har skrevet rapporten under DTU Sustains rammeaftale med Miljøstyrelsen, og den bygger på en gennemgang af litteraturen. BioPE og bioPP lavet af ethanol fra restbiomasse er de mest egnede typer, fordi de kan genanvendes sammen med fossil PE og PP. Ethanolruten udnytter højst 25 % af kulstoffet i biomassen mod måske 5-10 % for de øvrige typer. PLA, PHA, PBAT og PBS fylder så lidt på markedet, at sorteringsanlæggene ikke frasorterer dem. Poser af bioplast nedbrydes ikke i en rådnetank med 2-3 ugers opholdstid, men PHA er måske en undtagelse. Vurderingen bør tages op igen inden for ti år.' },
      { id: 'N06', title: 'Baggrundsnotat 1 vedr. brug af el-skraldebiler ved indsamlingen', org: 'Fors A/S og Holbæk Kommune', year: 2024, type: 'Notat', temaer: ['Udbud og kravspecifikationer', 'Teknologi', 'Klima'], img: 'img/dd649975c483eb9d8eb5e15a457e1360.jpg', url: 'https://dagsordener.holbaek.dk/vis/pdf/bilag/6f89575b-88da-4d5a-9a9f-2db915f5b7dd', res: 'Rambøll vurderer for Fors krav om el-skraldebiler i Holbæks næste indsamlingsudbud. El på 50-80 % af tømningerne sparer 330-528 ton CO2 og gør tømningerne 7-24 % dyrere.', long: 'Notatet er skrevet af Rambøll i april 2024 som forarbejde til en politisk beslutning i Holbæk Kommune. Det bygger blandt andet på en spørgeskemaundersøgelse blandt sammenlignelige kommuner og markedsdialog med Verdis og City Container. Indsamlingen med dieselbiler udledte 660 ton CO2 i 2023. En el-skraldebil koster ca. 4,5 mio. kr. mod 1,8 mio. kr. for en dieselbil, og en ladeplads koster ifølge City Container ca. 500.000 kr. plus 250.000 kr. pr. bil. Rambøll anser 100 % el-drift for urealistisk, fordi kommunen har store landområder, og anbefaler et minimumskrav på fx 50 % el med kvalitetspoint for mere og en kontrakt på mindst 8 år.' },
      { id: 'N07', title: 'Vejledning om affaldsløsninger i byggesager. Regler og råd i nybyggeri og renoveringer', org: 'Københavns Kommune', year: 2024, type: 'Vejledning', temaer: ['Etageboliger', 'Haveboliger/parcelhuse', 'Hente- og bringeordninger'], img: 'img/b9cc76696d80a2454b80d49242d1e3cb.jpg', url: 'https://www.kk.dk/sites/default/files/2026-07/Hent%20vejledningen%20om%20affaldsl%C3%B8sninger%20i%20byggesager.pdf', res: 'Københavns Kommunes vejledning til bygherrer om affaldsløsninger i nybyggeri og renoveringer. Den viser beholdertyper og antal og stiller krav til standpladser og adgangsveje.', long: 'Vejledningen, der er opdateret i marts 2024, viser bygherrer, hvordan de indretter affaldsløsninger, der lever op til Københavns regulativ for husholdningsaffald. Den skelner mellem etageejendomme og villaer og giver et skøn over beholderbehovet, fx ti 660 liters beholdere til restaffald ved 100 boliger. Beholderne skal stå i terræn højst 50 meter fra opgangen og mindst 5 meter fra vinduer, og der må højst være 30 meter fra renovationsbilens holdeplads. Den beskriver også nedgravede beholdere og sugeanlæg og anbefaler, at affaldsskakte nedlægges. Nye standpladser skal tilmeldes senest fire uger før ibrugtagning.' },
      { id: 'N08', title: 'Skabelon til kravspecifikation ved udbud af tekstilaffald', org: 'Miljøstyrelsen', year: 2023, type: 'Vejledning', temaer: ['Udbud og kravspecifikationer', 'Tekstil', 'Afsætning og behandling'], img: 'img/ca64785fecfe03b4d4b226c39b596c41.jpg', url: 'https://mst.dk/media/hfdhcfpn/skabelon-til-kravspecifikation-ved-udbud-af-tekstilaffald.pdf', res: 'Miljøstyrelsens skabelon til kommunale udbud af sortering og afsætning af tekstilaffald. Genbrug kommer først, og mindst 50 % af resten skal genanvendes eller materialenyttiggøres.', long: 'Skabelonen kommer fra et pilotprojekt om udbud, som Miljøstyrelsen faciliterede i 2022-2023 i partnerskabet om indsamling og behandling af tekstilaffald. Den dækker tekstilaffald fra husstande og evt. genbrugspladser og stiller krav til hvert led fra modtagekontrol til finsortering. Genbrugeligt tøj skal sorteres i EU/EØS, og mindst 50 % af det, der hverken genbruges eller frasorteres i modtagekontrollen, skal genanvendes eller materialenyttiggøres. Ved evalueringen vægtes mekanisk fiber-til-fiber-genanvendelse tre gange og kemisk to gange så højt som anden materialenyttiggørelse. Leverandøren skal dokumentere hele kæden med massebalancer.' },
      { id: 'N09', title: 'Vejledning om sorteringskriterier for husholdningsaffald', org: 'Miljøstyrelsen', year: 2022, type: 'Vejledning', temaer: ['Sorteringsvejledninger', 'Lovgivning og afgørelser', 'Erhverv'], img: 'img/1da12ad86905e03b49bd066f425b4ff7.jpg', url: 'https://www.retsinformation.dk/api/pdf/232279', res: 'Miljøstyrelsens vejledning med tekniske kriterier og lister over tilladte og forbudte emner for de ti affaldsfraktioner. Grundlag for kommunernes lokale sorteringsvejledninger.', long: 'Vejledningen fra juli 2022 afløser vejledning nr. 9920 fra december 2020 og uddyber fraktionsbeskrivelserne i affaldsbekendtgørelsens bilag 6. Den er skrevet til kommuner, affaldsselskaber, renovatører og virksomheder, som senest 31. december 2022 skal sortere husholdningslignende affald efter samme kriterier. Hver fraktion har en teknisk beskrivelse og positiv- og negativlister. Papir, pap, metal, plast og glas må som hovedregel ikke lægges i lukkede poser, mens tekstilaffald bør ligge i lukket pose. Kommunerne opfordres til at tilbyde taktile piktogrammer til blinde og svagtsynede. Den revideres i takt med det udvidede producentansvar.' },
      { id: 'N10', title: 'Affaldsanalyse af containere med småt brændbart fra nærgenbrugsstationer', org: 'Randers Kommune', year: 2026, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Genbrugspladser', 'Sorteringskvalitet'], img: 'img/3654a5f49679d7eca2e3c78c4ec4ed17.jpg', url: 'https://www.randers.dk/media/40yjdx0k/affaldsanalyse-af-containere-med-smaat-braendbart-fra-naergenbrugsstationer-2025_wt.pdf', res: 'Knap halvdelen af småt brændbart fra Randers Kommunes nærgenbrugsstationer var genanvendeligt, især tekstiler og træ, mens kun 38 % var korrekt sorteret brændbart affald.', long: 'Randers Kommune bad Econet undersøge, hvad der ender i containerne til småt brændbart på nærgenbrugsstationerne i boligområderne. I efteråret 2025 blev ca. 1,5 ton fra 68 af 126 containere på 13 af kommunens 32 stationer sorteret og vejet. Genanvendelige materialer udgjorde 49 %, heraf rent tøj og tekstil 15 % og genanvendeligt træ 13 %. Emballage med udvidet producentansvar stod for 12 %. Omkring 10 % lå i sække med kun én slags affald, hvilket kan tyde på overfyldte beholdere eller forvirring om reglerne. Econet konkluderer, at ordningen delvis bliver brugt til affald, der burde genanvendes.' },
      { id: 'N11', title: 'Kortlægning: Asbest på genbrugspladserne', org: 'Dansk Affaldsforening', year: 2021, type: 'Analyse', temaer: ['Genbrugspladser', 'Byggeaffald', 'Analyser og undersøgelser'], img: 'img/c52d0aef1207e7ed4914b1cdcc7c3245.jpg', url: 'https://cirkulaer.dk/files/media/document/Kortl%C3%A6gning-asbest-genbrugspladser-feb2021.pdf', res: 'Genbrugspladser i 71 kommuner modtog ca. 44.000 ton asbestholdigt affald i 2019. Kortlægningen råder kommuner og affaldsselskaber til at samle informationen til borgerne ét sted.', long: 'Dansk Affaldsforening har gennemgået den information om asbest, som alle 98 kommuner giver borgere og virksomheder, og præsenterer resultatet som et diasoplæg. Mængderne bygger på 2019-data fra 237 genbrugspladser i 71 kommuner, hvor asbest udgjorde 2,68 % af det afleverede affald. Ekstrapoleret skønnes 51-63 % af alt asbestholdigt affald i Danmark at blive afleveret på genbrugspladserne. Brudstykker skal som regel dobbeltemballeres, og mange steder må man højst aflevere 5-20 plader ad gangen. Provas og Silkeborg Forsyning modtager ikke asbest, og AVV holdt op med at modtage det fra 1. januar 2021.' },
      { id: 'N12', title: 'Høringsnotat vedr. udkast til bekendtgørelse om affaldsregulativer, -gebyrer og -aktører m.v.', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2022, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Økonomi'], img: 'img/18839a5690e38a2c762fad2ae1647943.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/434feb13-9bd0-409a-9d08-4cc08f4ec3ef/H%C3%B8ringsnotat%20-%20affaldsakt%C3%B8r-%20og%20affaldsregisterbekendtg%C3%B8relsen-KEFM.pdf', res: 'Høringsnotat om to bekendtgørelser, der udmønter L 898 fra juni 2022. Ministeriet svarer 19 parter, og kravet om markedspriser for erhvervsaffald gælder først fra 2023.', long: 'Notatet fra juni 2022 samler 20 høringssvar til ændringer i affaldsaktørbekendtgørelsen og bekendtgørelsen om Affaldsregistret, som udmønter L 898 af 21. juni 2022. Blandt parterne er KL og kommunerne Aalborg, Herning, København, Køge og Kolding. KL og flere kommuner frygter bl.a., at markedspriser bliver svære at fastsætte, og at dispensationsordningen ikke vil blive brugt. Efter et ændringsforslag til loven gælder kravet om markedspriser først fra 1. januar 2023. Ministeriet peger på, at private allerede håndterer ca. 95 % af erhvervsaffaldet egnet til materialenyttiggørelse. Kommunerne får lov at fastsætte gennemsnitsgebyrer for madaffald.' },
      { id: 'N13', title: 'Kan det betale sig at kildesortere plast fra husholdninger?', org: 'SDU Life Cycle Engineering', year: 2026, type: 'Oplæg', temaer: ['Reel genanvendelse', 'Afsætning og behandling', 'Klima'], img: 'img/4ddfe03e9a771279d84f99a8d1368b61.jpg', url: 'https://plast.dk/wp-content/uploads/2026/05/LOOP-2026-Henrik-Wenzel-29-04-2026.pdf', res: 'Oplæg af Henrik Wenzel, SDU, om kildesortering kontra eftersortering af plast. Kvaliteten er oftest næsten ens, og ifølge SDU er eftersortering billigst pr. sparet ton CO2.', long: 'Slides fra Henrik Wenzels oplæg på LOOP 2026 i København den 29. april 2026. Han gennemgår ti studier fra fem lande, der sammenligner kildesorteret plast med plast eftersorteret fra restaffald på fx polymerrenhed, kemisk forurening, lugt og fysiske egenskaber. Forskellene er oftest små og kan mindskes med bedre vask. Ved kildesortering står indsamling og transport for over 90 % af omkostningen. Ifølge SDU koster et sparet ton CO2 under 1.500 kr. ved eftersortering og omkring 3.000 kr. ved kildesortering, når borgerens tid ikke regnes med. Wenzel foreslår at bruge genvundet plast til produkter med lavere kvalitetskrav.' },
      { id: 'N14', title: 'Analyse af husholdningsaffald indsamlet af Forsyning Helsingør 2023', org: 'Forsyning Helsingør', year: 2024, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Sorteringskvalitet', 'Etageboliger'], img: 'img/65b5196333f0fcf0f04946feef928e27.jpg', url: 'https://www.fh.dk/files/media/document/2024-02-27%20Booklet-rapport%20affaldsanalyser%20-%20Forsyning%20Helsing%C3%B8r%202023.pdf', res: 'Affaldsanalysen fra efteråret 2023 viser, at enfamilieboliger i Helsingør sorterer bedst, mens etageboliger med firehjulede containere har størst potentiale, især for madaffald.', long: 'Forsyning Helsingør fik i september og oktober 2023 analyseret restaffald, plast/MDK, metal, papir/småt pap og glas fra tre boligtyper i 14 stikprøver på hver ca. 200 husstandes ugeaffald. I enfamilieboliger var der 3,7 kg restaffald pr. husstand om ugen, og 49 % var korrekt sorteret. Etageboliger og tæt-lav byggeri med firehjulede containere havde 7,5 kg, hvoraf kun 27 % hørte til i restaffaldet og 34 % var madaffald. I enfamilieboligerne kom 36 % af mad- og drikkekartonerne i den rigtige ordning, og tekstiler udgjorde 6 % af restaffaldet. Renheden af plast/MDK lå på 71-81 % og af glas på 96-98 %.' },
      { id: 'N15', title: 'Hjemtagning af affaldsindsamling', org: 'Brøndby Kommune', year: 2019, type: 'Analyse', temaer: ['Økonomi', 'Udbud og kravspecifikationer', 'Ledelse'], img: 'img/7b2f167d30475d33285daffe089e3060.jpg', url: 'https://dagsordener.brondby.dk/vis/pdf/bilag/e48cd9c0-9ea7-4a23-b70c-7c08fda974a1', res: 'COWI sammenligner udbud og hjemtagning af Brøndby Kommunes affaldsindsamling i fem scenarier. Hjemtagning ser lidt billigere ud, men forskellen ligger inden for usikkerheden.', long: 'Brøndby Kommune bestilte analysen i 2019, da kontrakten med Remondis skulle udløbe i 2021, og kommunen var utilfreds med servicen. Scenarierne dækker nyt udbud, fuld hjemtagning og kombinationer med Vestforbrændings fællesordning for nedgravede beholdere. Udbud koster skønnet 18,0 mio. kr. om året og hjemtagning 16,4 mio. kr., begge plus/minus 15 %, selv om hjemtagningen rummer 1,6 ekstra årsværk til bedre service. Fuld hjemtagning kræver investeringer for knap 26 mio. kr. Fællesordningen koster ca. 200 kr. pr. tømning mod skønnet 160 kr. ved udbud. COWI mener, at valget bør handle om servicekvalitet og fleksibilitet frem for laveste pris.' },
      { id: 'N16', title: 'Recommendations and Good Practices for Local Used Textile Management', org: 'ACR+', year: 2023, type: 'Rapport', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Udvidet producentansvar'], img: 'img/4f8099e6d730b481edb8b0035ca63353.jpg', url: 'https://www.acrplus.org/media/origin/images/technical-reports/2023_ACR_Recommendations_Good_Practices_Used_Textiles.pdf', res: 'ACR+ samler europæisk god praksis for brugte tekstiler. Kommuner bør styrke den lokale styring og vente med at sortere ikke-genbrugelige tekstiler, til der er producentansvar.', long: 'Rapporten bygger på en undersøgelse, som Brussels Environment bestilte forud for kravet om særskilt indsamling af tekstilaffald i 2025. ACR+ gennemgik fra januar til april 2023 europæiske studier og cases. Data er sparsomme, men indsamlingen ser ud til at være højere i Danmark og Holland end i Frankrig. Selv med effektiv automatisk sortering kan kun ca. 25 % af de ikke-genbrugelige tekstiler genanvendes i lukket kredsløb. Alternative indsamlingsformer har løftet indsamlingen, fx til en indsamlingsgrad på 45 % i København. ACR+ anbefaler lokal styring med klare mål og et europæisk producentansvar, før sorteringen udvides til alle tekstiler.' },
      { id: 'N17', title: 'Eftersortering af restaffald. Miljø- og samfundsøkonomisk analyse', org: 'Miljøstyrelsen', year: 2025, type: 'Analyse', temaer: ['Afsætning og behandling', 'Reel genanvendelse', 'Økonomi'], img: 'img/47d501f9b3a7f752eed8da8a94193061.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/02/978-87-7564-081-2.pdf', res: 'Miljøstyrelsens analyse viser, at eftersortering af alt restaffald fra husholdninger kan øge genanvendelsen med ca. 5 procentpoint. Det koster samfundet ca. 681 mio. kr. om året.', long: 'Provice og Nextpuzzle har for Miljøstyrelsen regnet på, hvad det betyder at eftersortere alt restaffald fra danske husholdninger, ca. 740.000 ton om året, på otte nye anlæg. Modellen bygger på erfaringer fra fem anlæg i Norden og Holland, hvor især plast, metal og drikkekartoner bliver sorteret ud. Den reelle genanvendelse stiger med 70.904 ton om året, og klimagevinsten er knap 24.000 ton CO2-ækvivalenter. Samfundet får en nettoomkostning på ca. 681 mio. kr. om året, og kommunerne får en merudgift på 624 kr. pr. ton restaffald i forhold til forbrænding. I Norge og Holland betaler producenterne en stor del af regningen.' },
      { id: 'N18', title: 'Forslag til lov om ændring af lov om miljøbeskyttelse og lov om Forsyningstilsynet', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2022, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Erhverv'], img: 'img/04c637a7f41387be6685f4c68903bf35.jpg', url: 'https://www.folketingstidende.dk/ripdf/samling/20211/lovforslag/l153/20211_l153_som_fremsat.pdf', res: 'Med lovforslag L 153 fra 2022 skal kommunerne udbyde behandlingen af genanvendeligt husholdningsaffald, og virksomheder får frit valg af indsamler til forbrændingsegnet affald.', long: 'Klima-, energi- og forsyningsministeren fremsatte forslaget 30. marts 2022 for at gennemføre dele af klimaplanen for en grøn affaldssektor og cirkulær økonomi fra juni 2020. Kommunerne må som udgangspunkt ikke behandle affald egnet til materialenyttiggørelse og skal udbyde behandlingen senest 1. juli 2023. Eksisterende anlæg kan fortsætte til 30. juni 2027, hvis de er udskilt i selskaber senest 1. januar 2024. Visse kommunale indsamlingsordninger for erhverv skal koste markedspris. Alle genbrugspladser skal have et område til genbrugsgenstande, som ca. 50 af ca. 370 mangler. Forsyningstilsynet får et gebyrfinansieret økonomisk tilsyn.' },
      { id: 'N19', title: 'Høring over udkast til affaldsbekendtgørelse (styrket affaldstilsyn og selektiv nedrivning)', org: 'Miljø- og Ligestillingsministeriet', year: 2024, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Byggeaffald', 'Erhverv'], img: 'img/3c0ff1ecab23b6b57a00ecfdefee6caf.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/40f3099e-2d0c-48e0-9056-189992e87163/H%C3%B8ringsnotat%20aff.bkg.pdf', res: 'Miljø- og Ligestillingsministeriet svarer på 32 høringssvar til ændringer i affaldsbekendtgørelsen om modtagekontrol på forbrændingsanlæg og sortering ved selektiv nedrivning.', long: 'Udkastet var i høring fra 23. september til 31. oktober 2024. Det flytter klassificeringen af affald fra kommunerne til Miljøstyrelsen, og KL og flere kommuner frygter længere sagsbehandling. Forbrændingsanlæg skal kontrollere mindst 5 % af læssene hver uge. Efter høringen sker fysisk afvisning med henblik på eftersortering, og den ansvarlige underrettes senest en hverdag efter. Fra 1. juli 2025 skal virksomheder pakke forbrændingsegnet affald i klare sække. Glasuld og fibergips kommer med i sorteringskravene til byggeaffald, og asbestholdigt affald foreslås tilføjet. Kommunerne skal varsle ændringer i kombineret indsamling senest 1. juni.' },
      { id: 'N20', title: 'Restaffald fra etageboliger og villaer i Ballerup', org: 'Ballerup Kommune', year: 2022, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Etageboliger', 'Haveboliger/parcelhuse'], img: 'img/0466dbf17ef8a44890e4ad7b72deba70.jpg', url: 'https://dagsorden.ballerup.dk/vis/pdf/bilag/e2b6507a-4462-486d-8ba8-757999bd13d7', res: 'Restaffaldet fra etageboliger og villaer i Ballerup bestod i efteråret 2022 af omkring en tredjedel madaffald og 28-31 % genanvendelige materialer, viser Econets sorteringsanalyse.', long: 'Econet har for Ballerup Kommune sorteret en uges restaffald fra 130 etageboliger i Måløv og 200 haveboliger i Måløv, Ballerup og Skovlunde, indsamlet i oktober-november 2022. Etageboligerne havde 6,4 kg restaffald pr. husstand om ugen og haveboligerne 4,3 kg, med 34 og 29 % madaffald. Haveboligernes restaffald rummede 9 % pap og karton, som Econet forklarer med store beholdere til mad og rest, der tømmes hver uge. Faldet hos haveboligerne fra 5,3 kg i 2021 skyldes nok mest problemer med indsamlingen dengang. Undersøgelsen er den første i en række, der skal følge effekten af affaldsplanen.' },
      { id: 'N21', title: 'Tilpasning af storskraldsordning ved fortovsindsamling i Greve- og Solrød Kommune', org: 'KLAR Forsyning', year: 2024, type: 'Notat', temaer: ['Storskraldsordning', 'Udbud og kravspecifikationer', 'Økonomi'], img: 'img/1bc963ce5afd5f9824d353457e9f6189.jpg', url: 'https://dagsordener.greve.dk/vis/pdf/bilag/63e7f9c6-c288-44dd-a8e9-1e9d757aeec0', res: 'COWI har for KLAR Forsyning sammenlignet storskraldsordningerne i Greve og Solrød før et fælles udbud. Notatet anbefaler fast rutetømning og at hente rent træ for sig.', long: 'Notatet fra oktober 2024 behandler seks emner, hvor de to ordninger er forskellige. En stikprøve viste, at 34 % af husstandene i Greve og 41 % i Solrød havde sat storskrald ud, så COWI anbefaler fast rutetømning frem for en bestillerordning, med storskrald hver 4. uge i begge kommuner. Rent træ og brændbart storskrald bør dog hentes hver for sig samme dag hver 8. uge, hvor udsorteringsgraden for træ skønnes til ca. 33 % mod mindst 16 % ved samlet indsamling. Haveaffald foreslås kun hentet marts-november plus en juletræsrunde, hvilket sparer Solrød 361.961 kr. om året. Til farligt affald anbefales en fælles løsning, gerne med miljøbil.' },
      { id: 'N22', title: 'Fremfærd: Fremtidens Renovation. Tværgående rapport', org: 'Fremfærd (KL og 3F)', year: 2023, type: 'Rapport', temaer: ['Ledelse', 'Etageboliger', 'Kommunikation'], img: 'img/abe5cb5649a4513e700ce0036aa7bb0d.jpg', url: 'https://cdn.sanity.io/files/6govnrwr/production/72702b170baddfb0541c13f262e5a0caf09f178b.pdf', res: 'Opsamling på tre forandringsprojekter 2021-2023 om renovationsarbejdernes rolle, da de ti nye fraktioner blev rullet ud. Varige forandringer kræver inddragelse og kompetenceløft.', long: 'Behave Green har for Fremfærd, et partssamarbejde mellem KL og 3F, samlet erfaringerne fra tre delprojekter fra august 2021 til sommeren 2023. Hos Ressourceindsamling A/S fik 10 renovationsarbejdere et kursus i borgerdialog og konflikthåndtering. I Middelfart lavede en arbejdsgruppe af medarbejdere fælles retningslinjer for indmeldinger og en ny hænger til spandene. Workshops i etageejendommen Eskebjerggård i Ballerup viste, at det ofte er uklart, hvem der har ansvaret for fejlsorteringer. De mange forandringer i branchen kan skabe modstand, og rapporten anbefaler tidlig inddragelse med reelt ansvar og kompetenceløft i hele organisationen.' },
      { id: 'N23', title: 'Klimaplan for en grøn affaldssektor og cirkulær økonomi', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2020, type: 'Strategi', temaer: ['Affaldsplaner/regulativer og strategi', 'Lovgivning og afgørelser', 'Klima'], img: 'img/a3d89b54bd2c524f4ccac813ed0de94a.jpg', url: 'https://www.kefm.dk/Media/4/3/aftaletekst%20Klimaplann%20for%20en%20gr%C3%B8n%20affaldssektor%20og%20cirkul%C3%A6r%20%C3%B8konomi.pdf', res: 'Den politiske aftale fra 16. juni 2020 sigter mod en klimaneutral affaldssektor i 2030. Den indfører ens indsamling af 10 affaldstyper og skærer ned på forbrændingskapaciteten.', long: 'Regeringen og syv partier indgik aftalen, så affaldssektoren kan bidrage til målet om 70 % lavere udledning i 2030 i forhold til 1990. Kommunerne skal indsamle 10 affaldstyper ens fra 1. juli 2021, tekstil dog fra 2022, og et parcelhus skal som udgangspunkt have højst 2-4 spande. Behandlingen af genanvendeligt husholdningsaffald skal i udbud, og kommunerne skal kræve 60 % reel genanvendelse af indsamlet plast. Forbrændingskapaciteten på 3,95 mio. tons skal tilpasses de ventede 2,6 mio. tons affald til forbrænding i 2030. Tiltagene ventes at spare ca. 0,7 mio. tons CO2 og give ca. 65 % mindre plast i forbrændingen, mens visionen er 80 %.' },
      { id: 'N24', title: 'Fordele og ulemper ved hhv. særskilte og kombinerede indsamlingsordninger', org: 'Reno Djurs', year: 2021, type: 'Analyse', temaer: ['Hente- og bringeordninger', 'Afsætning og behandling', 'Udbud og kravspecifikationer'], img: 'img/7b3590f6c5b86abd42792ff287dde175.jpg', url: 'https://renodjurs.dk/sites/default/files/2021-06/Bilag%207_Delrapport%20-%20Opsamling%20af%20aktivitet%201-3.pdf', res: 'Delrapport fra Econet om særskilt eller kombineret indsamling af genanvendeligt affald. Aftagerne får bedst kvalitet ved særskilt indsamling, men kombineret er billigere at tømme.', long: 'Delrapporten er lavet af Econet i april 2021 for Reno Djurs, Renosyd, Favrskov Forsyning og Affaldvarme Aarhus. Den bygger på interview med syv selskaber og kommuner, seks aftagere, emballagebranchen og leverandører af materiel og IT. Alle syv vil indsamle restaffald, madaffald og farligt affald særskilt, og alle på nær Odense Renovation også glas. De fleste regner med at starte i 2022 eller 2023. Deres beregninger for enfamilieboliger giver gebyrstigninger på 68-800 kr. pr. husstand om året. Reiling og Vestforbrænding ser lav kvalitet i glas fra kombineret indsamling, og Plastindustrien vil have ét rum til plast uden mad- og drikkekartoner.' },
      { id: 'N25', title: 'Strømlinet indsamling af storskrald. Potentialer ved best practice', org: 'Miljøstyrelsen', year: 2025, type: 'Analyse', temaer: ['Storskraldsordning', 'Direkte genbrug', 'Analyser og undersøgelser'], img: 'img/575f2e4b540b51472f906b3bf955ba81.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/02/978-87-7564-087-4.pdf', res: 'Miljøstyrelsen har kortlagt storskraldsordningerne i 74 kommuner. Ca. 32.500 af 87.761 ton fra 2024 kan flyttes op i affaldshierarkiet med skånsom indsamling og tidlig sortering.', long: 'Provice, Nextpuzzle og AffaldPlus har for Miljøstyrelsen gennemgået kommunernes hjemmesider og indsamlet data fra 33 kommuner. Møbler udgør 56 % af storskraldet og pap 28 %. Effekterne mister værdi, når de står i regn eller går i stykker i grab og komprimator, og 4-14 % kunne ofte genbruges direkte. Rapporten anbefaler blandt andet at indsamle pap med den almindelige husstandsindsamling og tørt indendørs træ som egen fraktion. Best practice giver ifølge beregningerne 14.483 ton mere genanvendelse, 7.345 ton genbrug, 9.861 ton mindre CO2 og en besparelse på ca. 43,7 mio. kr. om året. Besparelsen opstår kun i de større bykommuner.' },
      { id: 'N26', title: 'Høringsnotat vedr. forslag til Lov om ændring af lov om miljøbeskyttelse og lov om Forsyningstilsynet', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2022, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Genbrugspladser'], img: 'img/4cf9743b7dfc5cf150d235d702b6bcb1.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/5ca08f9a-1df7-4c0b-9f0e-b2ac1c4fd97e/H%C3%B8ringsnotat.pdf', res: 'Ministeriet svarer 34 parter, der har kommenteret lovforslaget om en stærk genanvendelsessektor. Efter høringen åbner det for, at virksomheder også kan bruge genbrugsområderne.', long: 'Klima-, Energi- og Forsyningsministeriet gennemgår høringen fra november 2021 til januar 2022 i tolv emner, bl.a. kommunal indsamling af erhvervsaffald og det skærpede økonomiske tilsyn. KL og flere kommuner kritiserer kravet om markedspriser og ophævelsen af ordningen for blandet bolig og erhverv, men ministeriet fastholder begge dele. Forslaget bliver rettet, så kommuner kan bruge affald egnet til materialenyttiggørelse i egne bygge- og anlægsprojekter, og så ansatte på genbrugspladsen må tage ting op af containerne til genbrug. Kommunale anlæg i overgangsordningen skal selskabsgøres fra 1. januar 2024 og afhændes senest 1. juli 2027.' },
      { id: 'N27', title: 'Indsamling og håndtering af tekstilaffald i kommunerne', org: 'Miljøstyrelsen', year: 2023, type: 'Analyse', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/351c0b06603226ffca19c7269cf4d268.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/03/978-87-7038-506-0.pdf', res: 'Miljøstyrelsen spurgte i 2022 kommuner med tekstilindsamling, og 28 svarede. Pose med storskrald var den mest brugte henteordning, og fire af 13 havde svært ved at finde aftagere.', long: 'Undersøgelsen er lavet i Tekstilaffaldspartnerskabets vidensbankprojekt, før kravet om tekstilindsamling trådte i kraft 1. juli 2023. Miljøstyrelsen sendte skemaet til 32 kommuner og fik svar fra 28, men de fleste spørgsmål var frivillige, og svarene bygger på skøn. Af dem havde 18 en henteordning og 21 en bringeordning. Ved enfamilieboliger brugte 11 af 15 kommuner pose med storskrald eller bestilling, og 11 af 16 hentede med ladbil eller lastvogn. Ti kommuner afveg fra bekendtgørelsens definition af tekstilaffald, især ved at tage fodtøj og genbrugstøj med. Rapporten peger også på et behov for bedre afsætning af tekstilaffaldet.' },
      { id: 'N28', title: 'Affaldsanalyse af restaffald fra enfamilieboliger og etageboliger med nedgravede beholdere 2025', org: 'Randers Kommune', year: 2026, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Etageboliger', 'Haveboliger/parcelhuse'], img: 'img/16fc01e5f3af5cd797eea71072d854cd.jpg', url: 'https://www.randers.dk/media/doyoh1el/affaldsanalyse-af-restaffald-fra-enfamilieboliger-og-etageboliger-med-nedgravede-beholdere-2025_wt.pdf', res: 'Restaffaldet fra etageboliger med nedgravede beholdere i Randers bestod i 2025 af 41 % madaffald mod 24 % i enfamilieboliger, viser Econets sorteringsanalyse af 1.525 kg.', long: 'Econet har for Randers Kommune sorteret restaffald fra 243 lejligheder i oktober 2025 og fra 105 enfamilieboliger i december 2025. Etageboligerne havde 3,4 kg restaffald pr. husstand pr. uge og enfamilieboligerne 3,9 kg. Genanvendelige materialer udgjorde 24 og 25 %, mest plast, og kun 32 % af restaffaldet fra etageboliger var korrekt sorteret mod 48 % i enfamilieboliger. Sammenlignet med 2021, før den opdelte sortering kom i foråret 2024, er de genanvendelige materialer i etageboligernes restaffald faldet fra 1.548 til 821 g pr. husstand pr. uge, mens madaffaldet er steget. I enfamilieboliger er de faldet fra 1.400 g i 2019 til 951 g.' },
      { id: 'N29', title: 'Tackling contamination in dry recycling: an updated guide for local authorities', org: 'WRAP', year: 2024, type: 'Vejledning', temaer: ['Sorteringskvalitet', 'Kommunikation', 'Hente- og bringeordninger'], img: 'img/d25e1004ec8f744a464b18d31e32b232.jpg', url: 'https://www.wrap.ngo/sites/default/files/2024-03/WRAP-Tackling-contamination-in-dry-recycling-report-March-2024.pdf', res: 'WRAPs vejledning til britiske kommuner om fejlsortering i det tørre genanvendelige affald, der hentes ved husstandene. Den anbefaler at lade fejlsorterede beholdere stå.', long: 'WRAP udgav vejledningen i 2015 og gennemgik den i marts 2024. Ifølge WRAPs Recycling Tracker 2023 lægger 81 % af britiske husstande noget til genanvendelse, som ikke modtages lokalt, og i slutningen af 2019 var 16,6 % af input til sorteringsanlæggene fejlsorteringer. Borgerne er i tvivl om reglerne og får ikke besked, når de sorterer forkert. Anden del er en plan i seks trin fra kortlægning til evaluering. WRAP anbefaler, at skraldemænd eller kontrollanter tjekker beholderne og lader de fejlsorterede stå med et mærke. Et forsøg i Bracknell Forest og Reading gav flere mærkede beholdere, men ingen målbar forbedring i sorteringsanlæggets prøver.' },
      { id: 'N30', title: 'Høringsnotat: Udkast til bekendtgørelse om Affaldsdatasystemet', org: 'Miljøstyrelsen', year: 2025, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Data, statistikker og nøgletal', 'Erhverv'], img: 'img/fd6d073069f3db0d5006741d8c47bc2b.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/718183d9-9d77-4dd0-b862-979c057f5fbd/H%C3%B8ringsnotat.pdf', res: 'Høringsnotat om nye regler for indberetning til Affaldsdatasystemet med svar på 18 høringssvar. Pligten til at indberette indsamlet husholdningsaffald udgår indtil videre.', long: 'Miljøstyrelsens udkast til bekendtgørelse om Affaldsdatasystemet var i høring i august og september 2025 og fik 18 svar, bl.a. fra KL og Københavns Kommune. Blandt andre KL og Cirkulær mente, at pligten til at indberette indsamlet husholdningsaffald ikke skaber værdi og kun giver flere administrative byrder. Pligten udgår af denne revision, og styrelsen tager i 2026 dialog med branchen om datakvaliteten. Fristen for indberetning rykkes trods protester fra 1. marts til 1. februar, og kommunerne får til 31. marts til at rette fejl i virksomhedernes data. Fraktionskoden for farligt affald fjernes, fordi EAK-koden viser, om affaldet er farligt.' },
      { id: 'NY001', title: 'Vejledning om håndtering af bygge- og anlægsaffald', org: 'Miljøstyrelsen', year: 2019, type: 'Vejledning', temaer: ['Byggeaffald', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/6fefb1f75b4f36b7696b9116f7f4339b.jpg', url: 'https://www.retsinformation.dk/api/pdf/207372', res: 'Miljøstyrelsens vejledning samler reglerne for bygge- og anlægsaffald, fra PCB-screening før nedrivning over anmeldelse og sortering til brug af lettere forurenet affald i fx veje.', long: 'Vejledningen fra 2019 er skrevet som opslagsværk for bygherrer, håndværkere, entreprenører og kommuner. Hovedvægten ligger på PCB og på, hvornår affaldet kan erstatte primære råstoffer i fx veje. Nedrivning og renovering over 10 m² eller med mere end 1 ton affald skal anmeldes til kommunen senest 2 uger før start, og bygninger opført eller renoveret i 1950-1977 skal screenes for PCB. Affald med over 50 mg PCB/kg er farligt affald, mens beton, uglaseret tegl og natursten med højst 2,0 mg PCB/kg under visse betingelser må bruges uden tilladelse efter anmeldelse senest 4 uger før. Vejledningen forklarer også, hvornår kommunen har anvisningsret.' },
      { id: 'NY002', title: 'Kvalitetskrav for indsamlingsordninger: metal, glas og hård plastik', org: 'Miljøstyrelsen', year: 2020, type: 'Rapport', temaer: ['Sorteringskvalitet', 'Hente- og bringeordninger', 'Reel genanvendelse'], img: 'img/1e35a06a4717d7ade6a8088f2c67e82f.jpg', url: 'https://mst.dk/media/fbylwzni/kvalitetskrav-for-indsamlingsordninger-metal-glad-og-haard-plastik.pdf', res: 'En pointmodel fra Rambøll til Miljøstyrelsen vurderer indsamlingsordninger for metal, glas og hård plast. MGP-indsamling scorede lavere end særskilt indsamling for glas og plast.', long: 'Rambøll sammenlignede i 2019-2020 særskilt indsamling af metal, glas og hård plastik med MGP-indsamling ud fra prøver fra to sorteringsanlæg og fra særskilt indsamling i tre geografier, ADS-data og materiale fra kommuner og branchen. Modellen ganger genanvendelses- og sorteringseffektivitet med en kvalitetsscore, hvor lav kvalitet vægtes med 0,3. Særskilt indsamlet hård plastik fik i snit 70,2 point mod 66,0 for MGP, og glas 89,9 mod 82,0. Glas fra kuber scorede højest med 94,0, og særskilt indsamlet metal fik fuld score. Rapporten anbefaler tre prøver fra tre dage og en margin på fx 2 point, når to ordninger skal regnes for lige gode.' },
      { id: 'NY003', title: 'Ressourceudnyttelse af storskrald ved robotsortering. Faglig afrapportering af arbejdspakke 1', org: 'Miljøstyrelsen', year: 2020, type: 'Rapport', temaer: ['Storskraldsordning', 'Teknologi', 'Afsætning og behandling'], img: 'img/4978f5030504456993cb89eb3a2dfb91.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2020/06/978-87-7038-200-7.pdf', res: 'Vestforbrænding testede maskiner til forsortering af brændbart storskrald før robotsortering. Neddeler, tromle- og vindsigte sendte ca. 73 % videre, ballistisk sigte kun ca. 30 %.', long: 'Afrapporteringen dækker arbejdspakke 1 i et MUDP-støttet projekt, hvor Vestforbrænding ville bygge et robotanlæg i Frederikssund til den del af storskraldet, der går til forbrænding. Fra 2015 til 2018 gennemførte selskabet bl.a. et udbud med konkurrencepræget dialog og forsøg med maskiner. Test i Helsinki pegede på, at omkring 50 % af det brændbare storskrald kunne sorteres til genanvendelse. Robotarmene kunne kun gribe emner op til 150 x 150 x 45 cm, og tekstilerne var så beskidte, at de bør holdes ude af ordningen. Projektet blev sat i bero i maj 2019 på grund af logistik og behov for flere investeringer.' },
      { id: 'NY004', title: 'Kvalitet og genanvendelsesandele for emballageaffald og ikke-emballage', org: 'Miljøstyrelsen', year: 2020, type: 'Rapport', temaer: ['Reel genanvendelse', 'Afsætning og behandling'], img: 'img/7a584819b91eeb6cb5e26e3d0a436f36.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2020/12/978-87-7038-258-8.pdf', res: 'Miljøstyrelsen har undersøgt, om emballage og ikke-emballage i en blandet strøm genanvendes lige godt. Det kan antages for træ, metal, glas, papir og pap, men ikke for plast.', long: 'Econet og Rambøll har for Miljøstyrelsen undersøgt, om emballage og ikke-emballage har samme genanvendelsesandel, når de er blandet i samme materialestrøm. Grundlaget er interview med 11 virksomheder i genanvendelseskæden fra oktober 2019 til august 2020. Blandingen sker ved indsamlingen, ikke hos modtageanlæggene. For træ og metal er der ingen teknisk forskel, og for glas, papir, pap og fødevarekartoner er forskellen uden praktisk betydning. Plast skiller sig ud. Et regneeksempel fra København viser, at 96 % af den hårde plastemballage er PET, HDPE og PP mod 72 % af ikke-emballagen. Data til at opgøre forskellen generelt findes ikke.' },
      { id: 'NY005', title: 'Sporing af affald i ADS', org: 'Miljøstyrelsen', year: 2020, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse'], img: 'img/d81f99422b8d4efad0f0c9db904a9c63.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2020/12/978-87-7038-259-5.pdf', res: 'Miljøstyrelsen har testet, om data i Affaldsdatasystemet kan følge affaldet fra første indvejning til slutbehandling. Det kan lade sig gøre, men datakvaliteten skal løftes først.', long: 'COWI og Polytec har for Miljøstyrelsen afprøvet to metoder til at spore affald i ADS. Den ene sammenholder primære og slutbehandlede mængder, den anden følger fx andelen af husholdningsaffald gennem hele behandlingskæden med et webværktøj fra COWI. Opgørelser på EAK-koder kan ikke anbefales, fordi affaldet typisk får en 19-kode, når det flyttes til et nyt anlæg. E/H-koder er mere stabile. For træ lå slutgenanvendelsen på 88 % i 2016 og 87 % i 2017, men ca. 10 procentpoint kommer formentlig fra træ, der er sorteret fra andet affald. Den første metode er billigst og kan bruges straks, mens værktøjet først skal bygges ind i ADS.' },
      { id: 'NY006', title: 'Handlingsplan for cirkulær økonomi. Faktaark', org: 'Miljøministeriet', year: 2021, type: 'Faktaark', temaer: ['Affaldsplaner/regulativer og strategi', 'Cirkulær økonomi', 'Data, statistikker og nøgletal'], img: 'img/ee078a5b5c30268d8fb33685810a65aa.jpg', url: 'https://mim.dk/media/fuufsbc4/alle-faktaark-2_dansk.pdf', res: 'Miljøministeriets faktaark om Handlingsplan for cirkulær økonomi viser planens mål og indsatser, bl.a. målet om 65 % genanvendelse af husholdningslignende affald i 2035.', long: 'Faktaarkene fra juli 2021 sammenfatter den nationale plan for forebyggelse og håndtering af affald 2020-2032 med 129 initiativer. I 2019 opstod ca. 12,7 mio. tons affald, og 44 % af det husholdningslignende affald blev genanvendt. Miljøstyrelsens fremskrivning viser, at Danmark er tæt på målene for 2025 og 2030, mens målet om 65 % i 2035 sandsynligvis kræver flere initiativer. Regeringen vil bl.a. strømline sorteringen af husholdningslignende affald og skære forbrændingskapaciteten med 30 % fra 2020 til 2030, hvor overkapaciteten er ca. 700.000 tons. Kun ca. 25 % af de 514.000 tons plastikaffald i 2019 blev indsamlet til genanvendelse.' },
      { id: 'NY007', title: 'Undersøgelse af fysiske urenheder i biopulp', org: 'Miljøstyrelsen', year: 2021, type: 'Rapport', temaer: ['Afsætning og behandling', 'Analyser og undersøgelser'], img: 'img/7aa55fa6edecfe71c88eb9130807f1a0.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2021/01/978-87-7038-261-8.pdf', res: 'Teknologisk Institut har målt fysiske urenheder i biopulp fra seks anlæg. Middelværdierne overholder grænseværdierne på alle anlæg, og poleringstrin giver meget ren pulp.', long: 'Teknologisk Institut undersøgte for Miljøstyrelsen, hvor ren biopulp fra forbehandlet organisk affald er. Der blev taget prøver på seks anonyme anlæg, hvoraf fem behandler særskilt indsamlet køkken- og madaffald, og plasten blev målt ned til 2 mm og 1 mm. Middelværdierne lå for alle anlæg under kravene i affald til jord-bekendtgørelsen. Et poleringstrin reducerede plast over 2 mm med ca. en faktor 12 på ét anlæg og ca. 200 gange på et andet. Det meste plast stammer fra affaldsposerne. Partikler på 1-2 mm øgede plastarealet med 9-11 % på de konventionelle anlæg, og den arbejdstunge 1 mm-analyse vurderes ikke at stå mål med den ekstra plast.' },
      { id: 'NY008', title: 'Nomi4s: forbedret teknologi for automatisk robotsortering af plastaffald', org: 'Miljøstyrelsen', year: 2021, type: 'Rapport', temaer: ['Teknologi', 'Afsætning og behandling'], img: 'img/6a4ce95de5bee3986b8e32a8fe29c291.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2021/01/978-87-7038-271-7.pdf', res: 'MUDP-projekt hos Nomi4s i Holstebro, der har forbedret robotsortering af plast fra husholdninger. Robotterne greb 85 % af HDPE-emnerne mod 71 % ved projektets start.', long: 'I fase 2 af et MUDP-projekt videreudviklede Nomi4s i/s sammen med Nordtec-Optomatic, Linatech og GRIPWIQ det robotanlæg, som siden 2016 har sorteret plast fra dagrenovation. Arbejdet foregik fra november 2017 til november 2019. En lånt ballistisk sigte kunne skille folie fra hård plast, og nye sugehoveder gav sikrere greb. Optimeret software fik robotterne til at sortere oftere og mere præcist. Et 3D-kamera viste sig uegnet, og udstyr til at presse emnerne sammen blev opgivet. Driftsudgifterne er anslået til 782.058 kr. om året, hvoraf operatøren står for 500.000 kr.' },
      { id: 'NY009', title: 'Udvikling af oparbejdningslinje til optimal genanvendelse af indsamlet plast fra husstande', org: 'Miljøstyrelsen', year: 2021, type: 'Rapport', temaer: ['Afsætning og behandling', 'Teknologi', 'Reel genanvendelse'], img: 'img/f5adf41d13728b6f1203249ba81d9491.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2021/03/978-87-7038-288-5.pdf', res: 'MUDP-projekt, hvor en prototype på en oparbejdningslinje gør husstandsindsamlet hård plast af HDPE og PP til salgbart regranulat med lille plasttab og lavt vandforbrug.', long: 'Aage Vestergaard Larsen A/S har i 2018-2020 sammen med Reno-Nord, ARC, Nomi4s og Teknologisk Institut udviklet en linje, der neddeler, vasker, densitetssorterer og tørrer polymersorteret hård plast fra husstande. Plasten kom fra flere indsamlingssystemer og blev sorteret på tre anlæg. Renheden svingede, mest på grund af folie og affald, men alle testede partier HDPE og PP gav piller i god, salgbar kvalitet. Plasttabet blev anslået til 5-9 % for HDPE og 8-12 % for PP, og linjen brugte ca. 0,8 liter vand pr. kg mod 2-3 liter på anlæg i udlandet. Den kan også udvinde PE og PP fra sort plast, men er ikke bygget til at oparbejde PET fuldt ud.' },
      { id: 'NY010', title: 'Økonomi ved behandling af emballageaffald i 2025', org: 'Miljøstyrelsen', year: 2021, type: 'Analyse', temaer: ['Økonomi', 'Udvidet producentansvar', 'Analyser og undersøgelser'], img: 'img/62f0abf1efeb38b1bcce2727ec142f9b.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2021/11/978-87-7038-356-1.pdf', res: 'COWI har for Miljøstyrelsen beregnet, at håndteringen af emballageaffald i 2025 forventes at koste 2,35 mia. kr. netto, svarende til 2.023 kr. pr. ton. Pant er ikke medregnet.', long: 'Analysen opgør nettoomkostningerne til indsamling, sortering og behandling af emballageaffald i 2025, når Klimaplanens krav er indført, og det udvidede producentansvar skal træde i kraft. Den bygger på ADS-data for 2019, emballagestatistikken for 2018, FRIDA-fremskrivninger og priser fra kommunale udbud. Af 1.160.254 ton emballage forventes ca. 83 % indsamlet til genanvendelse. Husholdningerne står for 1,50 mia. kr. og erhverv for 0,85 mia. kr., mens plast koster 1,12 mia. kr. og pap 0,63 mia. kr. Indsamlingen udgør 71 % af udgiften, og Klimaplanen alene øger omkostningen med 0,57 mia. kr. Med pant bliver totalen 2,52 mia. kr.' },
      { id: 'NY011', title: 'Ressourceforbruget forbundet med administrations- og tilsynsopgaverne med affald', org: 'Miljøstyrelsen', year: 2021, type: 'Analyse', temaer: ['Erhverv', 'Analyser og undersøgelser', 'Ledelse'], img: 'img/90e0740e38a3a53142add20a774be184.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2021/01/978-87-7038-263-2.pdf', res: 'Kommuner og styrelser brugte i 2018 ca. 57 årsværk på affaldstilsyn, anmeldelser, klassificering og anvisning af erhvervsaffald, viser NIRAS\' analyse for Miljøstyrelsen.', long: 'NIRAS har sammen med Bech-Bruun og BDO kortlagt ressourceforbruget i kommuner og stat på affaldstilsyn, anmeldelser, klassificering og anvisning af erhvervsaffald. Tallene bygger på en spørgeskemaundersøgelse fra 2019 om året 2018 suppleret med interview, og kommunetallene er skaleret op fra besvarelser fra 70 kommuner. Opgaver om husholdningsaffald og affaldsplanlægning er ikke med. Kommunerne står for ca. 47 årsværk og styrelserne for ca. 10. Med usikkerheden ligger det samlede forbrug på 43-72 årsværk, bl.a. fordi kun 10-15 % af kommunerne registrerer tid på affaldsopgaverne. Anmeldelser er den tungeste opgave med 22-30 årsværk.' },
      { id: 'NY012', title: 'Plast fra landbrugs- og byggesektoren afleveret til genanvendelse på genbrugspladser', org: 'Miljøstyrelsen', year: 2022, type: 'Analyse', temaer: ['Genbrugspladser', 'Erhverv', 'Data, statistikker og nøgletal'], img: 'img/93dbe680505e0f96c553a4a5e81d4fff.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2022/06/978-87-7038-424-7.pdf', res: 'Miljøstyrelsen skønner, hvor meget af plasten til genanvendelse på genbrugspladser der kommer fra landbrug og byggeri. Landbruget står for ca. 3 % og byggeriet for ca. 12 %.', long: 'Analysen skal gøre det muligt for Miljøstyrelsen at beregne, hvor meget plast fra landbrug og byggeri der indsamles til genanvendelse via genbrugspladser og modtageanlæg. Skønnene bygger på litteratur, interviews med 14 eksperter, ADS-data, brugerundersøgelser og en survey blandt 200 virksomheder, som dog ikke gav tal, der kan skaleres op. Landbruget skønnes at aflevere 20 % af sin plast til genanvendelse på genbrugspladser og 80 % hos modtageanlæg. Byggeriets plast ekskl. PVC fordeler sig ligeligt, mens 75 % af PVC-affaldet afleveres på genbrugspladser. Tallene er usikre, fordi viden på området er sparsom.' },
      { id: 'NY013', title: 'Sortering af genbrugsplads-samlede tekstiler fra Argo', org: 'Miljøstyrelsen', year: 2022, type: 'Notat', temaer: ['Tekstil', 'Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/81b295e328ff2247753eec06d4e5e145.jpg', url: 'https://mst.dk/media/dshfjzuj/rapport-sorteringsforsoeg-argo.pdf', res: 'Notat om sortering af 1.435 kg tekstiler fra to af ARGOs genbrugspladser. Af dem kunne 86,1 % genbruges, mest ved eksport, mens 13,1 % blev kasseret og 0,9 % kunne genanvendes.', long: 'Sorteringen fandt sted 8. marts 2022 hos AffaldPlus\' tekstilenhed og omfattede tekstiler afleveret 1.-7. marts på genbrugspladserne i Torkilstrup og Roskilde. ARGO håndterer ca. 1.000 ton tekstilaffald om året og samler det på genbrugspladserne i 770 l minicontainere, som tømmes ugentligt af en bil, der kun kører med tekstiler. Af stikprøven var 45,6 % tøj og 33,2 % boligtekstiler til genbrug i udlandet, mens 1,9 % kunne sælges i Danmark. Fugt- og rustskader udgjorde kun 1,8 %, langt mindre end i en tilsvarende analyse af storskrald i Gentofte. Kan dyner og puder (3,7 %) på sigt genanvendes, stiger den genanvendelige andel til 4,6 %.' },
      { id: 'NY014', title: 'Sortering af tekstiler fra to indsamlingsordninger i Gentofte', org: 'Miljøstyrelsen', year: 2022, type: 'Notat', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Sorteringskvalitet'], img: 'img/026db94164cd52beecd80c82271b537c.jpg', url: 'https://mst.dk/media/nhbnasr1/rapport-sorteringsforsoeg-gentofte.pdf', res: 'Tekstiler fra etageboligers beholdere og fra storskrald i Gentofte blev håndsorteret hos AffaldPlus. Omkring 70 % kunne genbruges, og fugt og rust kostede mere end fejlsortering.', long: 'I februar 2022 sorterede AffaldPlus 1.202 kg tekstil fra et forsøg i 20 etageejendomme med 530 lejligheder og 465 kg tekstilsække fra storskraldsordningen. Fra etageboligerne var 70 % egnet til genbrug, 8 % til genanvendelse, og 22 % blev kasseret. Kun 7,7 % lå i poser, selvom beboerne var bedt om det. Egentlig fejlsortering udgjorde 2,9 %, mens 12-13 % måtte kasseres på grund af fugt og rust, som ifølge notatet opstod efter afleveringen. Poserne i storskraldet beskyttede ikke bedre. Notatet foreslår blandt andet stærke, lukkede tekstilposer og krav i udbud om at undgå komprimering og tømme vand ud af bilens kammer.' },
      { id: 'NY015', title: 'Vejledende udtalelse om affaldsbekendtgørelsens krav om høj reel genanvendelse', org: 'Miljøstyrelsen', year: 2022, type: 'Vejledning', temaer: ['Reel genanvendelse', 'Lovgivning og afgørelser', 'Udbud og kravspecifikationer'], img: 'img/9ccc3e4a982789810b48d7abe75f4cd5.jpg', url: 'https://mst.dk/media/0gulpost/vejledende-udtalelse-for-kommuner-om-opgoerelse-og-dokumentation-for-reel-genanvendelse.pdf', res: 'Miljøstyrelsen forklarer, hvordan kommuner skal sikre og dokumentere høj reel genanvendelse af indsamlet affald, og giver vejledende tabsrater fra 3 % for papir til 54 % for plast.', long: 'Den vejledende udtalelse fra januar 2022 retter sig mod kommunerne og de virksomheder, der håndterer kommunens affald. Kommunen skal i sine aftaler kræve dokumentation for, hvor meget af fx mad-, papir-, glas-, plast- og tekstilaffald der reelt genanvendes. Der er ingen formkrav, men styrelsen foreslår dokumentation mindst en gang om året og peger bl.a. på kvalitetsstyring og modtagekontrol hos indsamlere og anlæg. Genanvendelsen kan beregnes ud fra gennemsnitlige sorteringseffektiviteter i hvert led, og i et eksempel ender 96 af 100 ton indsamlet glas som reelt genanvendt. Kommunen afgør selv, hvad høj genanvendelse er.' },
      { id: 'NY016', title: 'Reduktion af klimagasser fra behandling af haveaffald. Del 2: Emissionsfaktorer', org: 'Miljøstyrelsen', year: 2023, type: 'Rapport', temaer: ['Klima', 'Afsætning og behandling'], img: 'img/2ad4b7ae6b3c461ca78ef6c53af350d1.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/02/978-87-7038-478-0.pdf', res: 'Målinger på tre danske komposteringsanlæg og en finstofbunke giver lavere emissionsfaktorer for metan og lattergas fra haveaffald end dem, de nationale opgørelser bruger i dag.', long: 'COWI og DTU har for Miljøstyrelsen målt metan og lattergas fra haveaffald i fire målekampagner over et år hos Gemidan Tulstrup, Kerteminde Forsyning, Kredsløb Aarhus og en finstofbunke ved Venslev Huse. Sammen med ældre DTU-målinger giver det en gennemsnitlig emission fra kompostering på 2,54 g metan og 0,058 g lattergas pr. kg haveaffald, hvor DCE i dag bruger 3,19 g og 0,23 g. Finstof til direkte udspredning gav 2,95 g metan og 0,038 g lattergas pr. kg, men kun målt på én lokalitet. Med de nye faktorer falder den opgjorte udledning med ca. 55 %, også fordi kun 75 % af det modtagne haveaffald reelt komposteres eller spredes på marker.' },
      { id: 'NY017', title: 'Reduktion af klimagasser fra behandling af haveaffald. Del 3: Alternative teknologier', org: 'Miljøstyrelsen', year: 2023, type: 'Rapport', temaer: ['Afsætning og behandling', 'Klima', 'Teknologi'], img: 'img/b706e861f68eef5a8a034a9f30e16f9d.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/02/978-87-7038-489-6.pdf', res: 'COWI har for Miljøstyrelsen sammenlignet alternativer til åben milekompostering af haveaffald. Pyrolyse giver den største klimabesparelse og den laveste beregnede pris.', long: 'Tredje del af Miljøstyrelsens projekt om klimagasser fra haveaffald er skrevet af COWI og bygger på data fra aktører på markedet og videnskabelige artikler. I dag spredes 56 % som finstof på landbrugsjord, 25 % forbrændes og 19 % komposteres i åbne miler. Det sammenlignes med reaktorkompostering, pyrolyse, kombineret anaerob og aerob nedbrydning og ren forbrænding. Nettobesparelsen går fra 30 kg CO₂-ækv. pr. ton i dag til 263 kg ved pyrolyse, som også har den laveste beregnede pris på 108 kr./ton mod 173 kr./ton i dag. Prisen kan dog ligge mellem -114 og 371 kr./ton, og rapporten anbefaler ikke en bestemt løsning.' },
      { id: 'NY018', title: 'Tekstilaffaldspartnerskabets afslutningsrapport', org: 'Miljøstyrelsen', year: 2023, type: 'Rapport', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Udbud og kravspecifikationer'], img: 'img/772b55057adef9d17683dbea9df21e13.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/10/tekstilaffaldspartnerskabets-afslutningsrapport.pdf', res: 'Afslutningsrapporten fra Miljøstyrelsens Tekstilaffaldspartnerskab 2021-2023 samler erfaringer fra tre pilotprojekter. Våde tekstiler og meget genbrugstøj var store problemer.', long: 'Miljøstyrelsen faciliterede partnerskabet 2021-2023, frem mod kravet om særskilt indsamling af tekstilaffald fra husholdninger 1. juli 2023. I værdikædeprojektet fulgte deltagerne tekstiler gennem forsortering hos UFF Humana og NIR-sortering hos NewRetex. En materialeanalyse hos VIA University College viste så lav rivstyrke i bomulden, at kemisk genanvendelse passede bedst. Udbudsprojektet lavede en skabelon til kravspecifikation. 28 af de 32 kommuner, der i sommeren 2022 indsamlede tekstilaffald, svarede på et spørgeskema. Alle kommunerne havde haft problemer med våde tekstiler, og poser og biler uden komprimator gav de bedste erfaringer.' },
      { id: 'NY019', title: 'Økonomiske og miljømæssige konsekvenser ved at indføre et udvidet producentansvar for tekstilproducenter', org: 'Miljøstyrelsen', year: 2023, type: 'Analyse', temaer: ['Udvidet producentansvar', 'Tekstil', 'Økonomi'], img: 'img/07e61018602575be8fb614942cc578dc.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/04/978-87-7038-510-7.pdf', res: 'Deloitte har for Miljøstyrelsen regnet på et udvidet producentansvar for tekstiler. Det vurderes at koste samfundet ca. 159 mio. kr. om året og spare ca. 41.000 tons CO2e globalt.', long: 'Analysen bygger på registerdata, tidligere studier og 30 interviews med blandt andre producenter og kommunale indsamlere. I 2021 kom ca. 116.000 tons tekstiler på det danske marked, og 41 % blev indsamlet til genbrug af velgørende og private aktører. Med kommunal indsamling ved husstandene ventes ca. 6.700 tons indsamlet separat i 2024. Mellem 250 og 7.300 virksomheder kan blive omfattet, alt efter hvordan producenten defineres. Borgernes affaldsgebyr ville falde med ca. 165 mio. kr. om året, som producenterne i stedet ville betale, i snit 1,3 kr. pr. kg tekstil. Samfundets omkostning skyldes især faldende salg og mere administration.' },
      { id: 'NY020', title: 'Vejledende udtalelse om affaldsbekendtgørelsen § 43 (undtagelse fra særskilt indsamling)', org: 'Miljøstyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/4bdb93f9052e8b9e015b734aca53248f.jpg', url: 'https://mst.dk/media/xena3rln/vejledende-udtalelse-om-affaldsbekendtgoerelsen-43-undtagelse-fra-saerskilt-indsamling.pdf', res: 'Miljøstyrelsen forklarer, hvordan en kommune kan søge undtagelse fra kravet om særskilt indsamling, og hvilke kriterier i affaldsdirektivet styrelsen vurderer ansøgningen efter.', long: 'Udtalelsen fra juni 2023 afløser en version fra marts 2021 og gælder affaldsbekendtgørelsens § 43. Kun kommunalbestyrelsen kan på baggrund af ny teknologi bede om undtagelse fra særskilt indsamling, og styrelsen er ikke forpligtet til at forelægge forslag fra virksomheder for ministeren. Ansøgningen vurderes efter de fire betingelser i affaldsdirektivets artikel 10, stk. 3, og Klimaplanens krav om sammenlignelig kvalitet og lavt spild. Betingelse a dækker ikke indsamling sammen med restaffald, og c og d anses for mindre relevante. Ministeren beslutter, og da bekendtgørelsen og affaldsplanen først skal ændres, tager det mindst 6 måneder.' },
      { id: 'NY021', title: 'Styrket sporbarhed og sortering af bygge- og anlægsaffald på genbrugspladser', org: 'Miljøministeriet', year: 2024, type: 'Rapport', temaer: ['Byggeaffald', 'Genbrugspladser', 'Sorteringsvejledninger'], img: 'img/f4ae7c0cb43fce6934fa210de2b9ac16.jpg', url: 'https://mim.dk/media/yzbk5jvw/samlerapport_styrket-sporbarhed-og-sortering-af-byggeaffald-paa-genbrugspladser_.pdf', res: 'Kortlægning af 342 genbrugspladser, der modtager bygge- og anlægsaffald. Store og bemandede pladser sorterer bedst, og rapporten foreslår en fælles sorteringsvejledning.', long: 'TRE Rådgivende Ingeniører, Danish Waste Solutions og Econet har for Miljøministeriet kortlagt, hvordan genbrugspladserne modtager bygge- og anlægsaffald. Kortlægningen dækker 342 pladser hos 57 selskaber og kommuner og bygger på internetresearch, interviews og spørgeskemaer. Pladserne har i snit 14,2 fraktioner til byggeaffald, og fraktionernes indhold varierer meget. Kun 12 % af selskaberne har en særskilt container til PCB-affald, og affald under ét ton kan afleveres uden screening. Anbefalingerne er genbrugsområder til byggematerialer, særskilt håndtering af risikofraktioner, rene fraktioner af beton og tegl og ingen modtagelse af asbest.' },
      { id: 'NY022', title: 'Bilag 1-3 til Styrket sporbarhed og sortering af bygge- og anlægsaffald på genbrugspladser', org: 'Miljøministeriet', year: 2024, type: 'Regneark', temaer: ['Genbrugspladser', 'Byggeaffald', 'Data, statistikker og nøgletal'], img: '', url: 'https://mim.dk/media/gjkpphz5/bilag-1-3-styrket-sporbarhed-og-sortering-af-byggeaffald-paa-genbrugspladser.xlsx', res: 'Regneark med tre bilag om byggeaffald på genbrugspladser. Hos 57 kommuner og selskaber sorteres byggeaffaldet i snit i 14,2 fraktioner, men kun 14 tager imod mursten til genbrug.', long: 'Regnearket rummer tre bilag. Bilag 1 lister genbrugspladser med affaldsselskab, kommune, antal containere, størrelse, åbningstider og bemanding. Bilag 2 gennemgår byggeaffaldsfraktionerne hos 57 kommuner og selskaber med i alt 342 pladser. I snit sorteres i 14,2 fraktioner, fra 7 til 19. Alle 57 har uforurenet træ, metal, affald til forbrænding og deponi, og 56 har gips. Et område til byggematerialer til genbrug findes hos 21, men det tal er ufuldstændigt. Bilaget viser også, hvor mange navne der bruges for samme fraktion, og Bilag 3 samler definitioner af, hvad der må komme i hver container.' },
      { id: 'NY023', title: 'Recycling potential of separately collected post-consumer textile waste', org: 'Miljøstyrelsen', year: 2024, type: 'Analyse', temaer: ['Tekstil', 'Reel genanvendelse', 'Afsætning og behandling'], img: 'img/537a19c8ef2e5d5b7b29f5818ae3f3ae.jpg', url: 'https://www2.mst.dk/Udgiv/publications/2024/06/978-87-7038-623-4.pdf', res: 'DTU Sustain har for Miljøstyrelsen beregnet, at kun 5.586 af de ca. 52.000 ton tøj, der potentielt havner i et særskilt genanvendelsesspor, egner sig til genanvendelse.', long: 'Analysen er lavet af DTU Sustain for Miljøstyrelsen som led i Tekstilaffaldspartnerskabet. Tøjforbruget i danske husholdninger i 2022 er opgjort til 98.935 ton og fulgt gennem en materialestrømsanalyse fordelt på ti tøjkategorier. Godt halvdelen kan potentielt indsamles i et andet spor til genanvendelse. Heraf er 34 % vådt eller forurenet, og kun 11.478 ton er rent, tørt og uegnet til genbrug. Efter finsortering kan 5.586 ton genanvendes, mens 3.298 ton nedcykles. Bukser, kjoler, skjorter og t-shirts har størst potentiale. Tallene er et optimalt scenarie, og der anbefales bl.a. klarere sorteringsvejledninger og at holde tekstilerne tørre.' },
      { id: 'NY024', title: 'Renholds- og omkostningsanalyse jf. Engangsplastdirektivets oprydningsansvar', org: 'Miljøstyrelsen', year: 2024, type: 'Analyse', temaer: ['Udvidet producentansvar', 'Økonomi', 'Data, statistikker og nøgletal'], img: 'img/611d828231f2f6f01b7c3818ef8e5fd1.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2024/01/978-87-7038-575-6.pdf', res: 'Analysen opgør, hvor meget affald otte typer engangsplast giver i det offentlige rum. Oprydningen koster ca. 150 mio. kr. om året, og cigaretfiltre er den største post.', long: 'Econet og Hold Danmark Rent har for Miljøstyrelsen opgjort mængder og renholdsudgifter for de produkter, som engangsplastdirektivet giver producenterne oprydningsansvar for. Data fra 15 kommuner bygger på tællinger af henkastet affald og analyser af affaldskurve, suppleret med interviews med kommuner og Vejdirektoratet og spørgeskemaer i Naturstyrelsen. Hvert år indsamles ca. 450 mio. stk. engangsplast på 1.400 tons, heraf 300 mio. cigaretfiltre. Renholdet koster ca. 357 mio. kr., hvoraf ca. 151 mio. kr. vedrører engangsplast, og kommunerne bærer ca. 334 mio. kr. Tallene skal indgå, når Miljøstyrelsen beregner producenternes gebyr.' },
      { id: 'NY025', title: 'Supplerende fordelingsnøgler 2024', org: 'Miljøstyrelsen', year: 2024, type: 'Analyse', temaer: ['Udvidet producentansvar', 'Genbrugspladser', 'Erhverv'], img: 'img/589d265b85768e58e0b542808a289dfa.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2024/11/Supplerende-fordelingsn%C3%B8gler-2024.pdf', res: 'Econet har for Miljøstyrelsen målt emballageandelen i bl.a. tekstil, træ, pap og plast fra husholdninger og erhverv. Pap fra genbrugspladser er 91 % emballage, tekstil under 1 %.', long: 'Rapporten fra Econet til Miljøstyrelsen supplerer fordelingsnøglerne i Miljøprojekt 2279, som skal bruges til kompensationen mellem de kollektive ordninger og kommuner eller private indsamlere under producentansvaret for emballage. Tekstil fra henteordninger blev målt på godt 1 ton fra fem midtjyske kommuner og indeholdt 0,61 % emballage. På 16 genbrugspladser i 15 kommuner udgjorde emballage 91 % af pappet, 74 % af EPS, 23 % af den hårde plast og 16 % af indendørstræet, mest træpaller. Hos 13 besøgte virksomheder var 73 % af træaffaldet emballage, og paller alene udgjorde 65 %. Ikke alle nøglerne skal bruges i den kommende bekendtgørelse.' },
      { id: 'NY026', title: 'Vejledning om modtagekontrol på affaldsforbrændingsanlæg', org: 'Miljøstyrelsen', year: 2024, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Erhverv'], img: 'img/b257b0d722e527141f1fec01e46114ef.jpg', url: 'https://www.retsinformation.dk/api/pdf/247683', res: 'Vejledningen forklarer, hvordan forbrændingsanlæg fra 2025 hver uge skal kontrollere mindst 5 % af læssene og afvise læs med for meget affald, der kan genanvendes.', long: 'Miljøstyrelsen udsendte vejledningen i december 2024 som fortolkning af affaldsbekendtgørelsens §§ 51-55, der trådte i kraft 1. januar 2025 efter klimaplanaftalen fra 2022. Anlæg, der kun brænder slam, klinisk risikoaffald eller farligt affald, er undtaget. Kontrollen er visuel og dokumenteres med kamera, fx ved udspredning på gulv eller kameraovervågning. Et læs afvises fysisk eller, når det ikke er muligt, administrativt. Begge dele indberettes til Miljøstyrelsen og fører som udgangspunkt til administrativt affaldstilsyn. Fra 1. juli 2025 afvises læs også, hvis erhvervsaffald i ikke-klare sække gør vurderingen umulig.' },
      { id: 'NY027', title: 'Erhvervsaffaldsanalyse 2025', org: 'Miljøstyrelsen', year: 2025, type: 'Analyse', temaer: ['Udvidet producentansvar', 'Erhverv', 'Analyser og undersøgelser'], img: 'img/e923e919910420bed54a63ec5a155a8f.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2026/02/978-87-7564-086-7.pdf', res: 'Analysen fastlægger, hvor stor en del af erhvervsaffaldet fra byggeri, sundhedsvæsen og landbrug der er emballage. Tallene bruges til kompensation under producentansvaret.', long: 'Econet har for Miljøstyrelsen besigtiget affaldet hos 45 virksomheder i byggeri, sundhedsvæsen og sociale foranstaltninger samt landbrug og skønnet emballageandelen fraktion for fraktion. Resultatet er fordelingsnøgler til emballagebekendtgørelsen, der fordeler omkostninger under producentansvaret for emballage, som blev indført 1. oktober 2025. Pap er næsten rent emballage i alle tre brancher (96-99 %), mens metal fra byggeri og landbrug har under 5 % emballage. På byggepladserne ender meget pap, plast og træ i restaffaldet, i landbruget især plast. Byggeledere efterlyser mere ens krav fra kommunerne.' },
      { id: 'NY028', title: 'Guide til affaldstilsyn', org: 'Miljøstyrelsen', year: 2025, type: 'Vejledning', temaer: ['Erhverv', 'Lovgivning og afgørelser'], img: 'img/13320969fe43d3bb6cff178c83eb37b2.jpg', url: 'https://mst.dk/media/zxnjb3pk/mst_guide-til-tilsynsmyndighed-om-affaldstilsyn_24april.pdf', res: 'Miljøstyrelsens guide hjælper tilsynsmyndigheder med at føre fysisk affaldstilsyn med virksomheder efter det styrkede affaldstilsyn fra 2025, fra forberedelse til håndhævelse.', long: 'Version 2.0 af guiden er fra april 2025 og er skrevet til kommuner og andre tilsynsmyndigheder. Fra 2025 står Miljøstyrelsen for alle administrative tilsyn og udpeger virksomheder til fysisk tilsyn ud fra en risikoscore baseret på data fra Affaldsdatasystemet (ADS) og CVR. Styrelsen fører selv tilsyn med affaldshåndteringsvirksomheder og har overtaget klassificeringen af affald. Guiden viser, hvordan ADS-data kan bruges i forberedelse og dialog, og hvordan håndhævelsen trappes op fra henstilling til påbud. Tilsynet skal være 100 % gebyrfinansieret, og resultatet skal meldes til Miljøstyrelsen senest en måned efter tilsynet.' },
      { id: 'NY029', title: 'Kortlægning af kommunale affaldsordninger for husholdningsaffald 2025', org: 'Miljøstyrelsen', year: 2025, type: 'Regneark', temaer: ['Hente- og bringeordninger', 'Data, statistikker og nøgletal'], img: '', url: 'https://mst.dk/media/xn2cnal3/kortlaegning-af-kommunale-ordninger-2025-1.xlsx', res: 'Regneark fra Miljøstyrelsen med status pr. 31. december 2024 for kommunernes henteordninger for tolv fraktioner. 91 kommuner havde alle ordninger, 7 manglede mindst én.', long: 'Miljøstyrelsens kortlægning viser for hver af de 98 kommuner, om der pr. 31. december 2024 var en henteordning for tolv fraktioner ved etageboliger, parcelhuse og sommerhuse. De syv kommuner, der manglede mindst én ordning, var Allerød, Gribskov, Guldborgsund, Køge, Lolland, Ringkøbing-Skjern og Samsø. Køge manglede syv fraktioner ved sommerhuse, og Guldborgsund og Lolland manglede plast og mad- og drikkekartoner ved etageboliger. Ordningerne er planlagt indført mellem 2. kvartal 2025 og 1. kvartal 2026. Et detaljeark viser for hver kommune og boligtype, hvilken beholderløsning der bruges, og hvordan storskrald og haveaffald hentes.' },
      { id: 'NY030', title: 'Circular AI: AI og Machine Learning til closed-loop genanvendelse af plastemballage', org: 'Miljøstyrelsen', year: 2025, type: 'Rapport', temaer: ['Teknologi', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/1abefa588ce2ca7c6b882b3ac0624982.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2025/03/978-87-7038-723-1.pdf', res: 'IHFood har i et MUDP-projekt udviklet et AI-kamerasystem med sorteringsrobot, der genkender typer af sorte kødbakker og fødevarekartoner, som NIR ikke kan skelne.', long: 'IHFood har med støtte fra MUDP i 2022-2024 udviklet et machine vision-system med kamera, neurale netværk og en flexpicker-robot, som er afprøvet hos ARC og brugt til billedoptagelse hos Damifo i Vojens. Projektets egne NIR-forsøg viste, at sort plast ikke kan skelnes med NIR. En ResNet-18-model genkendte 89-98 % af fem bakketyper i testdata fra ARC og 79-97 % af fire typer hos Damifo uden at være trænet på data derfra. Syreholdige og ikke-syreholdige kartoner blev adskilt med 83 og 96 % præcision. Den bedste sugekop greb 60 % af 100 sorte kødbakker, hvilket giver et teoretisk output på 129 tons plast om året pr. robot.' },
      { id: 'NY031', title: 'NewRetex: Digital sortering og processering af kasserede tekstiler', org: 'Miljøstyrelsen', year: 2025, type: 'Rapport', temaer: ['Tekstil', 'Teknologi', 'Afsætning og behandling'], img: 'img/73428c462d39e8af348ac08f538c0d26.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2025/08/978-87-7564-037-9.pdf', res: 'MUDP-slutrapport om NewRetex\' anlæg, der sorterer kasserede tekstiler med NIR-sensorer og farvegenkendelse. Sorteringen nåede op til 95 % renhed i nogle fraktioner.', long: 'NewRetex har med støtte fra MUDP udviklet og testet et anlæg til modtagelse, sortering og processering af tekstilaffald. NIR-algoritmen skelner mellem 20 materialesammensætninger, som udgør over 95 % af de genanvendelige affaldstekstiler, og giver svar på under 0,5 sekund. En ny metode til farvegenkendelse klarer også flerfarvede tekstiler. I de fleste kommunale leverancer var 15-40 % vådt og 15-35 % andet affald, mens 5-15 % kunne genbruges og 30-60 % genanvendes. Husstandsindsamlede tekstiler havde den bedste kvalitet. Det sorterede tekstil kan endnu ikke bruges til fiber til fiber-genanvendelse, fordi markedet kræver høj fiberkvalitet.' },
      { id: 'NY032', title: 'Webinar om producentgebyret i kommunerne', org: 'Miljøstyrelsen', year: 2025, type: 'Oplæg', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/123412261c25741999e5060fd2302a87.jpg', url: 'https://mst.dk/media/uj2fs52z/indledning-og-vejledning-fra-mst-om-fastsaettelse-af-producentgebyr-i-kommunerne.pdf', res: 'Slides fra Miljøstyrelsens webinar 25. februar 2025 om producentgebyret for emballage. De giver svar på kommunernes spørgsmål om, hvordan gebyrerne fastsættes og indberettes.', long: 'Webinaret 25. februar 2025 blev holdt af Miljøstyrelsen og Miljø- og Ligestillingsministeriet. Slidesættet beskriver de to skabeloner, som kommunerne hvert år skal sende til Miljøstyrelsen efter emballagebekendtgørelsen, og en tidslinje med frister frem til 2028. Resten er svar på spørgsmål. Producentgebyrerne kan fastsættes administrativt uden politisk behandling, og der gives ingen dispensation fra fristen 1. april 2025 for gebyrerne. Genbrugspladser skal have deres eget gebyr, og det samme gælder generel administration og oplysning. Kommunerne skal bruge fordelingsnøglerne i bilag 8, og storskrald er ikke omfattet af producentansvaret.' },
      { id: 'NY033', title: 'Kommunale affaldsgebyrer 2019-2025', org: 'Forsyningstilsynet', year: 2025, type: 'Analyse', temaer: ['Økonomi', 'Data, statistikker og nøgletal'], img: 'img/573ac1fb699bab3ce4dacb7fe1e3330c.jpg', url: 'https://forsyningstilsynet.dk/Media/638986196020186285/Rapport%20-%20Kommunale%20affaldsgebyrer%202019-2025.pdf', res: 'Forsyningstilsynets årlige opgørelse viser, at det gennemsnitlige affaldsgebyr steg 50 % for haveboliger og 60 % for etageboliger fra 2019 til 2025. Stigningen er nu aftaget.', long: 'Forsyningstilsynet overvåger hvert år de kommunale affaldsgebyrer og har her samlet gebyrerne for 2019-2025 og kommunernes budget- og regnskabstal for 2019-2024. I 2025 betalte en havebolig i gennemsnit 4.036 kr. og en etagebolig 3.050 kr. Den største stigning kom fra 2022 til 2023, mens gebyrerne kun steg 2,4-2,5 % fra 2024 til 2025. Udgiften pr. bolig til genanvendelige fraktioner steg fra 190 kr. i 2019 til 818 kr. i 2024. Udviklingen falder sammen med udrulningen af de 10 fraktioner, men tilsynet kan ikke entydigt fastslå årsagen, og sammenligninger mellem kommuner kræver store forbehold.' },
      { id: 'NY034', title: 'Analyse af overordnede modeller for prislofter over de kommunale affaldsgebyrer', org: 'Forsyningstilsynet', year: 2025, type: 'Analyse', temaer: ['Økonomi', 'Udbud og kravspecifikationer'], img: 'img/f36b37c211d03bb0c6ca8e99359c9a17.jpg', url: 'https://forsyningstilsynet.dk/Media/638979293408704847/Analyse%20af%20overordnede%20modeller%20for%20prislofter_04.11.25.pdf', res: 'Forsyningstilsynet vurderer modeller for et prisloft over kommunernes affaldsgebyrer for husholdninger. Ingen model er klart bedst, så valget afhænger af de politiske hensyn.', long: 'Forsyningstilsynet har lavet analysen for klima-, energi- og forsyningsministeren. Den beskriver to grundmodeller, hvor kommunens gebyr sammenlignes med andre kommuners (model 1A-1C) eller med egne historiske gebyrer (model 2). Vægter man lave administrationsomkostninger og gennemsigtighed, peger tilsynet på 1A, 1B eller 2, mens 1C eller 1C kombineret med 2 giver størst effekt på priserne. Udbud (model 3) er særligt oplagt, da mange kommuner allerede udbyder store dele af opgaven. Tilsynet skønner at skulle bruge 4 til over 10 årsværk. Før der er ens regnskabsregler og et fælles udgangspunkt, anbefales et indikativt prisloft uden sanktioner.' },
      { id: 'NY035', title: 'Kommunale affaldsgebyrer. Fase 2: Forslag til ændring af nugældende regler', org: 'Forsyningstilsynet', year: 2024, type: 'Rapport', temaer: ['Økonomi', 'Lovgivning og afgørelser', 'Genbrugspladser'], img: 'img/5d0912fb1518e2927f2215388b33d0b7.jpg', url: 'https://forsyningstilsynet.dk/Media/638730497463802234/Affaldsgebyrprojektet%20del%202.PDF', res: 'BDO foreslår for Forsyningstilsynet, at affaldsgebyrer fremover bygger på et reguleringsregnskab og registrering pr. hovedfraktion, så gebyrerne bliver ensartede og gennemsigtige.', long: 'BDO har skrevet anden fase af Forsyningstilsynets gebyrprojekt om husholdningernes lovpligtige ordninger. Hovedforslaget er at adskille ordning og gebyr, så omkostninger registreres på hovedfraktioner som mad, papir, plast og restaffald, og hver fraktion skal hvile i sig selv. Det kommunale budget- og regnskabssystem foreslås erstattet af et reguleringsregnskab efter årsregnskabslovens principper med revisorerklæring. Over- og underdækning foreslås afviklet i det næstfølgende regnskabsår, mens genbrugspladser og storskrald bør beholde egne gebyrer. Som bilag følger kontoplan, konteringsvejledning, revisionsinstruks og gebyrberegningsmodel.' },
      { id: 'NY036', title: 'Udkast til gebyrberegningsmodel for kommunale affaldsgebyrer', org: 'Forsyningstilsynet', year: 2024, type: 'Regneark', temaer: ['Økonomi', 'Hente- og bringeordninger'], img: 'img/6da57f157894391f0ad559c05cf98184.jpg', url: 'https://forsyningstilsynet.dk/Media/638730501206521441/Udkast%20gebyrberegningsmodel%20-%20kommunale%20affaldsgebyrer.PDF', res: 'Udkast til en regnearksmodel, hvor kommunen fordeler affaldsudgifterne på fraktioner og beregner gebyr pr. beholder i henteordninger og pr. husstand for bringeordninger.', long: 'Udkastet er dateret 5. juli 2024 og er en PDF-udskrift af et regneark med faner for mængder, vægtninger, enhedspriser og gebyrer. Udgangspunktet er, at alle udgifter er fordelt på fraktioner i bogføringen, at indtægter fra producenter og materialesalg modregnes, og at over- og underdækning indgår. I henteordninger deles omkostningen for hver fraktion med de tømte liter pr. år, så man får en pris pr. volumenliter og et årligt gebyr pr. beholdertype. Bringeordninger på genbrugspladsen opgøres i tons og bliver til et gennemsnitsgebyr pr. husstand, som kan vægtes efter boligtype. Modellen er udfyldt med eksempeltal.' },
      { id: 'NY037', title: 'Konkurrencefremmende tiltag ved udbud af affaldsforbrænding', org: 'Forsyningstilsynet', year: 2024, type: 'Analyse', temaer: ['Udbud og kravspecifikationer', 'Afsætning og behandling', 'Lovgivning og afgørelser'], img: 'img/8aad5322f0d51983a7d76ac303c876b1.jpg', url: 'https://forsyningstilsynet.dk/Media/638511863599796007/Baggrundsrapport%20-%20Konkurrencefremmende%20tiltag%20ved%20udbud%20af%20affaldsforbr%C3%A6nding.pdf', res: 'Forsyningstilsynets analyse og syv tiltag for mere konkurrence, når kommuner udbyder affaldsforbrænding, fx delkontrakter på højst 20.000 ton om året og kontrakter på højst 4 år.', long: 'Rapporten har to dele. Delrapport 1 fra februar 2024 er skrevet af NIRAS med Viltoft og Københavns Universitet og beskriver markedet for forbrænding af husholdningsaffald, transport, miljø- og klimapåvirkning, udbudsregler og økonomisk teori. Den bygger på 19 udbud fra 22 kommuner og interview med 13 aktører. Udbud over 50.000 ton fik kun én tilbudsgiver. I Delrapport 2 fra maj 2024 opstiller Forsyningstilsynet syv tiltag, bl.a. markedsdialog før udbuddet, delkontrakter på højst 20.000 ton om året, kontrakter på højst 4 år og omkostningsægte transporttillæg. Afviger en kommune, skal den indberette en saglig begrundelse.' },
      { id: 'NY038', title: 'Vejledning om brug af de konkurrencefremmende tiltag ved udbud af affaldsforbrænding', org: 'Forsyningstilsynet', year: 2024, type: 'Vejledning', temaer: ['Udbud og kravspecifikationer', 'Afsætning og behandling', 'Lovgivning og afgørelser'], img: 'img/8750a9d555683863d4342457b5ded924.jpg', url: 'https://retsinformation.dk/api/pdf/244799', res: 'Forsyningstilsynets vejledning til kommuner, der udbyder affaldsforbrænding. Udbud bør deles i delkontrakter på højst 20.000 ton om året, og kontrakter bør højst vare 4 år.', long: 'Vejledningen er Forsyningstilsynets materiale efter miljøbeskyttelseslovens § 45 f og bygger på to delrapporter lavet med NIRAS. Den skelner mellem anbefalinger og konkurrencefremmende tiltag, som kommunen bør følge eller indberette en saglig begrundelse for at fravige. Tiltagene omfatter markedsdialog med forudgående screening, åbenhed om tiltag mod interessekonflikter, delkontrakter på højst 20.000 ton om året og kontrakter på højst 4 år, som godt 92 % af de analyserede udbud lå inden for. Transporttillæg bør være omkostningsægte, og vægtes miljø, bør det ske som samfundsøkonomiske skadesomkostninger, i regneeksemplet 15 kr. pr. ton.' },
      { id: 'NY039', title: 'Vejledning om fastsættelse af markedspriser for kommunal indsamling af visse typer erhvervsaffald', org: 'Forsyningstilsynet', year: 2025, type: 'Vejledning', temaer: ['Erhverv', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/06d1ef65a706c52e99c6aaa36023af03.jpg', url: 'https://forsyningstilsynet.dk/Media/638960390867698507/Vejledning%20-Markedspriser.pdf', res: 'Forsyningstilsynets vejledning til kommuner, der tilbyder virksomheder indsamling af affald. Prisen skal svare til markedsprisen og mindst dække alle omkostninger ved ordningen.', long: 'Vejledningen fra 10. september 2025 afløser en vejledning fra 2023. Den gennemgår, hvornår kommunen skal opkræve markedspris, fx for genanvendeligt erhvervsaffald på øer uden fast broforbindelse og for forbrændingsegnet affald fra kommunens egne institutioner, som regnes som erhvervsaffald. Prisen kan sættes ud fra en markedsundersøgelse eller som omkostninger plus et overskudstillæg, hvor tilsynet som udgangspunkt ikke efterprøver tillæg på 5-15 %. Hver ordning skal have sit eget regnskab, og overskuddet skal føres tilbage til det skattefinansierede område. Tre afgørelser med påbud fra 2024 og 2025 er gengivet.' },
      { id: 'NY040', title: 'BEATE 2022: Benchmarking af deponeringsanlæg', org: 'Forsyningstilsynet', year: 2024, type: 'Statistik', temaer: ['Data, statistikker og nøgletal', 'Afsætning og behandling', 'Økonomi'], img: 'img/56b8ef503a52e2368dea5f272bff9a77.jpg', url: 'https://forsyningstilsynet.dk/Media/638657137082947800/BEATE%202022%20Deponering.pdf', res: 'Forsyningstilsynets benchmarking af 40 danske deponeringsanlæg for 2022. Mængden af deponeret affald uden jord faldt ca. 7 % fra 2021, og jordmængderne svinger meget fra år til år.', long: 'Forsyningstilsynet har benchmarket økonomi og miljø på de 40 deponeringsanlæg, som skal deltage efter deponeringsbekendtgørelsen. 37 af dem er offentligt ejede. Data er indsamlet i efteråret 2023, kvalitetssikret af Viegand Maagøe og vist for 2013-2022 i faste 2022-priser. I 2022 blev der endeligt deponeret 773.000 ton inklusive jord, heraf 290.000 ton blandet affald. Kapaciteten til forurenet jord i København er brugt op, så 1,9 mio. ton blev mellemdeponeret. Uden afgifter og sikkerhedsstillelse koster blandet og mineralsk affald ca. 454 kr. pr. ton og ren jord 28 kr. Perkolat og gas udgør i gennemsnit 21 % af driftsomkostningerne.' },
      { id: 'NY041', title: 'Vurdering af KLs plan for nedlukning af de mindst effektive affaldsforbrændingsanlæg', org: 'Forsyningstilsynet', year: 2021, type: 'Analyse', temaer: ['Afsætning og behandling', 'Analyser og undersøgelser'], img: 'img/2c9a85a07f469ec36f6be47e05915955.jpg', url: 'https://forsyningstilsynet.dk/Media/638225141210498706/fsts-vurdering-af-kl-planen-2021-02-12.pdf', res: 'Forsyningstilsynet kan ikke godkende KLs plan om at lukke 10 forbrændingsanlæg frem mod 2030, fordi det ikke er dokumenteret, at netop de 10 er de mindst effektive.', long: 'Forsyningstilsynet vurderede i februar 2021 KLs plan for at tilpasse kapaciteten til affaldsenergi frem mod 2030, som klimaplanen for affaldssektoren fra juni 2020 kræver. Planen bygger på en analyse fra Ea Energianalyse af 23 anlæg på ovnlinjeniveau og udpeger 10 anlæg, der skal lukke, så kapaciteten falder 30 %. Tilsynet finder de fleste metodevalg rimelige, men peger på datafejl, fx lønomkostninger talt dobbelt på ét anlæg, og på udokumenterede antagelser om bl.a. transportomkostninger og lukning af MEC. Ti følsomhedsberegninger fra Ea tyder på, at lukkelisten ændrer sig, når forholdene rettes, og tilsynet kan derfor ikke godkende planen.' },
      { id: 'NY042', title: 'Information om dispensation til kommunal behandling af affald egnet til materialenyttiggørelse', org: 'Forsyningstilsynet', year: 2024, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Udbud og kravspecifikationer'], img: 'img/f6382e9e456408b1e2eb9e0faac29cf7.jpg', url: 'https://forsyningstilsynet.dk/Media/638404022880096827/2024%20information-om-dispensation-til-kommunal-behandling-af-affald-egnet-til-materialenyttiggoerelse-omfattet-af-en-kommunal-affaldsordning.pdf', res: 'Forsyningstilsynet forklarer, hvornår en kommune kan få dispensation til at deltage i behandling af genanvendeligt affald, fordi et udbud ikke gav antagelige tilbud.', long: 'Materialet er 2. udgave fra 9. januar 2024 og beskriver dispensationsordningen i affaldsaktørbekendtgørelsens kapitel 10, som Forsyningstilsynet administrerer. Kommunen skal have udbudt opgaven efter udbudsloven uden at modtage antagelige tilbud, og udbuddet skal bygge på en indledende markedsundersøgelse. Efter en dispensation skal aktiviteten ligge i et særskilt selskab på kommercielle vilkår, hvor private ejer mindst 25 % af kapital og stemmer, og opgaven skal genudbydes på samme vilkår. Tilsynet ser ordningen som særligt relevant, når overgangsordningen ophører i 2027. Materialet er ikke retligt bindende.' },
      { id: 'NY043', title: 'Information om anmeldelse om fortsat ejerskab af automatiserede sorteringsanlæg', org: 'Forsyningstilsynet', year: 2022, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/6b1f6685ae54ba83e600716a7f5670d6.jpg', url: 'https://forsyningstilsynet.dk/Media/638193904226076385/info-om-anmeldelse-automatiserede-sorteringsanlaeg.pdf', res: 'Forsyningstilsynets vejledning til kommuner, der vil bruge overgangsordningen og fortsat eje et automatiseret sorteringsanlæg i fem år efter forbuddet fra 1. juli 2022.', long: 'Informationsmaterialet (3. udgave, 29. september 2022) forklarer, hvordan kommuner anmelder deltagelse i overgangsordningen efter miljøbeskyttelseslovens § 49 g, stk. 2. Fristen var 30. september 2022. Kommunen skal angive anlægget og anmelderens CVR-nummer og oplyse, om anlægget var godkendt og i drift senest 1. juli 2022, eller om der inden da var foretaget væsentlige irreversible investeringer. Optisk posesortering er omfattet af forbuddet, mens sortering med en gravko betjent af en person regnes for manuel. Tilsynet godkender ikke anmeldelsen, men kan tage sagen op senere, og materialet er ikke retligt bindende.' },
      { id: 'NY044', title: 'Anlæg, der har anmeldt deltagelse på overgangsordningerne, 22. udgave', org: 'Forsyningstilsynet', year: 2026, type: 'Faktaark', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/fa54190393d6e5e7e56c701aee54b8b0.jpg', url: 'https://forsyningstilsynet.dk/Media/639198915275069605/Liste%20over%20anmeldelser%20p%C3%A5%20overgangsordning%2015.07.26.pdf', res: 'Forsyningstilsynets liste over 16 kommunalt ejede anlæg, der har anmeldt sig til overgangsordningen og derfor midlertidigt kan fortsætte med at behandle genanvendeligt affald.', long: 'Siden 1. juli 2022 må kommuner som udgangspunkt ikke behandle affald egnet til materialenyttiggørelse eller eje automatiserede sorteringsanlæg. Med overgangsordningen i miljøbeskyttelseslovens § 49 g kan anmeldte anlæg dog fortsætte i fem år. Den 22. udgave fra 15. juli 2026 rummer 16 anlæg hos ni ejere, bl.a. fire i Sønderborg Kommune og fire, som Holstebro, Lemvig, Skive og Struer ejer sammen. De fleste behandler have- og parkaffald, mens andre knuser beton og tegl eller sorterer træ og byggeaffald. Tilsynet godkender ikke anmeldelserne, men kan tage en sag op efter klage eller af egen drift.' },
      { id: 'NY045', title: 'Vejledende udtalelse om miljøbeskyttelseslovens § 49 b, stk. 1', org: 'Energistyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/e8975bda4f4b5a9e6b8894c91549d529.jpg', url: 'https://ens.dk/media/24/download', res: 'Energistyrelsen forklarer forbuddet mod, at kommuner behandler affald egnet til materialenyttiggørelse, og hvilke undtagelser der lader kommunen fortsætte visse aktiviteter.', long: 'Energistyrelsens vejledende udtalelse fra december 2023 fortolker forbuddet i miljøbeskyttelseslovens § 49 b, der trådte i kraft 1. juli 2022. Kommunen må hverken behandle affald egnet til materialenyttiggørelse eller eje anlæg, der gør det. Loven undtager vand- og spildevandsforsyning, affald fra øer uden fast broforbindelse og jord. Ved omlastning må kommunen af- og pålæsse, oplagre, fjerne grove fejlsorteringer, presse, ballere og komprimere EPS, men som udgangspunkt ikke knuse eller neddele andet affald. Kommunen må også behandle slagge fra egne forbrændingsanlæg og købe forbehandlet affald til egne bygge- og anlægsprojekter.' },
      { id: 'NY046', title: 'Vejledende udtalelse om miljøbeskyttelseslovens § 49 g', org: 'Energistyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/b6c72836a71c1bd4ddd46462578ec922.jpg', url: 'https://ens.dk/media/25/download', res: 'Energistyrelsens fortolkning af overgangsordningen, der frem til 1. juli 2027 lader kommuner deltage i behandling af genanvendeligt affald og eje sorteringsanlæg på visse vilkår.', long: 'Energistyrelsen gav 1. december 2023 sin vejledende fortolkning af miljøbeskyttelseslovens § 49 g. Som udgangspunkt må kommuner hverken behandle genanvendeligt affald eller eje automatiserede sorteringsanlæg. Overgangsordningen omfatter behandlingsanlæg, der var i drift eller havde fået væsentlige irreversible investeringer senest 16. juni 2020, og sorteringsanlæg med frist 1. juli 2022. Kommunen må kun vedligeholde anlæggene, ikke reinvestere. Aktiviteterne skal udskilles i aktie- eller anpartsselskaber 1. januar 2024 og anmeldes til Forsyningstilsynet senest 31. marts 2024. Ordningen ophører 1. juli 2027, hvor selskaberne skal afhændes.' },
      { id: 'NY047', title: 'Step-by-step guide til oprettelse af kommunale regulativer i NSTAR', org: 'Energistyrelsen', year: 2022, type: 'Vejledning', temaer: ['Affaldsplaner/regulativer og strategi', 'Lovgivning og afgørelser'], img: 'img/8f7a8d1c309d9fe93c451408e17d1b2d.jpg', url: 'https://ens.dk/media/13/download', res: 'Guide i otte trin til at oprette og udgive kommunens affaldsregulativ i den nationale regulativdatabase NSTAR, med svar på ni almindelige problemer i systemet.', long: 'Guiden viser, hvordan kommunen opretter sit regulativ i NSTAR ud fra standardregulativet i affaldsaktørbekendtgørelsen. Hver paragraf skal gemmes for sig, egne paragraffer kan kun tilføjes under frivillige ordninger, og stamdata kan først udfyldes, når alle obligatoriske felter er udfyldt. Regulativet træder tidligst i kraft dagen efter offentliggørelsen i NSTAR. Fejlafsnittet dækker bl.a. tekst kopieret fra Word. Har kommunen dispensation for en ordning, kan feltet udfyldes med en henvisning, fx fra madaffald (§ 10) til restaffald (§ 19). Kommunen bør sammenligne udgaven i NSTAR med den, der skal godkendes.' },
      { id: 'NY048', title: 'Monitorering af affaldsforbrændingskapaciteten. Afrapportering 2025', org: 'Energistyrelsen', year: 2025, type: 'Rapport', temaer: ['Afsætning og behandling', 'Data, statistikker og nøgletal', 'Klima'], img: 'img/399897e9e251cfc75d5e1733c6a6812f.jpg', url: 'https://ens.dk/media/7297/download', res: 'Energistyrelsens monitorering viser, at forbrændingsanlæggene i 2023 havde en funktionel kapacitet på 3,6 mio. ton og brændte godt 3 mio. ton dansk affald og 0,5 mio. ton import.', long: 'Monitoreringen følger op på klimaplanen fra 2020, hvor forbrændingskapaciteten skal ned til de danske affaldsmængder frem mod 2030. Den bygger på data fra Affaldsdatasystemet for 2020-2023 og på kapacitetsdata fra Miljøstyrelsen og anlæggene selv. Fra 2020 til 2023 faldt mængden af dansk affald på de almindelige anlæg med ca. 6 % til ca. 3 mio. ton, mens importen steg 37 % og udgjorde 15,1 % i 2023. Den miljøgodkendte kapacitet var ca. 4,4 mio. ton, og fossilt affald udgjorde i snit 44 %. Fremskrivningen venter, at kapaciteten falder til ca. 3 mio. ton i 2028 og derefter svarer nogenlunde til de danske mængder.' },
      { id: 'NY049', title: 'Analyse af kommunal affaldshåndtering', org: 'Energistyrelsen', year: 2021, type: 'Analyse', temaer: ['Økonomi', 'Udbud og kravspecifikationer', 'Analyser og undersøgelser'], img: 'img/1a28cc5a75998a660d60c357b72fdbc4.jpg', url: 'https://ens.dk/sites/ens.dk/files/Affald/deloitte_analyse_af_kommunal_affaldshaantering.pdf', res: 'Deloittes analyse for Energistyrelsen af kommunernes udgifter og gebyrer for husholdningsaffald. Den anslår et effektiviseringspotentiale på 4-10 %, eller 225-600 mio. kr. om året.', long: 'Deloitte lavede analysen for Energistyrelsen fra september 2020 til marts 2021 som led i arbejdet med Klimaplanen for en grøn affaldssektor. Den bygger på en spørgeskemaundersøgelse og interviews samt registerdata fra bl.a. kommunale regnskaber og Affaldsviden.dk. I 2019 brugte kommunerne ca. 6,1 mia. kr. på husholdningsaffald uden forbrænding, heraf 1,9 mia. kr. på genbrugsstationer. Ordningerne kostede i snit 1.621 kr. pr. husstand, og flere fraktioner i henteordning og hyppigere tømning giver højere omkostninger. Potentialet svarer til 80-220 kr. pr. husstand, og rapporten vurderer ti tiltag, bl.a. benchmarking af gebyrer og udbudspligt.' },
      { id: 'NY050', title: 'Opfølgende aftale om Klimaplan for en grøn affaldssektor og cirkulær økonomi', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2022, type: 'Strategi', temaer: ['Økonomi', 'Erhverv', 'Tekstil'], img: 'img/d223265c07c1105f20711953ac52fa1a.jpg', url: 'https://www.kefm.dk/Media/639189371794810107/Aftaletekst_ofoelgning_paa_aftale_om_klimaplan_for_en_groen_affaldssektor.pdf', res: 'Politisk aftale fra 30. august 2022, der sætter fristen for husstandsnær indsamling af tekstilaffald til 1. juli 2023 og lægger op til et prisloft på husholdningernes affaldsgebyr.', long: 'Aftalen mellem regeringen og seks partier følger op på Klimaplan for en grøn affaldssektor og cirkulær økonomi fra juni 2020. Kommunerne skal indsamle tekstilaffald særskilt ved husstanden fra 1. juli 2023. Fra 2025 overtager Miljøstyrelsen klassificering af affald og dele af affaldstilsynet, mens kommunerne fortsat fører fysisk tilsyn med ca. 400.000 virksomheder. Tilsynsfrekvensen bliver 1:15 administrativt og 1:75 fysisk og stiger efter planen i 2027 til 1:3 og 1:15. Forsyningstilsynet skal fastsætte et prisloft over husholdningernes affaldsgebyrer, som ifølge regeringen kan give effektiviseringer på mindst 80 kr. i snit (2021-priser).' },
      { id: 'NY051', title: 'Aftale om udvidet producentansvar for emballage og engangsplastprodukter', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2022, type: 'Strategi', temaer: ['Udvidet producentansvar', 'Økonomi'], img: 'img/ed2d1734fca44e0d8db18e27ccb30103.jpg', url: 'https://www.kefm.dk/Media/639189372943922511/Aftale_om_udvidet_producentansvar_for_emballage_og_engangsprodukter.pdf', res: 'Den politiske aftale fra 30. august 2022 lægger rammerne for producentansvar for emballage fra 2025. Kommunerne indsamler fortsat, men producenterne betaler for håndteringen.', long: 'Regeringen og syv partier aftalte at indføre udvidet producentansvar for emballage og visse engangsplastprodukter fra 2025. Ifølge aftalen sorterer borgerne fortsat i materialefraktioner, og kommunerne indsamler, men de tørre fraktioner overdrages til kollektive ordninger. Producenterne skal dække kommunernes udgifter til indsamling af husholdningernes emballageaffald ud fra et serviceniveau, som kommuner og kollektive ordninger forhandler. Producenternes betaling skal miljøgradueres, og erhvervsaffald forbliver på det private marked. Aftalen skønner, at 1.504 mio. kr. i 2025 flyttes fra husholdningernes gebyrer til producenterne.' },
      { id: 'NY052', title: 'Handlingsplan for cirkulær økonomi', org: 'Miljøministeriet', year: 2021, type: 'Strategi', temaer: ['Affaldsplaner/regulativer og strategi', 'Cirkulær økonomi', 'Klima'], img: 'img/b6f3d6d0e78e90dbab5df098770a3828.jpg', url: 'https://www.kefm.dk/Media/639189398314246691/Handlingsplan%20for%20cirkulaer%20oekonomi.pdf', res: 'Danmarks nationale affaldsplan fra juli 2021 med 129 initiativer for mindre affald og mere genanvendelse frem mod 2032. Visionen er en klimaneutral affaldssektor i 2030.', long: 'Miljøministeriets plan er Danmarks nationale plan for forebyggelse og håndtering af affald 2020-2032 og erstatter planerne Danmark uden affald fra 2014 og 2015. Rygraden er aftalen om Klimaplan for en grøn affaldssektor og cirkulær økonomi fra juni 2020. Blandt initiativerne er ens indsamling af ti affaldstyper tæt ved husstanden, udbud af alt genanvendeligt affald, mindre forbrændingskapacitet og krav om mindst 60 % reel genanvendelse af plastikaffald fra husholdninger. I 2019 blev 44 % af det husholdningslignende affald genanvendt. Regeringen venter at nå EU-målene på 55 % i 2025 og 60 % i 2030, mens målet for 2035 kræver nye initiativer.' },
      { id: 'NY053', title: 'Aftale om langsigtede rammevilkår for CO2-fangst i forsyningssektoren', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2024, type: 'Strategi', temaer: ['Klima', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/d7418fbfdc52cd6584323b85e16366c6.jpg', url: 'https://www.kefm.dk/Media/638429086843948317/Aftale%20om%20langsigtede%20rammevilk%C3%A5r%20for%20CO2-fangst%20i%20forsyningssektoren%20(002).pdf', res: 'Politisk aftale fra februar 2024, der skal fjerne regulatoriske barrierer for CO2-fangst på varmeværker og affaldsforbrændingsanlæg, så de kan byde på CCS-udbuddene.', long: 'Regeringen og syv andre partier indgik stemmeaftalen 7. februar 2024. Forsyningssektoren, herunder affaldsforbrænding, står for ca. to tredjedele af det danske potentiale for CO2-fangst. Partierne vil kræve, at fangst sker selskabsmæssigt adskilt fra fjernvarmenettet, og at der føres særskilte regnskaber under tilsyn af Forsyningstilsynet, hvis fangst og varmeproduktion ligger i samme selskab. Sparede afgifter og kvoter skal fortsat kunne opkræves i varmeprisen og gå til fangsten. Kommunerne skal kunne bære risiko uanset anlæggets størrelse og eje lokale rørledninger, og de må sælge klimakreditter. Aftalen gennemføres ved ny lovgivning.' },
      { id: 'NY054', title: 'Klimastatus og -fremskrivning 2026. Affaldsforbrænding. Forudsætningsnotat', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2026, type: 'Notat', temaer: ['Klima', 'Afsætning og behandling', 'Data, statistikker og nøgletal'], img: 'img/ad8917362f04d70e0f1fdaca8d4a522a.jpg', url: 'https://www.kefm.dk/Media/639141685503421955/11.%20KF26%20Forudstningsnotat%20affaldsforbrnding.pdf', res: 'Forudsætningsnotat til Klimastatus og -fremskrivning 2026 om affaldsforbrænding. Dansk forbrændingsegnet affald skønnes nu ca. 12 % fossilt, 8 procentpoint under forrige skøn.', long: 'Notatet fra maj 2026 beskriver, hvordan Klimastatus og -fremskrivning 2026 regner med kapacitet, affaldsmængder, brændværdi og emissionsfaktorer for affaldsforbrænding. De danske mængder bygger nu på Miljøstyrelsens Affaldsfremskrivning 2025 med data til 2023. De skønnes lavere end før i 2024-2033 og stiger derefter. Anlæggene antages at brænde alt dansk affald og fylde op med import til ca. 490 kr. pr. ton, og importaffaldet regnes som ca. 35 % fossilt. AffaldPlus Slagelse, BOFA, Svendborg Kraftvarme og Aars Fjernvarme antages at lukke som planlagt. For 2024 regnes med 93,5 ton CO2 pr. TJ indfyret affald, heraf 46,1 ton fossilt.' },
      { id: 'NY055', title: 'Beretning om særligt forurenende virksomheder', org: 'Rigsrevisionen', year: 2025, type: 'Evaluering', temaer: ['Afsætning og behandling', 'Lovgivning og afgørelser', 'Analyser og undersøgelser'], img: 'img/a94d65334d36a4bd89b9406580d3b7b1.jpg', url: 'https://cdn.rigsrevisionen.dk/rigsrevisionen/Media/639007868830320260/SR0625.pdf', res: 'Rigsrevisionen kritiserer Miljøstyrelsens godkendelser af og tilsyn med ca. 400 særligt forurenende virksomheder. 12 af 24 store affaldsforbrændingsanlæg mangler EU\'s kviksølvkrav.', long: 'Beretningen fra december 2025 undersøger Miljøstyrelsens miljøgodkendelser, revurderinger og tilsyn i 2020-2024 ud fra data fra Digital MiljøAdministration og sagsgennemgange. For 76 % af virksomhederne er reglen om revurdering mindst hvert 10. år ikke overholdt, og for 73 % er EU-krav ikke indført inden for fristen på 4 år. Kun 8 af 24 affaldsforbrændingsanlæg blev revurderet før december 2023, og 11 af de 12 revurderede fik den højest tilladte kviksølvgrænse på 20 mikrogram. Halvdelen af virksomhederne får ikke det lovpligtige tilsyn, og 244 uafsluttede sager havde i snit ventet 700 dage. Statsrevisorerne kritiserer forvaltningen skarpt.' },
      { id: 'NY056', title: 'Høringsnotat: Emballagebekendtgørelsen og pantbekendtgørelsen', org: 'Energistyrelsen', year: 2026, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Erhverv'], img: 'img/a5940cb1986e7369accee48f48297697.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/1859b501-d007-4e4b-8509-24d21a67ec37/H%C3%B8ringsnotat%20-%20Emballage%20og%20pant.pdf', res: 'Energistyrelsens høringsnotat gennemgår 19 høringssvar til de nye regler for emballage og pant. Garantien skal fremover også kunne dække kommunernes indsamlingsgebyrer.', long: 'Energistyrelsen svarer på 19 høringssvar til udkast til emballage- og pantbekendtgørelsen, som var i høring fra 18. februar til 11. marts 2026. Reglerne skal supplere EU\'s emballageforordning, der gælder fra 12. august 2026. Producentansvarsorganisationer og erhvervsorganisationer var imod at udvide garantien, mens KL og Københavns Kommune bakkede op. Styrelsen fastholder, at garantien kan dække kommunernes indsamlingsgebyrer og kompensation for erhvervsemballageaffald, men garantiens størrelse ændres ikke. Forslaget om bagatelgrænse og slutopgørelse er taget ud, og kravet om returprocent for genbrugsemballage udgår.' },
      { id: 'NY057', title: 'Affaldssortering i 10 fraktioner - en status', org: 'Brancheforeningen Cirkulær', year: 2023, type: 'Faktaark', temaer: ['Hente- og bringeordninger', 'Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/ffc3c9cf1d907e39c04b38230bdbf578.jpg', url: 'https://cirkulaer.dk/files/media/document/folder-sortering10fraktioner-feb2023.pdf', res: 'Faktasamling fra Dansk Affaldsforening om, hvor langt kommunerne var med de 10 husstandsfraktioner i februar 2023, med mængder fra 2020 og typiske problemer for hver fraktion.', long: 'Dansk Affaldsforening, i dag Brancheforeningen Cirkulær, gennemgår de ti fraktioner, som en række af Folketingets partier i 2020 besluttede, at alle danskere skal sortere hjemme. For hver fraktion beskrives, hvor affaldet ender, og hvad der giver problemer, sammen med den indsamlede mængde i 2020, fx 172.000 tons madaffald, 138.000 tons papir og 1.037.000 tons restaffald, men kun 4.000 tons tekstil. Afsætningspriserne spænder fra en indtægt på 1.000 kr. til en udgift på 5.000 kr. pr. ton, og indsamlingen står for ca. 70 pct. af gebyret. Det meste affald afleveres på genbrugspladserne, ca. 2,9 mio. tons mod 1,7 mio. tons i henteordningerne.' },
      { id: 'NY058', title: 'Vejledning til dokumentation af forbehandling og bioforgasning af madaffald', org: 'Brancheforeningen Cirkulær og ARI', year: 2024, type: 'Vejledning', temaer: ['Afsætning og behandling', 'Udbud og kravspecifikationer', 'Reel genanvendelse'], img: 'img/85e7b591f84e9afcfc5c34ae6683f5db.jpg', url: 'https://cirkulaer.dk/files/media/document/Vejledende%20retningslinjer-%20dokumentation-%20genanvendelse-madaffald.pdf', res: 'Vejledning fra Cirkulær og ARI med forslag til, hvilken dokumentation kommuner og affaldsselskaber kan kræve af dem, der forbehandler og bioforgasser madaffald.', long: 'En arbejdsgruppe med folk fra bl.a. Vestforbrænding, Marius Pedersen, Gemidan og flere kommuner har skrevet vejledningen, som kan bruges, når kommuner og affaldsselskaber laver udbudsmateriale. Den foreslår, at behandleren leverer et flowdiagram ved tilbudsgivningen og løbende fremlægger en massebalance for indvejet madaffald, procesvand, pulp og rejekt. Tabet af nedbrydeligt organisk stof i rejektet kan opgøres med en tilnærmet metode baseret på VS-analyser. I en ETV-test gik 5-6,5 % tabt med større organisk materiale og ca. 1 % med vand og overflader. Metantabet fra biogasanlægget bør oplyses, mens fosfor ikke behøver særskilt rapportering.' },
      { id: 'NY059', title: 'Harmonising waste labels on products and waste receptacles to guide citizen waste sorting', org: 'EUpicto', year: 2024, type: 'Oplæg', temaer: ['Sorteringsvejledninger', 'Kommunikation', 'Sorteringskvalitet'], img: 'img/abf6086b1b9029d9f1da67d2c4fc386b.jpg', url: 'https://cirkulaer.dk/files/media/document/Harmonising%20waste%20labels_bro_160424_final.pdf', res: 'Nordisk oplæg til EU om ens affaldspiktogrammer på emballage og affaldsbeholdere. Enkle piktogrammer hjælper borgerne med at sortere, viser bl.a. forsøg i København og Stockholm.', long: 'Oplægget er skrevet af bro Kommunikation for EUpicto, hvor organisationer fra Danmark, Sverige, Island og Finland samarbejder. Det er input til EU-Kommissionens forslag om mærkning af emballage og anbefaler ud fra adfærdsforskning enkle mærker efter nordisk model og ens mærker på emballage og beholdere. I et forsøg i 21 københavnske etageejendomme faldt restaffaldet med 15,7 % i gruppen med enkle piktogramskilte, og i Stockholm gav piktogrammer på beholderne 11,4 % mindre restaffald. I et dansk forsøg med over 1.600 deltagere tog valget i gennemsnit 60 sekunder længere, når der stod tekst ved piktogrammet, uden at sorteringen blev bedre.' },
      { id: 'NY060', title: 'EU\'s affaldsstatistikker og Danmarks affaldsmængder', org: 'Brancheforeningen Cirkulær', year: 2025, type: 'Analyse', temaer: ['Data, statistikker og nøgletal', 'Analyser og undersøgelser'], img: 'img/fd61a1711f4363f9367927ee3c8177bd.jpg', url: 'https://cirkulaer.dk/files/media/document/Analyse-EUaffaldsstatistikker-Cirkul%C3%A6r-april2025.pdf', res: 'Cirkulærs analyse viser, at Danmarks høje placering i Eurostats statistik over municipal waste bl.a. skyldes meget haveaffald og forskelle i, hvordan landene opgør erhvervsaffald.', long: 'Analysen fra april 2025 sammenligner Eurostats tal med Miljøstyrelsens affaldsstatistik. I 2022 var 4,4 af Danmarks 12,2 mio. ton affald municipal waste, svarende til 746 kg pr. indbygger. Eurostat angiver 802 kg, fordi affald fra renhold af gader og markedspladser tæller med der. Af den danske mængde gik 56 % til genanvendelse og 43 % til energiudnyttelse. I 2020 udgjorde haveaffald 20 % i Danmark mod 7 % i Italien og 10 % i Sverige. Erhvervsaffald udgør mindst 30 % i Danmark, og ifølge Nordisk Ministerråd svinger andelen fra 16 % i Sverige til 53 % i Island. Sammenligninger mellem landene skal derfor tages med forbehold.' },
      { id: 'NY061', title: 'Analyse: Borgerundersøgelse om affaldsforebyggelse i Danmark', org: 'Brancheforeningen Cirkulær', year: 2026, type: 'Analyse', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Analyser og undersøgelser'], img: 'img/8a1333f873c06cc6ba52c78e4544b371.jpg', url: 'https://cirkulaer.dk/files/media/document/Analyse-borgerunders%C3%B8gelse%20om%20affaldsforebyggelse.pdf', res: 'Brancheforeningen Cirkulær og Epinion har spurgt 1.005 danskere om genbrug og reparation. De fleste ved, hvor de kan købe brugt, men langt færre gør det i løbet af et år.', long: 'Brancheforeningen Cirkulærs undersøgelse fra marts 2026 dækker tøj, elektronik og møbler. 65-77 % har på et tidspunkt købt eller fået genbrug, men det seneste år gælder det 44 % for tøj og sko, 32 % for møbler og 22 % for elektronik. Mindst 75 % ved, hvor de kan finde brugte varer, så viden er ikke barrieren. Reparation er ikke lige så fast praksis, og kun 47 % ved, hvor de kan få repareret møbler. Til gengæld ville 54-70 % af dem, der fik noget repareret, ellers have købt nyt, mod 40-52 % ved genbrug. Foreningen anbefaler at rette indsatsen mod tryghed og praktisk tilgængelighed frem for informationskampagner til den enkelte forbruger.' },
      { id: 'NY062', title: 'Genbrugsløftet 2.0. Et kollektivt håndslag for mere genbrug', org: 'Brancheforeningen Cirkulær og ISOBRO', year: 2025, type: 'Strategi', temaer: ['Direkte genbrug', 'Genbrugspladser', 'Kommunikation'], img: 'img/a02396c24f4cddf0107fa8b3042ca97d.jpg', url: 'https://cirkulaer.dk/files/media/document/Genbrugsl%C3%B8ftet2-august2025.pdf', res: 'Med Genbrugsløftet 2.0 fra 2025 vil Brancheforeningen Cirkulær og ISOBRO fordoble genbruget frem mod 2030, bl.a. via bedre samarbejde mellem genbrugspladser og genbrugsbutikker.', long: 'Genbrugsløftet blev indgået i 2022 mellem Brancheforeningen Cirkulær (dengang Dansk Affaldsforening), Røde Kors, Kirkens Korshær og Folkekirkens Nødhjælp. I version 2.0 fra august 2025 sigter Cirkulær og ISOBRO mod at fordoble genbruget til 2030, efter at lovgivningen fra december 2024 gav kommunerne adgang til at drive og finansiere genbrugsområder. Flere genstande skal gå fra genbrugspladsen til butikkerne via guidelines og best practice. Parterne arbejder på en fælles opgørelsesmetode for genbrugsmængder og årlige beregninger af klima- og samfundseffekten, og borgerne skal hjælpes til at skelne genbrug fra affald, især tekstiler.' },
      { id: 'NY063', title: 'Katalog for affaldsforebyggelse og cirkularitet', org: 'Brancheforeningen Cirkulær m.fl.', year: 2025, type: 'Oplæg', temaer: ['Cirkulær økonomi', 'Direkte genbrug'], img: 'img/3bc24fd2b28fbe1ec130172f1c584fa5.jpg', url: 'https://cirkulaer.dk/files/media/document/Katalog%20for%20affaldsforebyggelse.pdf', res: 'I kataloget foreslår seks organisationer nationale mål og regulering, der skal forebygge affald fra emballage, organisk affald, tekstiler, elektronik og byggeri i Danmark.', long: 'Brancheforeningen Cirkulær, CONCITO, Danmarks Naturfredningsforening, IDA, Plastic Change og Rådet for Grøn Omstilling udgav kataloget i maj 2025. De peger på, at strategien for affaldsforebyggelse fra 2015 mangler regulering og bindende mål, og foreslår en ny med reduktionsmål og konkret regulering. Danskernes materialefodaftryk er 24,5 ton pr. indbygger om året, ca. tre gange det bæredygtige niveau. Forslagene er delt på fem affaldsstrømme plus tværgående tiltag, fx seks års reklamationsret, et permanent fradrag for reparationer, et nationalt retursystem for genbrugelig takeaway-emballage og krav om at bevare eller forklare før nedrivning.' },
      { id: 'NY064', title: 'Model til beregning af masse-, energi- og kulstofstrømme ved håndtering af plastaffald', org: 'Dansk Affaldsforening og Miljøstyrelsen', year: 2023, type: 'Notat', temaer: ['Afsætning og behandling', 'Reel genanvendelse', 'Teknologi'], img: 'img/91d435a7a4a4a9743003fc19506f4b5f.jpg', url: 'https://cirkulaer.dk/files/media/document/DTU%20Kemisk%20genanvendelse%20af%20plast%20-%20sammenfatning.pdf', res: 'DTU\'s sammenfatning af en model, der sammenligner forbrænding, mekanisk og kemisk genanvendelse af plastaffald. Data giver intet klart svar på, hvilken genanvendelse der er bedst.', long: 'Notatet fra januar 2023 sammenfatter et projekt, som DTU Sustain lavede i 2021-2022 sammen med Dansk Affaldsforening og Miljøstyrelsen. Projektet byggede en Excel-model på grundlag af massestrømsanalyse for PET, PE, PP, PS og en blandet fraktion med en worst og en best case. Potentialet for mekanisk og kemisk genanvendelse vurderes at være sammenligneligt, men tabet er formentlig større ved kemisk genanvendelse, og begge kan bruge væsentligt mere energi end forbrænding. Data for kemisk genanvendelse stammer mest fra laboratorieforsøg og skøn. Driften af det konkrete anlæg og affaldsstrømmen betyder mere end valget af teknologi.' },
      { id: 'NY065', title: 'Renovationskørsel på el. 2023 opdatering', org: 'Region Hovedstaden', year: 2023, type: 'Rapport', temaer: ['Teknologi', 'Udbud og kravspecifikationer', 'Klima'], img: 'img/422c4c33b7a5012f8a4ab8d8e7fc565c.jpg', url: 'https://cirkulaer.dk/files/media/document/Renovationskoersel-el%E2%80%932023opdatering.pdf', res: 'Opdateret rapport om elektriske skraldebiler med erfaringer fra kommuner i ind- og udland og en guide til at elektrificere indsamlingen. Markedet er modent, men bilerne er dyre.', long: '4-leaf Consulting har for Copenhagen Electric i Region Hovedstaden opdateret rapporten fra 2021. Den bygger på cases fra bl.a. Frederiksberg, hvor 21 af 25 skraldebiler kører på el, og København, hvor 109 af ARC\'s 130 biler er elektriske, samt en rundspørge fra foråret 2023 blandt medlemmer af Brancheforeningen Cirkulær. Her svarer 71 %, at de ikke har overvejet ladeinfrastruktur. Markedet vurderes som modent, men bilerne er stadig markant dyrere end dieselbiler. Guiden anbefaler politisk afklaring, ruteanalyse, tidlig dialog med netselskabet og at overveje separate udbud af biler og ladeinfrastruktur.' },
      { id: 'NY066', title: 'Mindre deponi på genbrugspladserne', org: 'Brancheforeningen Cirkulær', year: 2022, type: 'Rapport', temaer: ['Genbrugspladser', 'Sorteringskvalitet', 'Kommunikation'], img: 'img/5e2c703d12a42b9a3e815b55cfb846dc.jpg', url: 'https://cirkulaer.dk/files/media/document/Casesamling-mindre%20deponi%20p%C3%A5%20genbrugspladserne-jan2022.pdf', res: 'Casesamling om at holde fejlsorteret affald ude af deponi på genbrugspladser. Hos Favrskov Forsyning faldt fejlsorteringen fra 31 % i 2017 til 3 % i 2020 efter låg på containeren.', long: 'Dansk Affaldsforening, i dag Brancheforeningen Cirkulær, samlede i januar 2022 eksempler på, hvordan genbrugspladser kan mindske mængden af affald til deponi. Blandt tiltagene er lukkede containere, som personalet skal åbne, små tipcontainere bag afskærmning, deponering i bur og grønne guider. Et lille kar til klinker og krukker foran betoncontaineren fanger genstandene i halvdelen af tilfældene. Mange steder hedder deponi nu ”Til nedgravning”, så borgerne bedre forstår fraktionen. Favrskov Forsynings årlige stikprøver viser 31 % fejlsorteret i 2017, 3 % i 2020 og 9 % i 2021, hvor jern og metal samt jord vejede mest blandt fejlene.' },
      { id: 'NY067', title: 'Direkte genbrug på danske genbrugspladser', org: 'Brancheforeningen Cirkulær', year: 2020, type: 'Rapport', temaer: ['Direkte genbrug', 'Genbrugspladser'], img: 'img/4fa33ede9b443253fa6372046fb62ebe.jpg', url: 'https://cirkulaer.dk/files/media/document/Casesamling%20om%20direkte%20genbrug-feb2020.pdf', res: 'Dansk Affaldsforenings casesamling viser direkte genbrug ved danske genbrugspladser, fra REUSE i Aarhus til AVV\'s værksteder, med tal for genbrugte mængder og besøgende.', long: 'Dansk Affaldsforening har samlet eksempler på direkte genbrug fra kommuner og affaldsselskaber. I 2018 kunne borgerne aflevere ting til genbrug på 297 af landets 365 genbrugspladser. REUSE i Aarhus modtager dagligt ca. to tons fra byens seks andre genbrugsstationer. Reno Djurs anslår, at Gi\' det videre afsatte 1.500 ton i 2019, og AffaldPlus\' butikker solgte knap 1.800 tons samme år og har skabt 10 fuldtidsstillinger siden 2013. I Svendborg steg genbrugsprocenten fra 56 til 87 % med Her må du ta\'. AVV\'s cykelværksted reparerer ca. 1.700 cykler om året, og over halvdelen af integrationsborgerne i værkstederne har siden fået job.' },
      { id: 'NY068', title: 'Stigende affaldsmængder på landets genbrugspladser', org: 'Brancheforeningen Cirkulær', year: 2021, type: 'Analyse', temaer: ['Genbrugspladser', 'Data, statistikker og nøgletal', 'Byggeaffald'], img: 'img/921426231b019732c44d97ccb4da7af7.jpg', url: 'https://cirkulaer.dk/files/media/document/Corona-affald%20og%20genbrugspladser-aug2021.pdf', res: 'Genbrugspladserne i 69 kommuner modtog 11 % mere affald i coronaåret 2020 end i 2019, viser data fra affaldsviden.dk. Bygge- og anlægsaffald steg 17 % og jord 25 %.', long: 'Dansk Affaldsforening, i dag Brancheforeningen Cirkulær, lavede analysen i august 2021, efter at medlemmerne havde meldt om stærkt stigende mængder. Tallene kommer fra affaldsviden.dk, som JHN Processor driver, og dækker 58 til 69 kommuner. Genbrugspladserne modtog 2.456.282 tons i 2020 mod 2.213.816 tons året før, og husholdningsaffaldet steg 7 %. Genanvendelsen af husholdningsaffald steg alligevel fra 61 % i 2018 til 65 % i 2020. Månedsdata fra 11 kommuner viser et hop i april 2020, da pladserne genåbnede. Cases fra blandt andre Reno Djurs og Sønderborg Forsyning peger på renoveringer og flytteoprydning som årsager.' },
      { id: 'NY069', title: 'Fakta: Omkostningsfordeling ved indsamling af 10 fraktioner', org: 'Brancheforeningen Cirkulær', year: 2022, type: 'Faktaark', temaer: ['Økonomi', 'Haveboliger/parcelhuse', 'Hente- og bringeordninger'], img: 'img/09a3cce2f4d1c8a2119c3f4df46f1ea6.jpg', url: 'https://cirkulaer.dk/files/media/document/faktaark-kommunale%20affaldsgebyrer_marts2022.pdf', res: 'Faktaark med et regneeksempel for en villa i en kommune, der indsamler de ti fraktioner. Gebyret er 3.354 kr., og tømning, afsætning og beholdere udgør 70-90 % af udgifterne.', long: 'Eksemplet bygger på tal fra virkelige kommuner. Eksempelkommunen har 20.000 husstande, todelte 240-liters beholdere, kuber til glas, tekstil med storskrald og en miljøkasse. Af villaens gebyr på 3.354 kr. går 995 kr. til mad- og restaffald og 967 kr. til de tørre genanvendelige fraktioner, mens genbrugspladserne koster 871 kr. Kommunen betaler ca. 1,9 mio. kr. om året for at komme af med de genanvendelige fraktioner og ca. 11,6 mio. kr. for tømning og beholdere. Deres værdi skal derfor stige med ca. 13,5 mio. kr. blot for at dække tømning og beholdere, og de store poster styres af markedspriser, som kommunen næsten ikke kan påvirke.' },
      { id: 'NY070', title: 'Ny regulering af batterier', org: 'KL', year: 2025, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/8f05772312915b2dc9f949c5ecceb5f1.jpg', url: 'https://www.kl.dk/media/5vomgkh3/ny-regulering-af-batterier.pdf', res: 'KL-notat om den reviderede batteriforordning, der fra 18. august 2025 lægger ansvaret for indsamling af batterier hos producenterne. Kommunerne skal selv forhandle pris og vilkår.', long: 'Med den reviderede batteriforordning har kommunerne ifølge KL ikke pligt til at indsamle batterier fra 18. august 2025, hvor producenternes kollektive ordninger overtager. Resten af 2025 får de fortsat DUT-midler, og KL anbefaler at fortsætte indsamlingen. Fra 2026 kræver det en aftale med en kollektiv ordning, og KL har med Brancheforeningen Cirkulær og ordningerne lavet et udkast til standardkontrakt. Ifølge Niras dækker DUT-midlerne ikke udgifterne, og ordningerne vil afregne i kr. pr. kg, så kommunerne bør kende omkostninger og mængder. Uden aftale er det uafklaret, hvad kommunen gør med batterier, der alligevel afleveres.' },
      { id: 'NY071', title: 'Analyse af byggeaffaldsdata. Veje til øget datakvalitet og sporbarhed', org: 'KL, Miljøstyrelsen og Danske Regioner', year: 2025, type: 'Analyse', temaer: ['Byggeaffald', 'Data, statistikker og nøgletal', 'Analyser og undersøgelser'], img: 'img/f055c0ed2659dff0cfc800fee276651a.jpg', url: 'https://www.kl.dk/media/055kihf2/analyse_veje-til-oeget-datakvalitet-og-sporbarhed.pdf', res: 'NIRAS-analyse for KL, Miljøstyrelsen og Danske Regioner af data om affald fra renovering og nedrivning. Den peger på seks udfordringer og 11 initiativer til bedre datakvalitet.', long: 'NIRAS lavede analysen for KL, Miljøstyrelsen og Danske Regioner i efteråret og vinteren 2024/2025 ud fra 17 interviews og to workshops med aktører i branchen. Den følger data om affald fra renovering og nedrivning gennem fem faser, fra miljøkortlægning og anmeldelse til indberetning i Affaldsdatasystemet. Kun affaldstype, EAK-kode og vægt følger affaldet hele vejen. Blandt problemerne er manglende adgang til data, data i PDF-filer, anmeldelser uden faktiske slutmængder og løbenumre, der ikke altid følger affaldet. NIRAS anbefaler at begynde med initiativerne om data og systemer, bl.a. en fælles datastandard og et fællesoffentligt register.' },
      { id: 'NY072', title: 'Byggeaffaldsdata: Forslag til løsninger. Bedre datakvalitet og sporbarhed', org: 'KL, Miljøstyrelsen og Danske Regioner', year: 2025, type: 'Notat', temaer: ['Byggeaffald', 'Data, statistikker og nøgletal', 'Lovgivning og afgørelser'], img: 'img/2cd140eb919f86849d60e0b7c010eef0.jpg', url: 'https://www.kl.dk/media/gcsbj3av/notat_loesninger-paa-byggeaffaldsdata_2025_web.pdf', res: 'NIRAS foreslår 13 konkrete løsninger, der skal give bedre datakvalitet og sporbarhed for byggeaffald, bl.a. et fælles format for løbenummeret og påmindelser om slutmelding.', long: 'Notatet er skrevet for KL, Miljøstyrelsen og Danske Regioner og bygger videre på en analyse fra februar 2025. Forslagene er udviklet i sommeren 2025 ud fra en gennemgang af reglerne, interviews med ejerne af Bygningsaffald.dk og Byg og Miljø, dialog med Miljøstyrelsens ADS-team og fem interviews med kommuner og nedrivere. Løsningerne dækker adgang til data, løbenummeret, slutmeldinger og dataoverførsel. Blandt dem er fuldmagt fra bygherren, et fælles løbenummer i formatet YY-LL-NNNN-C, løbenummeret i ADS, en liste over godkendte modtagere og én datastruktur for anmeldelse og slutmelding. Nogle forudsætter ændret lovgivning.' },
      { id: 'NY073', title: 'Procedure for tildelingsordningen 2024', org: 'Dansk Producentansvar', year: 2026, type: 'Vejledning', temaer: ['Udvidet producentansvar', 'Genbrugspladser'], img: 'img/6e5e01244946af3fb9bd86d8b85a1a24.jpg', url: 'https://producentansvar.dk/wp-content/uploads/2022/04/procedure-for-tildelingsordning-beregningsmetode-og-tildelingskriterier.pdf', res: 'Dansk Producentansvar beskriver, hvordan producenternes pligt til at hente elektronikaffald fra husholdninger fordeles på kommunernes indsamlingssteder ud fra markedsandele.', long: 'Proceduren fra marts 2024, opdateret i april 2026, forklarer tildelingsordningen for husholdningernes elektronikaffald. Kommunerne registrerer deres indsamlingssteder hos Dansk Producentansvar (DPA) og sorterer affaldet i lovfastsatte fraktioner som skærme og lyskilder. DPA beregner hver producents andel ud fra den markedsførte mængde og en tilbagetagningsfaktor og korrigerer for over- eller underindsamling året før. Kommunens forventede mængde er gennemsnittet af de seneste tre år. Tildelingen sker pr. fraktion for 12 måneder fra 1. september med kommunen som mindste enhed, og der skal være så få producentordninger pr. kommune som muligt.' },
      { id: 'NY074', title: 'Udvikling af teknologi til sikker identifikation af asbestfri eternitplader', org: 'Miljøstyrelsen', year: 2023, type: 'Rapport', temaer: ['Byggeaffald', 'Teknologi', 'Afsætning og behandling'], img: 'img/794532af2726b4198cf587a0fa124b63.jpg', url: 'https://www.teknologisk.dk/_/media/87659%5FUdvikling%5Faf%5Fteknologi%5Ftil%5Fsikker%5Fidentifikation%5Faf%5Fasbestfri%5Feternitplader.pdf', res: 'MUDP-projekt, der har bygget en robotpilot, som aflæser NT-mærket på eternitplader og sorterer de asbestfri fra, så de kan genbruges hele eller blive råstof i ny cement.', long: 'DanRobotics, Norrecco, Cembrit, Kingo Karlsen, Deponi Syd og Teknologisk Institut stod bag projektet, der løb fra 2019 til 2022. I dag deponeres også asbestfri eternitplader ofte som asbestholdigt affald, fordi man ikke umiddelbart kan se, at de er asbestfri. Et neuralt netværk fandt NT-mærkningen med ca. 95 % præcision, men datasættet var kun 150 plader. Hos Aalborg Portland blev 17 ton knuste plader brugt som råstof uden problemer, og fabrikken kan aftage mindst 10.000 ton om året. Et anlæg til 7.400 ton om året løber cirka rundt, når 41 % af pladerne godkendes som asbestfri, og giver overskud ved forsorterede plader.' },
      { id: 'NY075', title: 'Forslag til standard for genbrugsvaregrupper', org: 'Brancheforeningen Cirkulær', year: 2022, type: 'Faktaark', temaer: ['Direkte genbrug', 'Data, statistikker og nøgletal', 'Genbrugspladser'], img: 'img/4404a4cce4f71bced6f6d6ca825a91d5.jpg', url: 'https://cirkulaer.dk/files/media/document/Faktaark-forslag-varegrupper-sept2022.pdf', res: 'Dansk Affaldsforening foreslår seks fælles varegrupper for genbrugsvarer, så mængder af direkte genbrug og CO2-beregninger kan sammenlignes på tværs af genbrugsaktører.', long: 'Genbrugsaktører inddeler varer efter eget formål og tradition, så nøgletal for direkte genbrug ikke nødvendigvis kan bruges på tværs. Faktaarket fra Dansk Affaldsforening, i dag Brancheforeningen Cirkulær, foreslår seks overordnede grupper, nemlig indbo, beklædning og tekstil, børn, underholdning og elektronik, byggematerialer og værktøj samt udendørs og have. Under dem ligger to niveauer af undergrupper, fx stole, sofaer, elværktøj og vinduer. Oversigten er lavet af COWI og foreningen ud fra interviews til rapporten Dokumentation af direkte genbrug på genbrugspladser. Grupperne kan også bruges til standardiserede stikprøvekontroller.' },
      { id: 'NY076', title: 'Status på ordning for tekstilaffald', org: 'Københavns Kommune', year: 2026, type: 'Notat', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Udvidet producentansvar'], img: 'img/fd766e21c5165ba43f9b4a093de1c218.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/c70d2c0b-027c-452e-b1d2-29f35530ae99/4c719d56-1304-4f8d-9cd6-bd5df02df39c-bilag-4.pdf', res: 'Københavns Kommune har skåret antallet af sorteringspunkter ned fra 530 til 362 og vil vente på EU\'s producentansvar for tekstiler, før tekstilordningen udvikles videre.', long: 'Klima-, Miljø- og Teknikforvaltningen orienterer i maj 2026 udvalget om ordningen for tekstilaffald. Tekstiler indsamles mest i sorteringspunkter, og efter nedskaleringen mangler bl.a. villaområder, Ørestad og dele af Sydhavnen et afleveringssted tæt på boligen. I 2025 blev der indsamlet 470 ton, og 294,8 ton gik til finsortering. Heraf var 21,3 % salgbar genbrugsvare, 35,9 % gik til klude, 12,3 % til genanvendelse i høj kvalitet og 18,6 % i lav kvalitet. Fra januar til april 2026 kom 154 ton ind, og 61 ton gik til forbrænding. Producentansvaret skal være i dansk lov senest 17. juni 2027, og indsamlingen bliver måske ikke en kommunal opgave.' },
      { id: 'NY077', title: 'Kundetilfredshedsmåling AffaldPlus, september 2023', org: 'AffaldPlus', year: 2023, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Genbrugspladser', 'Kommunikation'], img: 'img/468542cfb8d68df7e823d1200fd0aa27.jpg', url: 'https://affaldplus.dk/sites/default/files/2024-01/AffaldPlus_KTU_2023.pdf', res: 'Måling fra september 2023 af tilfredsheden hos AffaldPlus\' kunder med 1.308 svar. Tilfredshedsindekset er 5,7 på en skala fra 1 til 7, og informationen scorer lavest med 4,4.', long: 'Analyseinstituttet interresearch gennemførte målingen for AffaldPlus 13.-27. september 2023. I alt blev 5.000 kunder inviteret via digital post, og 26 % svarede. Svarene er givet på en skala fra 1 til 7 og sammenlignet med 2019 og et benchmark for forsyningsbranchen. Det samlede indtryk af AffaldPlus får 6,0 mod 5,7 i 2019. Tilfredsheden med haveaffaldspladserne er steget 0,5 til 6,3, mens genbrugspladserne ligger under benchmark på alle spørgsmål. Ifølge effektanalysen betyder temaet AffaldPlus og miljø mest for tilfredsheden. Kun 11 % kender den månedlige nyhedsmail, og 56 % ved, at AffaldPlus er en offentlig virksomhed.' },
      { id: 'NY078', title: 'Affaldsanalyse af Madaffald, MGP-affald, Papiraffald samt Restaffald fra enfamilieboliger i Randers', org: 'Randers Kommune', year: 2022, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Haveboliger/parcelhuse', 'Analyser og undersøgelser'], img: 'img/9f34515e85baa6776e97288a3c6ae7f2.jpg', url: 'https://www.randers.dk/media/3qkpe2zb/rapport-nordbyen-randers-2022-was.pdf', res: 'Econets affaldsanalyse fra 142 enfamilieboliger i Nordbyen i Randers viser 10,2 kg affald pr. husstand om ugen. 35 % er restaffald, og madaffaldet er 95 % rent.', long: 'Econet har for Randers Kommune analyseret rest-, mad-, papir- og MGP-affald indsamlet fra 142 husstande i Nordbyen i marts 2022. Madaffald er den største ordning med knap 4 kg pr. husstand pr. uge. Restaffaldet på ca. 3,6 kg består af 29 % madaffald mv. og 28 % genanvendelige materialer, heraf 12 procentpoint plast. 83 % af madaffaldet, 86 % af papiret, 96 % af glasemballagen og 79 % af metalemballagen sorteres fra, mens det kun gælder 58 % af plastemballagen. Papiret er 94 % rent og MGP-affaldet ca. 89 %. Etageboliger i Randers gav i 2021 kun 6,2 kg pr. husstand, og i Langå blev der i 2019 indsamlet 2,6 kg madaffald med 88 % renhed.' },
      { id: 'NY079', title: 'Affaldsanalyse af Madaffald, MGP-affald, Papiraffald samt Restaffald fra nedgravede beholdere', org: 'Randers Kommune', year: 2021, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Etageboliger', 'Analyser og undersøgelser'], img: 'img/5edfefa678011b07a02c0c16dd761ba1.jpg', url: 'https://www.randers.dk/media/tt1bl0w4/2021-09-09-rapport-randers-2021-was.pdf', res: 'Econet har analyseret affald fra nedgravede beholdere ved 196 husstande i Randers. Restaffald er 67 % af 6,2 kg pr. husstand om ugen, og 60 % af madaffaldet havner i restaffaldet.', long: 'Randers Kommune fik Econet til at sortere madaffald, MGP-affald, papiraffald og restaffald indsamlet i juni 2021 fra fire etageboligområder med nedgravede beholdere. Madaffaldet var 95 % rent og MGP-affaldet ca. 91 %. Ordningerne fangede 40 % af madaffaldet, 76 % af papiret, 70 % af glasemballagen og kun 14 % af plastemballagen. Restaffaldet bestod af 30 % madaffald og 34 % genanvendelige materialer. Rapporten sammenligner også med Horsens og med tidligere analyser i Randers. Sorteringen er bedre end i 2017, men ligger under haveboligerne i 2019, hvor 72 % af madaffaldet blev sorteret fra.' },
      { id: 'NY080', title: 'Afrapportering af kpi’er for 2024', org: 'AffaldPlus', year: 2025, type: 'Notat', temaer: ['Reel genanvendelse', 'Genbrugspladser', 'Direkte genbrug'], img: 'img/e7b318947c7f74b465e013c21ce534d6.jpg', url: 'https://affaldplus.dk/sites/default/files/2025-03/KPI_afrapportering_2024.pdf', res: 'AffaldPlus gør status på 15 kpi’er for 2024. Reel genanvendelse på genbrugspladserne faldt til 61,4 %, blandt andet fordi meget asbest blev afleveret før nye regler i 2025.', long: 'Notatet fra februar 2025 gennemgår AffaldPlus’ mål for genanvendelse, direkte genbrug, energi, forsyningssikkerhed og arbejdsmiljø. På genbrugspladserne faldt genanvendelsen efter den gamle metode fra 80,64 % til 78,5 %, og asbest udgjorde ca. 2 % af den samlede mængde. Plast fra husholdninger blev reelt genanvendt med 64,31 % mod et mål på 65 %. Der blev indleveret 2.074 ton varer til genbrug, og byggematerialer til genbrug steg fra 111 til 226 ton, hjulpet af to nye PlusByg-butikker. Forsinkede tømninger i Sorø og Ringsted lå på 4,2 og 3,2 promille mod et kontraktkrav på 1 promille, og målene for stress og ulykker blev ikke nået.' },
      { id: 'NY081', title: 'Pixi-drejebog om at være proaktiv i affaldstilsynet', org: 'Holbæk Kommune', year: 2021, type: 'Vejledning', temaer: ['Erhverv', 'Cirkulær økonomi'], img: 'img/abde104672a4c23fbe819e83da8e32ac.jpg', url: 'https://holbaek.dk/media/65376/pixi_drejebog.pdf', res: 'Drejebog fra Holbæk Kommune om, hvordan affaldsmyndigheden sammen med erhvervsråd og forsyning kan hjælpe virksomheder til bedre affaldssortering og symbiosesamarbejder.', long: 'Energy Cluster Denmark skrev drejebogen for Holbæk Kommune i 2021 i projektet Reaktiv til Proaktiv under Interreg ØKS. Den bygger på workshops med kommuner i Region Hovedstaden og Region Sjælland, Miljøstyrelsen, KL, Københavns Universitet og Holbæk Erhvervsforum. Kommunen, erhvervsrådet og forsyningen kan invitere virksomhederne ind i et netværk som en neutral platform. I Holbæk er det erhvervsrådets symbiosenetværk, som kommunen startede sammen med FORS. NIRAS trak ADS-data for 12 brancher i Holbæk og Lejre til benchmark i PARCK-projektets affaldsværktøj, men fandt tallene for lidt valide, og projektet anbefaler forbedringer af ADS.' },
      { id: 'NY082', title: 'Halvårlig status på Ressource- og Affaldsstrategi 2030 og målsætningerne', org: 'Københavns Kommune', year: 2026, type: 'Notat', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Reel genanvendelse'], img: 'img/f439abad53e1a8b6abf765c51a071500.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/7b5b42e1-395a-468a-b8db-915ca1745e11/18e02d0f-7b32-4db7-a67a-04e3de7d46fd-bilag-2.pdf', res: 'Københavns Kommunes status fra marts 2026 på de fire mål i Ressource- og Affaldsstrategi 2030. Den reelle genanvendelse var 41,3 % i 2025, mens målet for 2030 er 60 %.', long: 'Bilaget er skrevet af Klima-, Miljø- og Teknikforvaltningen. I 2025 blev der afsat 5.611 ton genbrug fra kommunens genbrugs- og nærgenbrugsstationer, 407 ton mere end året før, mod et mål på 10.000 ton. Den reelle genanvendelse af husholdningslignende affald fra husholdninger nåede 41,3 %, og forvaltningen vurderer, at der skal indsamles mindst 30.000 ton madaffald mod 20.000 ton i 2025 for at nå 60 %. Data for erhvervsaffald er to år forsinket, og byggeaffaldsprojekterne startede først i 2026. Strategien har en bevilling på 471 mio. kr., og 51 af 65 projekter er i gang. Affaldstaksten er 3.370 kr. pr. gennemsnitlig husstand i 2026.' },
      { id: 'NY083', title: 'Afrapportering af 1.2.3 Flere cykler til genbrug og genanvendelse', org: 'Københavns Kommune', year: 2026, type: 'Evaluering', temaer: ['Direkte genbrug', 'Hente- og bringeordninger', 'Storskraldsordning'], img: 'img/12712593f509cde5c0975e00a7ec42af.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/7b5b42e1-395a-468a-b8db-915ca1745e11/18e02d0f-7b32-4db7-a67a-04e3de7d46fd-bilag-11.pdf', res: 'Københavns Kommune har testet indsamling af ejerløse cykler fra gårdoprydninger. ARC hentede 15 ton i 2025, og 62 % blev genbrugt mod 5 % i Politiets nuværende ordning.', long: 'Afrapporteringen fra marts 2026 gør status på et pilotprojekt i Klima-, Miljø- og Teknikforvaltningen, der løber fra februar 2025 til december 2026. Politiet indsamler i dag 30.000-40.000 cykler om året fra byens gårde og afsætter kun 5 % til genbrug. I forsøget har 120 affaldsansvarlige bestilt afhentning i NEM Affaldsservice, og fem kommercielle og socioøkonomiske virksomheder aftog cyklerne. Forvaltningen indstiller en permanent bydækkende ordning fra 1. januar 2027, der ventes at give 280-370 ton genbrug om året. ARC\'s indsamling koster 5,3 mio. kr. årligt, og efter salg af cyklerne ventes taksten at stige 4-13 kr. pr. husstand om året.' },
      { id: 'NY084', title: 'Overblik: Affaldsanalyse i Herlev Kommune 2023', org: 'Herlev Kommune', year: 2024, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Analyser og undersøgelser', 'Etageboliger'], img: 'img/9b2797aea3e5bdbb044a3be26aba14e4.jpg', url: 'https://www.herlev.dk/Media/638610590121979506/2024-07-01%20Minirapport%20-%20Sammens%C3%A6tning%20af%20Restaffald%20og%20S%C3%A6rskilt%20indsamlet%20Madaffald%20fra%20husholdninger.pdf', res: 'Kort overblik over Econets analyse af rest- og madaffald i Herlev i 2023. 57 % af restaffaldet fra villaer og 73 % fra etageboliger kunne være sorteret i andre ordninger.', long: 'Econet har for Herlev Kommune kortlagt restaffald og særskilt indsamlet madaffald fra villaer og etageboliger i slutningen af 2023 og sammenlignet med en kortlægning fra 2020. Sammensætningen har kun ændret sig lidt, og der kan ikke aflæses en tydelig effekt af kommunens tiltag. Madaffald udgør 25 % af restaffaldet fra villaer og 39 % fra etageboliger, hvor der også var meget glas. Andelen af korrekt sorteret restaffald faldt fra 46 til 43 % i villaer og fra 32 til 27 % i etageboliger. Madaffaldet er generelt rent. Kommunen kan målrette kommunikationen mod madaffald, især madspild, og mod glas, plast og papir.' },
      { id: 'NY085', title: 'Forslag til økonomisk model og kriterier', org: 'Københavns Kommune', year: 2026, type: 'Notat', temaer: ['Økonomi', 'Hente- og bringeordninger', 'Etageboliger'], img: 'img/522214b3c44238caeedb5c4af72f9354.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/b2f78507-1b1e-48fd-ac48-c59551faa7df/2e0e3275-2dd9-4cb1-a98a-8482fa0432fc-bilag-4_0.pdf', res: 'Forslag til gebyrmodel og kriterier for nye miljøstationer i København. Tre forsøgsstationer kostede 5,9 mio. kr. at anlægge, og driften er 75 % dyrere end gårdbeholdere.', long: 'Forvaltningens notat bygger på tre forsøgsmiljøstationer med nedgravede beholdere og kuber på Nørrebro. Driften koster 714.000 kr. om året mod 409.000 kr. for beholdere i gårdene. Forvaltningen anbefaler et særskilt gebyrområde, hvor ordningsgebyret dækker det genanvendelige affald, mens restaffaldet får et volumenafhængigt gebyr og en engangsopkrævning hos de deltagende ejendomme. Med det eksisterende gebyr for private nedgravede beholdere på 8 kr./liter/uge ville restaffaldet mangle 35.000 kr. om året. Ifølge forslaget skal nye stationer være nedgravede og have mindst 160 boligenheder tilknyttet. Et nyt gebyr kan tidligst gælde fra 2028.' },
      { id: 'NY086', title: 'Svar på 10-dags forespørgsel fra Venstre vedr. økonomi ved håndtering af emballageaffald', org: 'Aarhus Kommune', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi'], img: 'img/4ce19879baa5112e4e650ef24b4e280c.jpg', url: 'https://aarhus.dk/media/inblcybs/besvarelse.pdf', res: 'Aarhus Kommune svarer på en byrådsforespørgsel om producentansvar for emballage. Villagebyret faldt 775 kr. i 2026, men producenterne ventes kun at dække ca. 80 % af udgifterne.', long: 'Teknik og Miljø besvarer i august 2026 fire spørgsmål fra Venstre om økonomien i producentansvaret for emballage, der trådte i kraft 1. oktober 2025. Svarene kommer fra Kredsløb, som indsamler emballageaffaldet og afregner med den kollektive ordning VANA. Gebyrerne for 2026 blev beregnet ud fra, at producenterne skulle betale 100 % af omkostningerne. De faldt med 775 kr. (ca. 20 %) for en villakunde og 270 kr. (ca. 10 %) for en midtbykunde. Reglerne er siden ændret, og Kredsløb regner nu med en dækning på ca. 80 %. Resten skal betales via gebyrerne, hvilket presser 2027-gebyrerne op. Kredsløb kalder modellen unødigt administrativt kompleks.' },
      { id: 'NY087', title: 'Evaluering af alternative nærgenbrugsstationer', org: 'Københavns Kommune', year: 2025, type: 'Evaluering', temaer: ['Genbrugspladser', 'Direkte genbrug'], img: 'img/239a617f60bd92b9cfeaa2a1c502fbea.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/0beb135a-b4ee-4384-891a-fb94ab2e4b5a/1721e3a6-cb37-424b-8275-b7b6b095e6d4-bilag-3_0.pdf', res: 'Behave Green har evalueret tre midlertidige nærgenbrugsstationer i København. Lokal forankring og fast lønnet bemanding virker bedst, og en handelsgade giver flest besøgende.', long: 'Behave Green lavede evalueringen for Københavns Kommune i april 2025 ud fra observationer, interviews med 10 medarbejdere, brugsdata og borgerportrætter fra kommunen. Lykkebazaren i et butikslokale har 1.497 besøgende om måneden, men det højeste genbrug pr. besøgende af de tre med 0,81 kg. Østerbrohuset ved Århusgade har 6.353 besøgende, men kun 0,51 kg pr. besøgende. Charlotte Ammundsens Plads har en tydelig tekstilprofil og holdt 135 aktiviteter med 4.670 deltagere i 2024, men egner sig dårligt til affaldsindsamling. Rapporten anbefaler lokale driftspartnere, lønnet bemanding, tydelige profiler og tomme butikslokaler på handelsgader.' },
      { id: 'NY088', title: 'Afrapportering og evaluering af Ressource- og Affaldsplan 2024', org: 'Københavns Kommune', year: 2025, type: 'Evaluering', temaer: ['Affaldsplaner/regulativer og strategi', 'Analyser og undersøgelser', 'Direkte genbrug'], img: 'img/ab8e61236b98897e2235370774522273.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/896bca9d-cd56-4ada-8aa9-adae0f59b624/12eac485-ea37-4aff-981b-e6e79676b52d-bilag-1_0.pdf', res: 'Københavns Kommunes slutevaluering af Ressource- og Affaldsplan 2024. Genanvendelsen af husholdningsaffald steg fra 39,7 til 46,3 %, men målet om 70 % blev ikke nået.', long: 'I notatet gør Teknik- og Miljøforvaltningen status for 2019-2024, hvor 40 af planens 45 indsatser blev gennemført. Genbrug steg fra 2.619 til 5.204 ton årligt mod et mål på 6.000 ton, og husholdningsaffaldet faldt fra 340 til 292 kg pr. indbygger. Vejledning af over 2.660 virksomheder vurderes at have flyttet ca. 30.000 ton erhvervsaffald til genanvendelse, men målet om 70 % for erhvervsaffald er ikke nået. Forvaltningen peger på urealistiske mål og for høje effektestimater, og flere indsatser kom for sent. Ressource- og Affaldsstrategi 2030 viderefører i vidt omfang målene, og 19,5 mio. kr. i ubrugte midler går tilbage til taksten.' },
      { id: 'NY089', title: 'Evaluering af sorteringspunkter', org: 'Københavns Kommune', year: 2024, type: 'Evaluering', temaer: ['Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/df0a90205ef3ac8f7b35af57e74d41ad.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/850553ca-a503-4b81-9058-f92df04135d5/20c3549d-9f8c-48a1-a3fb-93e9d77805fe-bilag-2_0.pdf', res: 'Notat om de første erfaringer med Københavns sorteringspunkter i byrummet. Tekstil fylder mest, og 76 % af brugerne i borgerpanelet er tilfredse, men datagrundlaget er spinkelt.', long: 'I et notat fra marts 2024 orienterer Teknik- og Miljøforvaltningen udvalget om sorteringspunkterne, hvor ca. 115 af de planlagte 550 var i drift. Fra januar til november 2023 blev der indsamlet ca. 90 ton til genanvendelse, og tekstil, plast, madaffald og papir udgjorde 89 % i november. Tekstil er den eneste fraktion med overfyldning, og vandindtrængning har ødelagt en del af tekstilaffaldet. ARC rydder op ved punkterne hver dag. I et borgerpanel med 3.591 svar kendte knap halvdelen punkterne, og 81 % synes godt om flere sorteringsmuligheder i byen. Forvaltningen vil fremover måle mængder, fejlsortering, drift og tilfredshed.' },
      { id: 'NY090', title: 'Orientering om haveaffaldsordningen', org: 'Københavns Kommune', year: 2024, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Sorteringskvalitet', 'Afsætning og behandling'], img: 'img/167a5a018131927f3f56759bed1175e0.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/850553ca-a503-4b81-9058-f92df04135d5/20c3549d-9f8c-48a1-a3fb-93e9d77805fe-bilag-3_0.pdf', res: 'Københavns Kommune opgiver at indsamle dyrestrøelse og pottemuld med haveaffaldet. Et forsøg gav 8 % fejlsortering, og indsatsen går i stedet på at få flere tilmeldt ordningen.', long: 'Teknik- og Miljøforvaltningen orienterer i notatet fra marts 2024 Teknik- og Miljøudvalget om indsats 10.1 i tillægspakken til Ressource- og Affaldsplan 2024. Forsøget omfattede 29 etagekundeforhold i tre måneder, og 2.670 kg affald blev håndsorteret. Fejlsorteringen var 8 %, hvor EU højst tillader 0,5 % i jordforbedringsprodukter, og fejlene var især plast samt mikroplast og Leca-kugler fra pottemulden. Kun ét af fire behandlingsanlæg kunne tage dyrestrøelsen. I stedet skal en kampagne få flere etageboliger med i haveaffaldsordningen, hvor kun 30 % er tilmeldt. Ændringen sænker udgiften til implementering fra 7,4 til 1,8 mio. kr.' },
      { id: 'NY091', title: 'Vurdering af effekt ved kombineret indsamling', org: 'Københavns Kommune', year: 2025, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Økonomi', 'Udvidet producentansvar'], img: 'img/3ca1626c59367f43d9b8eb8e899e803f.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/9b383522-525f-4b9c-9467-05defa19983e/a31c5ea4-8f62-4639-8d1c-33cc05b5365f-bilag-5_0.pdf', res: 'Københavns Kommune har regnet på at samle papir med pap og metal med plast og kartoner. Samlet kan udgiften falde lidt, men kommunens andel stiger op til 33,1 mio. kr. årligt.', long: 'Teknik- og Miljøforvaltningen skrev notatet efter et medlemsforslag om enklere affaldssortering i Borgerrepræsentationen 21. august 2025. Tre scenarier er beregnet ud fra emballagebekendtgørelsens nøgletal og ARC\'s skøn. Papir og pap sammen sparer 6,9 mio. kr. på indsamlingen, men kommunens andel af udgiften stiger 33,1 mio. kr., ca. 97 kr. pr. husstand. Ved metal med plast og kartoner ventes et metaltab på ca. 10 % mod 3 % ved kildesortering. Behandlingsanlæggene fraråder at blande materialerne, og DI og DTU anbefaler at holde fast i kildesorteringen. Adfærdsteamet vurderer, at færre fraktioner ikke i sig selv gør sorteringen nemmere.' },
      { id: 'NY092', title: 'Faktaark om sortering af affald', org: 'Københavns Kommune', year: 2025, type: 'Faktaark', temaer: ['Sorteringskvalitet', 'Afsætning og behandling', 'Data, statistikker og nøgletal'], img: 'img/5e4f6cbdd73510ee7e4a42e8e10b0d84.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/9b383522-525f-4b9c-9467-05defa19983e/a31c5ea4-8f62-4639-8d1c-33cc05b5365f-bilag-4_0.pdf', res: 'Københavns Kommunes faktaark svarer på typiske spørgsmål om kildesortering og sorteringsanlæg. Genanvendelsen af husholdningsaffald steg fra 39,5 % i 2019 til 46,3 % i 2024.', long: 'Teknik- og Miljøforvaltningen skrev faktaarket i oktober 2025 som bilag til en sag i kommunen. Forvaltningen kender ikke sorteringsanlæg, der helt kan erstatte borgernes sortering, og bl.a. tekstiler, glas, madaffald og farligt affald kan ikke sorteres ud af restaffaldet. Københavnerne udsorterede 102.000 ton i 2024, og den reelle genanvendelse var 40,3 %. Fejlsorteringen i restaffaldet faldt fra ca. 80 % i 2020 til ca. 69 % i 2023, og omkring 95 % af borgerne mener, at man bør sortere. ARCs anlæg til sortering af restaffald forventes at åbne i efteråret 2026, og Borgerrepræsentationen har godkendt en anlægsramme på 375 mio. kr.' },
      { id: 'NY093', title: 'Lovmæssige rammer for affaldssortering', org: 'Københavns Kommune', year: 2025, type: 'Notat', temaer: ['Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/af849da1dc5208acc13152c27f72b1ba.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/9b383522-525f-4b9c-9467-05defa19983e/a31c5ea4-8f62-4639-8d1c-33cc05b5365f-bilag-3_0.pdf', res: 'Notat fra Københavns Kommune om reglerne for særskilt indsamling. Fem kombinationer af fraktioner må indsamles sammen uden dispensation, mens central sortering kræver dispensation.', long: 'Bilaget fra oktober 2025 gennemgår reglerne for affaldssortering fra EU-niveau til kommunen. Affaldsdirektivet kræver særskilt indsamling og sætter mål for reel genanvendelse på 55, 60 og 65 % i 2025, 2030 og 2035. Efter affaldsbekendtgørelsens §§ 36-40 må kommunerne uden dispensation indsamle papir og pap, metal og glas, metal og plast, plast og mad- og drikkekartoner samt plast, kartoner og metal sammen. Andre kombinationer og forsøg med central sortering kræver dispensation, og i 2023 fik 10 fynske kommuner afslag på at samle plast og kartoner med restaffald. Folketinget forkastede i juni 2025 et beslutningsforslag om central sortering.' },
      { id: 'NY094', title: 'Affaldssortering blandt ældre i København', org: 'Københavns Kommune', year: 2025, type: 'Notat', temaer: ['Sorteringskvalitet', 'Analyser og undersøgelser', 'Etageboliger'], img: 'img/63d1f39918ee83b8cdc4e9faefb5db34.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/9b383522-525f-4b9c-9467-05defa19983e/9f237649-5d6f-4206-9830-1e469658e283-bilag-3_0.pdf', res: 'Københavns Kommune har set på ældres affaldssortering. Borgere fra 60 år sorterer bedst, og først når der er brug for støtte og pleje, bliver sorteringen sandsynligvis svær.', long: 'Teknik- og Miljøforvaltningen har trukket tal ud af kommunens borgermåling fra februar 2025 med 1.485 respondenter. Både holdningen til sortering og den oplevede viden om affald bliver stærkere med alderen, og selv borgere på 85 år og derover sorterer bedre end de 18-59-årige. Af 11.947 hjemmehjælpsmodtagere får ca. 8.700 hjælp til at bortskaffe affald, men hjemmeplejen eftersorterer ikke blandede poser af hensyn til arbejdsmiljøet. Ældrerådet ønsker ikke nye dyre tiltag, som hæver taksten eller belaster hjemmeplejen. Rådet beder om bedre kommunikation om sortering og om lukning af affaldsskakte, som skaber usikkerhed hos de ældre.' },
      { id: 'NY095', title: 'Resultater fra forsøg med indsamling af bleaffald', org: 'Københavns Kommune', year: 2025, type: 'Evaluering', temaer: ['Hente- og bringeordninger', 'Etageboliger', 'Analyser og undersøgelser'], img: 'img/1851dc5bda88c93bfcfabd147051d850.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/2b4c5ba1-e369-4ef7-95c7-0890e125019a/a55229db-f933-4857-98a3-2b65db4cbe02-bilag-2.pdf', res: 'Københavns Kommune har testet særskilt indsamling af bleer. Børnefamilier og daginstitutioner sorterede let og med høj sorteringsgrad, mens ældreboligerne mødte flere barrierer.', long: 'Bilaget fra Teknik- og Miljøforvaltningen samler erfaringerne fra forsøget. Det omfattede 10 etageboliger med ca. 2.600 beboere og et ældreboligkompleks med ca. 300 beboere, hvor der i alt blev stillet 29 beholdere på 190 liter op. Kommunale daginstitutioner deltog i efteråret 2022 og marts 2023 med en ekstra spand og blå poser til bleerne i puslerummet. Børnefamilierne oplevede generelt ikke, at sorteringen krævede ændret adfærd, og personalet vænnede sig hurtigt til den. I ældreboligerne var hjemmehjælpernes travlhed en stor barriere, og et udviklingsarbejde om sortering i ældreplejen forventes i 2025-2026. Ingen klagede over lugt.' },
      { id: 'NY096', title: 'Teknik- og Miljøforvaltningens hjemmel til at understøtte og fremme reparation', org: 'Københavns Kommune', year: 2024, type: 'Notat', temaer: ['Lovgivning og afgørelser', 'Direkte genbrug', 'Genbrugspladser'], img: 'img/5e9e0fa5af2a25f3fcbb4887e498ec5d.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/2ee559e1-111f-404b-9136-0039f86b72f4/c2117158-6118-4e88-8aea-d578e89e0c82-bilag-4_0.pdf', res: 'Københavns Kommune vurderer, at reparationscaféer på genbrugsstationer og tilskud til borgernes reparationer mangler hjemmel, mens kampagner og visse partnerskaber er lovlige.', long: 'Teknik- og Miljøforvaltningen gennemgår i notatet fra maj 2024 sin hjemmel efter miljøbeskyttelsesloven og kommunalfuldmagtsreglerne. Reparation er ikke affaldshåndtering, da borgeren beholder genstanden, og med henvisning til Ankestyrelsens udtalelser fra 2017 og 2024 er der ikke hjemmel til reparationscaféer på takstfinansierede nær- og genbrugsstationer. Tilskud til reparation efter Wien-modellen afvises også, selv om pengene kommer fra EU eller fonde. Kampagner og workshops om reparation kan derimod finansieres via administrationsgebyret, og forvaltningen kan i et afgrænset omfang facilitere partnerskaber med erhvervslivet om reparation.' },
      { id: 'NY097', title: 'Waste management country profile with a focus on municipal and packaging waste: Denmark', org: 'EEA', year: 2025, type: 'Faktaark', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse', 'Afsætning og behandling'], img: 'img/239eaa7e92623473c3a1becdeec77f79.jpg', url: 'https://www.eea.europa.eu/en/topics/in-depth/waste-and-recycling/municipal-and-packaging-waste-management-country-profiles-2025/dk-municipal-waste-factsheet.pdf/@@download/file', res: 'EEA\'s landeprofil for Danmark om kommunalt affald og emballageaffald. Danmark er på vej mod EU\'s 2025-mål for genanvendelse, men plast- og stålemballage halter efter.', long: 'Det Europæiske Miljøagentur bygger profilen på Eurostat-data for 2010-2022 og oplysninger fra danske myndigheder. Ifølge Eurostat producerede Danmark 802 kg kommunalt affald pr. indbygger mod et EU-gennemsnit på 513 kg, mens den reviderede danske statistik viser 746 kg i 2022. Genanvendelsen var 50 % i 2022 efter dansk opgørelse og 46 % hos Eurostat, og de nye regler fra 2020, hvor sorteringsrester trækkes fra, sænkede raten. Emballage blev genanvendt med 64,9 % i 2022, tæt på 2025-målet. Ved udgangen af 2023 havde 80 af 98 kommuner indført alle ti fraktioner. Profilen peger på stærkere virkemidler for forebyggelse og mindre forbrænding.' },
      { id: 'NY098', title: 'Waste prevention country profile: Denmark', org: 'EEA', year: 2025, type: 'Faktaark', temaer: ['Affaldsplaner/regulativer og strategi', 'Cirkulær økonomi', 'Direkte genbrug'], img: 'img/50aa204f1790e3320e420fc8f8d13d75.jpg', url: 'https://www.eea.europa.eu/en/topics/in-depth/waste-and-recycling/country-profiles-on-waste-prevention-2025/dk-waste-prevention-factsheet-final.pdf/@@download/file', res: 'EEA\'s landeprofil om dansk affaldsforebyggelse. Programmet er en del af Handlingsplan for cirkulær økonomi, og kommunalt affald lå på 746 kg pr. indbygger i 2022.', long: 'Profilen fra februar 2025 beskriver Danmarks Handlingsplan for cirkulær økonomi, som er den nationale plan for forebyggelse og håndtering af affald 2020-2032. Ifølge Eurostat havde Danmark 802 kg kommunalt affald pr. indbygger mod et EU-gennemsnit på 513 kg, mens revideret dansk statistik giver 746 kg i 2022. Planen har 129 initiativer med særligt fokus på biomasse, byggeri og plast, men intet særskilt budget, og status rapporteres hvert år til Folketinget. Madspild anslås til ca. 1,2 mio. tons om året. Om genbrug nævner profilen eksempler fra kommunale genbrugspladser, men Danmark havde ikke indberettet genbrugsdata for 2021 inden fristen.' },
      { id: 'NY099', title: 'Guidance for separate collection of municipal waste', org: 'Europa-Kommissionen', year: 2020, type: 'Vejledning', temaer: ['Hente- og bringeordninger', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/15545364dbec72f28b90df76994bc54d.jpg', url: 'https://op.europa.eu/o/opportal-service/download-handler?identifier=bb444830-94bf-11ea-aac4-01aa75ed71a1&format=pdf&language=en&productionSystem=cellar', res: 'Vejledning udarbejdet for EU-Kommissionen om kravet om særskilt indsamling og undtagelserne, med god praksis for bioaffald, plast, tekstil og farligt husholdningsaffald.', long: 'EY, PlanMiljø, ACR+, RWA og Öko-Institut har skrevet vejledningen for Kommissionen ud fra skriftlige kilder, 31 organisationers input og svar fra 15 medlemslande. Den fortolker kravene om særskilt indsamling og de fire grunde til undtagelse, som efter vejledningen oftest er overflødige. God indsamling kræver økonomiske incitamenter som PAYT, håndhævelse, tilpassede ordninger og kommunikation. Fire scenarier spænder fra henteordning med pant, som er dyrest men giver bedst resultat, til gadecontainere, som er billigst men giver flest urenheder. Målene er 55, 60 og 65 % genbrug og genanvendelse i 2025, 2030 og 2035 mod et EU-snit på 46 % i 2017.' },
      { id: 'NY100', title: 'Meddelelse fra Kommissionen: Særskilt indsamling af farligt husholdningsaffald', org: 'Europa-Kommissionen', year: 2020, type: 'Vejledning', temaer: ['Hente- og bringeordninger', 'Genbrugspladser', 'Lovgivning og afgørelser'], img: 'img/ef6959e54fcd167634e47451342c922b.jpg', url: 'http://publications.europa.eu/resource/cellar/0cf697ef-2003-11eb-b57e-01aa75ed71a1.0003.01/DOC_1', res: 'Kommissionens ikke-bindende retningslinjer for særskilt indsamling af farligt affald fra husholdninger. De beskriver bedste praksis for hver affaldstype med eksempler fra EU-lande.', long: 'Retningslinjerne er udarbejdet efter affaldsrammedirektivets artikel 20 og retter sig mod myndigheder og affaldsoperatører. Farligt husholdningsaffald er ca. 1 vægtprocent af det kommunale affald, eller 1-6 kg pr. indbygger om året, og ca. to tredjedele af det særskilt indsamlede afleveres på genbrugsstationer. Meddelelsen gennemgår bl.a. maling, pesticider, lægemidler, skarpe genstande, asbest, behandlet træ og kviksølv. Blandt eksemplerne er Odenses røde kasse, der samler ca. 1,6 kg pr. indbygger om året. Ifølge Kommissionen kombinerer gode ordninger økonomiske incitamenter, tilpassede faciliteter, kommunikation og håndhævelse.' },
      { id: 'NY101', title: 'Forordning (EU) 2025/40 om emballage og emballageaffald', org: 'Europa-Parlamentet og Rådet', year: 2025, type: 'Notat', temaer: ['Lovgivning og afgørelser', 'Udvidet producentansvar', 'Cirkulær økonomi'], img: 'img/ce5426ca1dd6e4aed297cd6f477aa739.jpg', url: 'http://publications.europa.eu/resource/cellar/d34251c8-d865-11ef-be2a-01aa75ed71a1.0003.01/DOC_1', res: 'EU\'s emballageforordning gælder fra 12. august 2026 og erstatter emballagedirektivet. Den stiller krav om genanvendelig emballage, genanvendt plast, pant og mindre emballageaffald.', long: 'Forordningen blev vedtaget 19. december 2024 og gælder direkte i alle medlemslande fra 12. august 2026, hvor direktiv 94/62/EF ophæves. Al emballage skal være genanvendelig, og fra 2030 skal plastemballage indeholde 10-35 % genanvendt plast afhængigt af typen, stigende til op til 65 % i 2040. Emballageaffaldet pr. indbygger skal ned med 5 % i 2030, 10 % i 2035 og 15 % i 2040 i forhold til 2018. Fra 2029 skal 90 % af engangsflasker af plast og metaldåser til drikkevarer indsamles særskilt via pant- og retursystemer, og i 2030 skal 70 % af alt emballageaffald genanvendes. Affaldsbeholdere til emballage skal have harmoniserede mærker.' },
      { id: 'NY102', title: 'Direktiv (EU) 2025/1892 om ændring af direktiv 2008/98/EF om affald', org: 'Europa-Parlamentet og Rådet', year: 2025, type: 'Afgørelse', temaer: ['Udvidet producentansvar', 'Tekstil', 'Lovgivning og afgørelser'], img: 'img/6bb0187eb7abe0515f69bef8e5937988.jpg', url: 'http://publications.europa.eu/resource/cellar/86745ca1-9a71-11f0-97c8-01aa75ed71a1.0003.01/DOC_1', res: 'EU-direktivet pålægger landene at indføre udvidet producentansvar for tekstiler og fodtøj senest 17. april 2028 og sætter mål for mindre madaffald i 2030.', long: 'Direktivet er vedtaget 10. september 2025 og skal være gennemført senest 17. juni 2027. Producenter af tekstiler og fodtøj skal via en producentansvarsorganisation betale for indsamling, transport, sortering og behandling. Indsamlingen skal dække hele landet og være gratis, og organisationerne må ikke afvise kommuner eller socialøkonomiske enheder, der vil deltage. Senest 1. januar 2026 og siden hvert femte år skal landene måle andelen af tekstil i blandet kommunalt affald. Madaffaldet skal senest i 2030 ned med 10 % i forarbejdning og fremstilling og med 30 % pr. indbygger i detailhandel, restauranter og husholdninger, målt mod 2021-2023.' },
      { id: 'NY103', title: 'Vejledning til forordning (EU) 2025/40 om emballage og emballageaffald', org: 'Europa-Kommissionen', year: 2026, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Udvidet producentansvar', 'Afsætning og behandling'], img: 'img/56da168130d276cab4bfccb46e816b90.jpg', url: 'http://publications.europa.eu/resource/cellar/50fcee7c-60e0-11f1-9b18-01aa75ed71a1.0023.02/DOC_1', res: 'Kommissionens vejledning giver i 33 afsnit sin fortolkning af udvalgte regler i EU\'s emballageforordning, som gælder fra 12. august 2026, bl.a. om pant og indsamling.', long: 'Vejledningen C(2026) 3702 svarer på spørgsmål fra myndigheder og andre interessenter om forordning (EU) 2025/40. For affaldssektoren gælder bl.a., at emballage, der opfylder kriterierne for design til genanvendelse, ikke må forbrændes eller deponeres fra 1. januar 2030. Medlemsstaterne skal fastsætte obligatoriske indsamlingsmål senest 1. januar 2029 og indsamle 90 % af engangsplastflasker og metaldåser til drikkevarer særskilt. Vil et land undgå et pantsystem, skal det nå 80 % i 2026. Affaldsoperatører skal kun indberette data, når det er nødvendigt for at krydstjekke producenternes tal, eller når medlemsstaten bestemmer det.' },
      { id: 'NY104', title: 'Development of an EU harmonised model for separate municipal waste collection', org: 'EU Joint Research Centre (JRC)', year: 2023, type: 'Analyse', temaer: ['Hente- og bringeordninger', 'Analyser og undersøgelser', 'Sorteringsvejledninger'], img: 'img/f5b506e33b046f68505cc738c36152ef.jpg', url: 'https://publications.jrc.ec.europa.eu/repository/bitstream/JRC130419/JRC130419_01.pdf', res: 'JRC\'s litteraturstudie finder, at henteordninger giver mere og renere materiale end bringeordninger, og at fælles piktogrammer er billigere at indføre end ens beholderfarver.', long: 'Rapporten er første led i JRC\'s projekt for DG Environment om, hvorvidt særskilt indsamling af kommunalt affald skal harmoniseres i EU, og bygger på litteratur gennemgået i 2021 og starten af 2022. Bioaffald, papir/pap og helst også glas bør indsamles for sig, men glas kan blandes med metal og metalemballage med plast. Betaling efter mængde (PAYT) kan mindske restaffaldet med op til 20-40 %. Med pant indsamles i gennemsnit 94 % af PET-flaskerne mod 47 % uden. Særskilt indsamling sænker miljøbelastningen, og de højere indsamlingsudgifter kan opvejes af indtægter og stordriftsfordele. Der mangler pålidelige data om renhed og fejlsortering.' },
      { id: 'NY105', title: 'Techno-scientific assessment of the management options for used and waste textiles', org: 'EU Joint Research Centre (JRC)', year: 2023, type: 'Rapport', temaer: ['Tekstil', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/29b6c2510b0292282bbad6d28636f3af.jpg', url: 'https://publications.jrc.ec.europa.eu/repository/bitstream/JRC134586/JRC134586_01.pdf', res: 'JRC har samlet den tekniske viden om brugte tekstiler og tekstilaffald i EU. Over 8 mio. tons brændes eller deponeres årligt, og genbrug giver mest for pengene og for miljøet.', long: 'Med forskere fra DTU blandt forfatterne har EU-Kommissionens forskningscenter JRC kortlagt tekstilstrømmene i EU-27 med 2019 som referenceår. Der indsamles ca. 2,4 mio. tons særskilt om året, men sorteringskapaciteten er kun 1,8 mio. tons, og ca. 48 % eksporteres efter sortering. Genanvendelseskapaciteten er 0,70-0,85 mio. tons om året, og det meste bliver til rengøringsklude og isolering. Livscyklus- og omkostningsanalyser viser, at genbrug er mest omkostningseffektivt og bedst for miljøet. Genanvendelse koster mere end forbrænding, men giver som regel en miljøgevinst. Producentansvar og end-of-waste-kriterier kan ifølge rapporten hjælpe.' },
      { id: 'NY106', title: 'Textile waste management in Europe\'s circular economy', org: 'EEA', year: 2024, type: 'Rapport', temaer: ['Tekstil', 'Data, statistikker og nøgletal', 'Hente- og bringeordninger'], img: 'img/1865cef61beea72670114cf75b69c120.jpg', url: 'https://www.eionet.europa.eu/etcs/etc-ce/products/etc-ce-report-2024-5-textile-waste-management-in-europes-circular-economy/@@download/file/Textile%20waste%20management%20in%20Europe\'s%20circular%20economy.pdf', res: 'Europæisk rapport om tekstilaffald baseret på svar fra 27 lande. Indsamlingsgraden er i gennemsnit kun 12 %, og restaffaldet rummer over dobbelt så meget som det indsamlede.', long: 'European Topic Centre on Circular Economy har skrevet rapporten for EEA ud fra et spørgeskema fra juni 2023, som 27 lande besvarede. I 2020 blev 1,95 mio. tons tekstilaffald eller 4,4 kg pr. indbygger indsamlet separat i EU27, mens restaffaldet indeholdt 11,6 kg tekstiler og sko pr. indbygger. Samlet anslås 6,95 mio. tons eller 16 kg pr. indbygger. Indsamlingsgraden er i gennemsnit 12 %, højest i Luxembourg og Belgien med 50 %. Ved udgangen af 2023 var producentansvar for tekstiler kun obligatorisk i Frankrig, Ungarn og Holland. Rapporten efterlyser en klar definition af tekstilaffald og pligt til at rapportere om indsamling og genbrug.' },
      { id: 'NY107', title: 'Measuring and enabling reuse: methods and policy insights', org: 'European Topic Centre on Circular Economy (ETC CE)', year: 2026, type: 'Rapport', temaer: ['Direkte genbrug', 'Data, statistikker og nøgletal', 'Cirkulær økonomi'], img: 'img/0748499decd5d03b74cfe4a7089cae3e.jpg', url: 'https://www.eionet.europa.eu/etcs/etc-ce/products/etc-ce-report-2026-6-measuring-and-enabling-reuse-methods-and-policy-insights/@@download/file/Measuring%20and%20enabling%20reuse_methods%20and%20policy%20insights.pdf', res: 'EU-rapport om, hvordan landene måler genbrug efter afgørelse (EU) 2021/19, og hvilke virkemidler de bruger. Tallene er svære at sammenligne, og de fleste tiltag er frivillige.', long: 'IVL og VITO har for Det Europæiske Miljøagentur analyseret landenes første indberetning af genbrug for 2021 og en rundspørge fra 2025. 26 lande indberettede tal, typisk via husstandsundersøgelser eller spørgeskemaer til genbrugsaktører, men uens definitioner og afgrænsninger gør dem svære at sammenligne. Danmark opregnede ud fra markedsandele skønnet af aktører og eksperter, hvilket giver stor usikkerhed. Blandt 252 indberettede tiltag dominerer oplysning og frivillighed, mens regulering er sjælden. Kun 13 lande har kvantitative genbrugsmål i landefaktaarkene fra 2025, og forfatterne anbefaler ensartede indikatorer og klarere vejledning.' },
      { id: 'NY108', title: 'Quantifying recycling quality in Europe', org: 'EEA', year: 2024, type: 'Rapport', temaer: ['Reel genanvendelse', 'Afsætning og behandling'], img: 'img/e8fdcb537ea7074b1d40b2475e681185.jpg', url: 'https://www.eea.europa.eu/en/analysis/publications/measuring-the-quality-of-recycling/technical-report-quantifying-recycling-quality-in-europe/@@download/file', res: 'Teknisk rapport til EEA med en ny model for kvaliteten af genanvendelse. Test på tre affaldsstrømme viser stigende kvalitet for PET og bioaffald, mens tekstiler scorer lavt.', long: 'Norion Consult og 3drivers har for Det Europæiske Miljøagentur udviklet Value Chain Model ud fra JRC\'s arbejde. Modellen vægter effektivitet og evnen til at holde materialet i kredsløb med 30 % hver og miljøpåvirkning med 40 % og samler resultatet efter markedsandele. PET-emballage steg fra 0,452 i 2018 til 0,523 i 2020, og pant med genanvendelse til ny emballage scorede højest. Bioaffald steg fra 0,394 i 2016-2017 til 0,423 i 2019-2020, mens tekstiler lå på 0,193 i 2019 på grund af lav særskilt indsamling og tab af materialeegenskaber. Forfatterne peger på store datahuller og anbefaler, at EEA udvælger få materialer til fast overvågning.' },
      { id: 'NY109', title: 'Waste prevention in the Nordics', org: 'Nordisk Ministerråd', year: 2025, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Direkte genbrug', 'Tekstil'], img: 'img/82be0486e0621cb08268c0f29bb0701f.jpg', url: 'https://pub.norden.org/temanord2025-502/temanord2025-502.pdf', res: 'Nordisk studie af tiltag, der forebygger kommunalt affald og fremmer genbrug. Landene mangler en systematisk tilgang, og økonomiske virkemidler virker bedst i kombination.', long: 'Studiet er finansieret af Nordisk Ministerråds arbejdsgruppe for cirkulær økonomi. Ud over tekstiler, som et casestudie uddyber, ser det på forbrugerelektronik og plastemballage. Forfatterne kortlagde 50 tiltag fra litteraturen, fik effekt og gennemførlighed vurderet i en ekspertundersøgelse i fem lande og analyserede 15 tiltag i dybden. Casestudiet viser, at afgifter på fast fashion efter fransk forbillede har størst potentiale, mens lavere moms på brugte varer og reparation har lille direkte effekt på affaldet. Anbefalingen er en værktøjskasse, der kobler producentansvar med regulering og økonomiske virkemidler, støttet af information.' },
      { id: 'NY110', title: 'Waste incineration in the Nordic countries', org: 'Nordisk Ministerråd', year: 2024, type: 'Rapport', temaer: ['Afsætning og behandling', 'Klima', 'Cirkulær økonomi'], img: 'img/d2ad868764b8e8f909b68f1d4f68ed99.jpg', url: 'https://pub.norden.org/temanord2024-524/temanord2024-524.pdf', res: 'Nordisk statusrapport om affaldsforbrænding. Landene har mere kapacitet, end deres eget affald kræver, og plast står for en stor del af fjernvarmens fossile CO2-udledning.', long: 'CIT Renergy, Carbon Limits og Motiva Services har for Nordisk Ministerråd samlet data og interviews om affaldsforbrænding i Norden. Danmark havde i 2020 26 anlæg med ca. 4,5 mio. tons kapacitet, og sektoren leverede 24 % af varmen til fjernvarmenettet og 4,3 % af elforsyningen. Norden har mere kapacitet, end eget affald kræver, og forskellen fyldes med importeret affald. CO2-fangst ses som en vej til lavere eller negative udledninger. Om målene for cirkulær økonomi nås, afhænger især af, hvor meget plast der bruges, og hvor godt den sorteres. Ulovlig affaldshåndtering er et problem, hvor høje gebyrer og få straffe gør det lukrativt.' },
      { id: 'NY111', title: 'Manual för plockanalys av hushållens vardagliga avfall', org: 'Avfall Sverige', year: 2025, type: 'Vejledning', temaer: ['Sorteringskvalitet', 'Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/7fd10595fab17988545a1c00d51f8844.jpg', url: 'https://www.avfallsverige.se/media/5kyfph2u/2024-20-rev-web.pdf', res: 'Svensk manual til plukanalyser af mad- og restaffald, emballage og returpapir fra husholdninger, så analyserne udføres ens og giver pålidelige resultater uanset udfører.', long: 'Miljö & Avfallsbyrån i Mälardalen har for Avfall Sverige opdateret manualen fra 2017 med erfaringer fra et projekt om kvalitetssikring af plukanalyser i 2023-2024, og i oktober 2025 blev sorteringsanvisningerne præciseret. Metoden har seks trin fra planlægning og forundersøgelse over prøveindsamling, neddeling og sortering til evaluering. Prøven skal dække mindst en uges affald, ved analyse af restaffald alene udtages mindst 500 kg, og affaldet sorteres i mindst 26 fraktioner. Der er råd om arbejdsmiljø og værnemidler og bilag med sorteringsprotokol og omkostningsberegning. Følges anvisningerne, kan resultaterne registreres i Avfall Web.' },
      { id: 'NY112', title: 'Volymvikter för avfall', org: 'Avfall Sverige', year: 2025, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Hente- og bringeordninger', 'Genbrugspladser'], img: 'img/a35b2562194bbc7e42272e33abdb0fec.jpg', url: 'https://avfallsverige.se/media/2y5mlias/2025-06-web.pdf', res: 'Avfall Sverige opdaterer volumenvægte for affald fra husstandsindsamling og genbrugspladser. Restaffald vejer 88-100 kg/m3, og madaffald i rullebeholdere vejer 192 kg/m3.', long: 'Ramboll har for Avfall Sverige opdateret volumenvægtene fra 2013 med over 20.000 målinger fra husstandsindsamling og over 11.000 fra genbrugspladser. Niveaumålere blev koblet med vejning i skraldebilerne i Växjö, Mölndal og Örebro, mens fire kommunale selskaber leverede containerdata. Restaffald fra steder med fuld sortering vejer 100 kg/m3 mod 88 kg/m3 uden, sandsynligvis fordi lette emballager sorteres fra. Madaffald vejer 192 kg/m3 i rullebeholdere og 307 kg/m3 i nedgravede beholdere, papiremballage kun 24 kg/m3. Tal for glas, metal og plast manglede og skulle først komme i andet kvartal 2025.' },
      { id: 'NY113', title: 'Kommunernes vej til cirkulær omstilling', org: 'Gate 21', year: 2021, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Direkte genbrug', 'Tekstil'], img: 'img/f1cacbf33a2ca1f66d48ff7c5de55938.jpg', url: 'https://rucforsk.ruc.dk/ws/files/78497711/Kommunernes_rolle_i_den_cirkul_re_omstilling.pdf', res: 'Gate 21 samler erfaringerne fra seks pilotprojekter i Partnerskab for Cirkulære Kommuner, bl.a. genbrug af byggematerialer på Bornholm og indsamling af tekstiler i Rødovre.', long: 'Projektet i Partnerskab for Cirkulære Kommuner kørte fra 2018 til 2021, drevet af Gate 21, RUC og Concito. På Bornholm kan genbrug af materialer fra nedrivninger skønsmæssigt spare 10 mio. kr., 333 ton CO2 og 1.832 ton affald over ti år. I Albertslund hentede eller afleverede i snit 170 borgere om ugen byggematerialer i Byt et Bræt på genbrugspladsen. I Hørsholm sorterer Norfors storskrald, så genbrugelige ting går til frivillige organisationer. I Rødovres tekstilforsøg kunne ca. en tredjedel genbruges og halvdelen genanvendes, og ordningen blev permanent. Rudersdal og Bornholm udviklede værktøjer til affaldstilsyn hos mindre virksomheder.' },
      { id: 'NY114', title: 'The influence of recycling schemes on the composition and generation of municipal solid waste', org: 'DTU og Econet', year: 2021, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/9278413daa4d0eab8c37efe42ed17d66.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/244601644/postscrip_manuscript.pdf', res: 'Videnskabelig artikel om 20 ton håndsorteret affald fra syv kommuner. Hvor både mad og plast blev sorteret fra, var der under halvt så meget restaffald som uden de ordninger.', long: 'Forskere fra DTU og Econet håndsorterede i 2011 og 2017 ca. 20 ton affald fra 1.800 husstande i Gladsaxe, Helsingør, Kolding, Viborg, Odsherred, Aabenraa og Rødovre. Uden særskilt indsamling af mad og plast var restaffaldet 3,7-4,1 kg pr. person pr. uge, mens det var 1,7 kg i Rødovre, hvor begge dele blev sorteret fra. Den samlede mængde var 11 % lavere i Rødovre end i kommunerne uden de to ordninger. Fejlsorteringen var størst i beholderne til madaffald, plast og restaffald. Artiklen er trykt i Journal of Cleaner Production og anbefaler, at livscyklusvurderinger regner med forskellig sammensætning af restaffaldet for hver ordning.' },
      { id: 'NY115', title: 'Combustible waste collected at Danish recycling centres', org: 'DTU Miljø', year: 2019, type: 'Analyse', temaer: ['Genbrugspladser', 'Sorteringskvalitet', 'Klima'], img: 'img/81c82ad623025f91de77a4f33d0c2822.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/178139041/WM_18_3225R1_revised_version_orbit_002_.pdf', res: 'DTU sorterede 25 tons småt brændbart fra otte genbrugspladser. Mellem 47 og 64 % kunne genanvendes, især tekstiler, plast og papir, mens under halvdelen var reelt brændbart.', long: 'Artiklen fra DTU Miljø er bragt i tidsskriftet Waste Management og finansieret af Miljøstyrelsen. Fra marts 2016 til juni 2017 blev ca. 25 tons småt brændbart fra genbrugspladser i Silkeborg, Lemvig, Roskilde, Hvidovre og Høje Taastrup sorteret i materialefraktioner. Tekstiler udgjorde i gennemsnit 13 %, plast 12 %, papir 10 % og træ 9 %. Sendte man de genanvendelige materialer til genanvendelse, ville genanvendelsen af husholdningsaffald i studiets beregning stige fra 27 til 30 %. Klimagevinsten ville vokse med 150.000 tons CO2-ækv. om året, 30 % mere end i dag, og 96 % af den kommer fra plast, tekstil og papir.' },
      { id: 'NY116', title: 'Environmental assessment of amending Amager Bakke with carbon capture and storage', org: 'DTU', year: 2022, type: 'Analyse', temaer: ['Klima', 'Afsætning og behandling', 'Teknologi'], img: 'img/4f56df5377ab7123e451f798421ae163.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/269721243/0734242x211048125.pdf', res: 'Livscyklusvurdering af CO2-fangst og lagring på forbrændingsanlægget Amager Bakke. CCS kan forbedre anlæggets klimaregnskab med ca. 820 kg CO2-ækv. pr. ton affald.', long: 'Forskere fra DTU har med ARC og Ramboll vurderet miljøeffekten af at udbygge Amager Bakke (600.000 ton affald om året) med CO2-fangst efter forbrændingen. Studiet er finansieret af ARC og bygger på anlæggets drifts- og emissionsdata fra 2020 og scenarier for affaldets sammensætning og energisystemet. Fangsten sænker elproduktionen fra ca. 615 til 310 kWh pr. ton, mens varmen stiger fra 9,1 til 9,5 GJ pr. ton. Med 90 % fangst går anlægget fra en klimabelastning på 140 kg til en besparelse på 680 kg CO2-ækv. pr. ton. Fuld CCS kan spare omkring 500.000 ton CO2 om året, og stigningen i andre miljøpåvirkninger er langt mindre end klimagevinsten.' },
      { id: 'NY117', title: 'Hjemtagning af affaldsindsamling. Tillægsnotat vedr. fælleskommunale løsninger', org: 'Brøndby Kommune', year: 2020, type: 'Notat', temaer: ['Ledelse', 'Udbud og kravspecifikationer', 'Økonomi'], img: 'img/85e65f58d30bd0464ec07b00256f7623.jpg', url: 'https://dagsordener.brondby.dk/vis/pdf/bilag/a06752cc-c4d4-4c0d-97f9-158ab50aa361', res: 'Tillæg til Brøndby Kommunes analyse af hjemtagning, som vurderer fælles indsamling med andre kommuner. Ingen løsning er med sikkerhed billigere end udbud eller hjemtagning.', long: 'Notatet supplerer en rapport fra 29. oktober 2019 om hjemtagning af indsamlingen i Brøndby med to scenarier for et fælleskommunalt samarbejde med enten én eller fem kommuner. Det gennemgår lovgrundlaget og sammenligner samarbejde uden selskab, I/S, a.m.b.a. og A/S, bl.a. på hæftelse og instruktionsbeføjelse. Beregningerne medtager 0,9-1,1 mio. kr. om året til direktør og billigere reservebiler og faciliteter, jo større samarbejdet er. Inden for en usikkerhed på 15 % er ingen løsning sikkert billigst, så diskussionen bør handle om servicen. Et fælles selskab mindsker sårbarheden ved en lille organisation, men giver mindre direkte styring.' },
      { id: 'NY118', title: 'Tekstil-innovation. Fra gamle underhylere til nye byggematerialer', org: 'AffaldPlus', year: 2020, type: 'Rapport', temaer: ['Tekstil', 'Cirkulær økonomi', 'Afsætning og behandling'], img: 'img/774e8ddfd603ef72f2c39bcb65994e7b.jpg', url: 'https://affaldplus.dk/sites/default/files/2021-12/FUTURE-Tekstilinnovation-AffaldPlus-Ramboll-Lendager_rapport_tilprint.pdf', res: 'Lendager Group, AffaldPlus og Rambøll har vist, at tekstilaffald, som ikke kan genbruges eller genanvendes, kan blive til isolering og til akustikpaneler i absorptionsklasse A.', long: 'Rapporten blev lavet i februar 2020 for udviklingsprojektet FUTURE og tager udgangspunkt i de ca. 26.000 tons tekstilaffald om året i Danmark, som ikke kan genbruges eller genanvendes og derfor brændes. AffaldPlus sorterede resttekstilerne fra sin indsamling af tøj og sko, og Eurofins fandt kun ét af 191 stoffer på REACH-kandidatlisten, DEHP, over detektionsgrænsen og langt under grænsen på 0,1 %. Isoleringsmåtten fik en lambdaværdi på 0,039 W/mK. En LCA giver 7 kg CO2e pr. m2 for akustikpanelet mod 14,4 kg for stenuld. Brandtest peger på brandklasse D til B afhængigt af brandhæmmer, og brandkravene gør vejen til markedet svær.' },
      { id: 'NY119', title: 'Vurdering af drivmidler til renovationsbiler', org: 'Favrskov Forsyning, Renosyd og Reno Djurs', year: 2021, type: 'Notat', temaer: ['Klima', 'Teknologi', 'Udbud og kravspecifikationer'], img: 'img/4ea7bb8c59a53c53e37725f9cf3d72e4.jpg', url: 'https://renodjurs.dk/sites/default/files/2021-06/Bilag%209_Alternative%20drivmidler.pdf', res: 'COWI sammenligner diesel, HVO og el til renovationsbiler for tre affaldsselskaber. HVO og el sparer mest CO2, men alternativerne gør ordningerne ca. 3-15 % dyrere end diesel.', long: 'Notatet er skrevet af COWI i maj 2021 for Favrskov Forsyning, RenoSyd og Reno Djurs, så selskaberne kan beslutte krav til drivmidler i kommende udbud. Det vurderer diesel og HVO med og uden eldreven lift og komprimator samt rene elbiler ud fra oplysninger for 2020. Pr. ton affald udleder en dieselbil 11,4 kg CO2, HVO 1,1 kg og en elbil på gennemsnitlig dansk el 2,3 kg. En elbil koster ca. 4,2 mio. kr. mod 2,1 mio. kr. for en dieselbil og har en rækkevidde på ca. 120 km ved indsamling, så den egner sig bedst til tæt bebyggelse. COWI anbefaler at vælge drivmiddel før udbuddet og gøre det til et mindstekrav.' },
      { id: 'NY120', title: 'Virkemiddelkatalog for affaldsforebyggelse', org: 'Miljøstyrelsen', year: 2022, type: 'Analyse', temaer: ['Cirkulær økonomi', 'Analyser og undersøgelser', 'Økonomi'], img: 'img/0689c51710d5786e1de057104a80a8ab.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2022/08/978-87-7038-438-4.pdf', res: 'COWI har regnet på seks virkemidler til affaldsforebyggelse for Miljøstyrelsen. Samlet kan de mindske husholdningsaffald og lignende med 1-2,5 %, eller 50.000-120.000 ton årligt.', long: 'Kataloget er lavet af COWI i 2021-2022 som forberedelse til kommende EU-mål for affaldsforebyggelse. Seks virkemidler, bl.a. Reklamer ja tak, mere donation af overskudsfødevarer, krav om genbrug af usolgt tøj og forbud mod gratis udlevering af engangsservice, er regnet igennem for 2025-2035 mod en baseline på ca. 4,8 mio. ton i 2025. Størst effekt har øget donation af overskudsfødevarer med op til 90.509 ton madaffald om året. Affaldshåndteringen bliver 50-140 mio. kr. billigere, og staten mister 380-670 mio. kr. i indtægter om året. Rapporten peger på store usikkerheder, bl.a. fordi flytning af forbrug til andre varer ikke er medregnet.' },
      { id: 'NY121', title: 'Survey om affaldssortering', org: 'Miljøstyrelsen', year: 2022, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Kommunikation', 'Sorteringskvalitet'], img: 'img/33ea60e061401631a3bb364b581f673e.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2022/01/978-87-7038-383-7.pdf', res: 'Rambølls survey for Miljøstyrelsen blandt 1.009 voksne om sorteringsvaner. 78 % synes godt om de 10 nye affaldstyper, men knap halvdelen af dem finder det besværligt.', long: 'Rambøll gennemførte undersøgelsen for Miljøstyrelsen i sensommeren 2021, op til de nye krav om ens sortering i 10 affaldstyper. Der kom svar fra 1.009 personer på 18 år eller derover fra hele landet. Blandt dem mener 79 %, at sortering er nødvendig for at passe på miljø og klima, og 60 % vil gerne vide mere om, hvad der sker med affaldet efter sorteringen. Glas og papir blev vurderet som nemmest at sortere og tekstiler og mad- og drikkekartoner som sværest. Mange fritekstsvar nævner manglende beholdere, pladsmangel, lugt og tvivl om, hvorvidt affaldet reelt bliver genanvendt. Et afsnit handler om tøj og tekstiler.' },
      { id: 'NY122', title: 'Undersøgelse af andre kommuner/selskabers kemirum', org: 'Reno Djurs', year: 2023, type: 'Rapport', temaer: ['Genbrugspladser', 'Ledelse'], img: 'img/2afae63d8e38d9ca061ceddbbfecd8bc.jpg', url: 'https://renodjurs.dk/sites/default/files/2023-12/Bilag%2031.1_Unders%C3%B8gelse%20af%20andre%20genbrugspladsers%20kemirum.pdf', res: 'Arbejdsmiljøcenter Midt-Vest har for Reno Djurs besøgt kemirum på over 20 genbrugspladser. Konklusionen er, at løbende ventilation betyder mere end typen af udsugning.', long: 'Arbejdsmiljøcenter Midt-Vest besøgte i august 2023 over 20 genbrugspladser hos bl.a. Revas, Silkeborg Forsyning, Kredsløb, RenoSyd og Nomi4S og sammenlignede kemirummene med Reno Djurs\' rum, der har rumventilation med ca. 2,5 luftskifte i timen. Løsningerne deles i seks grupper fra ingen udsugning til tøndeudsugning med automatisk oplukning. Hvor man havde valgt mere end Reno Djurs, byggede valget ikke på lovkrav eller målinger. Lugtgener blev især nævnt, hvor tønderne står med låg, og flere pegede på tunge løft af fx oliedunke over 20 kg som den største udfordring. Tøndeudsugning blev mest valgt i rum til husstandsindsamlede miljøkasser.' },
      { id: 'NY123', title: 'Notat om minimumsmodeller suppleret med bemærkninger om rammerne for ledelse', org: 'Københavns Kommune', year: 2024, type: 'Notat', temaer: ['Ledelse', 'Lovgivning og afgørelser'], img: 'img/546b96bf52b1da5ebc0e7aa012131497.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/6f65c288-7a78-49f5-a4fd-79b009a00776/6768a5ce-4249-443a-adfd-012720654f2b-bilag-5_0.pdf', res: 'DLA Piper beskriver to modeller for at udskille ARC\'s forbrændingsanlæg i et aktieselskab i 2024, en enkel model og en med holding- og serviceselskab, hvor alle ansatte samles.', long: 'Advokatfirmaet DLA Piper skrev notatet efter et møde i forligskredsen på Københavns Rådhus i februar 2024. I minimumsmodellen stiftes ARC Affaldsenergi A/S under I/S Amager Ressourcecenter og overtager affaldskraftvarmeanlægget, mens indsamling og genbrugsstationer bliver i I/S\'et. Den anden model tilføjer ARC Holding A/S og ARC Service A/S, hvor alle medarbejdere ansættes. Ejerkommunerne får ingen instruktionsbeføjelse over aktieselskabernes bestyrelser. Begge modeller opfylder lovkravet fra 1. januar 2025. Kommer der krav om selskabsgørelse af resten af affaldsområdet, anbefales modellen med serviceselskab, ellers den enkle model.' },
      { id: 'NY124', title: 'Hvem tager skraldet? Renovationsbranchen og psykisk arbejdsmiljø i den grønne omstilling', org: 'ARI', year: 2024, type: 'Rapport', temaer: ['Ledelse', 'Analyser og undersøgelser', 'Hente- og bringeordninger'], img: 'img/2e05770c1d90ae62c9aaedf842486116.jpg', url: 'https://www.vellivforeningen.dk/media/cfpj1gp4/hvem-tager-skraldet-lang.pdf', res: 'Undersøgelse af psykisk arbejdsmiljø i renovationsbranchen under den grønne omstilling. 34 % af chaufførerne har oplevet chikane, men de fleste er glade for deres job.', long: 'ARI og konsulenthuset Behave Green har med støtte fra Velliv Foreningen undersøgt, hvordan den grønne omstilling påvirker det psykiske arbejdsmiljø i fire renovationsvirksomheder. Grundlaget er 417 spørgeskemasvar, 27 telefoninterviews, syv ture på ruterne og to workshops. Medarbejderne sætter pris på friheden, men længere arbejdsdage, fejlsorteringer, trafik og modsatrettede krav trækker ned. 34 % af chaufførerne og 23 % af de administrative har oplevet chikane, mens 86 % og 98 % føler sig trygge. Rapporten anbefaler faste processer for psykisk arbejdsmiljø, opkvalificering, bedre samarbejde med kommunerne og mere synlig ledelse.' },
      { id: 'NY125', title: 'Redegørelse omkring håndtering af moms og tilbagesøgningskrav på moms på affaldsområdet', org: 'Middelfart Kommune', year: 2025, type: 'Notat', temaer: ['Økonomi', 'Lovgivning og afgørelser'], img: 'img/e7eb52868b42917210211925f3fbd552.jpg', url: 'https://cdn1.gopublic.dk/middelfartkommune/Media/638828228090226953/Redegrelse%20omkring%20hndtering%20af%20moms%20og%20tilbagesgningskrav%20p%20moms%20p%20affaldsomrdet.pdf', res: 'Middelfart Kommune forklarer, hvorfor den blev ved med at opkræve moms på affald frem til selskabsgørelsen, og hvordan 30,1 mio. kr. i tilbagesøgt moms skal tilbage til borgerne.', long: 'Notatet fra januar 2025 gennemgår kommunens momshåndtering efter Landsskatterettens afgørelse i 2020 og Skattestyrelsens styresignal af 3. november 2023. Kommunen fortsatte med at opkræve moms for at undgå udsving i taksterne og selskabsgjorde affaldsområdet pr. 1. september 2024. EY Revision søgte på kommunens vegne 30,1 mio. kr. netto tilbage for 2012-2023. Forvaltningen og EY anbefaler at føre pengene tilbage via lavere takster, fordi direkte tilbagebetaling er administrativt tungt, og debitordata ikke findes længere tilbage end 2017. Sagen skal behandles politisk, når Skattestyrelsen har svaret.' },
      { id: 'NY126', title: 'Status - Analyse af Genbrugsstationer 2023', org: 'Odense Renovation', year: 2023, type: 'Analyse', temaer: ['Genbrugspladser', 'Analyser og undersøgelser', 'Byggeaffald'], img: 'img/a17cf43f1b4203a249a42ecf0e052314.jpg', url: 'https://dagsordener.odense.dk/vis/pdf/bilag/832af38f-2147-4184-a085-471f5f2a1d83', res: 'Odense Renovations servicetjek af kommunens 8 genbrugsstationer. Ingen station lever op til alle parametre, og færre, større stationer kan give bedre service og arealudnyttelse.', long: 'Analysen sammenligner Odenses stationer med Aarhus, Aalborg, Svendborg og Kerteminde på køretid, besøg, mængder og bemanding og vurderer hver station på service, økonomi, arbejdsmiljø og miljø. Odense har 34 besøg pr. åbningstime mod 72 i Aarhus, og borgerne afleverer i snit ca. 48 kg pr. besøg, omtrent halvt så meget som i Aarhus. Overskuelige stationer, hvor tunge fraktioner let kan aflæsses, betyder mere for borgernes valg af station end kort køretid. Rapporten screener udvidelsesmuligheder, skitserer Havnegade og Energivej som stationer for bygge- og anlægsaffald og ser ingen umiddelbar grund til at flytte genbrugsbutikken Zirkel.' },
      { id: 'NY127', title: 'Nem adgang til genbrug og genanvendelse for alle: koncept for fremtidens genbrug i Odense', org: 'Odense Renovation A/S og Odense Kommune', year: 2024, type: 'Strategi', temaer: ['Genbrugspladser', 'Direkte genbrug', 'Affaldsplaner/regulativer og strategi'], img: 'img/208a0dd95188aea4986e2bc51fb2aac6.jpg', url: 'https://dagsordener.odense.dk/vis/pdf/bilag/a01e0e2a-b692-487b-a64f-2678acb764bd', res: 'Odenses koncept for en ny genbrugsstruktur med store og små genbrugsstationer, byttebokse og genbrugspunkter. Gebyret ventes at stige ca. 175 kr. pr. husstand frem mod 2031.', long: 'Konceptet skal give alle i Odense nem adgang til genbrug, også de ca. 44 % af familierne, der ikke har bil. Det består af få store genbrugsstationer, hvor alle fraktioner kan afleveres inden for 15 minutters kørsel, små gå- og cykelvenlige stationer i tæt by, beboergenbrugspunkter sammen med boligorganisationer, byttebokse ved fx letbanestop og en henteservice, der først spørger, om tingene kan genbruges. Op mod 4.200 ton kan flyttes fra forbrænding til genanvendelse, og 2.000 ton genbrugelige effekter samles ind om året. Udrulningen sker i tre etaper fra 2025, og i 2031 ventes gebyret at ligge ca. 175 kr. højere pr. husstand end i 2024.' },
      { id: 'NY128', title: 'Affaldshåndtering i Dronningensgadekvarteret: 3 scenarier', org: 'Odense Renovation', year: 2022, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Økonomi', 'Teknologi'], img: 'img/2327d307132e4e52742186f72fdb6daf.jpg', url: 'https://dagsordener.odense.dk/vis/pdf/bilag/f48b0418-8733-4bd9-a72f-f75a1febd61c', res: 'Odense Renovation vurderer tre scenarier for affaldet i det tætte Dronningensgadekvarter. Affaldssug koster 60,7 mio. kr. at anlægge, nedgravede beholdere 6,8 mio. kr.', long: 'Notatet fra december 2022 beskriver et kvarter, hvor 44 spande stod fast på fortovet ved en inspektion i 2020, og hvor 50 adresser har sække. Letbanen spærrer desuden skraldebilen ude fra 38 matrikler på Vestre Stationsvej. Scenarie 1 fortsætter med spande og sække. Scenarie 2 placerer 52 nedgravede beholdere på 19 steder og koster 26-30 p-pladser, mens scenarie 3 kobler kvarteret på affaldssuget med ca. 2.000 meter rør og 45 indkast. Over 30 år er omkostningerne beregnet til 21,1, 31,7 og 103,0 mio. kr. Affaldssuget har de laveste driftsudgifter og kortere gåafstande end de nedgravede beholdere.' },
      { id: 'NY129', title: 'Etablering af omlasteanlæg for affald og genbrugsø', org: 'Kerteminde Forsyning', year: 2023, type: 'Analyse', temaer: ['Afsætning og behandling', 'Genbrugspladser', 'Økonomi'], img: 'img/7c313f0428a89e09d325cfbc89a06b2c.jpg', url: 'https://dagsordener.kerteminde.dk/vis/pdf/bilag/3e3e298e-435e-4fb8-b69e-b10065f2f19b', res: 'COWI-notat for Kerteminde Forsyning om omlasteanlæg og genbrugsø i Munkebo. Omlastning sparer ca. 60.000 kr. om året, og en plansiloløsning anbefales til genbrugsøen.', long: 'COWI har for Kerteminde Forsyning vurderet et omlasteanlæg i Munkebo for husstandsindsamlet affald ud fra en fremskrivning til 6.474 ton i 2023. Omlastning sænker transportudgiften fra ca. 1,62 til 0,36 mio. kr. om året, men anlægget koster 15,9 mio. kr. og ca. 1,2 mio. kr. årligt med drift, forrentning og afdrag, så gevinsten er ca. 60.000 kr. om året. Ifølge CO2-bilaget falder transportens udledning fra 682 til 126 kg CO2-ækv. om året, men med byggeriet medregnet stiger den samlede udledning med 8.344 kg om året. Tre løsninger for genbrugsøen koster 7,2-13,3 mio. kr., og plansiloløsningen anbefales som billigst og bedst for kunderne.' },
      { id: 'NY130', title: 'Kravspecifikation, udbud af affaldsindsamling', org: 'Nordfyns Kommune', year: 2021, type: 'Rapport', temaer: ['Udbud og kravspecifikationer', 'Hente- og bringeordninger'], img: 'img/ec4a4190ad375693ffd7d68c90b02433.jpg', url: 'https://dagsordener.nordfynskommune.dk/vis/pdf/bilag/f57ba26c-9443-4124-a6e0-f5539b54125d', res: 'Rambøll har skrevet kravspecifikationen til Nordfyns Kommunes udbud af husstandsindsamling 2022-2028. Den kræver tømning på samme ugedag og sætter krav til biler og mandskab.', long: 'Bilag 1 til Nordfyns Kommunes udbud er fra februar 2021 og beskriver, hvordan husstandenes affald skal indsamles, fra mad- og restaffald til haveaffald og poser med batterier og småt elektronik på låget. Ordningen omfatter i dag ca. 47.600 beholdere og 1.165.000 tømninger om året ved bl.a. 11.550 enfamiliehuse og 3.200 sommerhuse. Alle fraktioner undtagen haveaffald skal hentes på samme ugedag. Senest fra juli 2024 skal mindst én elbil på grøn strøm køre og endnu én fra juli 2025, mens de øvrige biler skal have Euro 6-motorer og køre på anden generations HVO. Tekstil i poser på låget er med som option, fordi lovgivningen var uafklaret.' },
      { id: 'NY131', title: 'Katalog for serviceniveau ifm. husstandsindsamling i Assens Kommune', org: 'Assens Affald & Genbrug', year: 2022, type: 'Notat', temaer: ['Økonomi', 'Hente- og bringeordninger', 'Sommerhuse og kolonihaver'], img: 'img/006f843427a446ea3159c270388d14ac.jpg', url: 'https://dagsorden.assens.dk/vis/pdf/bilag/80b6dc49-f401-4586-aba0-a48fd1e3d744', res: 'Rambøll har beregnet, hvad Assens kan spare ved at ændre tømningsfrekvenser i husstandsindsamlingen, fx 2,3 mio. kr. om året uden ugetømning af rest- og madaffald om sommeren.', long: 'Rambøll skrev notatet i april 2022 for Assens Affald & Genbrug før den nye ordning 1. april 2023. Tallene bygger på antal beholdere ultimo 2021 og gennemsnitlige tømningspriser ekskl. moms. Tømning hver 4. uge frem for hver 3. uge sparer ca. 1,5 mio. kr. årligt for beholderen til papir, pap, metal og glas og ca. 1,6 mio. kr. for plast og kartoner, mens tømning af plastbeholderen hver 2. uge koster 3,2 mio. kr. mere. Sommertømning som tilvalg anslås til ca. 150 kr. årligt for en 2-delt 240 liters beholder. Med en fællesstation i sommerhusområder koster restaffald ca. 5 kr. pr. husstand pr. tømning mod 17-18 kr. for egen beholder.' },
      { id: 'NY132', title: 'Affald ved sommerhuse', org: 'Assens Affald & Genbrug', year: 2022, type: 'Notat', temaer: ['Sommerhuse og kolonihaver', 'Hente- og bringeordninger', 'Økonomi'], img: 'img/9ee93af261eef45f28b64b09b7007a14.jpg', url: 'https://dagsorden.assens.dk/vis/pdf/bilag/cf3be3d7-74f2-4ddc-975b-92fda04e4ebc', res: 'Rambøll sammenligner for Assens Affald & Genbrug tre indsamlingsløsninger i sommerhusområder. Beholdere ved huset giver høj effektivitet, mens fællesstationer alene er billigst.', long: 'Notatet fra august 2022 skulle hjælpe Assens Kommune med at vælge løsning i sommerhusområderne. Scenarierne holdes op mod vejledningen om indsamling af husholdningsaffald fra juli 2022. Alle fraktioner ved sommerhuset følger vejledningen og giver høj indsamlingseffektivitet, men pladsmangel og smalle veje kan give problemer, og tømningen koster ca. 1.144 kr. ekskl. moms pr. husstand årligt. Rest- og madaffald ved huset og resten i fællesstationer koster 1.046 kr. og følger ikke direkte vejledningen. Kun fællesstationer i gåafstand følger vejledningen og koster ca. 900 kr., men ventes at give lav effektivitet. Priserne dækker kun tømning.' },
      { id: 'NY133', title: 'Moms på renovationsydelser - Anbefaling vedrørende valg af tilbagebetalingsmodel', org: 'Middelfart Kommune', year: 2026, type: 'Notat', temaer: ['Økonomi', 'Lovgivning og afgørelser'], img: 'img/acc35aabfb91c68777a1b8118d7e02a8.jpg', url: 'https://dagsordener.middelfart.dk/vis/pdf/bilag/7e9cdb4e-c615-4c99-a476-7032a520241d', res: 'EY anbefaler Middelfart Kommune at føre ca. 57,7 mio. kr. i tilbagebetalt moms og renter tilbage via de fremtidige affaldstakster frem for at udbetale beløbet direkte.', long: 'EY har skrevet notatet til Middelfart Kommune i juni 2026, efter at Skattestyrelsen godkendte kommunens krav om tilbagebetaling af moms på renovationsydelser for 2012 til august 2024. Kommunen får 35.020.048 kr., og med en skønnet rentekompensation på 22.644.000 kr. ventes ca. 57,7 mio. kr. i alt. Direkte udbetaling frarådes, fordi der kun findes valide regningsdata fra 2020, og kommunen skønner opgaven til 83.342 timer og ca. 32 mio. kr. internt eller ca. 100 mio. kr. hos et konsulenthus. EY anbefaler i stedet at indregne beløbet i taksterne hos Middelfart Affald & Genbrug A/S, fx ved at nedbringe gæld eller sænke taksterne for 2027 og 2028.' },
      { id: 'NY134', title: 'Yderligere oplysninger til Kommunalbestyrelsesmøde', org: 'Svendborg Kommune', year: 2023, type: 'Notat', temaer: ['Affaldsplaner/regulativer og strategi', 'Hente- og bringeordninger', 'Storskraldsordning'], img: 'img/30573975694a1c2d5eabe46334d1d769.jpg', url: 'https://dagsordener.svendborg.dk/vis/pdf/bilag/8dec196f-d133-4d38-9b30-501cc9c06fba', res: 'Svendborg Kommune sammenligner sit forslag til affaldsregulativ med Assens og Faaborg-Midtfyn, især om beholdere ved private veje i landområder og om Genbrugsbilen.', long: 'Bilaget blev lavet til kommunalbestyrelsen i Svendborg som baggrund for et nyt regulativ for husholdningsaffald. Assens og Faaborg-Midtfyn er valgt, fordi de ligner Svendborg i befolkning og fordeling mellem land og by. Begge kræver også, at beholdere ved private veje i landområder stilles i skel, men Svendborg henter gratis op til 2 meter inde på grunden. Ingen af dem har en ordning som Svendborgs månedlige Genbrugsbil, og skal den køre ad alle private fællesveje, kræver det flere biler. Beboere på private fællesveje skal bære poserne til enden af vejen. Kravene til afhentning præciserer gældende regler.' },
      { id: 'NY135', title: 'Scenarier for fremtidig takststruktur for husholdningsaffald', org: 'Arwos', year: 2025, type: 'Notat', temaer: ['Økonomi'], img: 'img/13e1e10293f55d71d8cf625520eb2c81.jpg', url: 'https://dagsordener.aabenraa.dk/vis/pdf/bilag/4972fbb3-4387-47eb-b41e-d9360ca715f4', res: 'Arwos opstiller tre scenarier for takststrukturen for husholdningsaffald i Aabenraa. To bygger på BBR-boligtyper og hæver taksten med op til ca. 900 kr. for nogle lejligheder.', long: 'Notatet fra maj 2025 er baggrund for en indstilling i Aabenraa Kommune. Et parcelhus betaler i 2025 en fast takst på 3.402,50 kr. inkl. moms plus 776,25 kr. for restaffald. Scenarie 1 fastholder de nuværende boligtyper med indeks 50 for blandt andet lejligheder i ejendomme med over 8 boliger. Scenarie 2 følger de fleste kommuner med indeks 75 for alle lejligheder og 30 for kollegieboliger, så ca. 3.500 lejligheder i store ejendomme stiger ca. 800 kr., mens ca. 2.500 lejligheder, der i dag betaler som parcelhuse, falder lige så meget. Scenarie 3 tilføjer rækkehuse med indeks 80. Beløbene er omtrentlige indtil takstgodkendelsen ultimo 2025.' },
      { id: 'NY136', title: 'Anbefalinger vedr. takstfastsættelse affald/genbrug', org: 'Provas', year: 2022, type: 'Notat', temaer: ['Økonomi', 'Sommerhuse og kolonihaver', 'Hente- og bringeordninger'], img: 'img/26aec708ca6df7fb2e92069e19c3f43c.jpg', url: 'https://dagsordener.haderslev.dk/vis/pdf/bilag/a2e09b2c-2070-4354-a4c4-5a06d05decda', res: 'Provas\' bestyrelse anbefaler Haderslev Kommune et grundgebyr med faktorer efter boligtype, fx 0,6 for sommerhuse, og mulighed for bringeordning i sommerhusområder en del af året.', long: 'Haderslev Affald A/S (Provas) skrev notatet efter bestyrelsens delevaluering af den nye husstandsindsamling 29. august 2022. Anbefalingerne flytter udgifter mellem husstandene, men ændrer ikke de samlede omkostninger. Grundgebyret er i dag 2.643 kr./år for en almindelig bolig. Bestyrelsen foreslår faktor 1 for villaer, rækkehuse og etageboliger, 0,6 for ældreboliger, ungdomsboliger og sommerhuse, 0,2 for kolonihavehuse og værelser og 0 for ubeboede ejendomme. Madaffald bør indgå i grundgebyret som gennemsnitstakst. Sommerhusområder bør kunne få bringeordning en del af året og sække, hvor beholderne ellers skal flyttes ud til vejen.' },
      { id: 'NY137', title: 'Model for indsamling af genbrugsaffald fra private husstande', org: 'Tønder Kommune og Tønder Forsyning', year: 2022, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Økonomi', 'Haveboliger/parcelhuse'], img: 'img/31005401eb2491d1510176211aed6863.jpg', url: 'https://dagsordener.toender.dk/vis/pdf/bilag/aaae6bd8-a9ce-4d54-bd9c-ea1c01eae9e3', res: 'Tønder Forsyning sammenligner to beholdermodeller til de genanvendelige fraktioner. Den billigste giver en takststigning på 353 kr. om året for en standardhusstand.', long: 'Notatet fra januar 2022 skyldes, at affaldsbekendtgørelsen kræver ti affaldstyper hentet ved husstanden, og at den fælles indsamling af metal, glas og hård plast skal stoppe 31. marts 2023. Tønder Forsyning har regnet på 11 scenarier og sendt to i høring. I scenarie A kommer glas og metal i den eksisterende 240 liters beholder tømt hver 12. uge, og papir, pap, plast og mad- og drikkekartoner i en ny todelt 370 liters beholder tømt hver 4. uge. Det koster 16,9 mio. kr. i investering og 10,5 mio. kr. i årlig drift og er samlet billigst af de 11. Scenarie B med to 240 liters beholdere tømt hver 4. uge fylder mindre, men øger taksten med 480 kr.' },
      { id: 'NY138', title: 'Kortlægningsdel 2023-2028, Esbjerg Kommune', org: 'Esbjerg Kommune', year: 2023, type: 'Rapport', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Hente- og bringeordninger'], img: 'img/55118f419b7a66248812f5037a00be2f.jpg', url: 'https://dagsordener.esbjergkommune.dk/vis/pdf/bilag/29ab1e06-8cd2-47e4-b1e5-0929be592187', res: 'Kortlægningen bag Esbjerg Kommunes affaldsplan 2023-2028 opgør affaldsmængder 2017-2021, ordninger, anlæg og gebyrer og beskriver den nye indsamling fra 2025.', long: 'Kortlægningen bygger på kommunens egne opgørelser og Affaldsdatasystemet, og prognosen på Miljøstyrelsens model FRIDA. Affald fra de kommunale ordninger steg fra 99.165 tons i 2017 til 105.884 tons i 2021, og kommunen tilskriver stigningen i 2020 og 2021 covid-19. Restaffaldet faldt til 19.085 tons i 2021, efter at madaffald blev sorteret fra i oktober 2020. I 2030 ventes 126.411 tons. Fra 2025 får enfamilieboligerne en todelt beholder til mad og rest samt beholdere til papir/pap/tekstil og metal/glas/plast/kartoner. Det skønnes at koste ca. 200 kr. mere pr. husstand om året, oven i et renovationsbidrag på 2.657 kr. i 2022 ved 140 liter.' },
      { id: 'NY139', title: 'Optimering af processer for virksomhedsordning på Vejen Kommunes genbrugspladser', org: 'Vejen Kommune', year: 2022, type: 'Analyse', temaer: ['Genbrugspladser', 'Erhverv', 'Teknologi'], img: 'img/5346e308484baab232f0305ca8eaacc0.jpg', url: 'https://dagsordener.vejen.dk/vis/pdf/bilag/442adddf-d2fa-43a7-a8e2-80a82b77caa3', res: 'Business casen anbefaler, at Vejen Kommune indfører automatisk nummerpladegenkendelse på genbrugspladserne, så erhvervskunder registreres og faktureres automatisk.', long: 'Vejen Kommunes business case fra juli 2022 anbefaler at købe Optidatas OptiLPR med moduler som PayByPlate til kortbetaling og en app til varesalg. I dag skal virksomheder tilmelde sig hvert år, biler med årsabonnement skal vise et årskort i ruden, og pladsmedarbejderne skal opsøge biler med papegøjeplader. Målet er, at alle indkørsler med erhvervsaffald registreres og faktureres, så taksterne kan fastsættes uden krydssubsidiering mellem private og erhverv. Via appen skal der betales for farligt affald og købes bigbags til asbest. Nettoværdien kan ikke opgøres, men andre kommuners erfaringer tyder på, at systemet hurtigt er tjent hjem.' },
      { id: 'NY140', title: 'Vejle Kommunes Affalds- og Ressourceplan 2025-2037. Bilag 2: Kortlægning', org: 'Vejle Kommune', year: 2025, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Affaldsplaner/regulativer og strategi', 'Genbrugspladser'], img: 'img/267d33cf482e0577dc888d2515f5591f.jpg', url: 'https://dagsordener.vejle.dk/vis/pdf/bilag/4782f649-8d8e-4875-9fae-35e5afd9bf91', res: 'Kortlægningen bag Vejle Kommunes affaldsplan 2025-2037 beskriver ordninger og mængder. Husholdningsaffaldet blev genanvendt med 69 % i 2023, og restaffaldet er halveret siden 2015.', long: 'Bilaget fra maj 2025 er kortlægningsdelen af Vejle Kommunes Affalds- og Ressourceplan 2025-2037 og bygger mest på tal fra 2023 og 2024. I 2023 blev der genereret 342.455 ton affald i kommunen, og 71,5 % kom fra erhverv. Uden direkte genbrug blev 70 % af husholdningsaffaldet genanvendt mod 60 % i 2019. De fire genbrugspladser havde 609.368 besøgende i 2024, og ca. 1.918 ton gik til direkte genbrug om året. Bilaget opgør også investeringerne, bl.a. 203,3 mio. kr. til RessourceCenter Vejle, og evaluerer planen 2020-2032. Servicemålet om 85 % tilfredse borgere blev nået allerede i 2024.' },
      { id: 'NY141', title: 'Analyse af mulige synergier og styringsrelationer ved to modeller for fremtidig organisering', org: 'Jammerbugt Kommune', year: 2023, type: 'Analyse', temaer: ['Ledelse', 'Økonomi'], img: 'img/109b395043c7d56c2ecd731f58175c22.jpg', url: 'https://dagsordener.jammerbugt.dk/vis/pdf/bilag/dd28100c-a503-4037-8f4b-39052d87b698', res: 'Deloitte vurderer for Jammerbugt Kommune, om affaldsdriften skal flyttes til Nordværk eller til Jammerbugt Forsyning A/S. Nordværk giver de største synergier.', long: 'Aftalen om selskabsgørelse betyder, at driften af affaldsområdet skal ud af kommunen, og Deloitte har vurderet to modeller. Enten overtager Nordværk, som kommunen ejer med fem andre nordjyske kommuner, opgaverne, eller også lægges de i kommunens vandselskab Jammerbugt Forsyning A/S. Ud fra udgifter på 72 mio. kr. i regnskabsåret 2022 skønnes synergierne til 0,9-3,7 mio. kr. ved Nordværk og 0,4-0,9 mio. kr. i driften ved forsyningen. Nordværk giver en mere robust organisation og bedre indkøb, men mindre lokal indflydelse. Forsyningsmodellen giver fuld kontrol, men lægger opgaven i en lille organisation, der skal tilføres kompetencer.' },
      { id: 'NY142', title: 'Synergier ved etablering af et stærkere Nordværk', org: 'Nordværk', year: 2023, type: 'Analyse', temaer: ['Ledelse', 'Økonomi'], img: 'img/a9236a622e9f2ce2d049629981d79395.jpg', url: 'https://dagsordener.jammerbugt.dk/vis/pdf/bilag/56346d30-9dad-4f99-a74c-1281f973fc6d', res: 'Deloitte vurderer synergierne ved at samle ejerkommunernes affaldsdrift i Nordværk frem for i lokal forsyning. Størst gevinst ses i kommuner, der i dag ikke er med i indsamlingen.', long: 'Deloitte udarbejdede analysen i april 2023, da nye regler kræver, at kommunernes drift af affaldsaktiviteter lægges ud i selskaber. Den bygger på erfaringer fra forsyningsfusioner og fra sammenlægningen af Reno Nord og AVV, og kommunernes økonomiske oplysninger indgår ikke. Erfaringsmæssigt er synergipotentialet 30-50 % på administration ekskl. løn, 10-50 % på IT, 10-20 % på personale og 5-15 % på drift. Nordværk har allerede sparet bl.a. 3,9 mio. kr. på fællesindkøb af miljøkasser. Størst potentiale ses i kommuner, der i dag ikke er med i indsamling og genbrugspladser, mens Brønderslev og Hjørring får begrænsede synergier.' },
      { id: 'NY143', title: 'Due diligence-rapport: Forberedelse til kompetenceoverdragelse til Nordværk', org: 'Nordværk', year: 2023, type: 'Rapport', temaer: ['Ledelse', 'Økonomi'], img: 'img/38b61afc364b382e1de596c16ca150bc.jpg', url: 'https://dagsordener.rebild.dk/vis/pdf/bilag/0d0f9970-d523-4c66-80de-5893b5a07ee6', res: 'Deloitte og Bech-Bruun har gennemgået affaldsområdet i fire kommuner før overdragelsen til Nordværk og fandt ingen røde flag, der forhindrer overdragelsen 1. januar 2024.', long: 'Rapporten fra oktober 2023 skal forberede, at Aalborg, Rebild, Jammerbugt og Hjørring kommuner overdrager affaldsområdet til Nordværk I/S. Deloitte og Bech-Bruun har gennemgået økonomiske og juridiske forhold ud fra kommunernes datarum og interviews og farvekodet observationerne efter betydning. Med overdragelsen følger 205 medarbejdere fra Aalborg, 21 fra Rebild, 16 fra Jammerbugt og 2 fra Hjørring. Rådgiverne peger bl.a. på uregistrerede aktiver under 100.000 kr., uafklarede forpligtelser for lukkede deponier, risiko for manglende likviditet i starten af 2024 og et mangelfuldt datarum. For Aalborg nævnes en underdækning på 72 mio. kr.' },
      { id: 'NY144', title: 'Kortlægning af eksisterende genbrugspladsstruktur', org: 'Mariagerfjord Kommune', year: 2023, type: 'Analyse', temaer: ['Genbrugspladser', 'Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/bcbc78e4634d802bd8b8323cf662cd2d.jpg', url: 'https://dagsordener.mariagerfjord.dk/vis/pdf/bilag/869f6cf4-8d11-4822-9da6-65f9dd3d7352', res: 'Mariagerfjord Kommune har kortlagt sine fem genbrugspladser. Hadsund og Mariager er de mindst effektive, og kortlægningen foreslår at undersøge en ny plads i Hadsund.', long: 'Kortlægningen fra september 2023 gør status for 2022 på pladserne i Als, Arden, Hadsund, Hobro og Mariager. Den bygger på besøgstal, bemandingstimer, affaldsmængder, en teknisk gennemgang og en tilfredshedsundersøgelse fra maj 2022 med 1.446 brugere, hvor 98 % var tilfredse. Pladserne havde 265.768 besøg og modtog 27.408 ton affald, heraf 8.881 ton i Hobro. Hadsund og Mariager har den højeste bemanding pr. besøg og pr. ton. Hadsund-pladsen ligger desuden på et gammelt deponi i to niveauer. Kortlægningen anbefaler at undersøge en ny plads i Hadsund og at etablere genbrugsområder på alle pladser.' },
      { id: 'NY145', title: 'Åbningstider på genbrugspladserne', org: 'Vesthimmerlands Forsyning', year: 2024, type: 'Notat', temaer: ['Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/1e659816bb42a4ef974671463129a042.jpg', url: 'https://dagsordener.vesthimmerland.dk/vis/pdf/bilag/55f8612c-0894-4bbf-bd80-68f07af1c5e3', res: 'Vesthimmerlands Forsyning har brugt nummerpladedata fra 2023 til at se, hvornår de fire genbrugspladser bruges. Private står for 95,5 % af 145.461 besøg, og lørdag er travlest.', long: 'Det interne notat fra august 2024 blev lavet, fordi brugerne ønskede åbent på søn- og helligdage, og fordi åbningstiderne skulle vurderes til budget 2025. Grundlaget er nummerpladeregistreringer fra 2023 på pladserne i Aars, Farsø, Løgstør og Aalestrup, fordelt på ugedag, time, sommer og vinter samt privat og erhverv. Aars havde flest besøg med 57.701, ca. 19 pr. åbningstime, mens Løgstør kun havde ca. 10. Erhverv udgør 1,9-7,5 % af besøgene på hverdage og under 3 % i weekenden. I Aars og Løgstør kommer der få mellem kl. 7 og 9, og i weekenden er første åbningstime ofte den travleste.' },
      { id: 'NY146', title: 'Redegørelse om fremtidig organisering af affaldsområdet i Thisted Kommune', org: 'Thisted Kommune', year: 2023, type: 'Notat', temaer: ['Ledelse', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/e680beba230a74ed4c77ddf02781879a.jpg', url: 'https://dagsordener.thisted.dk/vis/pdf/bilag/09e7985d-2afe-40e1-bc49-b2ec0dbbefd3', res: 'Advokatredegørelse til Thisted Kommune fra maj 2023 om selskabsgørelse af affaldsforbrænding og affaldsydelser med tre selskabsmodeller og ejerskabet af Kraftvarmeværk Thisted.', long: 'Advokat Jacob Schousgaard fra Advodan Thisted skrev redegørelsen ud fra lovforslag L 115 og den politiske aftale fra august 2022 om selskabsgørelse. Lovforslaget lægger op til, at kommuner kun må drive affaldsforbrænding i aktie- eller anpartsselskaber, og en eventuel aftale om at overdrage I/S Thyras halvdel af I/S Kraftvarmeværk Thisted skulle indgås senest 30. juni 2023. Notatet beskriver tre modeller, fra et helejet Affald A/S til et tværkommunalt selskab, og ser på medarbejdere og kontrakter. Indsamling af farligt affald ventes at forblive kommunal. Han anbefaler at vælge model nu, men først etablere den, når loven er vedtaget.' },
      { id: 'NY147', title: 'Genbrugspladser: Scenarier for fremtidig struktur og serviceniveau', org: 'Frederikshavn Forsyning', year: 2023, type: 'Analyse', temaer: ['Genbrugspladser', 'Økonomi'], img: 'img/24c3d5f4ee99b6a450eb4bd4011271df.jpg', url: 'https://dagsordener.frederikshavn.dk/vis/pdf/bilag/2dbb2aa8-708f-410c-a8c1-81f33417a8ba', res: 'Rambøll vurderer tre scenarier for Frederikshavns 16 genbrugspladser. Udbygning af alle koster ca. 226 kr. pr. husstand om året, 8 pladser ca. 120 kr. og 5 pladser ca. 65 kr.', long: 'Frederikshavn Forsyning bad Rambøll om en ny gennemgang af kommunens 16 genbrugspladser, der årligt modtager ca. 42.300 ton affald. Kun 9 af pladserne er miljøgodkendte. Scenarie 1 udbygger alle pladser for 64,5 mio. kr. plus 10,7 mio. kr. til materiel. Scenarie 2 samler kapaciteten på 8 pladser for 35 mio. kr., og alle husstande får højst 10 km i fugleflugt. Scenarie 3 med fire storbypladser og en stor oplandsplads koster 20,7 mio. kr., men giver ca. 7 % af husstandene over 10 km. Rambøll kalder investeringerne i scenarie 1 overdimensionerede og foreslår, at små pladser kan blive rene gren- og haveaffaldspladser.' },
      { id: 'NY148', title: 'Muligheder for brug af mobilsugeanlæg til den fremtidige indsamling af 10 affaldsfraktioner', org: 'AffaldVarme Aarhus', year: 2022, type: 'Analyse', temaer: ['Etageboliger', 'Teknologi', 'Økonomi'], img: 'img/0fc7b605c30990f191b68a24260ca280.jpg', url: 'https://dagsordener.aarhus.dk/vis/pdf/bilag/d5d9456a-2262-43c2-a82a-c2a3f6343a6b', res: 'COWI-rapport for AffaldVarme Aarhus om mobilsug, når der skal sorteres i 10 fraktioner. Mobilsug kan ikke stå alene, og løsninger uden mobilsug er klart billigst for beboerne.', long: 'COWI har for AffaldVarme Aarhus undersøgt, om kommunens mobilsugeanlæg, 17 ved boligbebyggelser og 19 ved plejecentre, kan bruges, når der skal sorteres i 10 fraktioner. Analysen bygger på interview med leverandørerne Envac og Airbin og på tre fremtidsscenarier for tre ejendomme med 149, 221 og 72 lejligheder. Mobilsug egner sig ikke til glas og andet metal end dåser, men der er gode erfaringer med madaffald. Med mobilsug til restaffald koster løsningerne ca. 2.425-2.860 kr. pr. lejlighed om året, med mobilsug også til madaffald 3.025-3.575 kr. og helt uden mobilsug 965-1.315 kr. Uden mobilsug vil beboerne dog opleve en ringere service.' },
      { id: 'NY149', title: 'Sammenligning af affaldsgebyrer for 2025', org: 'Kredsløb', year: 2025, type: 'Analyse', temaer: ['Økonomi', 'Data, statistikker og nøgletal'], img: 'img/92c67be7e8fbcca57e21c8b72bea661b.jpg', url: 'https://dagsordener.aarhus.dk/vis/pdf/bilag/6ce9cf3d-5d76-4227-90ec-ec1182fa5822', res: 'Kredsløb sammenligner Aarhus\' affaldsgebyrer for 2025 med de fem andre største bykommuner. Aarhus er billigst for etageboliger, men villakunderne betaler mest af de seks byer.', long: 'Kredsløb har lavet sammenligningen for at følge op på Aarhus Kommunes ejerstrategi, hvor målet er at være blandt de to billigste af de seks største bykommuner. Der bruges gebyrer for 2025, fordi 2026-gebyrerne ikke var vedtaget alle steder. Den typiske midtbykunde med nedgravede beholdere er udeladt, fordi den løsning ikke er udbredt nok i de andre byer, og i stedet sammenlignes en etageboligkunde med beholdere på hjul. Aarhus er billigst for etageboliger og den 11. billigste kommune i landet, men dyrest for villakunder blandt de seks byer og nr. 49 på landsplan. Med de planlagte gebyrer for 2026 ventes en bedre placering for villakunderne.' },
      { id: 'NY150', title: 'Notat om ordning for afhentning af asbestholdigt affald', org: 'Silkeborg Genbrug og Affald', year: 2023, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Byggeaffald', 'Økonomi'], img: 'img/a5ba44bb6baaeff2b9ead534a9857dbe.jpg', url: 'https://dagsordener.silkeborg.dk/vis/pdf/bilag/9413d78d-78c0-455c-bc67-1614c015ce1b', res: 'Notat fra Silkeborg Genbrug og Affald om at erstatte bringeordningen for asbest på Tandskov med afhentning i big bags. Borgerne foreslås at betale 400-500 kr. pr. big bag.', long: 'Notatet fra september 2023 skal danne grundlag for Silkeborg Kommunes beslutning om en henteordning for asbestholdigt affald. I dag kan asbest kun afleveres på Affaldscenter Tandskov. Mængden lå omkring 950 tons om året i 2017-2022, og ordningen koster ca. 1 mio. kr. årligt. Ved et tilsyn i maj 2023 fandt Miljøstyrelsen, at håndteringen ikke overholdt vilkårene i miljøgodkendelsen. Notatet sammenligner ti kommuner og selskaber med kranbilsordninger og anslår, at afhentning koster 1.450-1.500 kr. pr. big bag, i alt ca. 1,4 mio. kr. om året. Erhverv foreslås at betale fuld pris, og der foreslås højst 6 big bags pr. afhentning.' },
      { id: 'NY151', title: 'Anvendelse af fællesløsninger for sommerhusområder', org: 'Silkeborg Genbrug og Affald', year: 2024, type: 'Notat', temaer: ['Sommerhuse og kolonihaver', 'Hente- og bringeordninger', 'Økonomi'], img: 'img/895abe2979ee8537f8f7a0bedc6e3e9f.jpg', url: 'https://dagsordener.silkeborg.dk/vis/pdf/bilag/186976de-4f11-43b0-84e4-071595300d2d', res: 'Silkeborg Genbrug og Affald anbefaler fælles affaldsøer med delvist nedgravede containere i 11 sommerhusområder for at løse arbejdsmiljøproblemer ved tømningen.', long: 'Notatet fra september 2024 tager afsæt i, at Arbejdstilsynet i flere tilfælde har givet renovatører påbud om ikke at tømme beholdere i sommerhusområder med ujævne standpladser og dårlige grusveje. Silkeborg har ca. 1.300 sommerhuse i 15 områder. Selskabet regner med, at en affaldsø kan dække ca. 30 sommerhuse, og at der højst bliver ca. 350 meter at gå. En ø koster 125.000-200.000 kr., og det samlede gebyr bliver 1.900-2.250 kr. om året, 150-200 kr. under gebyret for en almindelig enfamiliebolig. Ordningen kræver et ændret regulativ og skal være obligatorisk. Planen er at skifte beholderne ud i etaper frem til udgangen af 2026.' },
      { id: 'NY152', title: 'Statusrapport 2022-2024 for Affalds- og Ressourceplan 2022-2034', org: 'Nomi4s', year: 2025, type: 'Evaluering', temaer: ['Affaldsplaner/regulativer og strategi', 'Reel genanvendelse', 'Data, statistikker og nøgletal'], img: 'img/ee1ee928243fb7b6cd332e518b2b95e4.jpg', url: 'https://dagsordener.holstebro.dk/vis/pdf/bilag/c24609cf-d39a-425d-8284-69c35f80f053', res: 'Nomi4s gør status på affaldsplanen for Holstebro, Lemvig, Skive og Struer. Reel genanvendelse lå i 2024 på 59,8-63,6 %, så alle fire har nået EU-målet for 2025 på 55 %.', long: 'Statusrapporten fra september 2025 er Nomi4s\' tredje årlige opfølgning på den fælles Affalds- og Ressourceplan 2022-2034 og dækker arbejdet i 2024. Hvert initiativ under planens seks fokusområder har fået en farvekode for, hvor langt det er nået. Ordninger for blød plast, pap, mad- og drikkekartoner og farligt affald er indført, og siden september 2023 er tekstilaffald hentet i røde poser. Otte genbrugspladser har fået genbrugsområder. Reel genanvendelse steg fra 50,4-55,1 % i 2021 til 59,8-63,6 % i 2024. Mængden pr. indbygger var 790-935 kg mod 874 kg i hele Danmark, og store mængder asbestholdigt affald trak tallet op i 2024.' },
      { id: 'NY153', title: 'Administrationspraksis: Affaldssortering via miljøstationer i bolig og sommerhusområde', org: 'Holstebro Kommune', year: 2022, type: 'Vejledning', temaer: ['Sommerhuse og kolonihaver', 'Hente- og bringeordninger', 'Affaldsplaner/regulativer og strategi'], img: 'img/2a7a5c33b3a5bb134f7b0adbc3878cb7.jpg', url: 'https://dagsordener.holstebro.dk/vis/pdf/bilag/09c5a5de-c412-4b7e-86b9-f799a1ef5c18', res: 'Holstebro Kommunes regler for, hvornår grundejerforeninger i bolig- og sommerhusområder kan få fælles miljøstationer i stedet for indsamling af genanvendeligt affald ved hvert hus.', long: 'Dokumentet fastlægger, hvornår Holstebro Kommune og affaldsselskabet Nomi4s kan etablere fælles miljøstationer til genanvendeligt affald i stedet for husstandsindsamling. Sommerhusområder skal have 8 fraktioner, almindelige husstande 10. En fælles løsning kræver en grundejerforening med pligtigt medlemskab og hjemmel i vedtægterne, og stationerne skal stå i passende afstand fra alle husstande. De betales via miljøgebyret og er billigere for grundejeren end husstandsindsamling. Ved for dårlig sortering kan kommunen kræve flere stationer eller indføre husstandsindsamling, og så betaler foreningen den ikke afskrevne del af løsningen.' },
      { id: 'NY154', title: 'Analyse af selskabsgørelse af de gebyr- og takstfinansierede aktiviteter i Nomi4s i/s', org: 'Nomi4s', year: 2025, type: 'Analyse', temaer: ['Ledelse', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/72e7a1cd50ff3d95b0f2e2292f4a884c.jpg', url: 'https://dagsordener.skive.dk/vis/pdf/bilag/f4638db6-898f-48cb-9e8d-dc64b86cf22c', res: 'Nomi4s vurderer fordele og risici ved frivillig selskabsgørelse af de gebyrfinansierede affaldsaktiviteter og finder, at det kan være en fordel at komme lovgivningen i forkøbet.', long: 'Notatet fra juni 2025 er lavet af Nomi4s med Berg Advokater og BDO. Det gennemgår erfaringer fra de omkring 40 % af kommunernes affaldsaktiviteter, der er selskabsgjort, og ser på skat, moms, deponier og Forsyningstilsynets arbejde med gebyrer. Den påtænkte model har Nomi4s i/s som hovedejer af et holdingselskab med datterselskaber, mens deponiet i Kåstrup bliver i interessentskabet. Analysen finder ingen tegn på væsentlige risici for økonomi eller service, men regner med et momstab på ca. 130 kr. pr. husstand om året, som vurderes håndterbart. Fordelen er friere rammer for værdiansættelse og afvikling af overdækning, før en lov kommer.' },
      { id: 'NY155', title: 'Notat vedrørende overvejelser om hjemtagning af krankørselsopgaver ved Revas', org: 'Viborg Kommune', year: 2022, type: 'Notat', temaer: ['Udbud og kravspecifikationer', 'Økonomi', 'Hente- og bringeordninger'], img: 'img/677004346662a30e6bc2200ef48d4074.jpg', url: 'https://dagsordener.viborg.dk/vis/pdf/bilag/a60beb6c-5265-4cd4-8763-0a787168ef56', res: 'Revas i Viborg Kommune vurderer, om tømning af nedgravede affaldsløsninger med kranbil skal hjemtages. Notatet ser en økonomisk fordel og anbefaler hjemtagning i mindst seks år.', long: 'Notatet fra august 2022 er skrevet af Revas forud for en ny affaldsordning i 2024 med flere fraktioner i kommunens forventede ca. 700 nedgravede løsninger. Opgaven løses i dag af en privat vognmand med en lokal underleverandør, og den ældre kontrakt har ubeskrevne snitflader. Forvaltningen har beregnet en årlig udgift på 2.114.000 kr. ved hjemtagning mod 3.404.000 kr. for udbuddet i 2023, begge ved uændret drift. Notatet gennemgår også fyldemeldere, vejedata, kørselsoptimering og gebyrstruktur. Revas anbefaler at hjemtage opgaven i mindst seks år og i den periode afklare teknik, ruter, vejning og grundlaget for et eventuelt senere udbud.' },
      { id: 'NY156', title: 'Takstpolitik', org: 'Favrskov Kommune og Favrskov Affald A/S', year: 2022, type: 'Notat', temaer: ['Økonomi', 'Erhverv'], img: 'img/b263e9f1f1689e32a1b684dd40ca45f2.jpg', url: 'https://dagsordener.favrskov.dk/vis/pdf/bilag/681fd720-a485-4bd4-9c66-e912a7ea7c52', res: 'Favrskov Affalds takstpolitik forklarer, hvordan gebyret beregnes for hver ordning. Rest- og madaffald betales efter kapacitet, de genanvendelige fraktioner med et ens boliggebyr.', long: 'Takstpolitikken fra Favrskov Affald A/S gennemgår beregningen af affaldsgebyrerne for husholdninger og virksomheder. Gebyret for rest- og madaffald følger beholderstørrelse og tømmefrekvens, mens glas og metal, plast og kartoner samt papir, pap og tekstiler opkræves som et ens gebyr pr. bolig. Boliger i etageejendomme betaler 80 % af gebyret for genbrugspladserne. For madaffald og genanvendelige fraktioner betaler virksomheder en markedspris, beregnet som omkostningen plus 10 %. Virksomheder kan købe adgang til genbrugspladserne som årsabonnement pr. bil, der også gælder i Randers og Mariagerfjord, eller betale pr. besøg via en SMS-ordning.' },
      { id: 'NY157', title: 'Dagrenovation og genbrugsordning. Tilfredshedsundersøgelse 2023', org: 'Ikast-Brande Kommune', year: 2024, type: 'Evaluering', temaer: ['Analyser og undersøgelser', 'Hente- og bringeordninger', 'Haveboliger/parcelhuse'], img: 'img/5a892dccbbadfcf48b4f6dd5a87dc0d3.jpg', url: 'https://dagsordener.ikast-brande.dk/vis/pdf/bilag/3e665bc8-a29d-4edb-88b5-b6ee69fde6e8', res: 'Ikast-Brande Kommunes tilfredshedsundersøgelse af den nye affaldsordning viser, at 88 % af borgerne med egne beholdere er tilfredse, men mange mangler plads i genbrugsbeholderen.', long: 'Undersøgelsen indgår i evalueringen af indsamlingsordningen og bygger på 2.466 besvarelser, de fleste fra borgere tilmeldt SMS-varsling (svarprocent 22 %) og resten via Facebook. 91 % synes, at tømningen fungerer godt, og 80 % er tilfredse med den nye genbrugsbeholder. Pladsen er det hyppigste klagepunkt, og 51 % har oplevet for lidt plads til plast, metal og mad- og drikkekartoner og 42 % til pap og papir. Flere ønsker genbrugsbeholderen tømt hver anden uge og dagrenovationen hver tredje. 96 % har aldrig købt ekstra kapacitet, hvilket kan skyldes, at kommunikationen om muligheden har været sparsom.' },
      { id: 'NY158', title: 'Samlet beslutningsgrundlag for selskabsgørelse af aktiviteter i ARGO', org: 'ARGO', year: 2024, type: 'Notat', temaer: ['Ledelse', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/e6ff01cff8f3bc54720a65d43ee30b57.jpg', url: 'https://dagsordener.roskilde.dk/vis/pdf/bilag/1fc32d03-306d-470e-a2ca-f058a2a8e826', res: 'ARGOs beslutningsgrundlag for at udskille affaldsenergi, genbrugspladser og omlastning i aktieselskaber under ARGO I/S, så kravet om selskabsgørelse er opfyldt fra 2025.', long: 'Notatet fra marts 2024 skal give ARGOs ni ejerkommuner grundlag for at godkende en ny selskabsstruktur, fordi affaldsenergianlæg skal være selskabsgjort senest 1. januar 2025. ARGO I/S bevares som ejer af et ARGO Holding A/S med datterselskaber til affaldsenergi, genbrugspladser, omlastning og service, mens deponi bliver i I/S\'et. Senere kan Kalundborg, Lejre, Roskilde og Stevns få hvert sit indsamlingsselskab. Ejerkommunerne stiller garanti efter ejerandel for et lån i KommuneKredit på 851,8 mio. kr., og PwC vurderer en garantiprovision på 0,7 % om året som rimelig. Enhedsbestyrelsen evalueres i 2025 og I/S-modellen i 2027.' },
      { id: 'NY159', title: 'Notat: Etablering af erhvervsaffaldsordning i Roskilde Kommune', org: 'Roskilde Kommune', year: 2023, type: 'Notat', temaer: ['Erhverv', 'Hente- og bringeordninger', 'Økonomi'], img: 'img/4f3caf66022e6f425c05043534465378.jpg', url: 'https://dagsordener.roskilde.dk/vis/pdf/bilag/0c2f5a47-1687-4bb6-a4f4-86e854792745', res: 'Roskilde Kommunes administration foreslår, hvordan virksomheder efter reglerne fra 2023 kan få husholdningslignende affald hentet i husholdningernes beholdere mod 10 % tillæg.', long: 'Notatet tager afsæt i de skærpede regler fra 1. januar 2023, der lader kommunerne indsamle sorteret erhvervsaffald, når det i art og mængde svarer til en husholdnings. Administrationen anbefaler at bruge standardløsningen for egne ordninger, som 74 % af borgerne har, dvs. todelte 240- eller 370-liters beholdere samt tekstilposer og miljøkasse. Virksomhederne skal ikke kunne fravælge fraktioner, og haveaffald bør ikke indgå. Prisen foreslås sat efter Forsyningstilsynets metode 2 med et overskudstillæg på 10 %, der opkræves som et separat gebyr. Kommunens regulativ for erhvervsaffald skal derfor revideres.' },
      { id: 'NY160', title: 'Kortlægningsrapport. Bilag til Køge Kommunes Ressource- og Affaldsplan 2025-2036', org: 'Køge Kommune', year: 2024, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Affaldsplaner/regulativer og strategi', 'Reel genanvendelse'], img: 'img/902104e248ccad0bfec876108f6c6c96.jpg', url: 'https://dagsordener.koege.dk/vis/pdf/bilag/de640e1d-f9a4-42c2-9aa0-51eebf0ff3a2', res: 'Kortlægningen bag Køges affaldsplan 2025-2036 viser, at 48,8 % af husholdningsaffaldet gik til genanvendelse i 2023 mod 46,6 % på landsplan, lige under målet for 2025.', long: 'Teknik og Miljøforvaltningen i Køge Kommune har lavet rapporten som lovpligtigt bilag til affaldsplanen. Den opgør mængderne for 2018-2023 ud fra Affaldsviden.dk, ADS og indvejningsdata fra ARGO og beregner genanvendelsen efter Pejlemærket med effektiviteter fra Miljøprojekt 2145. I 2023 blev der produceret ca. 200.000 tons affald, heraf 27 % fra husholdninger. Genbrugspladserne modtog 38.030 tons og står for langt det meste af husholdningsaffaldet. Erhvervsaffaldet blev genanvendt med 57 % mod 76 % på landsplan, og Letland og Litauen tog ca. 77 % af det eksporterede affald. Ordningerne koster 110,1 mio. kr. i budget 2025.' },
      { id: 'NY161', title: 'Kommunikationsplan: Udrulning af affaldsordninger i 2023', org: 'Slagelse Kommune', year: 2022, type: 'Strategi', temaer: ['Kommunikation', 'Hente- og bringeordninger'], img: 'img/21933fd0975f6d20b3d0c4983f576889.jpg', url: 'https://dagsordener.slagelse.dk/vis/pdf/bilag/ade4855c-abfe-4db6-8ef4-23704fea1398', res: 'Slagelse Kommunes plan for informationen til borgere og boligselskaber frem mod de nye affaldsordninger, som efter tidsplanen sættes i gang omkring 1. maj 2023.', long: 'Kommunikationsplanen fra Miljø, Plan og Teknik bygger på byrådets beslutning af 29. november 2021 om hovedprincipper for affaldsordning 2023. Målet er, at ingen grundejere eller borgere skal føle sig utrygge eller uvidende, når ordningen indføres. Indsatsen er delt op i kvartaler fra 2022 til 2023 med en temaside på slagelse.dk, høring af regulativet, møder med boligselskaber og præsentation på Store Genbrugsdag og Sct. Michaels Nat. I 2023 følger bl.a. en app og korte film om, hvordan man sorterer. Erfaringerne fra ordningen i 2018 bruges igen, og ejendomsfunktionærer kan komme på kursus hos AffaldPlus.' },
      { id: 'NY162', title: 'Et styrket og mere fleksibelt affaldsfællesskab i AffaldPlus', org: 'AffaldPlus', year: 2023, type: 'Oplæg', temaer: ['Ledelse', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/e3dd4ace529d27e7c143d3f4888050bd.jpg', url: 'https://dagsordener.ringsted.dk/vis/pdf/bilag/db8b0a86-d7e7-4023-b137-f4369f952a02', res: 'AffaldPlus\' forslag fra juni 2023 til de seks ejerkommuner om at organisere affaldsydelser og affaldsenergi i nye aktieselskaber, når affaldsydelserne skal selskabsgøres.', long: 'Kataloget gennemgår ti forandringer i affaldssektoren, bl.a. selskabsgørelsen af de kommunale affaldsydelser og udbud af affald til forbrænding fra 1. juli 2025. AffaldPlus foreslår at samle opgaver, som ikke alle kommuner har overdraget, i AffaldPlus Kommunedrift A/S og at udskille forbrændingen i AffaldPlus Affaldsenergi A/S, mens genbrugspladser og administration bliver i AffaldPlus A/S. Erfaringerne fra Sorø og Ringsted, der overdrog driften i 2016 og 2021, bruges som model. Energiafdelingen havde 125 mio. kr. i hvile-i-sig-selv-kapital ved udgangen af 2022. Til sidst beskrives en overdragelse i fem trin.' },
      { id: 'NY163', title: 'Baggrundsnotat: Harmoniseringspotentialer og effektvurderinger', org: 'ARGO og Kalundborg, Lejre, Roskilde og Stevns kommuner', year: 2025, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Udbud og kravspecifikationer', 'Haveboliger/parcelhuse'], img: 'img/c7460fadd6755101bc6941fcb23a7287.jpg', url: 'https://dagsordener.kalundborg.dk/vis/pdf/bilag/33dc3b80-2467-4b5f-acad-0755d0f900e1', res: 'Rambøll vurderer fire forslag til at ensrette affaldsindsamlingen i Kalundborg, Lejre, Roskilde og Stevns, fx skelafhentning og at droppe sommertømning af mad- og restaffald.', long: 'Baggrundsnotatet fra februar 2025 er skrevet af Rambøll for ARGO og de fire kommuner som led i en fælles strategi for indsamling af husholdningsaffald. Det bygger på en kortlægning af kommunernes regulativer og aftaler samt dialog med kommuner og renovatører. Kommunerne prioriterede fælles skelafhentning, ens krav til samarbejdet med renovatøren, samme beholdere og fraktioner som i Roskilde og ens regler for sommertømning, mens bl.a. el-drift blev fravalgt. Hvert forslag er vurderet på økonomi, ressourcetræk, miljø og klima samt service. At droppe ugentlig sommertømning vurderes at sænke indsamlingsomkostninger og kørsel med ca. 15 %.' },
      { id: 'NY164', title: 'Kortlægning af serviceniveau i de kommunale indsamlingsordninger', org: 'ARGO', year: 2023, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/e57528eee7df9fdebfc9bffe6d32b138.jpg', url: 'https://dagsordener.kalundborg.dk/vis/pdf/bilag/c79c5fe4-b3ea-4c21-aa5b-ee0b64a84091', res: 'ARGO sammenligner affaldsindsamlingen i Kalundborg, Lejre, Roskilde og Stevns. Rest- og madaffald tømmes ens, men krav til standplads og ordninger som storskrald varierer meget.', long: 'Notatet er dateret 5. september 2023 og bygger på data, som de fire kommuner selv har udfyldt i en skabelon fra ARGO. Det skal bruges til at beskrive serviceniveauet, når opgaver overdrages til ARGO. Rest- og madaffald tømmes hver anden uge i alle fire kommuner, mens genanvendelige fraktioner tømmes alt fra hver anden uge i Kalundborg til hver ottende uge for glas og metal i Roskilde. Som standard må standpladsen højst ligge 5 m fra vej i Roskilde mod 45 m i Lejre. Kun Lejre og Roskilde henter storskrald, og Stevns lader ikke erhverv deltage i ordningerne. Et ændret serviceniveau kræver ændret regulativ og nye leverandøraftaler.' },
      { id: 'NY165', title: 'Notat om pizzabakker i papaffald', org: 'KLAR Forsyning', year: 2025, type: 'Notat', temaer: ['Lovgivning og afgørelser', 'Hente- og bringeordninger', 'Sorteringsvejledninger'], img: 'img/eb27f477273062fe117bf4b15a65387e.jpg', url: 'https://dagsordener.greve.dk/vis/pdf/bilag/18057cb0-9c0b-4d60-8628-de4b6c117fef', res: 'KLAR Forsyning gennemgår Københavns beslutning om at sortere pizzabakker som pap og anbefaler at undersøge økonomi og praksis, mens Miljøstyrelsens udtalelse afventes.', long: 'Notatet fra maj 2025 er skrevet til ejerkommunerne Greve og Solrød. København afprøvede i foråret 2024 pizzabakker i papfraktionen i 1.388 etageboliger, klassificerede dem i december 2024 som papemballage og begyndte indsamlingen i april 2025. Siden 1. januar 2025 har Miljøstyrelsen været myndighed for affaldsklassificering, så andre kommuner må vente på en udtalelse fra styrelsen. KLAR beskriver scenarier for frivillig eller obligatorisk indsamling og for uændret sortering. Selskabet vurderer, at det vil øge genanvendelsen af pap, men at borgerne kan mangle plads i papbeholderen, og at indsamleren vil kræve merbetaling.' },
      { id: 'NY166', title: 'Udbudsstrategi: Offentligt EU-udbud på indsamling af rest-, mad- og genanvendeligt affald', org: 'Vordingborg Kommune', year: 2024, type: 'Strategi', temaer: ['Udbud og kravspecifikationer', 'Hente- og bringeordninger', 'Klima'], img: 'img/c88a633f81c42a79bb44f97151eee0c0.jpg', url: 'https://dagsordner.vordingborg.dk/vis/pdf/bilag/58e4aeea-6cd2-4870-bd40-3d36f28a07eb', res: 'Strategien anbefaler, at Vordingborg Kommune sender affaldsindsamlingen i offentligt EU-udbud. Pris foreslås vægtet med 40 %, og brug af nul-emissionsbiler skal tælle i kvaliteten.', long: 'Strategien fra april 2024 dækker tømning af 2- og 4-hjulede beholdere, nedgravede løsninger med kranbil, storskrald og miljøkasser. Rådgiveren Tolstrup & Hvilsted anbefaler offentligt udbud, fordi formen er kendt på affaldsområdet og blev brugt ved kommunens sidste udbud. Kontrakten bør løbe mindst seks år, så renovatøren kan afskrive nye biler. Tilbudsgivere foreslås bl.a. at skulle have en reference med mindst 20.000 afhentningsadresser og en med nul-emissionsbiler. Pris vægter 40 % i det foreslåede skema, miljø- og driftshensyn ved bilerne 30 %, og her skal tilbudsgiverne konkurrere på andelen af tømninger med nul-emissionsbiler.' },
      { id: 'NY167', title: 'Orientering: Hvor ender affaldet?', org: 'Bornholms Regionskommune og BOFA', year: 2025, type: 'Notat', temaer: ['Afsætning og behandling', 'Genbrugspladser', 'Udvidet producentansvar'], img: 'img/73a2cd4bed7e7c5d381d148ee21d6e2e.jpg', url: 'https://dagsordener.bornholm.dk/vis/pdf/bilag/63f68773-49b4-46f3-910d-05d78705fb18', res: 'BOFA gennemgår de 69 affaldstyper, selskabet håndterer på Bornholm, og oplyser for hver fraktion fra genbrugspladser og indsamling, hvor den sendes hen, og hvordan den behandles.', long: 'Orienteringen blev givet til Natur-, Miljø- og Planudvalget i Bornholms Regionskommune 5. november 2025, efter at udvalget havde bedt BOFA om et overblik. Listen er opdateret pr. 1. oktober 2025. Beton og tegl knuses i Rønne og sælges som genbrugsstabil, dæk går til GENAN i Viborg, og madaffald bioforgasses hos Gemidan i Ølstykke. Blød PVC og asbest deponeres i Rønne, mens restaffald brændes i BOFAs energianlæg og bliver til fjernvarme. Genbrugseffekter doneres til lokale genbrugsbutikker og idrætsforeninger. For glas, plast og kartoner har BOFA siden 1. oktober kun ansvar for indsamling og opballering, fordi producentansvaret dækker resten.' },
      { id: 'NY168', title: 'Brugerundersøgelse: Reno Djurs’ genbrugsstationer 2023. Grundlag for fastsættelse af gebyrer', org: 'Reno Djurs', year: 2023, type: 'Analyse', temaer: ['Genbrugspladser', 'Økonomi', 'Erhverv'], img: 'img/db54f3515b61ee8b7d6870fefc1b4379.jpg', url: 'https://renodjurs.dk/sites/default/files/2023-03/Bilag%204.2_Brugerunders%C3%B8gelse.pdf', res: 'Brugerundersøgelse på Reno Djurs’ fem genbrugsstationer, som kan bruges til at beregne gebyrerne for 2024. Private kom med 70,3 kg pr. besøg, virksomheder med ca. 232 kg.', long: 'JHN Processor registrerede i januar og februar 2023 affaldet fra 1.016 brugere på ni hverdage på stationerne i Feldballe, Grenaa, Hornslet, Ebeltoft og Ryomgård. Mængderne er opskaleret til et helt år med Reno Djurs’ tællertal på 385.855 besøg, heraf 5.822 fra erhverv. Virksomhederne udgjorde 3,6 % af de besøgende mod 1,5 % i 2022 og stod for 5 % af knap 30.000 ton affald. Erhvervslæssene var i gennemsnit 53 kg tungere end året før, især på grund af mere beton og tegl. 57 % af de private havde højst 50 kg med. Siden 2022 har virksomhederne betalt pr. besøg via nummerpladegenkendelse.' },
      { id: 'NY169', title: 'Reno Djurs I/S Årsrapport 2025', org: 'Reno Djurs', year: 2026, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Økonomi', 'Genbrugspladser'], img: 'img/0961069e3c45059b534929ae38c378a0.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-05/Reno%20Djurs%20A%CC%8Arsrapport%202025%20underskrevet.pdf', res: 'Reno Djurs omsatte i 2025 for ca. 300 mio. kr. og fik et overskud på 2,8 mio. kr. mod et budgetteret underskud på 30,8 mio. kr. Selskabet modtog i alt 217.000 tons affald.', long: 'Årsrapporten for affaldsselskabet, der ejes af Norddjurs og Syddjurs Kommuner, rummer ledelsesberetning og regnskab med noter om mængder og økonomi for hver aktivitet. Af husholdningsaffaldet gik 65 % til genanvendelse, og de ni genbrugsstationer modtog 49.000 tons ved 690.000 besøg. Fra 1. juli 2025 brændes restaffaldet fra dagrenovationen hos Nordværk i Aalborg, og udgiften til transport og behandling stiger fra ca. 11,4 til 13,5 mio. kr. om året. Da kommunerne kun må opkræve 62,5 % af de beregnede producentgebyrer for emballage, venter selskabet en manko på ca. 9,3 mio. kr. i 2026. Selskabet har krævet 88,4 mio. kr. i moms tilbage.' },
      { id: 'NY170', title: 'Udbud af forbrændingsegnet affald. Resultat og konsekvenser', org: 'Reno Djurs', year: 2024, type: 'Notat', temaer: ['Afsætning og behandling', 'Udbud og kravspecifikationer'], img: 'img/72c8bd8eef2a650d223f94b237fb6281.jpg', url: 'https://renodjurs.dk/sites/default/files/2024-12/Bilag%2021_Resultat%20af%20udbud%20af%20forbr%C3%A6ndingsegnet%20affald.pdf', res: 'Bestyrelsesnotat om Reno Djurs\' EU-udbud af forbrændingsegnet affald. Nordværk vandt de ca. 11.000 tons restaffald, og Kredsløb de ca. 4.000 tons fra genbrugsstationerne.', long: 'Ny lovgivning kræver EU-udbud af affaldsforbrænding med virkning senest 1. juli 2025, så Reno Djurs kan ikke videreføre den horisontale aftale med Kredsløb fra 2007. Tilbuddene blev vurderet på pris pr. ton plus et transporttillæg efter afstanden til modtageanlægget. Nordværk I/S i Aalborg vandt restaffaldet fra henteordningerne med en evalueringssum på 7.899.430 kr. mod Kredsløbs 7.999.013 kr. Kredsløb Affaldsenergi i Lisbjerg vandt affaldet fra genbrugsstationerne med 3.918.896 kr. om året. Da komprimatorbilerne har begrænset rækkevidde, skal rest- og madaffald nu omlastes, og notatet peger på tre mulige steder.' },
      { id: 'NY171', title: 'Reno Djurs’ håndtering af eternitaffald', org: 'Reno Djurs', year: 2026, type: 'Notat', temaer: ['Genbrugspladser', 'Byggeaffald', 'Ledelse'], img: 'img/ae0ef5d7491427dff5e0dfcaa8ca7efe.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-03/Bilag%207_Notat%20om%20eternith%C3%A5ndtering.pdf', res: 'Notat til bestyrelsen om, hvorfor Reno Djurs fortsat kræver, at alt eternit afleveres emballeret som muligt asbestholdigt affald på genbrugsstationer og deponeringsanlæg.', long: 'Administrationen skriver i februar 2026, at alt eternitaffald behandles som muligt asbestholdigt, fordi det ved modtagelsen er svært at sikre, om det er asbestfrit. Emballeringskravet gælder fra 1. oktober 2024 og følger skærpede regler, bl.a. en grænseværdi sænket fra 0,1 til 0,003 fiber/cm3 i 2022. AffaldPlus og Thy Forsyning modtager asbestfrit eternit på udvalgte pladser, men Miljøstyrelsen ser som udgangspunkt eternit uden asbest som affald til deponering. Reno Djurs modtog i 2025 397 tons eternit på genbrugsstationerne og 39.991 tons på deponeringsanlægget. Ifølge direktionen vil en lempelse forringe beskyttelsen af ansatte og gæster.' },
      { id: 'NY172', title: 'Nyt skiltekoncept på genbrugsstationerne', org: 'Reno Djurs', year: 2026, type: 'Notat', temaer: ['Genbrugspladser', 'Sorteringsvejledninger', 'Kommunikation'], img: 'img/ac1c83d129928839eaeec182fbceef41.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-06/Bilag%2015_Nyt%20skiltekoncept%20p%C3%A5%20genbrugsstationerne.pdf', res: 'Reno Djurs indfører ens skilte på genbrugsstationerne, hvor fraktionerne nummereres efter affaldshierarkiet og får korte ja tak- og nej tak-lister. Notatet viser krav og eksempler.', long: 'Den hidtidige skiltning på Reno Djurs\' genbrugsstationer hang ikke sammen, og fraktionerne var ikke nummererede, hvilket gjorde vejledningen sværere. Bestyrelsesnotatet opstiller krav til skiltene, bl.a. at de tåler vind og vejr, og at magnetskiltene er lette at skifte. Nummereringen følger affaldshierarkiet, så direkte genbrug får de laveste tal og energiudnyttelse og deponering de højeste, med plads til nye fraktioner. Underskiltet har højst fem punkter i ja tak- og nej tak-listen tilsammen. Der kommer særskilte skilte til bl.a. invasive planter, jord, tekstil og asbest, og en forsøgsopstilling står på Feldballe Genbrugsstation.' },
      { id: 'NY173', title: 'Status for gennemførelse af Affaldsplan 2020', org: 'Reno Djurs', year: 2026, type: 'Notat', temaer: ['Affaldsplaner/regulativer og strategi', 'Genbrugspladser', 'Hente- og bringeordninger'], img: 'img/6797603a4db8776ece13c8105b31b4c7.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-06/Bilag%2011.2_Status%20affaldsplan.pdf', res: 'Reno Djurs\' administration gør status over Affaldsplan 2020. Mange tiltag er gennemført, bl.a. indsamling af madaffald fra 2023, mens enkelte indsatser ikke er sat i gang.', long: 'Notatet fra maj 2026 til bestyrelsen gennemgår planens aktiviteter. Husstande og sommerhuse fik i 2023 særskilt indsamling af madaffald og ti fraktioner, og ca. 200 kommunale institutioner følger samme ordning. Gi\' det videre giver ca. 2.000 ton effekter nyt liv om året, og på genbrugsstationerne er brændbart erstattet af rest efter sortering og polstrede møbler. Affaldsforebyggelse i institutioner og indkøb er ikke sat i gang. En reparationsordning er ikke undersøgt, fordi kommunerne efter Lov 898 ikke må deltage i behandling af affald egnet til materialenyttiggørelse. Målet om, at 99,9 % af afhentningerne sker på den lovede dag, er nået.' },
      { id: 'NY174', title: 'Principper for udbud', org: 'Reno Djurs', year: 2026, type: 'Notat', temaer: ['Udbud og kravspecifikationer', 'Hente- og bringeordninger', 'Afsætning og behandling'], img: 'img/892552e7ad5d290d483bc9bcf96ce981.jpg', url: 'https://renodjurs.dk/sites/default/files/2026-09/Bilag%2020.2_Udbudsprincipper.pdf', res: 'Notat til bestyrelsen i Reno Djurs om de principper, selskabet følger ved udbud af affaldsopgaver og indkøb, fra valg af udbudsform og tildelingskriterier til kontraktlængde.', long: 'Administrationen i Reno Djurs beskriver i august 2026, hvordan selskabet udbyder indsamling, transport, behandling af ca. 20 affaldstyper, varekøb og anlægsarbejder. Tjenesteydelser og varekøb over ca. 1,6 mio. kr. skal i EU-udbud. I indsamlingsudbuddet blev laveste pris brugt med høje mindstekrav, mens beholderudbuddet vægtede pris og kvalitet. Indsamlingskontrakter løber typisk 4-5 år, men udbuddet i 2021 fik 6 år plus 2 års option, bl.a. fordi entreprenøren skulle investere i dobbeltkammerbiler. Sortering af afsat affald skal normalt ske i EU/EØS, og de fleste kontrakter er klassiske kontrakter med hårde krav.' },
      { id: 'NY175', title: 'Beslutningsoplæg for håndtering af poser til hhv. mad- og tekstilaffald', org: 'FARR-samarbejdet', year: 2022, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Tekstil', 'Sorteringskvalitet'], img: 'img/0d5354010f7eb8aa73db7f1f71da5b99.jpg', url: 'https://renodjurs.dk/sites/default/files/2022-09/Bilag%2031_FARR-notat.pdf', res: 'Beslutningsoplæg til FARR-samarbejdets direktører om poser til mad- og tekstilaffald. Styregruppen anbefaler poser til begge fraktioner, farvede til madaffald og klare til tekstil.', long: 'Notatet fra juni 2022 går til direktørgruppen i FARR, hvor Favrskov Forsyning, Kredsløb, Renosyd og Reno Djurs samarbejder om at indføre sortering i 10 fraktioner. Loven kræver ikke poser til madaffald, men tekstilaffald skal i pose, fordi FARR indsamler det sammen med pap og papir. Notatet stiller tre scenarier op for madaffaldsposer, fra uddeling i ét år (2023) til løbende uddeling, og vurderer miljø, økonomi, service, arbejdsmiljø og risikoen for negativ politisk omtale. Løbende uddeling giver den bedste sortering, men koster mest og bruger mest plast. Styregruppen anbefaler en fælles opstart og samme uddelingsmodel for begge posetyper.' },
      { id: 'NY176', title: 'Koncept for farligt affald fra fælles bebyggelser', org: 'Favrskov Forsyning, Kredsløb, Renosyd og Reno Djurs', year: 2022, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Etageboliger', 'Økonomi'], img: 'img/e4c0410e31f5e24bc28f0d8103a7ad0a.jpg', url: 'https://renodjurs.dk/sites/default/files/2022-12/Bilag%2043_Koncept%20for%20farligt%20affald%20i%20f%C3%A6llesbebyggelser.pdf', res: 'Notatet foreslår fem måder at hente farligt affald i fælles bebyggelser, fra kasser på egen grund til automatskabe. Alle bygger på genbrugelige kasser på 10 og 21 liter.', long: 'De fire affaldsselskaber i FARR-samarbejdet beskriver i december 2022, hvordan farligt affald kan hentes i fælles bebyggelser, hvor kassen fra enfamilieboliger ikke kan stå på beholderne. Løsningerne er kasser på et afgrænset areal ved mindre bebyggelser, en viceværtordning, skabe med kodelås, automatskabe til bebyggelser uden egen plads og butiksskabe til batterier, elsparepærer og småt elektronik. En særlig operatør skal tømme og bytte kasserne fx 4, 6 eller 8 gange om året. Køb af kasser, indsamling, behandling og vask skal i fælles udbud, og de årlige omkostninger anslås til 35-115 kr. ekskl. moms pr. omfattet husstand.' },
      { id: 'NY177', title: 'Årsrapport 2025', org: 'Renosyd', year: 2026, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse', 'Økonomi'], img: 'img/6c25d8caf131b7957ac6a2f858a854a1.jpg', url: 'https://renosyd.dk/wp-content/uploads/2026/05/renosyd_aarsrapport-2025_endelig.pdf', res: 'Renosyds årsrapport for 2025, det første hele år med sortering i 10 fraktioner. Restaffaldet er halveret siden 2023, og gebyrerne er blandt de 10 % laveste i landet.', long: 'Årsrapporten fra affaldsselskabet for Skanderborg og Odder Kommuner dækker klima og miljø, pris og service, medarbejdere, ESG og regnskab og har et databilag med mængder pr. fraktion 2018-2025. Restaffaldet faldt fra 18.272 ton i 2023 til 8.918 ton i 2025, eller fra 205 til 99 kg pr. borger. Af 22.744 ton husstandsindsamlet affald blev 11.695 ton reelt genanvendt. Genbrugspladser og værdiparker havde 575.000 besøg, og over 99 % af tømningerne skete til tiden. Nettoomsætningen var 167,2 mio. kr., og selskabet hviler i sig selv. Producentansvaret for emballage fra 1. oktober 2025 har påvirket bl.a. økonomistyring og kontrakter.' },
      { id: 'NY178', title: 'Ejerpolitik for renosyd', org: 'Renosyd', year: 2025, type: 'Strategi', temaer: ['Affaldsplaner/regulativer og strategi', 'Ledelse'], img: 'img/76dc0b6f419bd10a5b42d2007269ed17.jpg', url: 'https://renosyd.dk/wp-content/uploads/2025/12/FINAL_Ejerpolitik-2025.pdf', res: 'Odder og Skanderborg Kommuners ejerpolitik for renosyd fastlægger visionen for selskabet og strategiske spor for pris og service, klima og miljø samt mennesker og fællesskaber.', long: 'Politikken blev godkendt af Odder Kommunalbestyrelse 11. november 2025 og Skanderborg Byråd 26. november 2025 og giver renosyds bestyrelse et tydeligt mandat. Visionen er, at renosyd bidrager til FN\'s verdensmål og overgangen til cirkulær økonomi. Gebyrerne, der i 2024 lå blandt de 10 % laveste i landet, skal fortsat være lave uden store udsving fra år til år. På klima og miljø skal renosyd bl.a. bygge videre på det direkte genbrug sammen med lokale frivillige organisationer. I 2024 betjente renosyd 42.000 ejendomme og indsamlede 70.000 ton affald. Politikken revideres normalt hvert fjerde år, men næste gang allerede i 2027.' },
      { id: 'NY179', title: 'Affaldshåndtering på genbrugspladser i Favrskov Kommune', org: 'Favrskov Forsyning', year: 2023, type: 'Rapport', temaer: ['Genbrugspladser', 'Direkte genbrug', 'Udbud og kravspecifikationer'], img: 'img/2206f8b84c3b3b9b2bb61536513d2ee0.jpg', url: 'https://www.favrskovforsyning.dk/Admin/Public/DWSDownload.aspx?File=%2fFiles%2fFiles%2fAffaldsh%c3%a5ndtering+p%c3%a5+genbrugspladser_rapport+AAL.pdf', res: 'Studerende fra Aalborg Universitet foreslår Favrskov Forsyning et udvidet affaldshierarki, 15 tiltag på genbrugspladserne og en udbudspolitik for valg af aftagere.', long: 'Seks studerende fra By-, Energi- og Miljøplanlægning på Aalborg Universitet skrev rapporten i efteråret 2023 i samarbejde med Favrskov Forsyning. Den bygger på interviews med forsyningen og en genbrugsvejleder, feltbesøg på Hammel Genbrugsplads, der sorterer i 38 fraktioner, og litteratur. Rapporten foreslår et udvidet affaldshierarki, hvor genbrug deles i direkte genbrug og forberedelse til genbrug, og genanvendelse i upcycling og downcycling. Den peger på 15 tiltag, fx grønne guider på pladserne, og på en udbudspolitik, der vægter økonomi, miljø og samfundsansvar ved valg af aftagere. Kunder og aftagere er ikke spurgt.' },
      { id: 'NY180', title: 'Vores fremtid i den grønne omstilling. Strategi for AffaldPlus 2025-2030', org: 'AffaldPlus', year: 2025, type: 'Strategi', temaer: ['Affaldsplaner/regulativer og strategi', 'Ledelse', 'Klima'], img: 'img/118d4fbe4d1e85021e16dcc64d8f18ba.jpg', url: 'https://affaldplus.dk/sites/default/files/2026-01/Strategi_2025-2030_final_dec_2025_0.pdf', res: 'AffaldPlus\' koncernstrategi for 2025-2030 har fem strategiske spor og 18 ambitioner med effektmål, fx 60 % genanvendelse i ejerkommunerne og mere direkte genbrug.', long: 'Bestyrelsen i AffaldPlus vedtog strategien i december 2025, og den gælder hele koncernen. Affaldsenergianlægget blev selskabsgjort 1. januar 2025 og drives nu på markedsvilkår, så AffaldPlus vil agere mere kommercielt. Ejerkommunerne skal hjælpes til 60 % genanvendelse i 2030 mod 57,6 % i 2024, og direkte genbrug skal stige med mindst 15 procentpoint. Genbrugsbutikkerne og -byggemarkederne skal have 600.000 kunder om året senest i 2028 mod 514.283 i 2024. I/S\'ets CO2e-udledning skal falde mindst 10 % fra 2026 til 2030, og i 2026 skal det afklares, under hvilke betingelser der kan etableres CCS ved affaldsenergianlægget.' },
      { id: 'NY181', title: 'Ledelses- og ansvarlighedsrapport 2024', org: 'Fors A/S', year: 2025, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Direkte genbrug', 'Genbrugspladser'], img: 'img/486cbbee864acfe3c7be0c6b4237dbf8.jpg', url: 'https://fors.dk/media/dzyoqwjy/ledelses-og-ansvarlighedsrapport2024.pdf', res: 'Fors-koncernens redegørelse for samfundsansvar 2024. Fors Affald Holbæk håndterede 54.668 tons affald og nåede 59,8 % genanvendelse af de syv fokusfraktioner.', long: 'Fors A/S udgav i juni 2025 koncernens lovpligtige redegørelse for samfundsansvar, som dækker vand, spildevand, varme og affald. Affaldsdelen gælder Fors Affald Holbæk A/S, der driver fem genbrugspladser og betjener ca. 26.359 kunder. I 2024 blev 40.353 af i alt 54.668 tons genanvendt, og 66,6 % af mængden kom fra genbrugspladserne. Genanvendelsen af de syv fokusfraktioner nåede 59,8 %, og målet på 65 % i 2025 vurderes urealistisk. Genbrugsbutikker, gratisområder, lagersalg og frivillige foreninger gav 594 tons nyt liv. Emissionsfaktoren er 19,15 kg CO2e pr. håndteret ton inklusive scope 3.' },
      { id: 'NY182', title: 'Affaldsstatus 2025. Allerød, Fredensborg, Hørsholm og Rudersdal Kommune', org: 'Norfors', year: 2026, type: 'Statistik', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse', 'Genbrugspladser'], img: 'img/97c692247bbceb7c395a6afde3a589a3.jpg', url: 'https://backend.norfors.dk/sites/default/files/2026-07/Affaldsstatus%202025.pdf', res: 'Norfors\' årlige opgørelse af husholdningsaffald i fire nordsjællandske kommuner for 2021-2025. Hver indbygger afleverede i snit 745 kg i 2025, og 67 % blev afsat til genanvendelse.', long: 'Affaldsstatus 2025 dækker Allerød, Fredensborg, Hørsholm og Rudersdal med ca. 151.000 indbyggere og viser mængderne samlet og for hver kommune. Tallene kommer fra Norfors\' og kommunernes registreringer og Affaldsdatasystemet. I 2025 blev der håndteret ca. 113.000 ton husholdningsaffald. Den reelle genanvendelse er 54 % ud fra Affaldsdatasystemet og 63 % ud fra de mængder, Norfors og kommunerne selv håndterer. Fra 2018 til 2025 steg de fem tørre fraktioner med 35 %, mens restaffaldet faldt 45 %. Siden 1. juli 2025 går det brændbare affald til ARGO, og Norfors importerede 27.712 ton affald i 2025.' },
      { id: 'NY183', title: 'Miljøberetning for genbrugspladserne 2025', org: 'Norfors', year: 2026, type: 'Statistik', temaer: ['Genbrugspladser', 'Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/331827b580e61f309623ceadbf15b957.jpg', url: 'https://backend.norfors.dk/sites/default/files/2026-07/Milj%C3%B8beretning%20Genbrugspladser%202025.pdf', res: 'Norfors\' seks genbrugspladser modtog 73.643 tons affald i 2025, 3 % mere end året før. Heraf gik 55.722 tons til genanvendelse, og pladserne havde knap 1,1 mio. besøg.', long: 'Miljøberetningen fra I/S Norfors dækker genbrugspladserne Allerød, Bakkegårdsvej, Blokken, Containerhaven, Højvangen og Vandtårnsvej med tal for 2021-2025 og et afsnit for hver plads. Af affaldet i 2025 gik 55.722 tons til genanvendelse, 7.445 til energiudnyttelse, 9.482 til specialbehandling og 995 til deponi. Imprægneret træ er steget fra 1.704 tons i 2021 til 7.805 tons. Kirkens Korshær og Spildopperne fik ca. 92 tons til direkte genbrug. Omkring 10 % af besøgene sker i den ubemandede åbningstid, som giver mere fejlsortering, og alle maskiner kører nu på HVO-diesel.' },
      { id: 'NY184', title: 'Vestforbrænding årsrapport 2025', org: 'Vestforbrænding', year: 2026, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Direkte genbrug', 'Genbrugspladser'], img: 'img/aecf81f15c1ef95c638187efbc2339a9.jpg', url: 'https://cms.vestfor.dk/media/rahpa2e3/vestforbraending-aarsrapport-2025.pdf', res: 'Vestforbrændings årsrapport for 2025 viser 10.000 ton direkte genbrug mod ca. 58 ton i 2021 og en reel genanvendelse på 52,4 %, mens årets resultat endte på -6 mio. kr.', long: 'I/S Vestforbrænding ejes af 19 kommuner og håndterer affald fra ca. en million borgere. Rapporten indeholder ledelsesberetning og regnskab. Genbrugsstationerne tog imod 329.400 ton, hvoraf 254.500 ton gik til mulig genanvendelse, og det direkte genbrug nåede 10.000 ton, især på grund af mursten fra byggeaffald. Den reelle genanvendelse var 52,4 % mod et mål på 53 % for 2025 og 60 % i 2030. Forbrændingen faldt til 438.300 ton, fordi et anlæg var ude af drift efter et strømnedbrud i august. Selskabet er begyndt at indsamle eternitplader uden asbest og tester sortering af tekstilaffald. For 2026 er målet 12.500 ton direkte genbrug.' },
      { id: 'NY185', title: 'Ejerstrategi for Halsnæs Forsyning', org: 'Halsnæs Kommune', year: 2025, type: 'Strategi', temaer: ['Ledelse', 'Affaldsplaner/regulativer og strategi'], img: 'img/a16a8bb5e25f53fc8bf0fb7b7e9ff40e.jpg', url: 'https://hnf.dk/files/media/document/Ejerstrategi%20for%20Halsn%C3%A6s%20Forsyning_Besluttet%20af%20Byr%C3%A5det%20d%2013112025.pdf', res: 'Halsnæs Kommunes ejerstrategi for Halsnæs Forsyning, vedtaget af byrådet 13. november 2025. Den sætter mål og rammer for selskabet, der også står for dele af affaldet.', long: 'Ejerstrategien rummer Halsnæs Kommunes mål for Halsnæs Forsyning A/S og er grundlag for dialogen mellem ejer og selskab. Koncernen har fem datterselskaber, heriblandt Halsnæs Affald A/S, og står for vand, spildevand, fjernvarme og dele af affaldshåndteringen. Forsyningen skal gennemføre de relevante dele af kommunens sektorplaner, herunder affaldsplanen, og bidrage til målet om CO2-neutralitet i 2050. Strategien fastlægger et årligt møde med Økonomiudvalget og kvartalsmøder mellem ledelserne. Byrådet udpeger 5 af bestyrelsens medlemmer og medarbejderne 3. Strategien afløser den fra 2016 og gælder til 1. januar 2030.' },
      { id: 'NY186', title: 'Nordværk I/S årsrapport 2025', org: 'Nordværk', year: 2026, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Afsætning og behandling', 'Økonomi'], img: 'img/e649574c08a1550baf2aefe68fe0716f.jpg', url: 'https://nordvaerk.dk/media/v23hlwtu/nordvaerk_aarsrapport_is_2025_endelig.pdf', res: 'Nordværks årsrapport for 2025 med regnskab og nøgletal. Omsætningen var ca. 1.001 mio. kr., og der blev i gennemsnit indsamlet 9,7 kg affald pr. husstand pr. uge i ejerkommunerne.', long: 'Nordværk I/S er et fælleskommunalt § 60-selskab ejet af syv nordjyske kommuner, og årsrapporten rummer ledelsesberetning og regnskab. Selskabet tømmer over 600.000 beholdere om måneden og driver 31 genbrugspladser med over 1,9 millioner besøgende. Andelen af husstandsindsamlet affald til genanvendelse lå på 43-49 % i seks kommuner, men kun 32 % i Aalborg, der startede madaffaldsindsamlingen sidst. Fælles udbud af fraktioner har givet besparelser på 12,9 mio. kr. Årets overskud blev ca. 4,1 mio. kr., og i 2026 venter selskabet at opkræve 100 mio. kr. i producentgebyr for emballageaffald på vegne af ejerkommunerne.' },
      { id: 'NY187', title: 'Miljøredegørelse for 2023', org: 'Nordværk', year: 2024, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Genbrugspladser', 'Afsætning og behandling'], img: 'img/2cbb83b6f98735442123a7dd445ae403.jpg', url: 'https://nordvaerk.dk/media/krvdckdk/endelig_miljoeredegoerelse.pdf', res: 'Nordværks miljøredegørelse for 2023 med mål og data for selskabets anlæg. Første år med nummerpladescanning viste, at virksomheder stod for 6 % af besøgene på genbrugspladserne.', long: 'Redegørelsen gennemgår årets miljø- og arbejdsmiljøindsats og har nøgletal for bl.a. genbrugspladser, sorteringsanlæg, energianlæg, deponi og transport. De 18 genbrugspladser, Nordværk drev i Hjørring og Brønderslev kommuner, modtog 55.728 ton i 2023, og 71,3 % gik til genanvendelse mod et mål på over 75 % i 2025. Ca. 1.800 virksomheder brugte pladserne 38.460 gange, uden at affaldsmængden steg. Sorteringsanlægget for plast, metal og mad- og drikkekartoner modtog godt 8.000 ton med over 40 % fejlsortering og blev solgt til Verdis. Efter to aflyste udbud af tekstilaffald fik Nordværk en toårig rammeaftale med Ragn-Sells fra april 2024.' },
      { id: 'NY188', title: 'Thy Forsyning A/S\' ansvarlighedsrapport 2025', org: 'Thy Forsyning', year: 2026, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Reel genanvendelse'], img: 'img/5a3c536b4623d673c941277aaf4d714f.jpg', url: 'https://thyforsyning.dk/media/twrhw4az/ansvarlighedsrapport-2025-thy-forsyning.pdf', res: 'Thy Forsynings første ansvarlighedsrapport dækker vand, spildevand og affald i 2025. Den reelle genanvendelse af husholdningsaffald i Thisted Kommune nåede 56,6 %.', long: 'Thy Forsyning har lavet rapporten efter inspiration fra VSME-standarden og på grundlag af en dobbelt væsentlighedsanalyse af driften i 2025. På affaldsområdet blev der indsamlet 33.095,5 ton, 66 % på genbrugscentrene og 34 % ved husstandene, og 1.186,6 ton var miljøfarligt affald. Den reelle genanvendelse af husholdningsaffald lå på 56,6 %, over EU-målet på 55 % for 2025 men under målene for 2030 og 2035. Sortering og genanvendelse gav en beregnet besparelse på 1.928 ton CO2e mod 2.158 ton i 2024. Alle fire genbrugscentre er nu renoveret. Selskabets egen udledning i scope 1 og 2 var 707 ton CO2e, opgjort lokationsbaseret.' },
      { id: 'NY189', title: 'Redegørelse for samfundsansvar 2024', org: 'Vesthimmerlands Forsyning', year: 2025, type: 'Rapport', temaer: ['Klima', 'Data, statistikker og nøgletal', 'Genbrugspladser'], img: 'img/66f665d1fe3c355079dde71b36b2225a.jpg', url: 'https://vesthimmerlandsforsyning.dk/Files/Files/Redegoerelse-for-samfundsansvar-2024.pdf', res: 'Vesthimmerlands Forsyning gør status over samfundsansvar i 2024 for affald, spildevand og drikkevand. Udledningen var 1.849 tons CO₂e, og genbrugspladserne fik 7,2 % flere besøg.', long: 'Vesthimmerlands Forsyning har skrevet redegørelsen med sparring fra Nexus Konsulenterne og opgjort CO₂e med Klimakompasset for scope 1 og 2. Affaldsområdets udledning faldt 4 % fra 2023, bl.a. fordi en ændring af storskraldsordningen i 2023 skar antallet af storskraldsbiler fra fire til én og dieselforbruget til storskrald med 74 %. De fire genbrugspladser havde 156.880 besøg, heraf 4,59 % fra erhvervskunder, hvilket selskabet vurderer ligger under den reelle brug. Der blev tømt 590.960 beholdere med 122 reklamationer. En case beskriver asbestordningen og den nye fraktion eternit uden asbest, der nu sendes til genanvendelse frem for deponi.' },
      { id: 'NY190', title: 'Status på husstandsindsamlet affald', org: 'Odense Renovation', year: 2026, type: 'Faktaark', temaer: ['Data, statistikker og nøgletal', 'Sorteringskvalitet', 'Afsætning og behandling'], img: 'img/dbcd08bbab3403abe1c48b4a73cf195d.jpg', url: 'https://www.odenserenovation.dk/media/3376/dit-affald-i-tal-juli-2026.pdf', res: 'Odense Renovations faktaark sammenholder de indsamlede mængder pr. husstand med potentialet for fem fraktioner. Restaffaldet kunne halveres, hvis alt blev sorteret korrekt.', long: 'For hver fraktion viser faktaarket potentialet pr. husstand ifølge affaldsanalyser, den indsamlede mængde i 2025 og mængden til og med maj 2026, inklusive fejlsorteringer. Potentialet for plast og mad- og drikkekartoner er 55 kg, og der blev indsamlet 34 kg i 2025. Ca. 59 % genanvendes efter sortering på et anlæg i Esbjerg, mens resten brændes. Papir og småt pap er en ren fraktion med 44 kg mod et potentiale på 80 kg, og ca. 97 % genanvendes. Ca. 88 % af madaffaldet bliver til biopulp hos Gemidan i Odense. Med 234 kg restaffald pr. husstand i 2025 mod et potentiale på 120 kg vurderer selskabet, at mængden kunne falde 50 %.' },
      { id: 'NY191', title: 'Ophævelse og hjemvisning i sag om Forsyning Helsingør Affald A/S’ delvise afslag på aktindsigt', org: 'Miljø- og Fødevareklagenævnet', year: 2021, type: 'Afgørelse', temaer: ['Lovgivning og afgørelser'], img: 'img/dc3b59a05f4942c12cc18c46ba64dc3f.jpg', url: 'https://mfkn.naevneneshus.dk/media/documents/__21_07527-16_21_07527_-_Afg%C3%B8relse_2650387_1_1_anonymiseret.pdf', res: 'Miljø- og Fødevareklagenævnet ophæver Forsyning Helsingør Affalds delvise afslag på aktindsigt, fordi selskabet brugte offentlighedsloven i stedet for miljøoplysningsloven.', long: 'En klager bad i marts 2021 Forsyning Helsingør Affald A/S om aktindsigt i materiale om en ny affaldsordning, bl.a. om hvilke villaer der skulle justere adgangsveje. Selskabet undtog en liste over adresser, der kunne blive berørt, med henvisning til offentlighedsloven. Nævnet fandt i december 2021, at selskabet er omfattet af miljøoplysningsloven, fordi det via Forsyning Helsingør A/S er 100 % ejet af kommunen og løser kommunens affaldsopgaver. Adresselisten blev indsamlet som led i den nye affaldsordning og rummer derfor miljøoplysninger. Sagen blev sendt tilbage, og et nyt afslag skal bygge på en konkret afvejning og begrundes.' },
      { id: 'NY192', title: 'Styresignal: Momslovens § 3, stk. 2, nr. 2 og 3. Kommunale renovationsydelser. Genoptagelse', org: 'Skattestyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Økonomi'], img: 'img/f1f4cb8b1ab86c1cb81f2a14439c0aa9.jpg', url: 'https://www.retsinformation.dk/eli/retsinfo/2023/10297/pdf', res: 'Skattestyrelsen ændrer praksis, så kommuner ikke skal opkræve moms af renovation til borgere og grundejerforeninger, og forklarer, hvordan momsen kan søges tilbage fra 2012.', long: 'Styresignalet følger Landsskatterettens afgørelser af 21. oktober 2020. Tre kommuner fik medhold i, at renovation ikke er momspligtig, fordi borgerne skal bruge den kommunale ordning og der derfor ikke er konkurrence. Den nye praksis omfatter også tilkøb som ekstra tømning og ydelser fra § 60-selskaber, men ikke private underleverandører. Det generelle administrationsgebyr fra 2010-2019 er omfattet og måske visse erhvervsaffaldsordninger. Kommunerne mister så fradrag for købsmoms. Pengene skal efter hvile i sig selv-princippet gå videre til gebyrbetalerne, og ekstraordinær genoptagelse skal søges senest 6 måneder efter offentliggørelsen.' },
      { id: 'NY193', title: 'Tilsynsudtalelse om Nordværks I/S’ hjemmeside genbrugsauktion.dk', org: 'Ankestyrelsen', year: 2023, type: 'Afgørelse', temaer: ['Lovgivning og afgørelser', 'Direkte genbrug'], img: 'img/fdc6c8c3e50061e01397b2706d24a659.jpg', url: 'https://cdn.ast.dk/ankestyrelsen/media/16175/230_Nordv%C3%A6rk_I_S_-_Udtalelse_-_Auktioner_over_genbrugsgenstande_p%C3%A5_hjemmeside.pdf', res: 'Ankestyrelsen vurderer, at Nordværk I/S må sælge genbrugsting fra egne pladser på genbrugsauktion.dk, men ikke mod gebyr lade andre affaldsselskaber holde auktioner på siden.', long: 'Udtalelsen fra 28. juni 2023 svarer på en tilsynssag, som Ankestyrelsen tog op i 2019. Siden blev oprettet i 2006 af Affaldsselskabet Vendsyssel Vest og drives nu af Nordværk I/S. Andre selskaber som Sønderborg Forsyning og Renosyd betaler et opstartsgebyr og et årligt gebyr for at sælge via siden. Salg af egne genbrugsgenstande til markedspris er efter Ankestyrelsens vurdering en lovlig afrunding af fællesskabets affaldsopgaver. Adgangen for andre er derimod salg af en tjenesteydelse og erhvervsvirksomhed uden hjemmel, da der hverken er tale om lovlig overkapacitet eller en betjeningsoverenskomst. Bestyrelsen bedes svare inden tre måneder.' },
      { id: 'NY194', title: 'Kendelse: Remondis A/S mod Silkeborg Genbrug og Affald A/S', org: 'Klagenævnet for Udbud', year: 2021, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/4a5f99cd6c18229e3bc7388378246552.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Remondis_AS_mod_Silkeborg_Genbrug_og_Affald_AS.pdf', res: 'Silkeborg Genbrug og Affald gav uden udbud HCS en midlertidig kontrakt om affaldsindsamling. Klagenævnet for Udbud annullerede tildelingen, men lod kontrakten løbe videre.', long: 'Remondis havde opsagt sin kontrakt med Silkeborg Genbrug og Affald (SGA), og to nye udbud var annulleret på grund af fejl. I september 2019 indgik SGA derfor uden udbud en kontrakt med HCS om indsamling fra 1. januar 2020 til 20. marts 2022 for ca. 31,8 mio. kr. om året. I kendelsen fra 6. januar 2021 fandt nævnet, at betingelserne i udbudslovens § 80, stk. 5, ikke var opfyldt, fordi SGA havde haft tid nok til et lovligt udbud. Kontrakten fik dog lov at løbe af hensyn til almenhedens interesser, fordi nye lastbiler havde 14-18 måneders leveringstid. Nævnet indgav i stedet politianmeldelse, og SGA skal betale 45.000 kr. i sagsomkostninger.' },
      { id: 'NY195', title: 'Kendelse: Remondis A/S mod Hedensted Kommune', org: 'Klagenævnet for Udbud', year: 2020, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/b94351ac27b154987bca3db231377557.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Remondis_AS_mod_Hedensted_Kommune.pdf', res: 'Klagenævnet for Udbud fandt, at Hedensted Kommune lovligt udbød indsamling af dagrenovation som en offentlig kontrakt på 6 år med option på 2 år og ikke som rammeaftale.', long: 'Hedensted Kommune udbød i 2020 indsamling af fem fraktioner kildesorteret dagrenovation til en anslået værdi af 135 mio. kr. og ville indgå kontrakt med Meldgaard Miljø. Remondis klagede og mente, at aftalen reelt var en rammeaftale, fordi leverandøren ikke er sikret en mindsteomsætning, og mængderne afhænger af borgernes valg. Derfor måtte den højst løbe 4 år. I kendelsen fra 7. oktober 2020 lagde nævnet vægt på, at leverandøren har sikkerhed for at hente dagrenovationen til de tilbudte enhedspriser, og at variationer ikke betyder, at der tildeles nye kontrakter. Remondis fik ikke medhold og skal betale 30.000 kr. i sagsomkostninger.' },
      { id: 'NY196', title: 'Kendelse: Verdis A/S mod Gribskov Genbrug & Ressourcer A/S', org: 'Klagenævnet for Udbud', year: 2024, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser'], img: 'img/66343ddc45635c46ef520c68687d7ac5.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Verdis_AS_mod_Gribskov_Genbrug_og_Ressourcer_AS.pdf', res: 'Klagenævnet for Udbud annullerer Gribskov Genbrugs tildeling af to kontrakter om dagrenovation, fordi selskabet ikke regnede tilbudte rabatter med, som udbudsbetingelserne sagde.', long: 'Gribskov Genbrug & Ressourcer A/S udbød i 2024 indsamling af dagrenovation i to delkontrakter for 55 % og 45 % af kommunen og gav begge til Svendsen & Søn. Tilbudsgiverne kunne give rabat, hvis de vandt begge dele, og Verdis tilbød 7,5 % mod 3,5 %. Selskabet vurderede hver delkontrakt for sig, og da Verdis med rabat fik 78,93 point mod 79 på Gribskov Øst, kom rabatten aldrig i spil. I kendelsen fra 29. oktober 2024 læste nævnet »samlet set« som begge delkontrakter under ét, og her var Verdis bedst. Tildelingen blev annulleret, og Gribskov Genbrug skal betale Verdis 25.000 kr. i sagsomkostninger.' },
      { id: 'NY197', title: 'Kendelse om erstatning: Verdis A/S mod Gribskov Genbrug & Ressourcer A/S', org: 'Klagenævnet for Udbud', year: 2025, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser'], img: 'img/90359bc99c48e4bb1a85817fcdad0a91.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Verdis_AS_mod_Gribskov_Genbrug_og_Ressourcer_AS_7OsX3vQ.pdf', res: 'Klagenævnet for Udbud tilkender Verdis 10 mio. kr. i erstatning, fordi Gribskov Genbrug ikke regnede rabatter med i evalueringen og gav indsamlingskontrakterne til en anden.', long: 'Kendelsen fra 24. marts 2025 følger op på nævnets kendelse fra oktober 2024, der annullerede Gribskov Genbrug & Ressourcers tildeling til Svendsen & Søn Transport, fordi rabatter ikke indgik i evalueringen af pris. Verdis krævede 19.153.000 kr. i positiv opfyldelsesinteresse ud fra en omsætning på 262,5 mio. kr. over otte år. Gribskov Genbrug mente, at evalueringsmodellen var så uklar, at udbuddet skulle have været annulleret. Det afviste nævnet, men Verdis kunne ikke dokumentere tabets størrelse. Erstatningen blev derfor skønsmæssigt sat til 10 mio. kr. med procesrente fra 11. november 2024 plus 35.000 kr. i sagsomkostninger.' },
      { id: 'NY198', title: 'Kendelse: Vognmand Andreas R. Søborg A/S mod Odsherred Kommune', org: 'Klagenævnet for Udbud', year: 2025, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Genbrugspladser'], img: 'img/030f90da16601754f93006f13e1668d1.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Vognmand_Andreas_R._S%C3%B8borg_AS_mod_Odsherred_Kommune.pdf', res: 'Odsherred Kommune afviste en vognmands tilbud på transport fra genbrugsstationerne på grund af referencerne. Klagenævnet for Udbud fandt kravet uklart og annullerede tildelingen.', long: 'Kendelsen fra februar 2025 gælder Odsherred Kommunes udbud af transport fra fire genbrugsstationer og en grenplads til anslået 60 mio. kr. Tilbudsgiverne skulle have en reference af samme art og størrelse fra de seneste 3 år eller som nye aktører vise relevant erfaring på anden vis. Kommunen mente, at den sidste mulighed kun gjaldt nystartede firmaer, og afviste Vognmand Andreas R. Søborg A/S, stiftet i 2019. Nævnet fandt, at kravet også omfattede ældre firmaer, der ikke før havde kørt affald, og at kommunen bar risikoen for uklarheden. Tildelingen til Olaf Jensen A/S blev annulleret, og kommunen skal betale 20.000 kr. i sagsomkostninger.' },
      { id: 'NY199', title: 'Kendelse: Fugato A/S mod Bornholms Regionskommune, Bornholms Affaldsbehandling', org: 'Klagenævnet for Udbud', year: 2022, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/ec6d51ae73c9e845cbf4b63181bf3d91.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Fugato_AS_mod_Bornholms_Regionskommune.pdf', res: 'Klagenævnet for Udbud gav ikke Fugato medhold i klagen over BOFAs udbud af affaldsindsamling på Bornholm. Evalueringen af vinderens tilbud lå inden for udbudsbetingelserne.', long: 'Kendelsen fra 23. maj 2022 gælder BOFAs udbud med forhandling af indsamling fra ca. 22.500 helårshusstande og 4.400 sommerhuse, anslået til 370 mio. kr. over 9 år og 3 måneder. Fugato klagede bl.a. over, at vinderen HCS fik point for brændstoffet GTL med CO2-kompensation, og over at BOFA efter de endelige tilbud bad HCS bekræfte en række forhold. Nævnet fandt, at BOFA holdt sig inden for sit skøn ved evalueringen. BOFA havde prissat vinderens forbehold på forhånd, og de øvrige fejl var åbenlyse og måtte præciseres efter udbudslovens § 159, stk. 5. Fugato skal betale 45.000 kr. i sagsomkostninger.' },
      { id: 'NY200', title: 'Kendelse: BioVækst A/S mod Københavns Kommune, Teknik og Miljøforvaltningen', org: 'Klagenævnet for Udbud', year: 2021, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/334bbc57b4b2ae35abcb626faefc7ced.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/BioV%C3%A6kst_AS_mod_K%C3%B8benhavns_Kommune.pdf', res: 'Klagenævnet for Udbud gav ikke BioVækst medhold i en klage over Københavns udbud af bioaffaldsbehandling, hvor tilslutning til et måleprogram for metantab var et mindstekrav.', long: 'Københavns Kommune udbød i 2020 behandling af ca. 14.000 ton bioaffald om året med pris vægtet 60 % og miljø 40 %. Et mindstekrav var, at biogasanlægget var tilsluttet Foreningen Biogasbranchens frivillige måleprogram for metantab eller en lignende ordning. Kommunen afviste tilbuddet, fordi BioVækst efter beskrivelsen selv og ikke et eksternt målefirma målte metantabet, og gav kontrakten til HCS A/S. I kendelsen fra 4. marts 2021 fandt klagenævnet, at programmet var kendt i branchen, også af BioVækst, og at kommunen ikke var forpligtet til at bede om en præcisering. BioVækst skal betale 25.000 kr. i sagsomkostninger.' },
      { id: 'NY201', title: 'Kendelse: Solum Roskilde A/S mod I/S Vestforbrænding', org: 'Klagenævnet for Udbud', year: 2024, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/561c61cd8892e96212e01b7fb554fb3f.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Solum_Roskilde_AS_mod_IS_Vestforbr%C3%A6nding.pdf', res: 'Klagenævnet for Udbud gav ikke Solum Roskilde medhold i en klage over Vestforbrændings pointgivning for miljø i et udbud af behandling af haveaffald. Ordregivers skøn holdt.', long: 'Kendelsen af 7. november 2024 gælder to delaftaler i Vestforbrændings udbud af behandling af haveaffald fra genbrugsstationer og husstandsindsamling, hvor miljø vægtede 60 % og omkostninger 40 %. Solum Roskilde tilbød kompostering med aktiv beluftning og fik 8 point for miljøperformance, fordi et lukket system med opsamling af klimagasser ville give flere. RGS Nordic vandt, først med 8,50 mod 7,97 point og igen efter ny evaluering. Nævnet fandt, at metoderne i udbudsbetingelserne kun var eksempler, og at vurderingen lå inden for ordregivers vide skøn, støttet af en rapport fra Miljøstyrelsen. Solum skal betale 10.000 kr. i sagsomkostninger.' },
      { id: 'NY202', title: 'Ragn-Sells Danmark A/S mod Argo I/S og Odsherred Kommune', org: 'Klagenævnet for Udbud', year: 2025, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/fa861cd7db3d637ae95ee90d29089a31.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Ragn-Sells_Danmark_AS_mod_ARGO_IS_og_Odsherred_Kommune.pdf', res: 'Klagenævnet for Udbud gav ikke Ragn-Sells medhold i klagen over, at Argo og Odsherred Kommune gav kontrakterne om behandling af hård plast og PVC fra genbrugspladserne til Posibi.', long: 'Kendelsen fra 20. august 2025 gælder et udbud af to delkontrakter om modtagelse og behandling af hård plast og PVC fra genbrugspladserne, ca. 1.700 tons årligt hos Argo og ca. 400 tons i Odsherred, med pris som eneste kriterium. Ragn-Sells mente, at Posibis tilbud var ukonditionsmæssigt, fordi det havde tre sorteringsled med ballotering før sortering i udlandet, hvor udbuddet viste to. Klagenævnet fandt, at det principielle flowdiagram kun var vejledende, og at Ragn-Sells ikke havde godtgjort, at Posibi brød kravet om at dokumentere 70 % genanvendelse. Klagen blev ikke taget til følge, og Ragn-Sells skal betale 20.000 kr. i sagsomkostninger.' },
      { id: 'NY203', title: 'Kendelse: Urbaser A/S mod Ringkøbing-Skjern Kommune', org: 'Klagenævnet for Udbud', year: 2019, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser'], img: 'img/e0d0203c40d194fe5883d50bb24ab8a0.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Urbaser_AS_mod_Ringk%C3%B8bing-Skjern_Kommune.pdf', res: 'Klagenævnet for Udbud gav ikke Urbaser medhold i klagen over Ringkøbing-Skjern Kommunes økonomiske krav i et udbud af affaldsindsamling, men kritiserede kommunens begrundelse.', long: 'Ringkøbing-Skjern Kommune krævede i et udbud af affaldsindsamling, at tilbudsgiverne i hvert af de seneste tre regnskabsår havde en omsætning på mindst 30 mio. kr., en egenkapital på mindst 3 mio. kr. og en soliditetsgrad på mindst 15 %. Urbaser blev afvist, fordi soliditetsgraden kun var opfyldt i 2015, og et nystiftet norsk moderselskab kunne ikke dække manglen. Ifølge kendelsen fra juli 2019 var kravene saglige og afvisningen berettiget. Kommunen brød dog udbudsloven ved ikke at oplyse, hvordan moderselskabets økonomi indgik. Tildelingen til Meldgaard Miljø blev ikke annulleret, og Urbaser skal betale 30.000 kr. i sagsomkostninger.' },
      { id: 'NY204', title: 'Kendelse: Be-Low A/S mod Kredsløb A/S', org: 'Klagenævnet for Udbud', year: 2026, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser'], img: 'img/dfcfff9617763725182ffec343aebaee.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Be-Low_AS_mod_Kredsl%C3%B8b_AS.pdf', res: 'Klagenævnet for Udbud gav ikke Be-Low medhold i klagen over Kredsløbs udbud af nedgravede affaldssystemer. Kravet om 2.500 kg last var et mindstekrav, som vinderen havde bekræftet.', long: 'Kendelsen fra 5. maj 2026 gælder Kredsløbs begrænsede udbud af levering af nedgravede affaldssystemer til en anslået værdi af 75 mio. kr., hvor pris vægtede 40 % og kvalitet 60 %. Be-Low mente, at vinderen Euro Groups tilbud ikke dokumenterede, at kæder eller trækstænger kan holde til 2.500 kg. Nævnet fandt, at kravet var et mindstekrav, selv om det ikke var kaldt sådan, men Euro Group havde bekræftet det uden forbehold, og Kredsløb havde ikke før kontraktindgåelsen fået oplysninger, der gav pligt til at kontrollere det. Nævnet fandt heller ikke fejl i evalueringen eller begrundelsen. Be-Low skal betale 35.000 kr. i sagsomkostninger.' },
      { id: 'NY205', title: 'Joca Trading A/S mod Allerød, Hørsholm og Rudersdal kommuner samt Fredensborg Affald A/S', org: 'Klagenævnet for Udbud', year: 2019, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser'], img: 'img/e4d2f43b5ef09038f9315f0760271e8f.jpg', url: 'https://klfu.naevneneshus.dk/media/documents/Joca_Trading_AS_mod_Aller%C3%B8d_H%C3%B8rsholm_og_Rudersdal_kommuner_samt_Fredensborg_Affald_AS.pdf', res: 'Klagenævnet for Udbud gav kun Joca Trading medhold i, at begrundelsen var for tynd i et udbud af affaldsbeholdere. Tildelingen til Plastic Omnium blev ikke annulleret.', long: 'Rudersdal, Allerød og Hørsholm kommuner og Fredensborg Affald A/S udbød en fireårig rammeaftale om affaldsbeholdere til genanvendelige fraktioner, anslået til 40 mio. kr. Kontrakten gik til Plastic Omnium, og Joca Trading klagede over, at de to andre tilbud indeholdt forbehold og var evalueret forkert. Klagenævnet fandt, at hverken franske bilag eller en 3D-printet skillevæg i vareprøven gjorde tilbuddene ukonditionsmæssige, og at evalueringen lå inden for ordregivernes skøn. Underretningen manglede en fyldestgørende begrundelse, men det kunne ikke føre til annullation. Joca Trading skulle betale 30.000 kr. i sagsomkostninger.' },
      { id: 'NY206', title: 'Biologisk APV på dagrenovation', org: 'BFA Transport og Engros', year: 2024, type: 'Vejledning', temaer: ['Ledelse', 'Hente- og bringeordninger', 'Udbud og kravspecifikationer'], img: 'img/3aa84f49ff6ab270662e5bb2ff03abbe.jpg', url: 'https://bfaportalen.dk/Files/Billeder/BFA-portalen/Transport/Godstransport/PDF/93169-BFA_Biologisk_APV_0612_web.pdf', res: 'Branchevejledning fra BFA Transport om biologisk risikovurdering ved indsamling af dagrenovation. Den viser, hvordan skraldemænd kan beskyttes mod mikroorganismer fra affaldet.', long: 'Vejledningen er udarbejdet af CRECEA for BFA Transport og gennemgået af Arbejdstilsynet i maj 2024. Den største smitterisiko er indånding af aerosoler fra affaldet, og derudover kan mikroorganismer komme ind via sår og beskidte hænder. Den biologiske risikovurdering er et lovkrav og skal laves mindst hvert tredje år som del af APV\'en, fx med en trafiklysmodel og skemaer til vurdering og handleplan. For hver arbejdsproces, fra førerhuset og tømningen til vask af bilen, er der forslag til forebyggelse, blandt andet P3-filter ved højtryksspuling. Et afsnit handler om udbyderens pligter i udbudsmaterialet, fx sommertømning og egnede poser.' },
      { id: 'NY207', title: 'Jeg er skraldemand. Branchevejledning', org: 'BFA Transport og Engros', year: 2011, type: 'Vejledning', temaer: ['Ledelse', 'Hente- og bringeordninger', 'Udbud og kravspecifikationer'], img: 'img/336110131dfad3e735ae6798a20ee6ee.jpg', url: 'https://bfaportalen.dk/Files/Billeder/BFA-portalen/Transport/Godstransport/PDF/93178-Jeg_er_skraldemand_2011.pdf', res: 'Branchevejledning om arbejdsmiljøet for skraldemænd, der indsamler dagrenovation. Den giver råd om adgangsveje, materiel, skraldebiler, hygiejne og kommunens ansvar som udbyder.', long: 'Vejledningen er udgivet i 2011 af Branchearbejdsmiljørådet for transport og engros og gennemset af Arbejdstilsynet. Den henvender sig til skraldemænd, renovationsvirksomheder og kommuner som udbydere og bygger på At-vejledningen om dagrenovationssystemer med eksempler på god praksis. Grundreglen er, at affald skal køres og ikke bæres. Adgangsveje skal helst være korte og vandrette, og de skal være oplyste og ryddet for sne. Ved hældninger over 1:4 skal affaldet normalt flyttes med løfte- eller hejseredskaber. Kommunen har stadig pligt til at sikre arbejdsmiljøet efter udbuddet og skal håndhæve sit regulativ over for borgerne.' },
      { id: 'NY208', title: 'Jeg kører storskrald', org: 'BFA Transport og Engros', year: 2010, type: 'Vejledning', temaer: ['Storskraldsordning', 'Ledelse'], img: 'img/f1e0917988128cbe1e8911354fb71acf.jpg', url: 'https://bfaportalen.dk/Files/Billeder/BFA-portalen/Transport/Godstransport/PDF/93182-Storskrald_2010.pdf', res: 'Branchevejledning fra 2010 om sikker og skånsom indsamling af storskrald. Den giver råd om løft, biler, hjælpemidler og krav til borgerne for hver enkelt affaldsfraktion.', long: 'Branchearbejdsmiljørådet for transport og engros har lavet vejledningen til skraldemænd og renovationsvirksomheder, og kommuner kan bruge den i regulativer og udbud. Den gennemgår fraktionerne fra aviser, pap og brændbart til glas, hårde hvidevarer, metal og elektronik. Avisbundter bør højst veje 15 kg og kunne gribes ca. 1 meter over jorden, og indkastet på bilen bør ikke ligge over ca. 1,6 meter. Ladbiler anbefales udstyret med kran og/eller bagsmæklift. Kommunen kan kræve sorteret affald inden for vægtgrænser, og reglerne for, hvornår affald må blive stående, bør aftales og meldes klart ud.' },
      { id: 'NY209', title: 'Transport og håndtering af asbest på genbrugspladser', org: 'BFA Transport og Engros', year: 2010, type: 'Vejledning', temaer: ['Genbrugspladser', 'Byggeaffald', 'Ledelse'], img: 'img/34a83446c46e7040e946415ca340ead0.jpg', url: 'https://bfaportalen.dk/Files/Billeder/BFA-portalen/Transport/Godstransport/PDF/93181-asbest_genbrugspladser.pdf', res: 'Branchevejledning om håndtering af borgernes asbestaffald på genbrugspladser og kørslen til deponi, så personale og chauffører ikke udsættes for unødigt asbeststøv.', long: 'Vejledningen fra 2010 blev skrevet, efter at tilsyn i 2007 havde vist usikkerhed om, hvordan genbrugspladser skal håndtere borgernes asbestaffald. Den gennemgår kravene til en særlig asbest-APV, der skal revideres mindst hvert tredje år, og grænseværdien på 0,1 fiber/cm3, hvor påvirkningen skal ned på en tiendedel for ikke at være unødig. Pladsen bør have en lukket, aflåst container, og støvende affald skal afleveres befugtet og emballeret. Besøg i Hørsholm, Viby og Middelfart viser praktiske løsninger som indkast gennem en brevsprække og vandforstøvning i containeren. På deponiet skal asbestaffaldet dækkes med mindst 0,2 meter samme dag.' },
      { id: 'NY210', title: 'Projekt affald i det offentlige rum', org: 'Fremfærd (KL og 3F)', year: 2026, type: 'Rapport', temaer: ['Analyser og undersøgelser', 'Sorteringskvalitet', 'Ledelse'], img: 'img/e90462d6f2b5b60141db68f86c104b2f.jpg', url: 'https://cdn.sanity.io/files/6govnrwr/production/c9e74a66bb47f021daa0bcbba2e9dfd486e9eb19.pdf', res: 'Opsamling på fire kommunale projekter om affald i det offentlige rum. Sortering i byrummet virker i Silkeborg, og driftspersonalet bør med, når nye beholdere vælges.', long: 'Behave Green har for Fremfærd, hvor KL og 3F sad i styregruppen, gennemført fire forandringsprojekter fra maj til december 2025. I Silkeborg var knap en femtedel af restaffaldet ved fem sorteringsøer genanvendeligt mod knap en tredjedel ved fem enkeltstående beholdere. Hvidovre fik anbefalinger om driftsvenlige beholdere og fraktionerne rest, glas/metal og plast/mad- og drikkekartoner, mens madaffald frarådes. Frederiksberg arbejdede med unge og henkastet affald, og Odense med civile affaldsindsamlere. Rapporten anbefaler at styrke samarbejdet, inddrage flere aktører, opbygge kompetencer i driften og genbesøge vante antagelser.' },
      { id: 'NY211', title: 'Affaldsanalyse af sortering i midtbyen', org: 'Fremfærd og Silkeborg Kommune', year: 2026, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Analyser og undersøgelser'], img: 'img/f1232a92c5b1ca5562a34e6fdf46e787.jpg', url: 'https://cdn.sanity.io/files/6govnrwr/production/a59e1c6d1b7fb817b1ad212b06dd44b6ef4d5d4b.pdf', res: 'Affaldsanalyse fra sorteringsøer i Silkeborg midtby. Glas og metal var 88 % korrekt sorteret, plast og mad- og drikkekartoner knap 50 %. Største fejl i plast var væske fra kopper.', long: 'Behave Green har for Silkeborg Kommune analyseret affald fra fem sorteringsøer og fem enkeltstående restaffaldsbeholdere i midtbyen som en del af Fremfærds projekt om affald i det offentlige rum. Stikprøven er affald fra tre hverdage i august 2025, bl.a. 22 kg glas/metal og 19 kg plast/MDK. Restaffaldet ved øerne indeholdt knap en femtedel genanvendeligt mod knap en tredjedel i de enkeltstående beholdere. I plast og MDK var madaffald den største fejl med 18 %, primært væske og rester fra kopper. Rapporten anbefaler at beholde glas/metal og informere om at tømme kopper. Madaffald bør ikke sorteres i byrummet, viser erfaringer fra Aarhus.' },
      { id: 'NY212', title: 'Anbefalinger til test af affaldssortering i det offentlige rum', org: 'Fremfærd og Hvidovre Kommune', year: 2026, type: 'Rapport', temaer: ['Analyser og undersøgelser', 'Sorteringskvalitet', 'Ledelse'], img: 'img/9ce95da431cc9dff4184da4796105ccd.jpg', url: 'https://cdn.sanity.io/files/6govnrwr/production/ad9da2c26aab9d65f854e1cd783882947a620f66.pdf', res: 'Behave Green giver Hvidovre Kommune råd til en test af sortering i byrummet. Anbefalingen er rotte- og fuglesikrede beholdere og sortering i restaffald, glas/metal og plast/MDK.', long: 'Behave Green skrev delrapporten i januar 2026 for Hvidovre Kommune som del af Fremfærds projekt Affald i det offentlige rum, hvor KL og 3F samarbejder. Den bygger på observationer og mini-interviews på fem lokationer, feltarbejde og workshops med driftspersonalet samt erfaringer fra Aarhus og Silkeborg. Anbefalingerne er ikke afprøvet i praksis. En affaldsanalyse fra Silkeborg viste 88 % korrekt sorteret glas/metal og ca. 45 % for plast/MDK. Madaffald, papir og pap, tekstil og farligt affald fravælges. Rapporten foreslår en test over seks måneder, farvede sække til hver fraktion og sorteringsøer der, hvor borgerne i forvejen går.' },
      { id: 'NY213', title: 'De almene boligafdelingers udgifter til renovation 2017-2023', org: 'Landsbyggefonden', year: 2024, type: 'Statistik', temaer: ['Økonomi', 'Etageboliger', 'Data, statistikker og nøgletal'], img: 'img/190acb5a2b026f37b8883dfff4b05510.jpg', url: 'https://lbf.dk/media/1c2brncy/temastatistik-2024-9-de-almene-boligafdelingers-udgifter-til-renovation-2017-2023.pdf', res: 'Almene boligafdelinger brugte i 2023 i gennemsnit 35,9 kr. pr. m2 på renovation, 40,2 % mere end i 2017. To ud af tre afdelinger kildesorterede affaldet i 2023.', long: 'Landsbyggefondens temastatistik bygger på afdelingernes regnskaber for 2017-2023 (konto 109) og dækker 98,1-99,3 % af de almene boliger. I 2023-priser er stigningen fra 2017 til 2023 på 11,5 %. Udgiften er højest i Region Sjælland med 41,0 kr. pr. m2 og lavest i Region Midtjylland med 27,8 kr., og blandt kommunerne spænder den fra 20,7 kr. i Tårnby til 60,2 kr. i Tønder. Afdelinger med boliger under 61 m2 betaler 45,7 kr. pr. m2 mod 27,6 kr. for boliger over 100 m2. Andelen med kildesortering steg fra 49,5 % til 65,4 %. Kommunale forskelle i service og gebyrer er ikke analyseret.' },
      { id: 'NY214', title: 'Status på kommunal affaldspraksis', org: 'BL, Danmarks Almene Boliger', year: 2024, type: 'Analyse', temaer: ['Økonomi', 'Etageboliger', 'Lovgivning og afgørelser'], img: 'img/43c9d69a2843cdef6c63bee700d98a36.jpg', url: 'https://bl.dk/media/f53jkc4v/status-paa-kommunal-affaldspraksis-analyse-og-bl-anbefalinger.pdf', res: 'BL har gennemgået 98 kommuners takstblade for 2024 og finder store forskelle i affaldsgebyrerne. Grundtaksten for etageboliger spænder fra 905 kr. til 5.110 kr. om året.', long: 'BL, Danmarks Almene Boliger, ser i denne analyse fra oktober 2024 på kommunernes affaldsgebyrer med de almene boligorganisationers øjne. Grundlaget er BLs egne beregninger på 98 kommunale takstblade for 2024 samt tal fra Forsyningstilsynet, der viser 46 % stigning for etageboliger 2019-2023. I 27 % af kommunerne skelnes der ikke mellem etageboliger og enfamilieshuse, og i 26 kommuner med ens gebyr er prisen pr. beboer 56 % højere i etageboliger. BL vurderer, at hver fjerde kommune stadig opkræver ulovlig moms. Analysen slutter med fire principper, bl.a. gennemsigtighed og omkostningsægthed, og en opfordring til dialog med boligselskaberne.' },
      { id: 'NY215', title: 'Datasæt til affaldsbrev', org: 'BL, Danmarks Almene Boliger', year: 2024, type: 'Regneark', temaer: ['Data, statistikker og nøgletal', 'Økonomi', 'Etageboliger'], img: '', url: 'https://bl.dk/media/5tpn0dki/datasaet-til-affaldsbrev-v11-publiceret-december-2024.xlsx', res: 'Regneark fra BL med data pr. kommune til et affaldsbrev, bl.a. almene boligafdelingers udgifter til renovation 2017-2023, og om renovationen løses kommunalt eller af et selskab.', long: 'I arket Data til affaldsbrev vælger brugeren en kommune og får areal, befolkningstæthed, indbyggere og boliger fordelt på parcelhuse, rækkehuse og etageboliger samt antallet af almene boligorganisationer, afdelinger og boliger. Tallene kommer fra Danmarks Statistik og fra Landsbyggefondens temastatistik, bl.a. om de almene boligafdelingers udgifter til renovation 2017-2023. På landsplan steg udgiften med 40,2 % i perioden, mens den faldt i enkelte kommuner som Albertslund. Arket Renovationstakster 2024 viser for hver kommune, om opgaven løses kommunalt eller af et selskab som ARC eller Vestforbrænding. Flere celler viser fejlen #REF!.' },
      { id: 'NY216', title: 'HDR Affaldsanalyse. Årsrapport 2024', org: 'Hold Danmark Rent', year: 2024, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/70b203cd35785661a271006b3a944b44.jpg', url: 'https://www.holddanmarkrent.dk/media/bk0bfr5j/%C3%A5rsrapport-hdr-2024.pdf', res: 'Hold Danmark Rent har talt 161.691 stykker henkastet affald i 24 danske kommuner. Mængden faldt 29 % fra 2023 til 2024, især for cigaretskod og småt affald.', long: 'Årsrapporten fra Hold Danmark Rent bygger på optællinger på 1.920 målepunkter i 24 kommuner fra april til september 2024. Den samlede mængde henkastet affald faldt 29 % i forhold til 2023. Skod og småt affald faldt hver 34 %, mens stort affald kun faldt 2 %. Skod udgør 58 % af det optalte affald. Landsindekset for renhed faldt fra 4,4 til 4,0, og antallet af kritiske lokaliteter faldt fra 155 til 101 ud af 480. Kommuner med store fald peger på hyppigere renhold og skodindsatser betalt af SUP-midler, og flere frivillige samler affald. HDR anbefaler fortsat fokus på de kritiske steder og kommunal støtte til frivillige indsamlinger.' },
      { id: 'NY217', title: 'Kortlægning af elektronikstrømme i Region Syddanmark', org: 'Region Syddanmark', year: 2022, type: 'Analyse', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Klima'], img: 'img/23a6cdfefcfbffdf236c4b4b7a8c70e2.jpg', url: 'https://regionsyddanmark.dk/media/fffhcpjh/kortl%C3%A6gning-af-elektronikstr%C3%B8mme-i-region-syddanmark.pdf', res: 'COWI har kortlagt elektronikforbruget i Region Syddanmark, ca. 36.000 ton om året, og regnet på klimagevinsten ved at bruge produkterne længere og reparere dem.', long: 'COWI har lavet analysen for Region Syddanmark som vidensgrundlag for arbejdet med cirkulær elektronik. Den bygger på statistik og interview med aktører i værdikæden. Hårde hvidevarer udgør ca. 75 % af de ca. 20.000 ton i de seks undersøgte produktgrupper. Alle grupper har en kortere faktisk levetid end den klimamæssigt optimale, fx ca. 5 år for en bærbar computer mod optimalt 20-44 år. Den årlige udskiftning giver ca. 170.000 ton CO₂-eq. Elreturs nye reparationsordning for hvidevarer kan spare 3.905 ton CO₂ om året, hvis 20 % af apparaterne genbruges. Central fjernelse af kalk i drikkevandet og gensalg af computere ses også som lovende.' },
      { id: 'NY218', title: 'Nedgravede affaldsløsninger. En vejledning til dig og din organisation', org: 'Mariagerfjord Kommune', year: 2023, type: 'Vejledning', temaer: ['Etageboliger', 'Hente- og bringeordninger'], img: 'img/e66568891cd807b4505de33de2c41f94.jpg', url: 'https://www.mariagerfjord.dk/media/nfphawbx/vejledning-nedgravede-affaldsloesninger-rev-2024.pdf', res: 'Mariagerfjord Kommunes vejledning til boligselskaber og foreninger, der vil etablere nedgravede affaldsløsninger på egen grund, med minimumskrav til placering og tømning.', long: 'Vejledningen fra april 2023 henvender sig til boligselskaber, ejerforeninger og andelsboligforeninger, der vil erstatte beholdere på hjul med nedgravede løsninger. Løsningen skal rumme fraktionerne i kommunens regulativ, og indkastene skal mærkes med Dansk Affaldsforenings piktogrammer. Kravene omfatter bl.a. højst 2 meter fra tømningskrog til holdeplads, ca. 10 meters frihøjde, 0,8 meters fri passage og mindst 10 meter til vejkryds. Til dimensionering er der vejledende tal, fx 40 liter restaffald om ugen pr. husstand i etagebolig. Ejeren betaler etablering og drift, og kommunen skal godkende løsningen på forhånd.' },
      { id: 'NY219', title: 'Bygningsreglementets vejledning om affaldssystemer', org: 'Social- og Boligstyrelsen', year: 2018, type: 'Vejledning', temaer: ['Etageboliger', 'Lovgivning og afgørelser'], img: 'img/9b246af2d934b9e2f81d20b31e052442.jpg', url: 'https://www.bygningsreglementet.dk/media/5icp3dmy/generel_vejledning.pdf', res: 'Vejledningen forklarer BR18\'s funktionskrav til affaldssystemer, der i 2017 afløste kravet om affaldsskakte, og hvordan beboerne skal kunne bruge systemerne ved egen hjælp.', long: 'Siden 1. juli 2017 har bygningsreglementet stillet funktionskrav til affaldssystemer i stedet for at kræve affaldsskakte i boligbyggeri med mere end tre etager. Systemerne skal tage hensyn til sundhed, komfort, kildesortering og energiforbrug. Vejledningen beskriver skakte, central- og mobilsug, nedgravede beholdere og affaldsøer og nævner, at der ofte skal være materiel til 5 til 10 fraktioner. Den giver råd om adgangsveje, afstande, indkasthøjde og skiltning af hensyn til fx kørestolsbrugere og svagtseende. Nedlægges en affaldsskakt i eksisterende byggeri, skal hensynene dokumenteres, og det vil formentlig oftest kræve byggetilladelse.' },
      { id: 'NY220', title: 'Nedgravede affaldsløsninger. Vejledning til etablering', org: 'Odense Renovation', year: 2024, type: 'Vejledning', temaer: ['Etageboliger', 'Hente- og bringeordninger'], img: 'img/9a36b48561b20e70a278cad583e223b6.jpg', url: 'https://www.odenserenovation.dk/media/3167/etablering-af-nedgravet-affaldsloesning_2024_.pdf', res: 'Odense Renovations vejledning til bolig- og ejerforeninger, der vil have nedgravede affaldsbeholdere. Den beskriver krav til beholdere, kapacitet, placering og tilkørsel.', long: 'Vejledningen henvender sig til bolig- og ejerforeninger i Odense Kommune, som vil etablere fuldt eller delvist nedgravede beholdere, også med to rum. Foreningen betaler selv indkøb, etablering, vedligehold og et årligt lovpligtigt eftersyn, mens Odense Renovation kun tømmer. Pr. husstand regnes med ca. 83 liter restaffald og 21 liter madaffald hver 14. dag. Papir og småt pap kræver ca. 108 liter pr. måned og plast og kartoner 90 liter, mens glas og metal kræver 29 liter. Der må højst være 5 meter fra bilens side til beholderens centrum. Byggetilladelse kræves ikke, men foreningen skal selv tjekke bl.a. lokalplan og ledninger i jorden.' },
      { id: 'NY221', title: '10 affaldsfraktioner i Odense Kommune. Valg af affaldsløsning', org: 'Odense Renovation', year: 2023, type: 'Vejledning', temaer: ['Etageboliger', 'Hente- og bringeordninger'], img: 'img/3f7541a749b9b5fefba51315e343796f.jpg', url: 'https://www.odenserenovation.dk/media/2992/10-fraktioner-valg-af-affaldsloesning_2023_.pdf', res: 'Odense Renovations brochure hjælper udlejere og boligforeninger med at vælge beholdere til de 10 affaldsfraktioner og viser, hvor mange husstande der kan dele hver beholder.', long: 'Odense Renovation og Odense Kommune har lavet brochuren til boligforeninger, private udlejere, andels- og ejerforeninger, da ordningen udvides til 10 fraktioner. Den gennemgår beholdere på 2 og 4 hjul fra 140 til 660 liter, vippecontainere på 4,5-16 m³, nedgravede løsninger og affaldssug. Pr. husstand regnes med 83 liter restaffald og 21 liter madaffald hver 2. uge og 108 liter papir og småt pap hver 4. uge. Tabeller viser, hvor mange husstande der kan dele hver beholder. Den anbefalede afstand fra hoveddøren er højst 50 meter til rest- og madaffald og 200 meter til de genanvendelige fraktioner. Udlejere kan få hjælp fra et rådgiverhold.' },
      { id: 'NY222', title: 'National Handlingsplan for Tekstiler', org: 'Dansk Mode & Textil, Lifestyle and Design Cluster og TRACE', year: 2026, type: 'Strategi', temaer: ['Tekstil', 'Udvidet producentansvar', 'Cirkulær økonomi'], img: 'img/d062b30ba50bea327c1617049f4e75d4.jpg', url: 'https://webpagefilestorage.blob.core.windows.net/webpagefilecontainer/National%20Handlingsplan%20for%20Tekstiler%20Digital.pdf', res: 'Danmarks handlingsplan for tekstiler samler ni initiativer i 2026-2029, bl.a. et dialogforum om producentansvaret for tekstiler og en analyse af fremtidens tekstilinfrastruktur.', long: 'Planen udspringer af Finansloven 2025 og skal bidrage til mindre tekstilproduktion og -forbrug. Dansk Mode & Textil, Lifestyle and Design Cluster og TRACE står for den med Energistyrelsen som tilsagnsgiver. Den sætter ingen bindende mål. Ni initiativer i tre spor går fra virksomhedernes EU-parathed til en informationskampagne. Da en bekendtgørelse om producentansvar for tekstiler ventes udstedt i 2027 med ikrafttræden i foråret 2028, opretter initiativ 2.1 et dialogforum med bl.a. kommuner og opdaterer tekstilstrømsanalysen fra 2018. Initiativ 2.2 analyserer behovet for bl.a. finsortering og reparation og udvælger 1-3 områder til opfølgning.' },
      { id: 'NY223', title: 'Forbrugeradfærd i tekstilbranchen', org: 'Dansk Erhverv', year: 2026, type: 'Analyse', temaer: ['Tekstil', 'Direkte genbrug', 'Cirkulær økonomi'], img: 'img/23db12bb62a094e9a5ff3e4e75fb2739.jpg', url: 'https://www.danskerhverv.dk/siteassets/mediafolder/dokumenter/01-analyser/analysenotater-2026/forbrugeradfard-i-tekstilbranchen.pdf', res: 'Dansk Erhvervs måling af danskernes køb og brug af tøj. 90 % køber mest nyt, og tøj uden fejl går oftest til containere og genbrugsbutikker, mens 13 % smed det ud.', long: 'Analysen bygger på en Norstat-måling blandt 1.005 danskere fra januar 2026 og dækker køb, tillid til grønne budskaber, cirkulære services, reparation og digitale produktpas. Om det seneste stykke tøj uden fejl, folk skilte sig af med, svarer 27 % container, 25 % genbrugsbutik, 13 % familie og venner og 11 % salg online, mens 9 % brugte tekstilaffald og 4 % restaffald. Velgørenhed motiverer 63 % til at aflevere tøj, nem aflevering 26 %. Når tøj går i stykker, reparerer 28 % selv, mens 16 % smider det i tekstilaffald. Kun 18 % har prøvet at betale for reparation, og halvdelen vil ikke betale mere for bukser med gratis reparation.' },
      { id: 'NY224', title: 'Case: Dynamisk affaldsindsamling i Vestforbrænding og Gentofte Kommune', org: 'Dansk Erhverv', year: 2023, type: 'Analyse', temaer: ['Teknologi', 'Økonomi', 'Hente- og bringeordninger'], img: 'img/65f8fc048c4ad1d787af1d79926bbf09.jpg', url: 'https://www.danskerhverv.dk/siteassets/mediafolder/dokumenter/01-analyser/analysenotater-2024/business-case---dynamisk-affaldsindsamling.pdf', res: 'Dansk Erhverv regner på Gentofte Kommunes fuldmeldere i kuber til glas, papir og metal. Tømningerne faldt 58 %, og investeringen er tjent hjem på 1 til 5 år.', long: 'Analysenotatet fra Dansk Erhverv bygger på data fra Vestforbrænding, Gentofte Kommune, Remondis og IoT Sensors om sensorer i kuber og nedgravede beholdere i offentligt rum. Indsamling efter fyldningsgrad i stedet for faste intervaller gav 58 % færre tømninger og 21 % færre kørte kilometer inklusive kørsel til anlæg. Fordi tømmeprisen kan stige, regnes der på fem scenarier. Med en investering på ca. 187.000 kr. og driftsudgifter uden sensorer på ca. 675.000 kr. om året ligger den årlige besparelse på 43.000 til 315.000 kr. Projektet er rentabelt, så længe tømmeprisen ikke stiger mere end 116 %, og det sparer 2,6 ton CO2 om året.' },
      { id: 'NY225', title: 'Designguide: Genbrug og genanvendelse af plastemballager til de private forbrugere', org: 'Plastindustrien', year: 2023, type: 'Vejledning', temaer: ['Cirkulær økonomi', 'Reel genanvendelse', 'Afsætning og behandling'], img: 'img/ee97b2703be1ac16bbe649166a4c8dc5.jpg', url: 'https://plast.dk/wp-content/uploads/2024/08/Dansk-Designguide-Genbrug-og-genanvendelse-af-plastemballage-til-de-private-forbrugere.pdf', res: 'Plastindustriens designguide viser, hvordan plastemballage til private kan genbruges eller designes, så den kan sorteres og genanvendes i høj kvalitet i det danske system.', long: 'Guiden fra oktober 2023 er 3. udgave fra Netværk for Cirkulær Plastemballage under Plastindustrien. Den følger affaldshierarkiet og gennemgår først forretningsmodeller for genbrugsemballage og derefter design til genanvendelse. Stikprøver af husstandsindsamlet plast fra Københavns Kommune i 2019 viste, at 91 % var PP, PE eller PET, og at 76 % var emballage. Guiden har derfor grøn-gul-rød-skemaer for disse plasttyper og for fleksible folier. Emballage med carbon black kan generelt ikke ses af NIR-scannere og kasseres, og PVC-etiketter frarådes. Guiden efterlyser også sorteringsteknik, der kan holde food, near-food og non-food adskilt.' },
      { id: 'NY226', title: 'Sektorkøreplan for byggebranchen. Sektorsamarbejdet for udsortering af plast i byggeriet', org: 'Sektorsamarbejdet for plast i byggeriet', year: 2022, type: 'Rapport', temaer: ['Byggeaffald', 'Cirkulær økonomi'], img: 'img/f7d03b34b0bd9175de5c2a4d094e842d.jpg', url: 'https://www.danskindustri.dk/globalassets/medlemsforeninger/ari/dokumenter/sektorkoreplan_plast-i-byggeriet.pdf', res: 'Køreplanen fra sektorsamarbejdet om plast i byggeriet samler 30 forslag til mere udsortering af byggeplast, fx obligatorisk affaldsplan og en EPS-fraktion på alle genbrugspladser.', long: 'Sektorsamarbejdet blev nedsat under Det Nationale Plastikcenter efter klimaplanen fra 2020, og DI og ARI har haft formandskab og projektledelse. Målet er at udsortere 25 % i 2025 og 75 % i 2030 af de ca. 25.600 tons byggeplast, der ved start endte til forbrænding eller deponi, ud af anslået 31.600 tons. Arbejdet bygger på ti case-projekter om PVC, EPS samt LDPE og HDPE. Datagrundlaget er usikkert, bl.a. fordi ingen data opsamles om afleveringer på genbrugspladserne. Ni af de 30 forslag prioriteres, fx separat sortering af blød plast på byggepladser og krav om affaldshåndtering i udbud. Den største udfordring er ifølge køreplanen logistik.' },
      { id: 'NY227', title: 'CENELEC EN 50614:2020. Krav angående forberedelse til genbrug af el- og elektronikskrot', org: 'Elretur', year: 2022, type: 'Faktaark', temaer: ['Direkte genbrug', 'Cirkulær økonomi'], img: 'img/b7cf0e77791b0c219f6e6d6657f7bcd7.jpg', url: 'https://elretur.dk/wp-content/uploads/2022/06/CENELEC-EN-50614-opsummering.pdf', res: 'Elretur opsummerer kravene i standarden EN 50614 til reparatører, der forbereder elektronikaffald til genbrug, fra modtagelse og sikkerhedstest til mærkning og 90 dages garanti.', long: 'Opsummeringen giver et første overblik og er hverken udtømmende eller en direkte oversættelse, så den kan ikke bruges til at vurdere, om en reparatør lever op til standarden. Standarden gælder kun elektronik, der er blevet til affald. Reparatøren skal have et ledelsessystem for sundhed, sikkerhed, miljø og kvalitet og kunne spore udstyret fra den første inspektion. Udstyr uden CE-mærke eller producentens mærkeplade må ikke forberedes til genbrug, og det samme gælder tilbagekaldte produkter. Alle persondata skal slettes efter en dokumenteret procedure, og det solgte udstyr skal have en holdbar label og mindst 90 dages garanti.' },
      { id: 'NY228', title: 'Household Food Waste Collections Guide', org: 'WRAP', year: 2026, type: 'Vejledning', temaer: ['Hente- og bringeordninger', 'Etageboliger', 'Kommunikation'], img: 'img/dface000e8bdcb4a7fb77e0219488ee0.jpg', url: 'https://www.wrap.ngo/sites/default/files/2026-06/WRAP-Household-Food-Waste-Guidance-June26-v3.pdf', res: 'WRAP\'s vejledning i at indføre og drive madaffaldsindsamling fra husstande. Ugentlig særskilt indsamling giver mest, og gratis poser og mærkater på restaffaldsbeholderen hjælper.', long: 'Den britiske organisation WRAP samler erfaringer fra forsøg, borgerundersøgelser og kommunale data i 13 afsnit om bl.a. beholdere, poser, biler, behandling, etageboliger og økonomi. I 2021/22 indsamlede 140 britiske kommuner med ugentlig særskilt indsamling i snit 1,47 kg madaffald pr. husstand om ugen. Blandes madaffaldet med haveaffald, regner WRAP med 0,8 kg ved ugentlig og 0,5 kg ved tømning hver anden uge. Restaffald hver anden uge giver mere madaffald end ugentlig tømning. I forsøg gav en pakke med klistermærke på restaffaldsbeholderen, folder og en rulle poser mest for pengene, og WRAP anbefaler en løbende gratis forsyning af poser.' },
      { id: 'NY229', title: 'Local Authority Textile Collections: Situational Report', org: 'WRAP', year: 2026, type: 'Analyse', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Afsætning og behandling'], img: 'img/f76826e721692b3aac8d44340d7b14d4.jpg', url: 'https://www.wrap.ngo/sites/default/files/2026-03/WRAP-Textile-Collection-Situation%20-Report-Local-Authorities-England.pdf', res: 'WRAP-rapport om engelske kommuners indsamling af brugte tekstiler. Faldende indtægter og ringere kvalitet presser ordningerne, og kun 25 % af kommunerne indsamler ved boligen.', long: 'Rapporten fra marts 2026 kortlægger, hvordan engelske kommuner indsamler tekstiler ved boligen, på genbrugspladser og i containere. Grundlaget er eksisterende data, et besøg på et sorteringsanlæg og 16 interviews med bl.a. kommuner, sorterere og velgørende organisationer. Færre kommuner har indsamling ved boligen end i 2013/14, og 49 % af kasserede tekstiler ender i restaffaldet. Kommunerne bruger anslået 73 mio. pund på at bortskaffe tekstiler, og et kollaps i genbrugssektoren kan koste 64 mio. pund mere om året. De interviewede peger på producentansvar og automatisk sortering, og rapporten efterlyser klar kommunikation til borgerne.' },
      { id: 'NY230', title: 'Recycling Tracker Survey in the UK: Spring 2026', org: 'WRAP', year: 2026, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Kommunikation', 'Analyser og undersøgelser'], img: 'img/34fa166bf348ebd33a5699f52f8cc534.jpg', url: 'https://www.wrap.ngo/sites/default/files/2026-09/WRAP-UK-Recycling-Tracker-Spring-2026-v2.pdf', res: 'WRAP\'s årlige måling af britiske borgeres sorteringsvaner med 5.213 svar. De, der er sikre på reglerne, laver færre fejl, men 78 % har lagt noget forkert i genbrugsspanden.', long: 'Undersøgelsen blev lavet online i februar og marts 2026 blandt britiske voksne, der står for husstandens affald, og svarene er koblet til de lokale indsamlingsordninger. 88 % siger, at de sorterer det meste eller alt, men 57 % har smidt mindst én genanvendelig ting i restaffaldet, oftest parfumeflasker af glas (55 %) og folie (34 %). 46 % bruger en ordning for madaffald. En regressionsanalyse kobler sikkerhed om reglerne og stærke sociale normer til færre fejl, mens tillid til, at kommunen genanvender, hænger sammen med troen på, at sortering nytter. WRAP anbefaler klarere vejledning og mere åbenhed om, hvad der sker med affaldet.' },
      { id: 'NY231', title: 'Service Change Communications Guide', org: 'WRAP', year: 2022, type: 'Vejledning', temaer: ['Kommunikation', 'Hente- og bringeordninger'], img: 'img/95c01d118b8e2c426e5fa94162144238.jpg', url: 'https://www.wrap.ngo/sites/default/files/2023-01/WRAP%20Service%20Change%20Comms%20Guide_0.pdf', res: 'Vejledning fra WRAP til engelske kommuner om at planlægge og evaluere kommunikationen, når indsamlingsordningen ændres, med eksempler på budget og tidsplan.', long: 'WRAPs guide går trin for trin gennem kommunikationsplanen ved ændringer i husstandsindsamlingen, fra mål og målgrupper over budskaber til tidsplan, budget og evaluering. Borgerne bør få besked seks uger før ændringen og en informationspakke med sorteringsvejledning og tømmekalender to uger før. WRAP anbefaler budskaber, der viser sortering som det normale, og fraråder blot at bede folk sortere mere. De nødvendige aktiviteter budgetteres først, med et startbudget på 0,50-1,50 pund pr. husstand. Et regneeksempel med indførelse af madaffald hos 44.000 husstande giver eksterne udgifter på 42.910 pund eller 98 pence pr. husstand.' },
      { id: 'NY232', title: 'A longitudinal analysis of the Impact of Food Waste Collections on Household Food Waste Arisings', org: 'WRAP', year: 2025, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Hente- og bringeordninger'], img: 'img/6d9c47033b2a320736acd3b07d93fac7.jpg', url: 'https://www.wrap.ngo/sites/default/files/2025-07/A-longitudinal-analysis-of-the-Impact-of-Food-Waste-Collections-on-Household-Food-Waste-Arisings_0.pdf', res: 'Separat indsamling af madaffald i britiske kommuner har ikke målbart ændret husholdningernes samlede mængde madaffald, viser WRAPs analyse af data fra 2006 til 2022.', long: 'WRAP har fulgt 131 britiske kommuner med data fra affaldsanalyser og WasteDataFlow. I et kvasi-eksperiment blev 37 datapar fra kommuner, der indførte separat madaffaldsindsamling, sammenlignet med 174 datapar fra kommuner uden ændring. Kommunerne med ny ordning fik en stigning på 12,4 kg pr. husstand om året mod 4,8 kg i kontrolgruppen, normaliseret mod britisk gennemsnit, men forskellen er ikke statistisk signifikant. Ordningen flytter madaffald ud af restaffaldet, men forebygger ikke i sig selv madspild. WRAP anbefaler tydelig kommunikation, vejledning fra kommunerne, visuelle nudges som klistermærker og evaluering af pilotprojekter.' },
      { id: 'NY233', title: 'Household Waste Recycling Centre Intervention Analysis: Final Report', org: 'Zero Waste Scotland', year: 2025, type: 'Analyse', temaer: ['Genbrugspladser', 'Analyser og undersøgelser', 'Direkte genbrug'], img: 'img/0069884a23813a802b6912e083de876f.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-xyde0wdl-1764325646d', res: 'Eunomia har for Zero Waste Scotland modelleret fire tiltag på skotske genbrugspladser. Krav om at åbne sorte sække hæver genanvendelse og genbrug mest, med 10,3 procentpoint.', long: 'Skotland har 170 genbrugspladser i 32 kommuner, og rapporten bygger på britiske erfaringer og data fra 26 af kommunerne. En model beregner effekten af fire tiltag ud fra 2023, hvor 59,0 % af affaldet på pladserne blev genanvendt eller genbrugt. Krav om at åbne sorte sække giver 10,3 procentpoint, oplæring af personalet mindst en gang om året 7,1, booking for alle besøgende 1,4 og en genbrugscontainer 1,1. Containeren hæver til gengæld genbrugsandelen fra 0,3 til 1,4 %. Effekterne kan ikke lægges sammen, og modellen regner hverken på økonomi eller klima. Et pilotforsøg med sækkeåbning i Angus Council skal give resultater i 2026.' },
      { id: 'NY234', title: 'Making Reuse Happen at Household Waste Recycling Centres: Guidance for local authorities', org: 'Zero Waste Scotland', year: 2024, type: 'Vejledning', temaer: ['Direkte genbrug', 'Genbrugspladser', 'Udbud og kravspecifikationer'], img: 'img/23c64835e21942c4bb2a64b1f59e2b89.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-vswa0g9a-1734698472d', res: 'Skotsk trin-for-trin-vejledning til kommuner, der vil øge direkte genbrug på genbrugspladser, med cases fra fem skotske kommuner og bud på, hvad der skal til for at lykkes.', long: 'Zero Waste Scotland har udgivet vejledningen på grundlag af research og interview fra Enscape Consulting. Del A beskriver otte trin fra indledende gennemgang og data over finansiering, business case og udbud til opfølgning og kommunikation. Del B opdeler i fire modeller fra genbrugsbutik på pladsen til styrede containere, der forsyner butikker andre steder, og har cases fra Dumfries & Galloway, East Lothian, Moray, North Ayrshire og Perth & Kinross. Butikkerne i Forres og Stranraer genbrugte 200 og 188 ton i 2022 og har over 20 ansatte hver. Containere uden tilsyn fanger færre brugbare ting, så en styret container anbefales som minimum.' },
      { id: 'NY235', title: 'Increasing Food Waste Yields: A Guide for Local Authorities', org: 'Zero Waste Scotland', year: 2026, type: 'Evaluering', temaer: ['Kommunikation', 'Sorteringskvalitet', 'Analyser og undersøgelser'], img: 'img/1613506342ebbfabfbdbb66aad8b003c.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-z0ui4usk-1770052465d', res: 'Zero Waste Scotland har testet tre tiltag for mere madaffald hver for sig i South Ayrshire. Et klistermærke på restaffaldsbeholderen gav den største stigning og var billigst.', long: 'Syntesen fra februar 2026 samler forsøget i South Ayrshire fra oktober 2023 til oktober 2024, hvor fire indsamlingsruter fik en kampagne, gratis poser til køkkenspanden, klistermærker på restaffaldsbeholderen eller ingen indsats. Mængden af indsamlet madaffald steg 42,1 % i klisterområdet, mens poser gav 14,4 % og kampagnen 10,4 %, men klisterområdet startede lavest. Rullet ud i hele kommunen anslås klistermærker at spare ca. 74.200 pund om året, mens kampagnen koster mere, end den sparer. WRAP-forsøg med en pakke af klistermærke, poser og folder gav i snit ca. 32 % mere madaffald. Vil kommunen kun gøre én ting, anbefales klistermærket.' },
      { id: 'NY236', title: 'Promoting household recycling: Local Authority communications best practice report', org: 'Zero Waste Scotland', year: 2025, type: 'Rapport', temaer: ['Kommunikation'], img: 'img/10d1f81199ea820791c657b5b6a684e9.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-zdjectj4-1769621688d', res: 'Zero Waste Scotland samler god praksis for kommunale kampagner om affaldssortering og anbefaler integrerede kampagner på flere kanaler under det fælles brand Recycle for Scotland.', long: 'Rapporten fra marts 2025 skal støtte arbejdet med en ny lovbestemt skotsk praksiskodeks for genanvendelse. Den gennemgår kendte kampagner, også uden for affaldsområdet, og knytter dem til fire adfærdsmodeller, bl.a. COM-B til daglige vaner og nudging til konkrete handlinger. Kampagner på flere kanaler virker langt bedre end på én kanal, og kampagner, der gentages hvert år, får mere ud af pengene. Den foreslår ca. 40 % af budgettet til bærende hovedindhold og 5 % til måling og viser lokale fireugers kampagner til 40.000-250.000 pund. Alle kommuner bør fortsat bruge det nationale brand Recycle for Scotland, der er bygget op over 14 år.' },
      { id: 'NY237', title: 'The composition of household waste at the kerbside in 2021-23: Methodology Overview', org: 'Zero Waste Scotland', year: 2023, type: 'Rapport', temaer: ['Analyser og undersøgelser', 'Sorteringskvalitet', 'Data, statistikker og nøgletal'], img: 'img/0f79fd4d31fefd15295ab141a7e3b033.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-zwftrfku-1696500258d', res: 'Zero Waste Scotland beskriver metoden bag de nationale tal for husstandsindsamlet affald i Skotland 2021-23, der bygger på sorteringsanalyser i 15 af landets 32 kommuner.', long: 'Metoderapporten ledsager Zero Waste Scotlands opgørelse af husholdningsaffald indsamlet ved boligen. Femten kommuner lavede sorteringsanalyser efter en fælles vejledning med stikprøver på 50 husstande pr. gadeblok, og alt indsamlet affald blev sorteret. De stod for 67 % af restaffaldet i analysen (715.214 af 1.070.019 tons). De øvrige kommuner fik profilen fra en lignende kommune ud fra ordninger og socioøkonomi, og tallene blev opregnet med indberetninger til WasteDataFlow for 2021. Erfaringerne viser bl.a., at ordningernes indretning betyder mindst lige så meget som socioøkonomi, og at indberetningsdata skal bruges med forsigtighed.' },
      { id: 'NY238', title: 'Digital technologies in kerbside collections: Insights from Scottish local authorities', org: 'Zero Waste Scotland', year: 2026, type: 'Analyse', temaer: ['Teknologi', 'Hente- og bringeordninger'], img: 'img/bdeb210bb3c34e033a749a48b0842efa.jpg', url: 'https://cdn.zerowastescotland.org.uk/managed-downloads/mf-9pftf1zj-1788334807d', res: 'Skotsk opsamling af kommunernes brug af digitale værktøjer i husstandsindsamlingen. Ruteoptimering og mobile systemer i bilerne er udbredt, mens AI og sensorer bruges få steder.', long: 'GC Insight har for Zero Waste Scotland gennemgået litteratur om digital teknologi i indsamlingen og holdt et webinar i februar 2026 med 49 deltagere fra 28 af 32 skotske kommuner. Ruteoptimering bruges af 24 kommuner, og 22 har eller indfører mobile systemer i bilerne, mens få bruger sensorer, RFID eller vejning. Kommunerne oplever især mere pålidelig service og lavere omkostninger, og én sparer 100.000-140.000 pund om året på tryk og porto til kalendere. Barriererne er bl.a. budget, svær integration mellem systemer, fejl i adressedata og medarbejdere, der ikke bruger udstyret fuldt ud. Dokumentation for effekt på genanvendelsen er sparsom.' },
      { id: 'NY239', title: 'Preparing for Reuse: Towards Cooperation for the Inner Cycles and the Local Loops', org: 'Aalborg Universitet', year: 2022, type: 'Rapport', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Genbrugspladser'], img: 'img/169c29dcab80bede1a74382e7f741858.jpg', url: 'https://vbn.aau.dk/ws/files/549453475/phd_RMM_e_pdf.pdf', res: 'Ph.d.-afhandling om forberedelse til genbrug og reparation i affaldsselskaber. I praksis prioriteres genanvendelse stadig over genbrug, og selskaberne mangler nye kompetencer.', long: 'Rikke Marie Moalem fra Aalborg Universitet undersøger, hvad der sker, når den cirkulære økonomis indre kredsløb møder en praksis bygget på affaldshierarkiet. Hun bygger på casestudier og aktionsforskning i Interreg-projektet FUTURE med bl.a. AffaldPlus, BOFA og Lund Renhållningsverk. Et studie følger, hvordan AVV med private partnere gjorde gamle mursten og elektronikaffald til forretning. Reparationscaféer kan supplere, men ikke erstatte professionelle reparatører. Konklusionen er, at genbrugelige ting defineres som affald, og at genanvendelse i praksis går forud for genbrug. Flere selskaber end pionererne bør tilskyndes til genbrug.' },
      { id: 'NY240', title: 'BOFAs samarbejde med det civile samfund omkring genbrug 2018-2021. Slutrapport', org: 'BOFA og Aalborg Universitet', year: 2021, type: 'Rapport', temaer: ['Direkte genbrug', 'Genbrugspladser'], img: 'img/ccfa4bb0aca11567c38be012ff22d475.jpg', url: 'https://vbn.aau.dk/ws/files/468729503/Rapport.pdf', res: 'Slutrapport om BOFAs donationscontainere til idrætsforeninger på bornholmske genbrugspladser. I Aakirkeby blev 5 % frasorteret, og foreningen solgte 963 produkter på to måneder.', long: 'Aalborg Universitet og BOFA beskriver BOFAs del af FUTURE-projektet 2018-2021, hvor BOFA stillede donationscontainere op på Hasle og Aakirkeby genbrugspladser til to idrætsforeninger. Rapporten bygger på interview, observation og registerdata, og resultaterne gælder kun Aakirkeby Idrætsforening. I december 2020 og januar 2021 solgte foreningen 963 produkter, og en forsigtig beregning for ca. halvdelen af dem giver 7,3 ton sparet CO2. Indtjeningen steg fra 20.000 kr. om året på loppemarked til 60.000 kr. på fire måneders onlinesalg. BOFA vil udbrede ordningen til alle seks genbrugspladser med et bookingsystem for foreningerne.' },
      { id: 'NY241', title: 'Erfaringer hos borgere i Region Hovedstaden med reparation og genbrug', org: 'Aalborg Universitet', year: 2021, type: 'Analyse', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Analyser og undersøgelser'], img: 'img/02949628dee97368cb4791858b2693fd.jpg', url: 'https://vbn.aau.dk/ws/files/450017559/Rapport_ART_survey_2019_2020.pdf', res: 'Spørgeskemaundersøgelse blandt 1.000 borgere i Region Hovedstaden. Den viser, at 50-87 % af defekt elektronik ikke bliver repareret, og at prisen oftest afgør, om noget repareres.', long: 'Michael Søgaard Jørgensen fra Aalborg Universitet har analyseret en survey fra projektet Affald og ressourcer på tværs, som i samarbejde med Norstat blev sendt til 1.000 repræsentativt udvalgte borgere i oktober 2020 og dækker januar 2019 til september 2020. Hvert år får 18 % af husstandene en defekt mobil, men kun 45 % repareres, og for fodtøj er tallene 27 % og 38 %. Opskaleret kasseres mindst 100.000 mobiltelefoner og 100.000 køkkenapparater om året uden reparation. Møbler købes oftest brugt (25-44 % af anskaffelserne), mod ca. 10 % for sportstøj og fodtøj. Rapporten peger på billigere reparation og redesign af køkkenudstyr og fodtøj.' },
      { id: 'NY242', title: 'Udvikling af lokale strategier for cirkulær økonomi: reparation, genbrug, deleøkonomi', org: 'Aalborg Universitet', year: 2024, type: 'Notat', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Affaldsplaner/regulativer og strategi'], img: 'img/94156e3112fff761da0b638f92b2d684.jpg', url: 'https://vbn.aau.dk/ws/files/750573043/Udvikling_af_lokale_cirk_k_strategier_-_MSJ_AAU_-_2024.pdf', res: 'Notat fra Aalborg Universitet med forslag til, hvordan kommuner sammen med lokale aktører kan udvikle en lokal strategi for reparation, genbrug og deleøkonomi i syv trin.', long: 'Michael Søgaard Jørgensen fra Aalborg Universitet har opdateret et notat fra 2022 om lokale initiativer for cirkulær økonomi. Han peger på repair cafeer og affaldsselskabers reparation af hårde hvidevarer fra genbrugspladser, men hos AVV kunne højst 20 % af de kasserede hvidevarer repareres med overskud. Klimagevinsten ved at reparere et fjernsyn anslås til ca. 300 kg CO2-ækvivalenter mod ca. 3 kg ved genanvendelse. En survey fra Region Hovedstaden viser, at 27 % af husstandene årligt har fodtøj, der skal repareres, og 18 % en mobiltelefon. Notatet foreslår syv trin fra kortlægning af reparationsbehov til deleordninger i boligafdelinger.' },
      { id: 'NY243', title: 'Ledelse af innovation i den offentlige sektor: Kommunal affaldshåndtering som en del af noget større', org: 'Aalborg Universitet', year: 2020, type: 'Analyse', temaer: ['Ledelse', 'Hente- og bringeordninger'], img: 'img/6205aa3053fc2d04a301fd1cb171b9d1.jpg', url: 'https://rauli.cbs.dk/index.php/SiS/article/download/5956/6616', res: 'Forskningsartikel om Aalborg Renovations omlægning til mere sortering hos borgere og virksomheder, set som et åbent system med mange aktører frem for ren top-down eller bottom-up.', long: 'René Nesgaard Nielsen fra Aalborg Universitet bruger i en artikel fra 2020 Aalborg Renovation som case på innovation i den offentlige sektor. Casen bygger på dokumentstudier og tre interviews med to ledere og en medarbejder i 2017-2019. Affaldet sorteres nu langt mere hjemme og hos virksomhederne og kontrolleres på et fælles kommunalt sorteringsanlæg. Omlægningen skulle ske inden for budgetrammen og uden højere takster. Overgangen gav problemer og utilfredshed hos nogle borgere, men den politiske opbakning holdt. Artiklen peger på ledernes blik for den politiske kontekst og på, at udvikling skal ske, mens den tunge drift kører videre.' },
      { id: 'NY244', title: 'Factors influencing changes in island waste systems: The case of Bornholm, Denmark', org: 'BOFA og Aalborg Universitet', year: 2023, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Affaldsplaner/regulativer og strategi', 'Cirkulær økonomi'], img: 'img/e3d3ec8d053b9170d3deecc7c8dfdad3.jpg', url: 'https://vbn.aau.dk/ws/files/539142133/1-s2.0-S2772912523000064-main.pdf', res: 'Et spørgeskema besvaret af 1.049 bornholmere viser høj miljøbevidsthed og ønske om at behandle affaldet på øen. Mange vil betale mere for genbrug, men færre jo dyrere det bliver.', long: 'Artiklen i Cleaner Waste Systems har forfattere fra BOFA, Aalborg Universitet og Federal University of Paraná og tager afsæt i BOFA\'s vision om et affaldsfrit Bornholm i 2032 uden forbrænding og deponi. Den bygger på en repræsentativ spørgeskemaundersøgelse fra april-maj 2021 med 1.049 svar ud af 3.325 udtrukne samt interview. 60 % finder det vigtigt eller meget vigtigt, hvor affaldet behandles, og 36 % bakker fuldt op om genbrug og genanvendelse, selv om det koster mere. 45 % tror let at kunne klare sig med højst fire affaldsbeholdere. Forfatterne mener, at faktorerne kan bruges i planlægning og politik for affald på øer.' },
      { id: 'NY245', title: 'Bioaerosol exposure, inflammation, and symptoms in waste collectors', org: 'Det Nationale Forskningscenter for Arbejdsmiljø', year: 2026, type: 'Analyse', temaer: ['Ledelse', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/2f6d98e8e9a37f6c02daf872f082c10e.jpg', url: 'https://lirias.kuleuven.be/retrieve/5346c851-fc2d-4711-98f8-3c40299e5bf1', res: 'NFA har målt bioaerosoler hos 56 renovationsarbejdere. Anaerobe bakterier hang sammen med let inflammation, og spisning i førerhuset var forbundet med øjensymptomer og diarré.', long: 'Artiklen fra NFA og KU Leuven er udgivet i International Journal of Hygiene and Environmental Health. Luftmålinger blev taget hos 56 renovationsarbejdere i 2022-2023 og blodprøver hos 42, mens ugeeksponeringen blev beregnet ud fra målinger på 105 arbejdere. Hos 20 lå endotoksin over den foreslåede grænse på 90 EU/m³. En fordobling af anaerobe bakterier i luften hang sammen med 6,2 % højere SAA og 5,5 % højere hs-CRP. Rengøring af lastrummet var forbundet med højere eksponering og flere øjen- og luftvejssymptomer, mens hyppig brug af håndsprit fulgte med færre forkølelser. Forfatterne kalder fundene hypoteser til senere interventionsstudier.' },
      { id: 'NY246', title: 'Review of biological risks associated with the collection of municipal wastes', org: 'Det Nationale Forskningscenter for Arbejdsmiljø', year: 2021, type: 'Analyse', temaer: ['Ledelse', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/256f144c05c42c490d8caf11534e93b7.jpg', url: 'https://iris.unil.ch/bitstreams/d901dd22-7ebe-45fc-b5e3-2b119be13543/download', res: 'Europæisk litteraturstudie om renovatørers udsættelse for bioaerosoler. Sjældnere tømning og højere temperatur øger udsættelsen, som hænger sammen med nedsat lungefunktion.', long: 'Forskere fra ti europæiske institutioner skrev artiklen i regi af netværket PEROSH, og førsteforfatteren er fra NFA. Den udkom i Science of the Total Environment i 2021 og gennemgår litteratur fra 1995 til 2019 om indsamling af husholdningsaffald. Median udsættelse ligger typisk omkring 10.000 cfu/m³ for svampe og bakterier og 10 EU/m³ for endotoksin, men enkelte studier ligger 10-20 gange højere eller lavere. Mere sortering og sjældnere tømning kan give mere vækst i affaldet. Høj læssehøjde, ventilation og rengøring af førerhuset, affald i lukkede sække og håndsprit mindsker udsættelsen. Forfatterne efterlyser langtidsstudier af helbredet.' },
      { id: 'NY247', title: 'Plastikforbrug i Danmark', org: 'Danmarks Statistik', year: 2026, type: 'Analyse', temaer: ['Data, statistikker og nøgletal', 'Cirkulær økonomi', 'Afsætning og behandling'], img: 'img/64fee54b5d55096ca8e6f81ff06910cd.jpg', url: 'https://www.dst.dk/analysepdf/58181', res: 'Danmarks Statistik følger plastik gennem økonomien. Nettoforbruget steg fra 118 kg pr. indbygger i 2010 til 161 kg i 2024, og kun 22 % af plastikken i affaldet i 2020 var sorteret.', long: 'Analysen fra juni 2026 bygger på Danmarks Statistiks materialestrømsregnskab for 2020 og tal for handel og sorteret affald over flere år. Det samlede plastikinput var 2,5 mio. tons, og 94 % var importeret. Godt halvdelen blev eksporteret igen, 24 % blev ophobet i bl.a. biler og byggematerialer, mens 22 % blev til affald, som for det meste blev brændt. Husholdningerne brugte 364.000 tons plastik, heraf 40 % emballage. Det indsamlede affald indeholdt 604.000 tons plastik, hvoraf 132.000 tons var udsorteret, og i 2023 nåede den sorterede mængde 163.000 tons, mere end dobbelt så meget som i 2011. Mange af tallene er skøn med stor usikkerhed.' },
      { id: 'NY248', title: 'Uligheder, sårbarhed og robuste lokale hverdagsløsninger', org: 'Nationalmuseet', year: 2024, type: 'Rapport', temaer: ['Etageboliger', 'Analyser og undersøgelser', 'Sorteringskvalitet'], img: 'img/c8894307820066c6b0fd8e95c0985931.jpg', url: 'https://natmus.dk/fileadmin/user_upload/Editor/Sarahs_arbejdsmappe_kommunikation_/SUMO_websektion/FF_rapport.pdf', res: 'Antropologisk undersøgelse af affaldssortering i almene boligområder. Lange afstande til fælles affaldsøer rammer sårbare beboere, som selv finder løsninger som fx indkøbsvogne.', long: 'Antropolog My Madsen har i Nationalmuseets og Arkitektskolen Aarhus\' projekt Fleksible Fællesskaber fulgt affaldshåndteringen i tre almene boligområder i to år. Materialet er ca. 100 interview, ca. 40 timers observation, to workshops og beboerblade fra 1970\'erne til 2021. Sortering i 10 fraktioner kræver materialeforståelse og fysisk styrke, og afstanden til molokker og containere rammer især ældre og psykisk sårbare. Beboerne har skabt uofficielle affalds- og byttesteder og fragter affaldet i indkøbsvogne. Rapporten anbefaler flere superlokale sorterings- og byttesteder og at gøre vognene til en lovlig del af faciliteterne.' },
      { id: 'NY249', title: 'Evaluation of tools to reduce food waste at the household level', org: 'Aarhus Universitet', year: 2025, type: 'Evaluering', temaer: ['Kommunikation', 'Analyser og undersøgelser'], img: 'img/617a0cd813fcf2f8babfa25a94b11883.jpg', url: 'https://pure.au.dk/ws/files/426032295/Levering_Evaluation_of_tools_to_reduce_food_waste_at_the_household_level.pdf', res: 'Aarhus Universitet har evalueret tre værktøjer mod madspild i et forsøg med 322 børnefamilier. De blev godt modtaget, men et fald i madspildet kunne ikke påvises sikkert.', long: 'DCA ved Aarhus Universitet har for Fødevarestyrelsen evalueret en madspildsdagbog, Køleskabsskilte og Bonusmåltid hos børnefamilier. I september-oktober 2024 deltog 322 personer fordelt på en kontrolgruppe og to grupper, der testede to værktøjer i to uger, og 13 blev interviewet. Bonusmåltid blev brugt af 85 %, de andre af ca. 60 %. Kun gruppen med Bonusmåltid og Køleskabsskilte blev mere opmærksom på madspild. Selvrapporteret madspild faldt i alle grupper, også kontrolgruppen, og gruppens ekstra fald var ikke statistisk sikkert (p=0,077). Deltagerne fandt værktøjerne nemme og gode til at spare penge, men færre ville fortsætte med dagbogen.' },
      { id: 'NY250', title: 'Vejledende udtalelse om kommunernes omkostningsfordeling i producentgebyrerne for emballageaffald', org: 'Miljøstyrelsen', year: 2025, type: 'Vejledning', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/7aff41a14a9c065759baaa9b73c3f022.jpg', url: 'https://mst.dk/media/cbhn5gsb/miljoestyrelsens-vejledende-udtalelse-om-kommunernes-omkostningfordeling-i-producentgebyrer.pdf', res: 'Vejledende udtalelse fra Miljøstyrelsen om producentgebyrer for emballage. Fælles omkostninger bør deles ligeligt mellem ordninger og udgifter til flerkammerspande efter volumen.', long: 'Udtalelsen fra 5. september 2025 skal ensrette, hvordan kommunerne fordeler omkostninger, når de fra 2026 fastsætter producentgebyrer for indsamling af emballageaffald efter emballagebekendtgørelsen. Formålet er at undgå en fordeling, der rammer materialer med høj reel genanvendelse. Generelle omkostninger til administration og til oplysning og kommunikation bør deles ligeligt mellem ordningerne, så 100.000 kr. fordelt på syv ordninger giver 14.286 kr. pr. ordning. Udgifter til flerkammerspande bør fordeles efter kamrenes andel af volumen. Indholdet er vejledende, men Miljøstyrelsen vil skrive metoden ind i bekendtgørelsen som et krav.' },
      { id: 'NY251', title: 'Afklaring af kommunernes opkrævning af kost- eller markedspris for indsamling af batterier', org: 'Miljøstyrelsen', year: 2025, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/bd36810d092773e129e481caddcf8ce3.jpg', url: 'https://mst.dk/media/3wnnzog2/050525-notat-afklaring-om-kost-eller-markdspris-for-kommunal-indsamling-af-batterier-under-forordningen.pdf', res: 'Miljøstyrelsen vurderer, at kommuner skal tage markedspris og ikke kostpris, når de indsamler batterier for producenternes kollektive ordninger under batteriforordningen.', long: 'Notatet fra maj 2025 svarer på en henvendelse fra KL. Med batteriforordningen skal producenterne via kollektive ordninger indsamle bærbare batterier og LMT-batterier, og de kan bruge kommunernes husstandsnære henteordninger eller andre aktører, fx distributører. Kommunernes indsamling indgår dermed på et marked med konkurrence. Da ruterne også betales af emballageproducenter og affaldsgebyret, kan omkostninger ende under anden indsamling som krydssubsidiering. Miljøstyrelsens umiddelbare vurdering er, at kommunalfuldmagten og konkurrencelovens § 11 a kræver en markedspris. KL kan forelægge spørgsmålet for Konkurrence- og Forbrugerstyrelsen.' },
      { id: 'NY252', title: 'Tidsfrister for kommuner efter emballagebekendtgørelsen', org: 'Miljøstyrelsen', year: 2025, type: 'Faktaark', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/e8ea6995b3d03f8f8913f4473b3d9b7d.jpg', url: 'https://mst.dk/media/hodjgirr/tidsfrister-kommuner-15-10-2025.pdf', res: 'Miljøstyrelsens tabel over kommunernes frister efter emballagebekendtgørelsen, fra kvartalsvis opkrævning af gebyrer hos virksomheder fra 1. oktober 2025 til årlige indberetninger.', long: 'Oversigten fra Miljøstyrelsen viser i tidsorden, hvad kommunalbestyrelsen skal gøre efter emballagebekendtgørelsen, hvem der modtager det, og hvilken paragraf der gælder. Gebyrer opkræves hos virksomhederne kvartalsvis fra 1. oktober 2025, og gebyrerne fastsættes og offentliggøres senest 15. oktober hvert år. Rapporten om baggrunden for omkostningerne skal til Miljøstyrelsen første gang 1. november 2025 og den årlige opgørelse af gebyrer og omkostninger 1. maj 2026. Indsamlingsordningerne skal oplyses til Dansk Producentansvar første gang 1. juni 2026. Tabellen er kun til orientering og henviser til paragrafferne i bekendtgørelsen.' },
      { id: 'NY253', title: 'Life Cycle Assessment of Mattresses – Reuse and Recycle Systems, a Pilot to Scale', org: 'DTU Sustain', year: 2025, type: 'Analyse', temaer: ['Afsætning og behandling', 'Klima', 'Storskraldsordning'], img: 'img/bdae60db62676a82b3e2b1f08a331855.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/437650194/LCArapport-Madrasser-projekt_M-RRS.pdf', res: 'DTU\'s livscyklusvurdering af kasserede madrasser viser, at adskillelse og genanvendelse efter hollandsk model belaster klimaet mindre end forbrænding, men usikkerheden er stor.', long: 'DTU Sustains livscyklusvurdering fra december 2025 hører til et treårigt projekt med bl.a. Odsherred, Vejle og Københavns Kommuner, ARC, Vestforbrænding og ARGO. Madrasser fra storskrald og genbrugspladser skulle være rene og tørre og blev adskilt i Holland. Ca. 650.000 madrasser kasseres årligt i Danmark, og de fleste brændes. Pr. ton madras giver de to forbrændingsscenarier 350 og 190 kg CO2-ækv., mens genanvendelse sparer 290 og 270 kg. Bliver skummet til ny polyol, er scenariet bedst i 10 af 16 kategorier, men som isolering giver det ingen klar miljøgevinst. Manglende primærdata og et uklart marked for genbrugsskum gør resultaterne usikre.' },
      { id: 'NY254', title: 'Waste containing asbestos and other environmentally problematic substances', org: 'Miljøstyrelsen', year: 2022, type: 'Rapport', temaer: ['Byggeaffald', 'Afsætning og behandling'], img: 'img/34082b00128f3f58bb3188f40ef07c01.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/302213476/978_87_7038_454_4.pdf', res: 'DTU og Aarhus Universitet har for Miljøstyrelsen undersøgt affald med asbest og fx tungmetaller eller PCB. Fliser og linoleum overholder kriterierne for deponi af farligt affald.', long: 'Rapporten fra DTU og Aarhus Universitet bygger på litteratur, svar fra 46 kommuner og 8 virksomheder, forsøg med fire prøver og en risikoscreening. Der opstår ca. 90.000 ton asbestholdigt affald om året, men kun få hundrede ton skønnes også at rumme andre problematiske stoffer, især vinyl- og linoleumsgulve og fliser med tungmetaller og tagpap med organiske stoffer. Risikoen for vandmiljø og drikkevand ved deponi vurderes som lav. Ved 1.100 °C blev de organiske stoffer stærkt reduceret, og asbestfibrene i linoleum ser ud til at blive ødelagt. Forfatterne foreslår en officiel vejledning i prøvetagning, så kommunerne klassificerer affaldet ens.' },
      { id: 'NY255', title: 'Climate footprint assessment of plastic waste pyrolysis', org: 'Roskilde Universitet og DTU', year: 2024, type: 'Analyse', temaer: ['Klima', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/674dc3901b947fb77ca092283939224d.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/347508489/1-s2.0-S0301479723025689-main.pdf', res: 'Forskere fra RUC og DTU finder, at dansk plastaffald bør holdes ude af forbrænding, når der er alternativer, og at mekanisk genanvendelse plus pyrolyse giver størst klimagevinst.', long: 'Den videnskabelige artikel sammenligner pyrolyse, mekanisk genanvendelse, forbrænding og brug som brændsel i industrien for syv plastfraktioner, de fleste fra danske affaldsproducenter, med data fra pyrolyseforsøg i laboratorieskala. Pyrolyse sparer hhv. 1.400 og 4.800 kg CO2e pr. ton PS og PMMA, mekanisk genanvendelse 1.000 kg pr. ton PE, mens forbrænding udleder 1.600-2.200 kg pr. ton. Danmark har ca. 480.000 ton plastaffald om året, hvoraf 110.000 ton er kildesorteret, og håndteringen giver 0,79 mio. ton CO2e. Pyrolyse af rejekt fra genanvendelsen sparer 15 %. Sorteres 40 % af plasten fra restaffaldet, kan udledningen falde 48-66 %.' },
      { id: 'NY256', title: 'Analyse og kortlægning af materialestrømme bygge- og anlægsaffald i Danmark', org: 'Realdania', year: 2026, type: 'Analyse', temaer: ['Byggeaffald', 'Data, statistikker og nøgletal', 'Reel genanvendelse'], img: 'img/4cbd48438648ede5a6db6ec945c0e3de.jpg', url: 'https://realdaniadk-umbraco-app-p-we.azurewebsites.net/media/e5pgqmp4/delrapport-1-analyse-og-kortlaegning-af-materialestroemme-bygge-og-anlaegsaffald_rev-00.pdf', res: 'Kortlægning af 17 materialefraktioner i bygge- og anlægsaffald. Der opstår 7,5 mio. ton om året, men ADS registrerer kun 4,5 mio. ton, fordi meget beton og tegl nyttiggøres lokalt.', long: 'Første delrapport i Realdanias Cirkulært Byggeri 2.0 er skrevet af TRE, Om Affald og Danish Waste Solutions ud fra ADS-data, litteratur, cases og interviews. De ca. 3 mio. ton, der mangler i ADS, er beton og tegl, som nyttiggøres lokalt eller bruges som fyld efter restproduktbekendtgørelsen. De lette fraktioner registreres, men gemmer sig i blandede fraktioner som blandet byggeaffald på ca. 530.000 ton om året. Af de 7,5 mio. ton bliver 1 % genbrugt, 23 % genanvendt og 64 % nyttiggjort, mens resten forbrændes eller deponeres. Størst potentiale for at flytte materialer op i affaldshierarkiet er der i asfalt, beton, mursten, tagsten og træ.' },
      { id: 'NY257', title: 'Fra vision til handling: Sådan blev seks danske kommuner mere cirkulære', org: 'Realdania', year: 2024, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Byggeaffald', 'Direkte genbrug'], img: 'img/c4f234c6150ff52d6a0f16599ef1684c.jpg', url: 'https://realdaniadk-umbraco-app-p-we.azurewebsites.net/media/op0ly310/wp-cirkulaere-byer.pdf', res: 'Casesamling fra innovationsforløbet Cirkulære Byer 2022-2024, hvor seks kommuner testede cirkulære løsninger. Foreløbige data viser 30 % mere sortering på Københavns byggepladser.', long: 'CLEAN og Dansk Design Center drev projektet med støtte fra Realdania og har skrevet publikationen, der samler erfaringer fra Aalborg, Fredensborg, Fredericia, Kolding, København og Odsherred. København arbejdede med kildesortering på byggepladser, og kommunens foreløbige data viser 30 % mere sortering af genanvendelige materialer efter øget tilsyn og adfærdstiltag. Fredensborg undersøgte, om overskudsjord og brugte mursten kan bruges i Nivå Bymidte, og lagde materialer fra en selektivt nedrevet skole til side. Aalborg oplevede, at reglerne om forurening gør genbrug svært. Sidst beskrives en designproces i tre faser til brug i andre kommuner.' },
      { id: 'NY258', title: 'Circular CDW in Roskilde: Demonstration Report', org: 'Roskilde Kommune', year: 2023, type: 'Rapport', temaer: ['Byggeaffald', 'Direkte genbrug', 'Klima'], img: 'img/57bc3a04e53c2580c814b26bfd1b9fb3.jpg', url: 'https://cityloops.eu/fileadmin/user_upload/D2.12_CDW_Demonstration_Report_for_Roskilde.pdf', res: 'Roskilde Kommune testede i EU-projektet CityLoops cirkulær nedrivning, genbrug af beton i P-huse og jordhåndtering i Musicon. Ved Hal 11/12 er over 110 ton CO2 sparet.', long: 'Rapporten fra september 2023 er skrevet af Roskilde Kommune og Roskilde Universitet. Demonstrationerne i Musicon omfatter ombygning og delvis nedrivning af Hal 11 og 12, to nye P-huse og cirkulær jordhåndtering. Kommunen udviklede bl.a. en procedure for materialepas og CO2-beregnere, der vurderer håndteringen af jord og byggeaffald. Udbuddet på nedrivning af første del af Hal 12 kræver over 50 % genbrug eller højværdig genanvendelse. Ved P-huset Indfaldet blev 1.087 ton beton fra grunden knust og brugt som fyld og tilslag, hvilket ifølge business casen sparede knap 53.000 euro. Til P-huset Pulsen er 12.000 tagsten lagt til side til genbrug.' },
      { id: 'NY259', title: 'Partnership for circular textiles - ReYarn: Project end report', org: 'Københavns Kommune', year: 2023, type: 'Evaluering', temaer: ['Tekstil', 'Direkte genbrug', 'Udbud og kravspecifikationer'], img: 'img/6b42b7490e7cffc6ebf6e0bf66bdb757.jpg', url: 'https://circular.kk.dk/sites/default/files/2026-04/Read%20the%20report%20from%20the%20ReYarn%20project%20here.pdf', res: 'Københavns Kommune og partnere testede 2021-2022 at forsortere brugt tekstil med lokalt genbrug først. Det krævede lokal markedsviden, og produkter af genanvendt fiber var dyre.', long: 'Slutrapporten fra ReYarn er skrevet af Revaluate og Københavns Kommune, der arbejdede sammen med Trasborg, Frelsens Hær, Wolkat og Bacher. Fra maj 2021 til marts 2022 blev ca. 40 ton tekstil fra kommunens nærgenbrugsstationer indsamlet og sorteret i to forsøg. Da Trasborg sorterede, gik kun 2,6-6,3 % til lokalt genbrug, og cirka halvdelen kunne Frelsens Hær alligevel ikke sælge. Andelen steg, når Frelsens Hær sorterede først, og andelen til forbrænding kunne komme ned nær 5 %. Wolkat lavede viskestykker med 42 % brugt tekstil, men de kostede det dobbelte. Rapporten anbefaler udbud, der fremmer innovation og ser på levetidsomkostninger.' },
      { id: 'NY260', title: 'Evaluering af bokse til genbrug af elektronik', org: 'Københavns Kommune', year: 2025, type: 'Evaluering', temaer: ['Direkte genbrug', 'Kommunikation', 'Genbrugspladser'], img: 'img/5046ea03eaff445ffdb7993791bb9907.jpg', url: 'https://circular.kk.dk/sites/default/files/2025-02/Rapport%20-%20Evaluering%20af%20elektronikbokse%20til%20genbrug%20%28Danish%29.pdf', res: 'Evaluering af Københavns Kommunes forsøg med aflåste bokse til brugte mobiltelefoner, tablets og bærbare. Kun knap 11 % af de 2.870 indleverede enheder kunne genbruges direkte.', long: 'Behave Green har evalueret pilotprojektet for kommunen. Ragn-Sells drev 15 bokse på 18 steder, bl.a. biblioteker, supermarkeder, indkøbscentre og to genbrugsstationer, mens kommunen stod for kampagnerne. Evalueringen bygger på interviews og Ragn-Sells\' data om enhederne. 82 % af de adspurgte har gammel elektronik liggende, men frygt for persondata og uklarhed om forskellen på genbrug og genanvendelse holder dem tilbage. 78 % af enhederne endte til genanvendelse. Boksene på genbrugsstationerne virkede bedst, men blev brudt op. Rapporten anbefaler bl.a. sikker indsamling på genbrugsstationer og en guide til datasletning.' },
      { id: 'NY261', title: 'Transforming mattresses from waste to resource: trials Denmark', org: 'Københavns Kommune', year: 2022, type: 'Analyse', temaer: ['Afsætning og behandling', 'Reel genanvendelse'], img: 'img/0917cd46a1bb3f30393a534507525390.jpg', url: 'https://circular.kk.dk/sites/default/files/2026-04/Download%20the%20report%20on%20automatic%20sorting%20of%20mattress%20waste.pdf', res: 'RetourMatras testede 302 danske madrasser. De madrasser, der kan skilles ad maskinelt, nåede 74-80 % genanvendelse, mens boxmadrasser med træramme ikke kan betale sig.', long: 'Den hollandske genanvender RetourMatras modtog to læs madrasser fra indsamling i København, Vejle og Hillerød på sit anlæg i Lelystad for at se, om de adskiller sig fra hollandske madrasser. Læsset fra storskrald talte 130 madrasser og læsset fra genbrugsstationer 172, heraf i alt 122 boxmadrasser. Pocket- og skummadrasser blev skilt ad maskinelt med 74 % genanvendelse fra storskrald og 80 % fra genbrugsstationer. De fleste boxmadrasser består af over 50 % træ og tager ca. 15 minutter at skille ad i hånden mod 50 sekunder på maskinen. Ellers ligner de danske madrasser de hollandske, og metoden vurderes at kunne bruges i Danmark.' },
      { id: 'NY262', title: 'Test af cirkulær værdikæde med komposterbare bleer i København', org: 'Københavns Kommune og Frederiksberg Kommune', year: 2023, type: 'Evaluering', temaer: ['Analyser og undersøgelser', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/3e5133cb9f6fc1da14e9855a4e215e79.jpg', url: 'https://circular.kk.dk/sites/default/files/2026-04/Report%20on%20the%20test%20scheme%20for%20compostable%20diapers%202023%20%28Danish%29_0.pdf', res: 'To vuggestuer i København og på Frederiksberg testede komposterbare bleer i marts 2023. Bleerne gav meget biogas, men fungerede dårligt, og komposten overskred grænseværdier.', long: 'Transition ApS har skrevet rapporten om en test, som et projektteam lavede med Københavns og Frederiksberg Kommuner. Bleer udgør 31 % af restaffaldet i Københavns Kommunes daginstitutioner. To vuggestuer brugte bleerne i marts 2023, og en tredje trak sig efter en uge. Pædagogerne oplevede utætte bleer med dårlig pasform, og fejlsorteringen i bleposerne var ca. 1,3 %. Laboratorietest gav 221,2 m3 biogas pr. ton mod 55,1 m3 for almindelige bleer. Hygiejniseringen nåede 70 °C, men komposten overskred grænseværdier for enterokokker, kobber, nikkel og zink. Metallerne kom formentlig fra en grab hos BOFA. Opskaleringsmatricen er overvejende gul.' },
      { id: 'NY263', title: 'Faktaark 2024: Behandling og genanvendelse af husstandsindsamlede affaldsfraktioner', org: 'Københavns Kommune', year: 2025, type: 'Faktaark', temaer: ['Reel genanvendelse', 'Afsætning og behandling', 'Data, statistikker og nøgletal'], img: 'img/4746fe965165df9f5c2d3bed35447fb6.jpg', url: 'https://circular.kk.dk/sites/default/files/2025-09/Fact%20Sheets%20on%20Household%20Waste%20Flows%20%28Danish%29.pdf', res: 'Faktaark om 15 affaldsfraktioner indsamlet ved husstandene i København i 2024. For hver fraktion vises mængde og behandling og for de fleste også reel genanvendelse og klimaeffekt.', long: 'Københavns Kommune beskriver i faktaarkene, hvordan affaldet fra husstandene blev indsamlet og behandlet i 2024. Affald fra genbrugsstationerne indgår som udgangspunkt ikke. Den reelle genanvendelse er 98 % for glas, 95 % for madaffald og papir, ca. 82 % for metal, 67 % for plast og ca. 27 % for stort indbo. De 18.128 tons madaffald bliver til biogas ved Solrød, mens plast og kartoner sorteres i Tyskland. Glasset gav den største CO₂-besparelse på 8.500 tons. De 92.135 tons restaffald gav en merudledning på 2.000 tons CO₂, og en opgørelse fra 2023 viser, at 37 % af restaffaldet er madaffald.' },
      { id: 'NY264', title: 'Batterier i nordiske småsamfund', org: 'Nordisk Ministerråd', year: 2024, type: 'Analyse', temaer: ['Hente- og bringeordninger', 'Udvidet producentansvar', 'Affaldsplaner/regulativer og strategi'], img: 'img/48b6d1e8287b3f0ad706b93270ec87e0.jpg', url: 'https://norden.diva-portal.org/smash/get/diva2:1860071/FULLTEXT01.pdf', res: 'Norion Consult og DTU har for Nordisk Ministerråd undersøgt indsamling af batterier på Bornholm, Færøerne og Island og anbefaler faste indsamlingsmål og bedre monitorering.', long: 'Analysen bygger på litteratur, statistik, interviews med 20 aktører og tre online workshops. Øerne genanvender ikke selv batterierne, så affaldet eksporteres. På Bornholm står BOFA for indsamlingen, som er steget fra 11-16 tons blandede batterier om året i 2012-2017 til 19-24 tons efter 2017. Øen mangler lokale mål for batterier og monitorering af, hvilke typer der indsamles. Bornholm anbefales at sætte årlige indsamlingsmål frem til 2032 og stille krav om genopladelige batterier i kommunens indkøb. Færøerne bør indføre udvidet producentansvar, mens Island bør sætte mål og lave vejledninger til borgere og virksomheder.' },
      { id: 'NY265', title: 'Supervision to combat waste crime', org: 'Nordisk Ministerråd', year: 2024, type: 'Analyse', temaer: ['Lovgivning og afgørelser', 'Erhverv'], img: 'img/0be9ecaa454210849e4fc0d25743a3c1.jpg', url: 'https://norden.diva-portal.org/smash/get/diva2:1920987/FULLTEXT01.pdf', res: 'Studie af tilsyn med affald og affaldskriminalitet i de nordiske lande. Mangel på data og sporing af affald samt svagt internationalt samarbejde er fælles udfordringer.', long: 'Ensucon AB har lavet studiet for Naturvårdsverket med finansiering fra Nordisk Ministerråd. Det bygger på 14 interviews med myndigheder i seks nordiske lande i foråret 2024 og en digital workshop i juni. Typiske overtrædelser er manglende dokumentation og forkert klassificering. Tilsynet planlægges oftest ud fra risikovurderinger og bygger på virksomhedernes egne oplysninger. Blandt de største udfordringer er adgang til data og sporing af affald, uklare regler, knappe ressourcer og svagt internationalt samarbejde. Som godt eksempel fremhæves Danmarks automatiske, risikobaserede udvælgelse til tilsyn fra 2025.' },
      { id: 'NY266', title: 'Towards a sustainable circular system of textiles in the Nordics', org: 'Nordic Innovation', year: 2022, type: 'Rapport', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Afsætning og behandling'], img: 'img/f40cf102b608df5b9a13b3280aad63bb.jpg', url: 'https://norden.diva-portal.org/smash/get/diva2:1719494/FULLTEXT03.pdf', res: 'Slutrapport fra det nordiske SATIN-projekt om indsamling og sortering af tekstilaffald. Indsamling i to fraktioner letter sorteringen, og nye nordiske anlæg kan klare det meste.', long: 'SATIN kørte 2020-2022 under Nordic Innovation med svenske VTI som leder og 24 partnere, bl.a. Aalborg Universitet. Det bygger på interview i fire nordiske lande og ni pilotforsøg med indsamling. Mellem 55 % (Danmark) og 67 % (Sverige) af de udtjente tekstiler ender i restaffaldet. Indsamling i to fraktioner understøtter den senere sortering, og placering tæt på boligen eller på genbrugspladsen ser ud til at virke. De kommende nordiske anlæg kan klare næsten alle genanvendelige tekstiler, men mangler kapacitet til ca. 11.200 ton syntetiske fibre. Ubalancer mellem landene kræver samarbejde, og forsorteringen skal løses i Norden.' },
      { id: 'NY267', title: 'Sustainability assessment of textile reuse and recycling in and outside of Europe', org: 'IVL Svenska Miljöinstitutet', year: 2025, type: 'Analyse', temaer: ['Tekstil', 'Direkte genbrug', 'Klima'], img: 'img/4f3ab71e2725a78c6a462473863d26f1.jpg', url: 'https://ivl.diva-portal.org/smash/get/diva2:1926690/FULLTEXT01.pdf', res: 'Livscyklusvurdering fra IVL af 1 ton indsamlede T-shirts. Genbrug giver lavest klimapåvirkning, både i og uden for Europa, mens genanvendelse ikke er meget bedre end forbrænding.', long: 'IVL har med støtte fra bl.a. Humana LT og Human Bridge sammenlignet genbrug og fiber-til-fiber-genanvendelse i og uden for Europa med forbrænding. Eksemplet er 1 ton T-shirts af 60 % bomuld og 40 % polyester indsamlet i Sverige. Genbrug giver lavest påvirkning i alle kategorier undtagen vandknaphed, hvor genanvendelse klarer sig bedst. Resultatet afhænger meget af, hvor meget tøj der går tabt ved salg i Afrika. Studiet antager 2 %, mens kilder angiver 1-50 %. Litteratur og interviews om Litauen og Kenya viser, at handlen med brugt tøj giver job og billigt tøj, men at faldende kvalitet og uformelle job er risici.' },
      { id: 'NY268', title: 'Maturity of fibre-to-fibre recycling in Europe: Assessment of recycling companies in Europe', org: 'IVL Svenska Miljöinstitutet', year: 2025, type: 'Analyse', temaer: ['Tekstil', 'Cirkulær økonomi', 'Afsætning og behandling'], img: 'img/da0160d844a8b34318314c2d7708af5a.jpg', url: 'https://ivl.diva-portal.org/smash/get/diva2:1933003/FULLTEXT01.pdf', res: 'IVL har vurderet seks europæiske virksomheder, der genanvender tekstil til nye fibre. Mekanisk genanvendelse er mest moden, og kundemodenheden halter efter teknologien.', long: 'Rapporten er lavet i projektet Sustainable clothing futures, finansieret af Formas, og vurderingen blev foretaget i efteråret 2024. Med KTH’s Innovation Readiness Level-model blev Aquafil, Comistra, CuRe Technology, Ioncell, Recover og Worn Again scoret på teknologi, forretningsmodel og kunder. Teknologien lå i snit på 6,5, forretningsmodellen på 6,2 og kundemodenheden på 5,0, og Aquafil og Comistra lå højt på alle tre. Kun 1 % af verdens tekstilfibre stammer i dag fra genanvendte tekstiler. Ifølge forfatterne kræver opskalering også holdbare forretningsmodeller og tæt samarbejde i værdikæden, og EU’s regulering har stor betydning.' },
      { id: 'NY269', title: 'Implications for the Kenyan Mitumba Market from Introduction of Basel Convention Rules', org: 'IVL Svenska Miljöinstitutet', year: 2026, type: 'Analyse', temaer: ['Tekstil', 'Direkte genbrug', 'Afsætning og behandling'], img: 'img/60bd1b22e2ff8c525f241a51d9e26608.jpg', url: 'https://ivl.diva-portal.org/smash/get/diva2:2074885/FULLTEXT02.pdf', res: 'IVL vurderer, hvordan nye regler under Baselkonventionen kan ramme Kenyas marked for brugt tøj. Hvis tøj til genbrug behandles som affald, risikerer handlen at bryde sammen.', long: 'IVL Svenska Miljöinstitutet har lavet rapporten for Humana Ltd, som sorterer brugt tøj. Den bygger på interview i Nairobi og høringssvar til Baselkonventionen fra december 2025 og dækker kun genbrugstekstiler. Skærpet affaldskontrol med forudgående samtykke (PIC) kan give 1-6 måneders forsinkelse og højere omkostninger, så importen falder. Regnes tøjet som produkter i et andet liv, kan handlen fortsætte med lidt mere administration. Kenya importerede brugt tøj for ca. 230 mio. USD i 2024, og ifølge studier fra Østafrika er kun 1-2 % af ballernes indhold affald. Rapporten anbefaler bedre handelskoder, der skiller genbrugstekstiler fra affald.' },
      { id: 'NY270', title: 'Färdplan för en säker arbetsmiljö vid insamling och reparation för återbruk av elektronik', org: 'IVL Svenska Miljöinstitutet', year: 2024, type: 'Rapport', temaer: ['Ledelse', 'Direkte genbrug', 'Genbrugspladser'], img: 'img/5c5b47421dd951755e23635fb4f1f131.jpg', url: 'https://ivl.diva-portal.org/smash/get/diva2:1922683/FULLTEXT01.pdf', res: 'Svensk forskningsrapport om arbejdsmiljøet, når elektronik indsamles og repareres til genbrug. Den kemiske eksponering var lav, men der mangler viden om risici og forebyggelse.', long: 'IVL Svenska Miljöinstitutet har med støtte fra Forte og Formas undersøgt arbejdsmiljøet hos en virksomhed, der istandsætter elektronik, og på to genbrugspladser. Projektet bygger på interview, en spørgeskemaundersøgelse om sikkerhedsklima og målinger af kemisk eksponering. Luftmålinger hos i alt 20 personer viste, at støv, 19 metaller, ftalater, kviksølv og kvælstofdioxid lå under 10 % af de hygiejniske grænseværdier. Nikkel på huden kunne dog give eksem hos folk, der allerede er nikkelallergiske. Forskerne fandt 12 udfordringer inden for 6 områder, bl.a. sikkerhedskultur og rutiner, og anbefaler et mere forebyggende arbejde.' },
      { id: 'NY271', title: 'Mikroorganismer i arbetsmiljön vid förbehandlings- och samrötningsanläggningar', org: 'IVL Svenska Miljöinstitutet', year: 2022, type: 'Rapport', temaer: ['Ledelse', 'Afsætning og behandling'], img: 'img/2d3b9e9bcaf89b366b8c14980e7dd94c.jpg', url: 'https://ivl.diva-portal.org/smash/get/diva2:1657612/FULLTEXT01.pdf', res: 'Svensk rapport om støv og mikroorganismer i arbejdsmiljøet på anlæg, der forbehandler organisk affald. Hvor andre tiltag ikke virker, anbefales mere brug af åndedrætsværn.', long: 'IVL Svenska Miljöinstitutet målte i samarbejde med Avfall Sverige støv på tre forbehandlingsanlæg, der modtager 20.000-65.000 ton organisk affald om året. Et optisk instrument stod fast eller blev båret af personalet, i alt 52 målinger, og 21 ansatte blev interviewet. Forhøjede halter fandtes ved åben håndtering med for lidt ventilation og steg yderligere ved højtryksspuling, eller når materialet var i bevægelse. De steder, personalet selv pegede på som kritiske, passede godt med målingerne. Som tiltag nævnes blandt andet rumopdeling, indkapsling, reguleret vandtryk ved spuling og kameraovervågning i stedet for inspektionsrunder.' },
      { id: 'NY272', title: 'Fördjupad analys av plast i hushållens restavfall', org: 'RISE Research Institutes of Sweden', year: 2024, type: 'Analyse', temaer: ['Klima', 'Analyser og undersøgelser', 'Sorteringskvalitet'], img: 'img/dc3f3b99de0b90385fd11ccf09a17799.jpg', url: 'https://ri.diva-portal.org/smash/get/diva2:1834719/FULLTEXT01.pdf', res: 'RISE har målt fossilt kulstof i hver fraktion af husholdningers restaffald fra Göteborg. Hård og blød plastemballage står for 35-43 % af den fossile CO2 ved forbrænding.', long: 'Den svenske rapport fra januar 2024 bygger på plukanalyser og kemiske analyser af to samleprøver af restaffald fra Göteborg, fra etageboliger og et rækkehusområde, indsamlet i oktober og november 2022. For hver fraktion er andelen af fossilt og biogent kulstof målt. Plastemballage giver 35-43 % af den fossile CO2 ved forbrænding, anden plast 12-17 %, andet brændbart 11-12 %, bleer 6-9 % og tekstiler 3-8 %. Når emballagen sorteres fra ved boligen, bliver bleer, anden plast og andet brændbart de største kilder, og her peger RISE på CO2-fangst. De to sidste indeholder ftalater, som kan hindre genanvendelse.' },
      { id: 'NY273', title: 'The circular bio-waste management handbook for local authorities', org: 'CityLoops', year: 2023, type: 'Vejledning', temaer: ['Afsætning og behandling', 'Hente- og bringeordninger', 'Cirkulær økonomi'], img: 'img/7530056bdada89e0076cad7ac44940bb.jpg', url: 'https://cityloops.eu/fileadmin/user_upload/Materials/Deliverables/CityLoops_2023_Handbook_Biowaste.pdf', res: 'Håndbog fra EU-projektet CityLoops om cirkulær håndtering af bioaffald i kommuner, fra forebyggelse og omfordeling af overskudsmad til separat indsamling og behandling.', long: 'CityLoops samlede syv europæiske byer, heriblandt Høje-Taastrup og Roskilde. ICLEI har skrevet håndbogen ud fra bioaffaldsprojekterne i Apeldoorn, Mikkeli, Porto og Sevilla. Den prioriterer forebyggelse og omfordeling af overskudsmad, derefter hjemme- og fælleskompostering og separat indsamling til behandling på anlæg, hvor lokal behandling ikke er mulig, fx i bymidter. I Mikkeli faldt andelen af bioaffald i restaffaldet fra 35 % til 27 % efter en kampagne med papirposer, og Portos donationsnetværk undgik 144 ton madaffald fra 2021 til maj 2023. Anden del gennemgår ni forudsætninger som strategi, data, finansiering og cirkulære indkøb.' },
      { id: 'NY274', title: 'Affaldsgebyrerne er steget med 50 pct. siden 2019', org: 'CEPOS', year: 2025, type: 'Analyse', temaer: ['Økonomi', 'Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/ef9b34b6ca2ce16934bb5632ac74be20.jpg', url: 'https://cepos.dk/wp-content/uploads/2025/11/Affaldsgebyrer_analyser_2025.pdf', res: 'CEPOS sammenligner kommunernes affaldsgebyrer for enfamiliehuse i 2025 og vurderer, at en husstand i snit kan spare 1.050 kr. om året. Gebyrerne er steget 50 % siden 2019.', long: 'Analysen fra november 2025 bygger på kommunernes takstblade for standardløsningen til enfamiliehuse. Gebyret ligger mellem 2.193 kr. i Herning og 6.539 kr. i Rudersdal, i snit 4.050 kr. CEPOS bruger benchmarkingmetoden DEA, sammenligner kommuner med og uden moms hver for sig og tager højde for indsamlet volumen og befolkningstæthed. Besparelsespotentialet er i alt 2,8 mia. kr. og procentvis størst i Herlev med 61 %. Fra 2019 til 2025 steg gebyrerne med 1.353 kr., mens forbrugerpriserne steg 18 %. CEPOS anbefaler bl.a. at ophæve kommunernes monopol og indføre udbudspligt på indsamlingen.' },
      { id: 'NY275', title: 'Bedre forsyning kan styrke danskernes hverdagsøkonomi', org: 'CEPOS', year: 2026, type: 'Analyse', temaer: ['Økonomi', 'Lovgivning og afgørelser'], img: 'img/e6c8e98033c822338058ac8fac9cf310.jpg', url: 'https://cepos.dk/wp-content/uploads/2026/06/Bedre-forsyning-kan-styrke-danskernes-hverdagsokonomi_CEPOS.pdf', res: 'CEPOS anslår et uudnyttet effektiviseringspotentiale i forsyningssektoren på 11,2-12,7 mia. kr. om året og vil ophæve kommunernes monopol på husholdningernes affald.', long: 'Analysen fra maj 2026 af Line Andersen Wendland og Otto Brøns-Petersen bygger på nettoprisindekset 2021-2026 og tidligere effektiviseringsanalyser. Potentialet inklusive indsamling af husholdningsaffald er 11,2-12,7 mia. kr. om året, eller 3.900-4.400 kr. pr. husholdning. På affaldsområdet kunne husstandene spare omkring 1.000 kr. om året, hvis kommunerne blev lige så effektive som de bedste sammenlignelige, og gebyret for enfamilieboliger steg fra 2.697 kr. til 4.050 kr. fra 2019 til 2025. CEPOS anbefaler at ophæve monopolet og hvile-i-sig-selv-princippet, selskabsgøre affaldsopgaverne og indføre reelle prislofter og udbudspligt.' },
      { id: 'NY276', title: 'Næste skridt for CCS i Danmark', org: 'CONCITO', year: 2026, type: 'Analyse', temaer: ['Klima', 'Afsætning og behandling'], img: 'img/65c41af9b29512308e1aa7abfe3c1a9a.jpg', url: 'https://concito.dk/files/media/document/N%C3%A6ste%20skridt%20for%20CCS%20i%20Danmark.pdf', res: 'CONCITO vurderer, at CCS har leveret mindre end ventet, og at udbuddene viser omkostninger på omkring det dobbelte af statens skøn. Analysen foreslår syv modeller.', long: 'Analysen fra juni 2026 tager udgangspunkt i tre CCS-udbud, som forventes at give godt 1,8 mio. ton CO2 om året fra 2030. I det seneste udbud trak 8 af 10 prækvalificerede selskaber sig, og kun Aalborg Portland tog imod støtte. CONCITO foreslår bl.a., at staten tager mere risiko i transport og lagring, og at det undersøges at indføre et de facto krav om CCS på affaldsforbrændingsanlæg, evt. kombineret med at fjerne afgifterne på affaldsvarme. Et fast tilskud til negative udledninger kan støtte fangst af den biogene CO2 fra affaldsforbrænding, som udgør 50-60 %. På lang sigt skal fangst direkte fra luften udvikles i stor skala.' },
      { id: 'NY277', title: 'Effekten af CCS-udbuddet er behæftet med stor usikkerhed', org: 'CONCITO', year: 2025, type: 'Analyse', temaer: ['Klima', 'Afsætning og behandling'], img: 'img/6c97af0b11547d4a032bb606cb492da7.jpg', url: 'https://concito.dk/files/media/document/Effekten%20af%20CCS-udbuddet%20er%20beh%C3%A6ftet%20med%20stor%20usikkerhed.pdf', res: 'CONCITO vurderer, at statens CCS-udbud på 29 mia. kr. kan give mindre CO2-fangst end de 2,3 mio. tons, regeringen regner med. Seks af de ti bydere er affaldsforbrændingsanlæg.', long: 'Tænketanken CONCITO gennemgår de ti prækvalificerede bydere i CCS-udbuddet, som ventes afgjort i april 2026. Seks er affaldsforbrændingsanlæg, bl.a. ARC og Vestforbrænding, og Kredsløb byder med et halm- og affaldsfyret værk. Ifølge Energistyrelsens skøn er cement billigst og affaldsforbrænding næstbilligst. Med de tal leverer udbuddet godt 2,2 mio. tons om året, heraf godt 0,8 mio. tons fra to-tre affaldsanlæg. Er CCS 20 % dyrere, falder det til knap 1,8 mio. tons og ét affaldsanlæg, og CONCITO anser højere priser for mest sandsynligt. Tænketanken anbefaler at holde fast i tidsplanen og sikre reduktioner i andre sektorer.' },
      { id: 'NY278', title: 'Kemisk genanvendelse af plastik', org: 'Plastic Change', year: 2024, type: 'Analyse', temaer: ['Afsætning og behandling', 'Reel genanvendelse', 'Klima'], img: 'img/22d5642cb112cdb8093e32aacc833d15.jpg', url: 'https://plasticchange.dk/wp-content/uploads/2024/11/Vidensartikel_Kemisk-genanvendelse_9-11-2024_FINAL.pdf', res: 'Plastic Change gennemgår studier af kemisk genanvendelse af plast. Teknologierne giver meget lidt ny plast og meget CO2 og bør rangere under mekanisk genanvendelse.', long: 'Claudia Sick fra Plastic Change skrev vidensartiklen i 2024 med afsæt i studier fra bl.a. Zero Waste Europe, EU JRC, Öko-Institut og IPEN. Ved pyrolyse og forgasning tabes over halvdelen af kulstoffet, og i bedste fald bliver kun 2 % af plastaffaldet til ny plast via pyrolyse. Pyrolyse udleder tre ton CO2 pr. ton genanvendt plast, og kemisk genanvendelse giver 800 kg farligt affald pr. ton plastaffald. Et planlagt pyrolyseanlæg ved ReSource i Esbjerg vil ifølge artiklen konkurrere med mekanisk genanvendelse om blød LDPE. Plastic Change prioriterer forebyggelse og udfasning af skadelig kemi og advarer mod fri allokering af genanvendt indhold.' },
      { id: 'NY279', title: 'PVC – den mest problematiske plast af alle', org: 'Plastic Change', year: 2024, type: 'Notat', temaer: ['Reel genanvendelse', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/56873910696ec2f5e03746db77cfe0ce.jpg', url: 'https://plasticchange.dk/wp-content/uploads/2025/01/Vidensartikel_PVC_FINAL_4-11-2024.pdf', res: 'Plastic Change gennemgår PVC fra produktion til affald og vurderer, at kun 1,6-7,8 % af den PVC, der bruges i Danmark, reelt genanvendes. Organisationen anbefaler at udfase PVC.', long: 'Vidensartiklen er skrevet af Claudia Sick fra Plastic Change i november 2024 og bygger bl.a. på Miljøstyrelsens kortlægninger af PVC og en rapport fra EU-Kommissionen. Forsyningen af PVC i Danmark steg fra 64.000 ton i 2017 til 73.000 ton i 2020, og blød PVC udgør 39 %. Stort set al blød PVC ender på deponi, mens ca. 5.000 ton hård PVC blev indsamlet i 2017, halvdelen via WUPPI-ordningen. Med 2017-tal beregnes den reelle genanvendelse til 1,6-7,8 %, langt fra de 35 %, industrien fremhæver ud fra byggeplast. Når PVC brændes, dannes bl.a. saltsyre og dioxiner. Der findes alternativer til stort set alle PVC-produkter.' },
      { id: 'NY280', title: 'Sammen mod tøjspild: Vejen til et tøjforbrug med mindre miljø- og klimaaftryk', org: 'Forbrugerrådet Tænk', year: 2023, type: 'Analyse', temaer: ['Tekstil', 'Direkte genbrug', 'Kommunikation'], img: 'img/7d74c9c8ebfed4d70370824dec99c369.jpg', url: 'https://taenk.dk/system/files/2023-02/T%C3%B8jspild%20analyserapport.pdf', res: 'Forbrugerrådet Tænk har undersøgt, hvorfor danskerne har svært ved at mindske tøjspild. Mange vil gerne handle bæredygtigt, men mangel på tid og tvivl om genbrug står i vejen.', long: 'NORION Consult har lavet analysen for Forbrugerrådet Tænk med støtte fra Salling Fondene. Den bygger på et litteraturstudie, en YouGov-undersøgelse med 2.004 danskere på 25-50 år og hjemmebesøg hos 15 hyppige tøjkøbere. I undersøgelsen er 82 % bekymrede for klimaet, og 87 % siger, at de tager hensyn til miljø og klima, men kun 9 % nævner ansvarlig produktion som udslagsgivende ved seneste tøjkøb. Informanterne er i tvivl om, hvornår tøj er godt nok til genbrug, og hvad der sker med tøj i containere, og det kan give problemer for den nye indsamling af tekstilaffald. Rapporten slutter med syv designprincipper for kampagner om tøj.' },
      { id: 'NY281', title: 'IDAs anbefalinger til en national indsats til fremme af højkvalitetsgenanvendelse', org: 'Ingeniørforeningen IDA', year: 2021, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Reel genanvendelse', 'Udvidet producentansvar'], img: 'img/eb10058f8b3c900ef87b6e628e1b10dd.jpg', url: 'https://ida.dk/media/9661/idas-strategi-for-cirkulaer-oekonomi-2021-14-enkelt-sidet-til-net.pdf', res: 'IDAs ekspertgruppe foreslår en national strategi for højkvalitetsgenanvendelse med et nyt genanvendelseshierarki, så genanvendelse måles på kvalitet og ikke kun på mængde.', long: 'En ekspertgruppe i Ingeniørforeningen IDA giver sit bud på en dansk strategi for genanvendelse med tekstiler og elektronik som eksempler. Forslaget deler genanvendelse op i fire niveauer fra A, hvor materialet bevarer næsten alle egenskaber, til D, hvor produktet ikke kan cirkuleres. Afgifterne bør følge hierarkiet, og andelen af indsamlet affald, der højkvalitetsgenanvendes, bør gå fra 20 % i 2023 til 80 % i 2025. IDA vil genoprette et genanvendelsesråd med 100 mio. kr. over fem år og kræve mindst 55 % genanvendt materiale i produkter, der markedsføres som genanvendte. Desuden foreslås digitale produktpas og producentansvar for tekstiler.' },
      { id: 'NY282', title: 'Klima- og økonomiske konsekvenser ved madspild 2025', org: 'ONE\\THIRD', year: 2025, type: 'Analyse', temaer: ['Klima', 'Data, statistikker og nøgletal'], img: 'img/640640243de77308527405b131568daf.jpg', url: 'https://onethird.dk/wp-content/uploads/2025/08/SPISBAR-2025_KLIMA-OG-OKONOMISKE-KONSEKVENSER-VED-MADSPILD-2025.pdf', res: 'Tænketanken ONE\\THIRD anslår madspildet i Danmark til ca. 880.000 ton om året med en klimabelastning på 2,0 mio. ton CO2e og et værditab på godt 11 mia. kr.', long: 'COWI har for ONE\\THIRD opdateret beregningerne fra 2021 med Miljøstyrelsens nyeste kortlægninger med data fra 2021-2023 og nye klima- og prisdata fra CONCITO og Danmarks Statistik. Omkring halvdelen af madspildet sker i forarbejdning og fremstilling og 235.000 ton, ca. 27 %, i husholdningerne. Klimabelastningen svarer til 3,4 % af Danmarks udledning i 2023. Siden 2021 er mængden steget 8 % og klimabelastningen 13 %, det sidste især på grund af kød i forarbejdning og fremstilling. Husholdningerne står for 55 % af værditabet, ca. 2.150 kr. pr. husstand om året. Affaldsbehandlingen af madspild efter forbrugerleddet er ikke regnet med.' },
      { id: 'NY283', title: 'Madspildsaspekter i skolemadsordninger', org: 'ONE\\THIRD', year: 2025, type: 'Rapport', temaer: ['Kommunikation', 'Analyser og undersøgelser'], img: 'img/c026dc7fe237fc11ef8312a8820b5450.jpg', url: 'https://onethird.dk/wp-content/uploads/2025/05/Madspild-og-skolemad_OT-2025_bro.pdf', res: 'ONE\\THIRD samler viden om madspild i skolemadsordninger og giver skolerne konkrete råd om anretning, portioner, spisetid, måling af spild, feedback til eleverne og indkøb.', long: 'Bureauet bro har skrevet rapporten for tænketanken ONE\\THIRD som vidensgrundlag til en mulig national skolemadsordning. Den bygger på danske og udenlandske studier, interview med tre eksperter og med Madspildskrigerne, der har udviklet et system til at veje madspild. Anbefalingerne dækker fem områder fra anretning og servering til indkøb. Eleverne bør have mindst 20 minutters reel spisetid, og portionerne bør passe til alderen. Lærerne bør spise med, og spildet bør vejes dagligt og opdeles efter, hvor det opstår. I et pilotprojekt i 18 københavnske daginstitutioner faldt madspildet med 23-37 %.' },
      { id: 'NY284', title: 'Forslag til koncept for charteret: Offentlige Køkkener mod Madspild', org: 'ONE\\THIRD', year: 2022, type: 'Notat', temaer: ['Cirkulær økonomi'], img: 'img/5bb5b6cc582e25125dff3075bc632aca.jpg', url: 'https://onethird.dk/wp-content/uploads/2022/12/Charter-om-madspild-for-det-offentlige.pdf', res: 'Notatet foreslår et frivilligt charter, hvor kommuner, regioner og statslige institutioner forpligter sig til at halvere madspildet inden 2030 i mindst 80 % af deres køkkener.', long: 'Konceptet er udviklet i 2022 af en projektgruppe med 11 aktører, som tænketanken ONE\\THIRD nedsatte, med hjælp fra konsulenter fra inVirke. Offentlige køkkener serverer ca. 800.000 måltider om dagen. Reduktionen på 50 % måles i forhold til en baseline, og madspildet opgøres i kilo pr. bruger og indrapporteres årligt, men målemetoden er fri. Gruppen anbefaler at placere charteret under Fødevareministeriet og ONE\\THIRD og at lancere det med mindst 15 underskrivere. Lanceringsevent, hjemmeside og PR anslås til mindst 200.000, 150.000 og 100.000 kr., og driften kræver mindst et halvt årsværk til 350.000 kr. om året.' },
      { id: 'NY285', title: 'Measuring up: First edition of ZWE\'s municipal manual for circular textile systems', org: 'Zero Waste Europe', year: 2025, type: 'Vejledning', temaer: ['Tekstil', 'Hente- og bringeordninger', 'Udbud og kravspecifikationer'], img: 'img/23374ec4b01691bdcbe82933479d3e72.jpg', url: 'https://zerowasteeurope.eu/wp-content/uploads/2025/11/zwe_Nov25_measuring-up_full-report.pdf', res: 'Zero Waste Europe giver europæiske kommuner en vejledning i at indsamle tekstiler, så mere kan genbruges, og anbefaler indsamling ved husstanden frem for kun containere på gaden.', long: 'Første udgave af Zero Waste Europes kommunemanual for tekstiler gennemgår indsamling ved husstanden, containere på gaden, mobile indsamlinger og indsamling til genanvendelse. Baggrunden er EU\'s krav om særskilt indsamling fra 2025 og producentansvar fra marts 2028. I et pilotforsøg i Põlva i Estland blev der hentet 3,6 ton hos 174 husstande, 45 % kunne bruges igen, og prisen var 0,82 euro pr. kg mod 1,00-1,20 euro i små europæiske kommuner. Kommunerne opfordres til at bruge udbud til at stille krav om datadeling og social inklusion og til at overveje adskilte strømme til genbrug og genanvendelse.' },
      { id: 'NY286', title: 'Facilitating the Adoption of Takeaway Reuse Systems', org: 'Zero Waste Europe', year: 2024, type: 'Analyse', temaer: ['Direkte genbrug', 'Økonomi', 'Cirkulær økonomi'], img: 'img/ae8f42fecf402c4e8e8bbdde71f339e1.jpg', url: 'https://zerowasteeurope.eu/wp-content/uploads/2024/09/ZWE_Sep24_Report_Facilitating-the-Adoption-of-Takeaway-Reuse-Systems.pdf', res: 'Eunomia har for Zero Waste Europe regnet på genbrugsemballage til takeaway i Aarhus og Berlin. Uden afgifter koster genbrug sælgerne mere, men samfundet vinder samlet set.', long: 'Analysen fra september 2024 sammenligner omkostninger ved engangs- og genbrugsemballage for seks emballagetyper med udgangspunkt i Aarhus Kommunes og TOMRAs pilotordning. Modellen viser et scenarie for 2030 med 85 % markedsandel og 98 % returrate. Kopper, skåle og sushibakker er tæt på at løbe rundt, mens pizzabakker koster markant mere. Engangsemballagens omkostninger til henkastet affald og klima overstiger sælgernes meromkostninger, men resultatet er følsomt over for antagelserne. Rapporten anbefaler afgifter eller højere producentansvarsgebyrer på engangsemballage og krav til returrater. Bindende mål og senere forbud kan blive nødvendige.' },
      { id: 'NY287', title: 'Høringsnotat: afsætning af genbrugsgenstande og ny affaldsaktørbekendtgørelse', org: 'Energistyrelsen', year: 2022, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Økonomi'], img: 'img/d662884786b51126df5ab0a537f2db60.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/6ead805f-b81e-4cb8-bbf4-e9031bc44f67/H%C3%B8ringsnotat.pdf', res: 'Høringsnotatet samler svarene på forslaget til ny affaldsaktørbekendtgørelse om markedspriser for kommunal indsamling af erhvervsaffald. Reglerne om genbrugsgenstande blev udskudt.', long: 'Notatet fra 16. december 2022 opsummerer høringen i oktober 2022, der gav 18 høringssvar. På grund af den parlamentariske situation blev bekendtgørelsen om genbrugsgenstande fra genbrugsområder udskudt og træder ikke i kraft 1. januar 2023 som planlagt. Notatet dækker derfor kun ændringerne efter L 898 om markedspriser og særskilte regnskaber for kommunal indsamling og behandling af visse typer erhvervsaffald. Ministeriet tilføjer, at kravene kun gælder, hvis kommunen tilbyder ydelserne, og at overskud ikke må finansiere gebyrordninger. Regnskaberne skal fremover sendes til Forsyningstilsynet senest 15. juli.' },
      { id: 'NY288', title: 'Høringsnotat vedr. udkast til ændringsbekendtgørelse til affaldsaktørbekendtgørelsen', org: 'Energistyrelsen', year: 2023, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Genbrugspladser'], img: 'img/0c22708cffea0c26ef6acd4b9bd7eb7d.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/1741e7be-e669-420a-abc9-894de48e8db0/H%C3%B8ringsnotat.pdf', res: 'Energistyrelsen gennemgår ni høringssvar om en midlertidig undtagelse, så kommuner frem til 1. juli 2024 kan kompostere haveaffald, der er afleveret på genbrugspladser.', long: 'Udkastet til ændring af affaldsaktørbekendtgørelsen var i høring fra 12. april til 10. maj 2023 og fik 9 svar, bl.a. fra KL, Dansk Affaldsforening, Forsyningstilsynet og Reno Djurs. Forslaget undtager kommunernes kompostering af haveaffald afleveret på genbrugspladser fra forbuddet mod kommunal behandling og fra udbudspligten frem til 1. juli 2024. ARI og KL støtter, mens Dansk Erhverv og DTL/Danaffald er imod. Ministeriet fastholder, at undtagelsen kun gælder kompostering på selve genbrugspladsen og ikke haveaffald fra henteordninger. Høringen fører kun til én ændring, en frist til 30. september 2024 for at anmelde selskabsgørelse.' },
      { id: 'NY289', title: 'Høringsnotat vedr. ny organisering af affaldsforbrændingssektoren', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2023, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Udbud og kravspecifikationer'], img: 'img/efb71225a0fa76fef879a58558b94042.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/4985e2a2-6a3a-409a-aaaa-8fc1dd3d2cbe/H%C3%B8ringsnotat.pdf', res: 'Klima-, Energi- og Forsyningsministeriet gennemgår høringssvarene til lovforslaget om at selskabsgøre forbrændingsanlæggene og sende det forbrændingsegnede affald i udbud.', long: 'Høringsnotatet fra 19. april 2023 gennemgår svar fra 57 høringsparter, bl.a. KL, mange kommuner og Forsyningstilsynet. Lovforslaget lægger op til, at anlæggene skal være selskabsgjort senest 1. januar 2025, og at kommunerne skal udbyde det forbrændingsegnede affald. Mange kommuner frygter tab og højere takster og kalder puljen på 200 mio. kr. til strandede omkostninger for lille. Ministeriet svarer, at puljen dækker op til 70 % af et tab og dermed knap 300 mio. kr. i strandede omkostninger. Efter høringen foreslås det, at fristen for selskabsgørelse kan forlænges i særlige tilfælde, og at Forsyningstilsynet kan give kommunerne påbud.' },
      { id: 'NY290', title: 'Ny organisering af affaldsforbrændingssektoren og konkurrenceudsættelse af forbrændingsegnet affald', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2023, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Udbud og kravspecifikationer'], img: 'img/0344c3ad805ef744deadb55c3f9b433f.jpg', url: 'https://www.folketingstidende.dk/ripdf/samling/20222/lovforslag/l115/20222_l115_som_fremsat.pdf', res: 'Lovforslag fra april 2023 om at gøre de kommunale affaldsforbrændingsanlæg til selskaber og pålægge kommunerne at sende behandlingen af forbrændingsegnet affald i udbud.', long: 'Klima-, energi- og forsyningsministeren fremsatte L 115 den 26. april 2023 som led i klimaplanen for affaldssektoren fra 2020. Forslaget lægger op til, at kommunalt ejede forbrændingsanlæg skal drives i aktie- eller anpartsselskaber senest 1. januar 2025, og at kommunerne skal udbyde behandlingen af forbrændingsegnet affald med kontrakt senest 1. juli 2025. Efter forslaget skal Forsyningstilsynet føre tilsyn og kan påbyde en kommune at ophæve en kontrakt med eget anlæg uden saglig begrundelse. Konkurrencen skal få kapaciteten og importen af affald ned. En pulje på 200 mio. kr. skal dække op til 70 % af kommunernes strandede omkostninger.' },
      { id: 'NY291', title: 'Høringsnotat vedr. udkast til ny hovedbekendtgørelse af affaldsaktørbekendtgørelsen', org: 'Energistyrelsen', year: 2024, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Genbrugspladser', 'Afsætning og behandling'], img: 'img/7acfc82c6c0475aa054f65398a86132d.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/e416e1a3-6c4a-40d8-9b2d-c87e9b82dfd4/H%C3%B8ringsnotat.pdf', res: 'Energistyrelsen gennemgår høringssvar om at gøre kommunernes adgang til at kompostere haveaffald på genbrugspladser permanent. Svarene fører ikke til ændringer i udkastet.', long: 'Udkastet var i høring fra 15. april til 6. maj 2024 og foreslår i § 35 at gøre en midlertidig undtagelse permanent. Der kom 9 svar. Kredsløb, KL og Brancheforeningen Cirkulær støtter forslaget, mens DTL/Danaffald er imod, og ARI mener ikke, at det er i tråd med målet om en stærk privat genanvendelsessektor. Ministeriet afviser Cirkulærs ønske om også at tage haveaffald fra henteordninger med. Undtagelsen skal kun dække kompostering direkte på genbrugspladsen af haveaffald, som husholdninger og erhverv har afleveret dér. Andre kommunale anlæg kan kun fortsætte, hvis de er anmeldt til overgangsordningen, der løber til 1. juli 2027.' },
      { id: 'NY292', title: 'Høringsnotat vedr. udkast til bekendtgørelse om affaldsregulativer, -gebyrer og -aktører m.v.', org: 'Energistyrelsen', year: 2024, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Affaldsplaner/regulativer og strategi'], img: 'img/df455de0a051dc3f87f92bdc12f57be5.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/0770ddd2-8987-4a90-9d27-9ed6c496a758/H%C3%B8ringsnotat.pdf', res: 'Energistyrelsens høringsnotat gennemgår svar fra ti parter på ændringer af affaldsaktørbekendtgørelsen, bl.a. den ophævede anvisningsret for forbrændingsegnet erhvervsaffald.', long: 'Udkastet var i høring fra 4. til 22. november 2024, og notatet er fra 25. november. Af tolv svar havde ti bemærkninger, bl.a. fra KL, Cirkulær, ARI, Forsyningstilsynet og Sønderborg Kommune. Flere efterlyste en gennemskrivning af bekendtgørelsen og standardregulativet for erhvervsaffald, når anvisningsretten ophører 1. januar 2025, og KL påpegede, at kommunerne ikke kan nå nye erhvervsregulativer i tide. Ministeriet når ikke gennemskrivningen nu, men fjerner den uklare § 28, stk. 2, og indsætter en manglende strafbestemmelse. Kommunerne må forberede affald fra genbrugspladser til genbrug, dog ikke affald under producentansvar som elektronik.' },
      { id: 'NY293', title: 'L 38: Forslag til lov om ændring af lov om miljøbeskyttelse (Styrket affaldstilsyn m.v.)', org: 'Miljø- og Ligestillingsministeriet', year: 2024, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Genbrugspladser'], img: 'img/47a4515150ae46454f51d730857036ed.jpg', url: 'https://www.folketingstidende.dk/ripdf/samling/20241/lovforslag/l38/20241_l38_som_fremsat.pdf', res: 'Lovforslag om hjemmel til at kræve, at forbrændingsanlæg kontrollerer og afviser affaldslæs med genanvendeligt affald, og om at ophæve bestemmelserne om genbrugsområder.', long: 'Miljøministeren fremsatte L 38 den 3. oktober 2024 og foreslår ikrafttræden 1. januar 2025. Forslaget vil give ministeren hjemmel til at kræve, at affaldsbehandlingsanlæg kontrollerer modtaget affald, afviser læs med genanvendeligt affald eller usolgte forbrugerprodukter omfattet af ecodesignforordningen og indberetter til tilsynet. Ved stikprøvekontrol af 5 % skal forbrændingsanlæggene kontrollere ca. 45.000 vognlæs om året, hvilket anslås at koste erhvervet 4,6 mio. kr. årligt i 2025-2026 og 3,4 mio. kr. derefter. Hjemlen til at kræve og gebyrfinansiere genbrugsområder på genbrugspladser foreslås ophævet til fordel for frivillig indsats.' },
      { id: 'NY294', title: 'Høringsnotat: Lovforslag om udvidet producentansvar for emballage og engangsplastprodukter', org: 'Miljø- og Ligestillingsministeriet', year: 2024, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/27dd420626bf7c7099c1bef1b502b00b.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/f4b853f9-9cd5-4d73-b85c-4d4a90515460/H%C3%B8ringsnotat.pdf', res: 'Ministeriets svar på 24 parters høringssvar til lovforslaget om producentansvar for emballage. Efter forslaget indsamler kommunerne fortsat og overdrager til kollektive ordninger.', long: 'Udkastet var i høring fra 1. juli til 22. august 2024, og ministeriet fik 26 svar, heraf 24 med bemærkninger fra bl.a. KL, ARC, Brancheforeningen Cirkulær og Forsyningstilsynet. Siden første høring i 2023 er forslaget justeret, så ikkeemballageaffald kan overdrages sammen med emballagen, og kommunen kan anmode om betaling på vegne af virksomheder. Producenterne skal efter forslaget betale fra 1. oktober 2025, trods ønsker om 1. januar 2026. Ministeriet venter at fastsætte et serviceniveau senest i 2027, og indtil da skal kommunerne årligt rapportere det. Producentgebyrer skal bygge på kommunens egne faktiske omkostninger.' },
      { id: 'NY295', title: 'Indhold af lovforslag om udvidet producentansvar for emballage mv.', org: 'Miljøministeriet', year: 2024, type: 'Notat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser'], img: 'img/e096dc453c60489a11d62019fbfc4744.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/f4b853f9-9cd5-4d73-b85c-4d4a90515460/Notat%20om%20lovforslagets%20indhold.pdf', res: 'Miljøministeriets notat fra juli 2024 opsummerer lovforslaget om udvidet producentansvar for emballage, hvor producenterne foreslås at betale for affaldet fra 1. oktober 2025.', long: 'Lovforslaget skal give hjemmel til at gennemføre den politiske aftale fra august 2022 ved bekendtgørelse. Efter forslaget kan kommunerne pålægges at indsamle emballageaffald i de kendte fraktioner uden at skelne mellem emballage og ikke-emballage og at overdrage det til kollektive ordninger. Producenterne foreslås at betale producentgebyrer, som kommunerne fastsætter ud fra de faktiske omkostninger, og Forsyningstilsynet skal overvåge gebyrerne. Reglerne foreslås at få virkning ti måneder efter direktivfristen, hvilket kan udløse en åbningsskrivelse fra EU. Et fast serviceniveau for indsamlingen ventes først i 2027.' },
      { id: 'NY296', title: 'KL\'s høringssvar til lovforslag om udvidet producentansvar for emballage og batteriforordning', org: 'KL', year: 2024, type: 'Notat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/bdeb7e09295d912e9358f1913406c6fb.jpg', url: 'https://www.kl.dk/media/03yfud2g/kls-hoeringssvar-om-udvidet-producentansvar-og-batteriforordningen.pdf', res: 'I høringssvaret fra august 2024 er KL mere positiv over for udkastet om producentansvar for emballage end sidste år, men vil have producenterne til at betale fra 1. januar 2025.', long: 'KL kommenterer her lovudkastet om udvidet producentansvar for emballage og om batteriforordningen. KL støtter tvungent medlemskab af kollektive ordninger og at vente med et fast serviceniveau. Kravet om en årlig rapport om omkostningseffektivitet kaldes en unødig ekstra byrde, og KL foreslår i stedet årlige møder med den kollektive ordning. Producenterne bør også betale for emballage i farligt affald og i restaffaldet, og KL ønsker tildelingsperioder på mindst 36 måneder. Ministeriets skøn på 16,9 mio. kr. til kommunernes batteriindsamling i 2026 er ifølge KL for lavt, da Niras anslog ca. 26 mio. kr. i 2022.' },
      { id: 'NY297', title: 'Bilag 1: Konkrete bemærkninger til bekendtgørelsen', org: 'Brancheforeningen Cirkulær', year: 2024, type: 'Notat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/d7f7ef764826d480cf9d218c8891261f.jpg', url: 'https://cirkulaer.dk/files/media/document/Hoeringssvar-emballagebekendtgoerelsen-okt2024.pdf', res: 'Cirkulær gennemgår udkastet til emballagebekendtgørelsen paragraf for paragraf og vil bl.a. have længere tildelingsperioder, og at producenterne dækker flere kommunale udgifter.', long: 'Bilaget hører til foreningens høringssvar af 1. november 2024. Cirkulær påpeger, at loven bag bekendtgørelsen endnu ikke er vedtaget, og opfordrer til at se på reglerne igen i 2025. Producenter bør tildeles kommuner i 3 år frem for 2, da de 1-årige perioder for elektronikaffald giver problemer. Oplysninger om ordninger bør hentes i regulativdatabasen NSTAR i stedet for at blive indberettet igen. Alt affald, der overdrages til producenterne, også ikke-emballager, bør genanvendes uden downcycling. Producenterne bør også betale for deres emballage, der havner i kommunale ordninger, og for ekstra omkostninger ved deres valg af behandlingsanlæg.' },
      { id: 'NY298', title: 'Høringsnotat: Bekendtgørelse om visse krav til emballager, udvidet producentansvar for emballage', org: 'Miljø- og Ligestillingsministeriet', year: 2024, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/e54b21c1f59f50ea1dc6feb06a361fe8.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/68c942ff-b13c-496f-9bda-6c91cbb8e1c8/H%C3%B8ringsnotat.pdf', res: 'Ministeriets svar på 48 høringssvar til bekendtgørelsen om producentansvar for emballage. Producenterne betaler fra 1. oktober 2025, og der indføres ikke et clearing house.', long: 'Høringsnotatet fra november 2024 samler bemærkningerne til udkastet til bekendtgørelsen om udvidet producentansvar for emballage, bl.a. fra KL, ARC, Københavns Kommune, Kredsløb, Reno Djurs og Renosyd. Ministeriet fastholder, at producenternes betaling starter 1. oktober 2025, og at tildelingsperioden er 2 år, selv om KL og flere kommuner ønskede længere perioder. Emballage fra genbrugspladser overdrages, når der sorteres som i henteordningerne, mens fejlsorteret emballage i restaffald fortsat betales af borgerne. Producentgebyrer for flerdelte spande skal opgøres pr. fraktion, og et serviceniveau ventes fastsat senest i 2027.' },
      { id: 'NY299', title: 'Høringsnotat: Bekendtgørelse om udvidet producentansvar for visse engangsplastprodukter', org: 'Miljøstyrelsen', year: 2024, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/1b04de2e58d6a52dd6e70cc234a0c572.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/42343463-d99a-422a-a92c-d6667a8ac5dd/H%C3%B8ringsnotat.pdf', res: 'Høringsnotat om oprydningsbekendtgørelsen, som skal pålægge producenter af visse engangsplastprodukter at betale gebyr til den offentlige oprydning og indsamling af affaldet.', long: 'Notatet fra 13. juni 2024 gennemgår de 20 høringssvar til udkastet, der var i høring 24. april til 27. maj 2024. Udkastet lader producenterne betale et kvartalsvist gebyr pr. produktkategori til kommunal og statslig oprydning, indsamling fra offentlige indsamlingssystemer, oplysning og data. Tobaksvirksomheder og Horesta kritiserede omkostningsanalysen, og JTI Danmark peger på en stigning fra 56 til 150 mio. kr. Miljøstyrelsen fastholder metoden og den kvartalsvise betaling og lover vejledning, bl.a. mod free-riders, som KL efterlyste. Ønsket om kun at omfatte drikkevarebeholdere op til 0,6 liter afvises, da direktivet gælder op til 3 liter.' },
      { id: 'NY300', title: 'Forslag til lov om ændring af lov om miljøbeskyttelse (udvidet producentansvar for emballage m.v.)', org: 'Miljø- og Ligestillingsministeriet', year: 2024, type: 'Lovforslag', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/da7445be165975b269f8df6d4cf36dbc.jpg', url: 'https://www.folketingstidende.dk/ripdf/samling/20241/lovforslag/l84/20241_l84_som_fremsat.pdf', res: 'Lovforslag L 84 fra 2024 lægger op til, at producenter betaler for emballageaffald fra 1. oktober 2025, mens kommunerne indsamler og overdrager det til kollektive ordninger.', long: 'Miljøministeren fremsatte forslaget 7. november 2024 for at udmønte den politiske aftale fra august 2022 og tilpasse loven til EU\'s batteriforordning. Det giver hjemmel til regler om tvungent medlemskab af kollektive ordninger og en tildelingsordning for kommunalt indsamlet emballageaffald, hvor kommunerne opkræver producentgebyrer. Ministeriet skønner, at affaldsgebyret falder med ca. 500-600 kr. ekskl. moms pr. husstand om året, og at erhvervslivet får ca. 1,5 mia. kr. i nye udgifter i 2025. Kommunernes pligt til at indsamle bærbare batterier foreslås ophævet, og hjemlen til oprydningsgebyrer for otte engangsplastprodukter præciseres.' },
      { id: 'NY301', title: 'Høringsnotat vedr. bekendtgørelse om Affaldsregistret', org: 'Energistyrelsen', year: 2025, type: 'Høringsnotat', temaer: ['Lovgivning og afgørelser', 'Erhverv'], img: 'img/06e04884aefb9ccb732cb043016c7826.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/7424b6ae-435c-45f1-8d86-15cb3e2cb179/H%C3%B8ringsnotat.pdf', res: 'Energistyrelsens høringsnotat om de nye regler for Affaldsregistret. De 12 høringssvar gav kun mindre præciseringer, bl.a. at miljøgodkendelsen skal foreligge før tilmelding.', long: 'Notatet fra 1. september 2025 samler svarene på udkastene til bekendtgørelser om Affaldsregistret og om betaling for registrering, der var i høring i april og maj 2025. KL og ARI advarer mod, at registreringen bliver en formalitet, ARC vil fastholde kravet om dokumentation for miljøgodkendelse, Københavns Kommune ønsker fortsat godkendelse af indsamlere, og flere vil have affaldsfraktioner med i registret. Klima-, Energi- og Forsyningsministeriet fastholder, at registret ikke skal rumme fraktioner, og henviser til virksomhedernes hjemmesider og Digital MiljøAdministration. Energistyrelsen vil lave en ny tilsynsstrategi med stikprøvekontrol.' },
      { id: 'NY302', title: 'Notat om høring over udkast til vejledning om fastsættelse af markedspriser', org: 'Forsyningstilsynet', year: 2025, type: 'Høringsnotat', temaer: ['Erhverv', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/e21e510649bba1337249ed0407817104.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/cdfcf2d4-b802-47f4-a5a8-98c1fd805455/H%C3%B8ringsnotat.pdf', res: 'Forsyningstilsynets høringsnotat om vejledningen om markedspriser for kommunal indsamling af erhvervsaffald gennemgår syv høringssvar og de få ændringer, de har ført til.', long: 'Forsyningstilsynet fik i høringen om vejledningen fra 19. maj til 13. juni 2025 svar fra bl.a. KL, Brancheforeningen Cirkulær, Københavns Kommune og ITD. Det tydeliggøres nu, at kommuner som hovedregel ikke må indsamle erhvervsaffald, og at ordningerne er frivillige. Metoden med markedsundersøgelse bevares, da den står i lovforslaget, og ved omkostningsmetoden skal kommunen bruge relevante omkostninger, ikke nødvendigvis affaldsgebyret. Overskudstillægget på 5-15 % genovervejes ved evalueringen i efteråret 2025. Moms henvises til Skattestyrelsen, og Energistyrelsen er bedt om at fortolke reglerne for overskud i kommunalt ejede selskaber.' },
      { id: 'NY303', title: 'Høringsnotat: Bekendtgørelse om visse krav til emballager, udvidet producentansvar for emballage', org: 'Miljø- og Ligestillingsministeriet', year: 2025, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/7bc8491ec588b53aa10ec028775814c9.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/beba8fd0-b9f3-409d-b12c-c299ba166450/H%C3%B8ringsnotat.pdf', res: 'Høringsnotat om ændret emballagebekendtgørelse, der sænker producenternes gebyr til kommunerne og giver alle kommuner samme beregningsmetode. 23 parter afgav høringssvar.', long: 'Miljø- og Ligestillingsministeriet gennemgår 23 høringssvar til udkastet fra 13. september 2025 og 12 svar fra en tidligere høring om sikkerhedsstillelse. Ændringen gennemfører to af regeringens tiltag fra 11. september 2025, så producenterne foreløbig betaler 62,5 % af det gebyr, kommunerne har fastsat, svarende til 1,0 mia. kr., og alle kommuner skal bruge samme beregningsmetode. Efter høringen flyttes fristen for kommunernes gebyr til 15. oktober, og ministeren skal inden 1. oktober 2026 fastsætte et basisserviceniveau. Vælger en kommune højere service, betales det over affaldsgebyret. En lånepulje skal hjælpe kommuner med likviditet.' },
      { id: 'NY304', title: 'Høringsnotat: Bekendtgørelse om supplerende bestemmelser til forordning om batterier', org: 'Miljøstyrelsen', year: 2025, type: 'Høringsnotat', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Genbrugspladser'], img: 'img/f89df7881bd2c1648bad665cde208622.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/91d914c8-916d-48ce-9223-5129cb93de4e/H%C3%B8ringsnotat.pdf', res: 'Miljøstyrelsens høringsnotat om den nye batteribekendtgørelse samler 12 høringssvar og styrelsens svar, blandt andet om kontrakter mellem kommuner og producenterne.', long: 'Udkastet fra foråret 2025 udfylder EU\'s batteriforordning fra 2023 og foreslår blandt andet et producentregister, tvungent medlemskab af en producentansvarsorganisation for bærbare batterier og batterier til lette transportmidler, garanti, gradueret bidrag og krav om kontrakt om indsamling. KL frygter flere batterier i restaffaldet, og Forbrugerrådet Tænk frygter, at kommunale indsamlingssteder lukker. Ifølge Miljøstyrelsens svar giver forordningen ikke plads til at kompensere kommuner uden aftale eller fastholde den kommunale ordning. Kommuner uden for et indsamlingsnetværk må ikke indsamle batterierne og kan afvise dem på genbrugspladsen.' },
      { id: 'NY305', title: 'Maksimal størrelse af gebyr og kommunalbestyrelsens periodisering af omkostninger', org: 'Miljø- og Ligestillingsministeriet', year: 2026, type: 'Høringsudkast', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/b114f358f916a19d61689930c8b921f0.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/f1dd31f5-dcda-461d-bfac-154577d91273/Udkast%20til%20lovforslag%20om%20maksimal%20st%C3%B8rrelse%20p%C3%A5%20gebyr%20og%20periodisering.pdf', res: 'Høringsudkast til lovforslag om et loft over det gebyr, kommunerne kan opkræve hos producenterne for at indsamle emballageaffald, og om periodisering af omkostningerne.', long: 'Miljø- og Ligestillingsministeriet foreslår, at miljøministeren fra 1. juli 2026 kan fastsætte et loft over producentgebyret. Loftet tænkes beregnet med en benchmarkmodel ud fra de billigste kommuner pr. fraktion, med særskilte lofter for tre kommunetyper. Kommunerne forventede i maj 2025 omkostninger på 1,6 mia. kr. om året, mens ministeriet anslår de nødvendige til ca. 1,2 mia. kr. Siden 1. oktober 2025 har kommunerne kun måttet opkræve 62,5 %, ca. 1,0 mia. kr. om året. Det manglende beløb frem til 1. juli 2026, ca. 150 mio. kr., foreslås opkrævet over fire år med markedsrente. Højere service kan finansieres via affaldsgebyret.' },
      { id: 'NY306', title: 'Forslag til lov om ændring af lov om miljøbeskyttelse (Supplerende bestemmelser til emballageforordningen)', org: 'Miljø- og Ligestillingsministeriet', year: 2026, type: 'Høringsudkast', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser'], img: 'img/b7efe4de7d0a720ae08817e56b5627d8.jpg', url: 'https://prodstoragehoeringspo.blob.core.windows.net/f831e4f2-08a5-4bb2-aaa4-ce7b58afd0e1/Udkast%20til%20lovforslag%20om%20supplerende%20bestemmelser%20til%20emballageforordningen.docx.pdf', res: 'Lovudkastet foreslår at tilpasse miljøbeskyttelsesloven til EU\'s emballageforordning, der gælder fra 12. august 2026, og at give miljøministeren hjemmel til supplerende regler.', long: 'Miljø- og Ligestillingsministeriet foreslår en ny § 13 b, så ministeren kan fastsætte regler til at gennemføre forordning 2025/40 og Kommissionens retsakter. Hjemlen skal også dække frivillige ordninger, fravigelser, hvor EU tillader dem, opgaver til private organisationer og gebyrer. Dele af § 9 p om producentansvar foreslås ophævet eller tilpasset, så loven passer til forordningen. Kommunernes producentgebyrer skal efter forslaget dække mærkning af beholdere til emballageaffald, og producenterne skal betale for undersøgelser af blandet kommunalt affald. Udkastet vurderes ikke i sig selv at have økonomiske konsekvenser for kommunerne.' },
      { id: 'NY307', title: 'KL\'s høringssvar på lovforslaget om maksimal størrelse af gebyr og periodisering', org: 'KL', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/c87e438770098061e23eaa399de470c6.jpg', url: 'https://www.kl.dk/media/zlkbpfow/kls-hoeringssvar-paa-lovforslaget-om-miljoebeskyttelsesloven-maksimal-stoerrelse-af-gebyr-og-periodisering-af-omkostninger-under-udvidet-producentansvar.pdf', res: 'I sit høringssvar kritiserer KL lovforslagets benchmark-model, som vil skære producenternes betaling for indsamling af emballage til 1,2 mia. kr. og lægge resten på affaldsgebyret.', long: 'Høringssvaret fra 2. marts 2026 gælder Miljøministeriets lovforslag om maksimalt producentgebyr og periodisering under producentansvaret for emballage. Benchmark-modellen bygger på de billigste priser i tre kommunegrupper uanset serviceniveau og sætter de nødvendige omkostninger til 1,2 mia. kr. Ifølge KL må borgerne så betale ca. en fjerdedel af indsamlingen. KL foretrækker det serviceniveau, Forhandlingsudvalget blev enige om. Ø-kommuner kan ikke få dækket deres udgifter, og Dragør og Frederiksberg får samme benchmark trods vidt forskellige boliger. KL foreslår, at tilgodehavendet for 2026 opkræves på én gang i stedet for over fire år.' },
      { id: 'NY308', title: 'KL\'s høringssvar på emballagebekendtgørelsen 2026', org: 'KL', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/9b5f0a9f1b3c7a25b679abf71625cbf6.jpg', url: 'https://www.kl.dk/media/nxipynme/kls-hoeringssvar-paa-emballagebekendtgoerelsen-2026.pdf', res: 'KL kritiserer de maksimale gebyrer i udkastet til ny emballagebekendtgørelse. Ifølge KL er det et prisloft, der flytter ca. 3,9 mio. kr. pr. kommune over på affaldsgebyret.', long: 'I høringssvaret af 27. marts 2026 afviser KL den model, der skal flytte 400 mio. kr. fra producenter til borgere. Beløbene i bilag 18 er fundet som gennemsnit af de billigste kommuner i tre kategorier, og KL kalder dem et prisloft, fordi der ikke er et serviceniveau at styre efter. Modellen fjerner ikke administration, giver risiko for suboptimering, rammer ø-kommuner hårdt og svækker incitamentet til at øge sorteringen. KL foreslår et loft ud fra de samlede indsamlingsomkostninger, regler for genberegning, en vejledning om tillægsgebyr og markedsrente og at fristen for producentgebyrer flyttes til 15. oktober.' },
      { id: 'NY309', title: 'Høringssvar: Maksimal størrelse af gebyr under udvidet producentansvar for emballager', org: 'Brancheforeningen Cirkulær', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/4d3e4d281ec8af7b85cda5d28d1a9f61.jpg', url: 'https://cirkulaer.dk/files/media/document/01%20H%C3%B8ringssvar%20Brancheforeningen%20Cirkul%C3%A6r%2003182026.pdf', res: 'Høringssvar, hvor Brancheforeningen Cirkulær advarer mod et loft over producentgebyret for emballage. Kommunerne kan ifølge foreningen mangle 400-600 mio. kr. om året.', long: 'Høringssvaret fra marts 2026 gælder et lovforslag om at give miljøministeren hjemmel til et loft over producentgebyret og regler for kommunernes periodisering. Regeringen ønsker, at producenterne højst betaler 1,0-1,2 mia. kr. om året mod de 1,6 mia. kr., kommunerne har budgetteret. Ifølge Cirkulær kan kommunerne mangle 400-600 mio. kr. årligt, og forslaget kan indebære statsstøtte til producenterne. Foreningen vil vide, hvorfor de forventede 1,2 mia. kr. blev til 1,6 mia. kr., og kritiserer benchmarkmodellen med henvisning til BDO og JHN Processor. Modellen fjerner ifølge foreningen kommunernes tilskyndelse til at indsamle mere emballage.' },
      { id: 'NY310', title: 'Bilag 1: Yderligere bemærkninger til lov om ændring af lov miljøbeskyttelse', org: 'Brancheforeningen Cirkulær', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/74686e326053edd23f36d074909ec368.jpg', url: 'https://cirkulaer.dk/files/media/document/02%20Bilag%201%20Brancheforeningen%20Cirkul%C3%A6r%2003182026.pdf', res: 'Cirkulærs uddybende høringssvar kritiserer forslaget om maksimale producentgebyrer for emballage, der ifølge foreningen lader borgerne betale 400 mio. kr. årligt via gebyret.', long: 'Bilaget fra 17. marts 2026 uddyber Brancheforeningen Cirkulærs høringssvar til Miljø- og Ligestillingsministeriets lovforslag. Loftet på 1,2 mia. kr. bygger på en COWI-rapport fra 2021, mens kommunernes budgetterede omkostninger er 1,6 mia. kr. om året, og ifølge foreningen er forskellen ikke undersøgt. Benchmarkmodellen kritiseres for at inddele kommunerne efter størrelse og jobtilgængelighed og for reelt at udbetale et fast beløb pr. ton. Cirkulær mener, at kommunerne mister tilskyndelsen til at forbedre indsamlingen, stiller spørgsmål om modellens forhold til EU\'s genanvendelsesmål og forureneren betaler-princippet og beder om aktindsigt.' },
      { id: 'NY311', title: 'Høring over udkast til bekendtgørelse om visse krav til emballager (emballagebekendtgørelsen)', org: 'Brancheforeningen Cirkulær', year: 2026, type: 'Notat', temaer: ['Udvidet producentansvar', 'Økonomi', 'Lovgivning og afgørelser'], img: 'img/ffafe2ab5fd3af0c2a9ee8febe862578.jpg', url: 'https://cirkulaer.dk/files/media/document/01%20H%C3%B8ringssvar%20Brancheforeningen%20Cirkul%C3%A6r%2004212026.pdf', res: 'I sit høringssvar advarer Cirkulær om, at et loft på 1,2 mia. kr. om året for producenternes betaling vil efterlade kommunerne med udækkede udgifter til emballageaffald.', long: 'Høringssvaret fra 15. april 2026 gælder Miljøstyrelsens udkast fra 24. februar 2026, der bygger på et lovforslag om ændring af miljøbeskyttelsesloven. Udkastet lægger op til maksimale producentgebyrer pr. ton for hver emballagetype efter en benchmarkmodel, så producenterne højst betaler 1,2 mia. kr. om året. Ifølge Cirkulær budgetterer kommunerne med 1,6 mia. kr. om året. Foreningen kalder datagrundlaget usikkert og dækningen tilfældig, fordi den afhænger af den indsamlingsløsning, kommunen allerede har valgt. Cirkulær ønsker regler, der passer til benchmarkmodellen, og en vejledning, og kritiserer, at ministeriet har afvist aktindsigt.' },
      { id: 'NY312', title: 'Vejledning om brændbare faste stoffer. Kapitel 5: Lagerafsnit i det fri', org: 'Beredskabsstyrelsen', year: 2020, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/7b179f76f4e49465a8e15e84bdff9107.jpg', url: 'https://www.brs.dk/link/df8de79ef75e4245a7473df40e1a2cd7.aspx', res: 'Beredskabsstyrelsens vejledning forklarer brandkravene til oplag i det fri af bl.a. brændbart affald, træ, plast og halm, med eksempler på milestørrelser, friarealer og afstande.', long: 'Kapitel 5 i vejledningen til de tekniske forskrifter for brændbare faste stoffer udkom 1. juli 2020 og dækker lagerafsnit i det fri med bl.a. plast, træ, træflis, brændbart affald og halm. For brændbart affald vises miler på højst 70 m i længden, 10 m i bredden og 5 m i højden med friarealer på mindst 5 m og køreveje, så beredskabet kan lave standsningslinjer. Med den indretning kan 20 m til naboskel og vejmidte være nok for nogle affaldsoplag, og større oplag bør ligge mindst 50 m fra letantændelig vegetation. Vejledningen omtaler også jorddækning, brandveje, indsatsplaner, selvantændelse og en drifts-, kontrol- og vedligeholdelsesplan.' },
      { id: 'NY313', title: 'Vejledning om brændbare faste stoffer, kapitel 3: Lagerafsnit i bygning', org: 'Beredskabsstyrelsen', year: 2020, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/01bd93deef2cc6e517602fac16592e2f.jpg', url: 'https://www.brs.dk/link/8a0357dd0db14b80bb871a911b6b8758.aspx', res: 'Beredskabsstyrelsens vejledning til brandreglerne for lagre af brændbart affald, halm og træflis i bygninger. Den angiver bl.a. 2,5-5 m afstand fra affaldscontainere til ydervægge.', long: 'Vejledningen fra juli 2020 forklarer kapitel 3 i de tekniske forskrifter for brændbare faste stoffer, som gælder indendørs lagre af bl.a. brændbart affald, halm, korn, træpiller og træflis. Den gennemgår brandmæssige adskillelser, bærende konstruktioner, flugtveje, afstande, håndildslukkere og ordensregler. Fra rum med flere lagerafsnit bør der være mindst to uafhængige flugtveje og højst 25 m til nærmeste udgang. Affaldscontainere bør stå mindst 2,5 m fra vægge med klasse 1-beklædning uden åbninger og 5 m fra vægge med ringere beklædning. Ved risiko for selvantændelse skal der føres egenkontrol, fx med temperatur og fugt.' },
      { id: 'NY314', title: 'Vejledning om brandsikring af større oplag af litiumionbatterier samt BESS', org: 'Beredskabsstyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/9c177f474afe10eb0729be4539c9cfb3.jpg', url: 'https://www.brs.dk/globalassets/brs---beredskabsstyrelsen/dokumenter/forebyggelse/2023/-vejledning-om-brandsikring-af-storre-oplag-af-litiuimionbatterier-samt-bess-.pdf', res: 'Beredskabsstyrelsen anbefaler brandsikring af større oplag af litiumionbatterier og batterilagre (BESS), fx hos virksomheder, der modtager udtjente batterier fra genbrugspladser.', long: 'Vejledningen fra maj 2023 er skrevet til de kommunale redningsberedskaber, der fastsætter vilkår efter beredskabslovens § 34, stk. 2, men kan også bruges af virksomheder og rådgivere. Den afløser meddelelse nr. 25 fra 2021 og bygger bl.a. på en rapport fra MOE A/S. Oplag af udtjente batterier regnes som større over 1.000 kWh, mod 2.000 kWh for fabriksnye og ikke-udtjente batterier og for BESS. Genbrugspladser regnes normalt ikke som større oplag, men det gør virksomheder, der modtager batterier derfra. Udtjente batterier bør stå udendørs eller i containere, og beskadigede batterier bør i karantæne i mindst en uge.' },
      { id: 'NY315', title: 'Særlige nationale bestemmelser for vejtransport af affald, der er farligt gods', org: 'Beredskabsstyrelsen', year: 2023, type: 'Vejledning', temaer: ['Lovgivning og afgørelser', 'Genbrugspladser', 'Erhverv'], img: 'img/276e09f4e1a12df7f667c2eb2d05fa47.jpg', url: 'https://www.brs.dk/link/c41cfaba0fe34a87be4f8112cb24c0eb.aspx', res: 'Beredskabsstyrelsens vejledning om de danske undtagelser fra ADR ved transport af farligt affald, fx fra genbrugspladser og i miljøkasser fra husstande og virksomheder.', long: 'Vejledningen forklarer § 9 og bilag 2 i bekendtgørelsen om vejtransport af farligt gods, som lemper ADR-reglerne ved national transport i danskregistrerede køretøjer. Virksomheder må selv køre eget farligt affald af samme karakter som husholdningers til nærmeste genbrugsplads, men ikke som henteordning. Bilagets syv kapitler dækker blandt andet indsamlet affald i indvendige emballager på op til 5 eller 30 liter, spraydåser, trykflasker og tomme IBC-beholdere. Ved miljøkasser på højst 45 liter er indsamleren, typisk kommunen, afsender og pakker, og ved højst 300 kg brutto pr. transportenhed kan undtagelsesgrænserne i ADR antages overholdt.' },
      { id: 'NY316', title: 'Fokusanalyse 2024: Brande i mindre litiumionprodukter', org: 'Beredskabsstyrelsen', year: 2024, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Data, statistikker og nøgletal'], img: 'img/861beb4c610ad2bc1ce3cdd9ba2db1b1.jpg', url: 'https://www.brs.dk/link/b04ded10f8df4802811e68258c63edd2.aspx', res: 'Beredskabsstyrelsens opgørelse af brande i mindre litiumionprodukter 2018-2023. I affald og oplag blev der registreret 28 brande i 2020-2023, heraf 12 alene i 2023.', long: 'Analysen bygger på redningsberedskabernes indberetninger i ODIN og omfatter 430 brande fra 2018 til 2023, der startede i et mindre produkt med litiumionbatteri. I 2023 blev beredskabet kaldt ud til 131 af disse brande, 24 % flere end året før, og 35 % af brandene i perioden opstod under opladning. Elcykler var det enkeltprodukt, der oftest brændte. Afsnittet om affald viser, at brandene i affald og oplag steg fra 5-6 om året i 2020-2022 til 12 i 2023. Tolv af de 28 brande startede i containere, og 3 opstod i skraldebilen, hvor forkert sorterede batterier blev mast ved afhentning af dagrenovation.' },
      { id: 'NY317', title: 'Brannstatistikk gjenvinningsbransjen 2024', org: 'Norsk Industri', year: 2025, type: 'Statistik', temaer: ['Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/60595c49e447dcfd515ca5275d88b135.jpg', url: 'https://norskindustri.no/siteassets/dokumenter/bransjer/gjenvinning/brannstatistikk-gjenvinningsbransjen-2024.pdf', res: 'Norsk Industri har opgjort 459 brandhændelser hos 16 norske genanvendelsesvirksomheder i 2024. Batterier står bag 86 % af hændelserne med kendt årsag, især dem i restaffaldet.', long: 'Statistikken er den fjerde fra Norsk Industri og bygger på indberetninger fra 16 virksomheder og koncerner i den norske genanvendelsesbranche. Den er ikke nødvendigvis repræsentativ for hele branchen. De fleste brandtilløb og brande blev håndteret af virksomhederne selv, og kun to var større brande med store materielle skader. Batterier forårsagede 60 % af alle hændelser, og i over 30 % kunne årsagen ikke fastslås. Fejlsorterede batterier i restaffald er den største risiko, men batterier i pap, papir, kompleksjern og elektronikaffald gav også hændelser. Blandt de øvrige årsager nævnes nødblus og fyrværkeri.' },
      { id: 'NY318', title: 'Industry guidance for collecting, handling, and treating waste lithium batteries', org: 'WEEE Forum m.fl.', year: 2025, type: 'Vejledning', temaer: ['Genbrugspladser', 'Afsætning og behandling', 'Ledelse'], img: 'img/92b5d02a35b69a16a2704fba27b36470.jpg', url: 'https://weee-forum.org/wp-content/uploads/2025/02/IndustryGuideforcollectinghandlingandtreatingLithiumBatteries2025.pdf', res: 'Europæiske brancheforeninger og forsikringsbranchen giver råd om at forebygge brande fra litiumbatterier, fra indsamlingssted og genbrugsplads til transport, oplag og behandling.', long: 'Otte europæiske brancheforeninger, bl.a. WEEE Forum, EERA, Eucobat, EuRIC og FEAD, har skrevet vejledningen med Insurance Europe. Den bygger på arbejde fra 2019 og 2020 om brande i elektronikaffald. På genbrugspladser bør containerne have låg og stå i ly for regn og sol, og personalet skal kunne genkende beskadigede batterier og isolere polerne på større batterier. Elektronikaffaldsanlæg bør pakke usorterede batterier i 60 liters UN-godkendte tromler eller kasser, gerne med vermiculit eller sand. Fra 2027 skal batterier i bærbart udstyr som udgangspunkt kunne tages ud, men elektronik med indbyggede batterier vil komme i mindst ti år endnu.' },
      { id: 'NY319', title: 'Pligt til afrapportering i forbindelse med offentlig anskaffelse af renere køretøjer', org: 'Miljøstyrelsen', year: 2025, type: 'Vejledning', temaer: ['Udbud og kravspecifikationer', 'Lovgivning og afgørelser', 'Klima'], img: 'img/ed91606e10babf357e3733bcd1570594.jpg', url: 'https://mst.dk/media/xivj0yto/clean-vehicles-directive-brugervejledning.pdf', res: 'Miljøstyrelsens brugervejledning til, hvordan offentlige ordregivere skal rapportere renere køretøjer i TED, også ved kontrakter om indsamling af affald, og hvilke mål Danmark har.', long: 'Vejledningen forklarer kravene i EU-direktiv 2019/1161 og bekendtgørelse nr. 1726 af 2021 om minimumsmål for offentlige indkøb af renere køretøjer. For hver omfattet kontrakt skal ordregiveren i TED-databasen angive det samlede antal køretøjer og hvor mange af dem der er renere eller tunge nulemissionskøretøjer. Miljøstyrelsen kan give bøde, hvis det ikke sker. Indsamling af affald er blandt de omfattede tjenesteydelser. Danmarks mål for renere lette køretøjer er 37,4 % i begge perioder. For lastbiler er målet 10 % i 2021-2025 og 15 % i 2026-2030, for busser 45 % og 65 %.' },
      { id: 'NY320', title: 'Sagsfremstilling til Holbæk Kommune: Elektriske skraldebiler, miljøkasser og tekstilaffald', org: 'Fors A/S og Holbæk Kommune', year: 2024, type: 'Notat', temaer: ['Udbud og kravspecifikationer', 'Klima', 'Storskraldsordning'], img: 'img/cfb81eb86dfe9fe53877bea01a1e05bf.jpg', url: 'https://dagsordener.holbaek.dk/vis/pdf/bilag/523f7899-c019-4da6-b02b-c839152b78e8?redirectDirectlyToPdf=true', res: 'Fors A/S anbefaler, at mindst 50 % af tømningerne i Holbæk sker med el-skraldebiler i udbuddet, og hælder til at hente miljøkasser og tekstil med storskrald fire gange om året.', long: 'Sagsfremstillingen forbereder udbuddet af affaldsindsamling i Holbæk Kommune i 2024 og bygger på en trafikanalyse og et baggrundsnotat fra Rambøll. Med 70 km rækkevidde kan el-biler klare 50 % af tømningerne, svarende til 35 % af de kørte km og en årlig CO2-reduktion på 240 ton ud af 685 ton i 2023. Rambøll anslår en prisstigning på 7-15 % pr. tømning. Fors anbefaler point for mere eldrift, et sideordnet tilbud på 75 % og kontrakter på mindst 8 år. Miljøkasser og tekstil kan hentes med storskrald fire gange om året for ca. 1,2 mio. kr. årligt inkl. storskrald, svarende til 32 kr. pr. husstand, eller på skraldebilerne, som er mindre afprøvet.' },
      { id: 'NY321', title: 'Underretning om resultat af EU-udbud af indsamling og transport af affald i Køge Kommune', org: 'Køge Kommune', year: 2023, type: 'Afgørelse', temaer: ['Udbud og kravspecifikationer', 'Hente- og bringeordninger'], img: 'img/bcb80a784653cc13dba869c0a67851ce.jpg', url: 'https://dagsordener.koege.dk/vis/pdf/bilag/4307f344-ad72-4ad1-b47b-2b5902beea61?redirectDirectlyToPdf=true', res: 'Køge Kommunes underretning fra juli 2023 om resultatet af et EU-udbud af affaldsindsamling. Urbaser vandt delaftale 2 med 7,25 point mod 2,48 til kommunens eget kontrolbud.', long: 'Brevet fra 21. juli 2023 er sendt til kommunens egen driftsenhed Vej, Park & Byrum (VPB), som havde afgivet kontrolbud på delaftale 2 om papir, pap, plast, glas, metal og mad- og drikkevarekartoner. Urbaser bød på både delaftale 1 om mad- og restaffald og delaftale 2. Tilbuddene blev vurderet på pris (50 %), driftssikkerhed (25 %) og klima- og miljøvenlig indsamling (25 %). Urbaser bød 12.003.149,24 kr. mod VPB\'s 15.167.792,63 kr. og fik også flest kvalitetspoint. Begrundelserne peger bl.a. på, at VPB mangler skriftlige instrukser til afløsere og ikke kan sætte en reservevogn ind.' },
      { id: 'NY322', title: 'Vurdering af drivmiddel og valg mellem et- og toholdsdrift', org: 'Gladsaxe Kommune', year: 2022, type: 'Notat', temaer: ['Hente- og bringeordninger', 'Teknologi', 'Økonomi'], img: 'img/34137d860cae91b0dcdffdc91f97fd51.jpg', url: 'https://dagsordener.gladsaxe.dk/vis/pdf/bilag/bf1c137b-4433-42dd-ba35-e19be911858f?redirectDirectlyToPdf=true', res: 'Gladsaxe Kommune anbefaler el-skraldebiler, når kommunen hjemtager indsamlingen i 2024, og regner sig frem til, at toholdsdrift kan spare op til 3,07 mio. kr. om året.', long: 'Notatet er bilag til sagen om hjemtagning af affaldsindsamlingen, når kontrakterne med Urbaser og Remondis udløber 30. september 2024. Forvaltningen sammenligner diesel, HVO, biogas, brint og el og anbefaler el-biler til ca. 4 mio. kr. stykket, mens reservebiler kan købes på diesel eller gas. Beregningen bygger på et normtal på 850 beholdere pr. skraldemand om ugen og 21.347 husstande i ved-vej-ordningen. Med toholdsdrift fra 04.30 til 18.30 falder behovet fra 26 til 16 biler og indkøbet fra 100 til 62 mio. kr. Den årlige besparelse på 3,07 mio. kr. er et maksimum, da længere åbningstid på modtageanlæggene ikke er regnet med.' },
      { id: 'NY323', title: 'Valg af drivmidler i renovationsbiler i Viborg Kommune', org: 'Viborg Kommune', year: 2022, type: 'Notat', temaer: ['Klima', 'Udbud og kravspecifikationer', 'Teknologi'], img: 'img/06e5c7883f61102f59934c26ba686675.jpg', url: 'https://dagsordener.viborg.dk/vis/pdf/bilag/bc063a4b-8f06-4ad8-b83e-bbcb71d27181?redirectDirectlyToPdf=true', res: 'Bilag til Viborg Kommunes Klima- og Miljøudvalg om drivmidler i renovationsbiler før nyt udbud. Renovatørerne anbefaler el i Viborg by og HVO på landruterne.', long: 'Bilaget samler dias fra udvalgets temamøde den 28. februar 2022 og tal fra en COWI-rapport fra 2021 om omkostninger og emissioner ved diesel, HVO og el. Kommunen vurderer, at den opfylder kravet om ikke-fossilt brændstof ved at gå fra diesel til HVO. Renovatørerne anbefaler scenarie 4, hvor bilerne i Viborg by kører på el, bilerne i de større byer på HVO med el-komprimator og landbilerne på ren HVO. Det skønnes at koste ca. 20 % mere end diesel, mens el-komprimator på alle HVO-biler giver 20-30 % og el i alle biler 30-60 % i merpris. De fraråder batteripakker på landruterne, fordi de øger brændstofforbruget og kræver flere biler.' },
      { id: 'NY324', title: 'Forslag til brandtekniske krav til BESS og oplag af litium-ion batterier', org: 'Beredskabsstyrelsen', year: 2022, type: 'Rapport', temaer: ['Genbrugspladser'], img: 'img/d2733bf4cbf00c4bab36a85451e71c1f.jpg', url: 'https://www.brs.dk/globalassets/brs---beredskabsstyrelsen/dokumenter/forebyggelse/2023/-forslag-til-brandtekniske-krav-til-bess-og-oplag-af-litium-ion-batterier-.pdf', res: 'MOE\'s rapport til Beredskabsstyrelsen foreslår brandkrav til batterianlæg og batterilagre, bl.a. at genbrugsstationer lægger brugte batterier i lag af ubrændbart granulat.', long: 'Rådgiveren MOE A/S skrev rapporten i oktober 2022 som baggrundsviden for Beredskabsstyrelsen. Den gennemgår udenlandske vejledninger som NFPA 855 og nyere brandforsøg og foreslår krav til batterianlæg (BESS) og lagre af nye og brugte litiumionbatterier. Genbrugsstationer anbefales at opbevare udtjente batterier udendørs i plastbeholdere på højst 220 liter, i lag adskilt af mindst 15 cm vermiculit eller lignende og mindst 5 m fra brændbart oplag. Batterier med synlige skader bør i mindst en uge stå i en karantænecontainer med højst 200 kWh, placeret mindst 10 m fra anden bebyggelse og brændbart oplag.' },
      { id: 'NY325', title: 'Vurdering af drivmidler til renovationsbiler', org: 'KLAR Forsyning', year: 2024, type: 'Notat', temaer: ['Klima', 'Udbud og kravspecifikationer', 'Økonomi'], img: 'img/62a4bb7d2461ab2730ad7e2e469922bd.jpg', url: 'https://dagsordener.greve.dk/vis/pdf/bilag/08060b8a-fa89-45db-8d50-e0669ce929ec?redirectDirectlyToPdf=true', res: 'COWI har for KLAR Forsyning sammenlignet diesel, HVO, biogas og el til skraldebiler. El giver den bedste balance mellem miljø og økonomi, men gør ordningen 13 % dyrere.', long: 'Notatet fra oktober 2024 skal hjælpe KLAR Forsyning med at stille krav til drivmidler i et kommende udbud, med Greve og Solrød Kommuner som grundlag. COWI vurderer diesel, HVO og biogas, med og uden eldreven lift og komprimator, samt el ud fra CO2, NOx, partikler, støj, tilgængelighed og økonomi ved 10.700 km kørsel pr. bil om året. Med elbiler falder CO2-udledningen til 3 % af dieselniveauet, og den lokale luftforurening forsvinder. En elbil koster ca. 4,1 mio. kr. mod 2,3 mio. kr. for diesel. Med den nuværende logistik slår rækkevidden på ca. 150 km til, men da behandlingsanlæggene kan skifte, anbefaler COWI at se på omlastning.' },
      { id: 'NY326', title: 'Selektiv nedrivning', org: 'Værdibyg', year: 2026, type: 'Vejledning', temaer: ['Byggeaffald', 'Lovgivning og afgørelser', 'Cirkulær økonomi'], img: 'img/581c846e1f18b46129f9ed9306afbf89.jpg', url: 'https://vaerdibyg.dk/wp-content/uploads/2026/05/56_Selektiv_nedrivning_Web.pdf', res: 'Værdibygs vejledning fører bygherrer, rådgivere, nedrivere og myndigheder gennem kravet om selektiv nedrivning, som fra 1. juli 2025 gælder, når mindst 250 m² etageareal fjernes.', long: 'Brancheinitiativet Værdibyg har lavet vejledningen med støtte fra Grundejernes Investeringsfond på grundlag af bekendtgørelsen om selektiv nedrivning. Bygherren skal tilknytte en uddannet miljø- og ressourcekoordinator og bruge en autoriseret nedrivningsvirksomhed med en ressourceansvarlig. Den standardiserede nedrivningsplan har 22 punkter. Punkt 1-8 sendes med ansøgningen om nedrivningstilladelse, og punkt 9-22 skal være hos kommunens miljøafdeling senest tre uger før nedrivningen. Vejledningen gennemgår faserne fra forundersøgelser til slutdokumentation, aktørernes roller i forskellige entrepriseformer og giver syv råd om udbud.' },
      { id: 'NY327', title: 'Ressourcekortlægning', org: 'Værdibyg', year: 2024, type: 'Vejledning', temaer: ['Byggeaffald', 'Direkte genbrug', 'Cirkulær økonomi'], img: 'img/6f0b6bec121fc3549ac79ef462c01638.jpg', url: 'https://vaerdibyg.dk/wp-content/uploads/2025/08/54_Ressourcekortlaegning_Web.pdf', res: 'Værdibygs vejledning viser bygherrer, hvordan en ressourcekortlægning før selektiv nedrivning planlægges og udføres, så flest mulige materialer kan genbruges eller genanvendes.', long: 'Vejledning 54 fra Værdibyg henvender sig især til bygherrer, der skal rive ned. Den forklarer reglerne fra 1. juli 2025 om selektiv nedrivning, når mindst 250 m² etageareal fjernes, og om en standardiseret nedrivningsplan med ressourcescreening og ressourcekortlægning til kommunen. Screeningen giver et første overblik, mens kortlægningen går i dybden med mængder, tilstand, nedtagning og afsætning. Mange kortlægninger er i dag for overfladiske og uens, og intet krav sikrer, at ressourcerne faktisk genbruges. Vejledningen anbefaler at lave screeningen allerede i idé- og programfasen og at lægge rapporterne med i udbuddet af nedrivningen.' },
      { id: 'NY328', title: 'Virksomheder driver den cirkulære omstilling. DI\'s politik for cirkulær økonomi', org: 'Dansk Industri', year: 2024, type: 'Oplæg', temaer: ['Cirkulær økonomi', 'Byggeaffald', 'Tekstil'], img: 'img/c04680c0878026ccee71f07184543320.jpg', url: 'https://www.danskindustri.dk/globalassets/politik-og-analyser/di-mener/miljo-og-circular-okonomi/cirkular-okonomi---udspil-2024_web.pdf', res: 'DI\'s udspil til en national strategi for cirkulær økonomi med 24 forslag, bl.a. et reduktionsmål på 20 % for affald pr. indbygger i 2030 og ét samlet datasystem for affald.', long: 'Dansk Industri giver forslag på ti områder, fra klima og offentlige indkøb til emballage, tekstiler og byggeri. Ifølge Circularity Gap-analysen er Danmark 4 % cirkulær og bruger 24,5 tons materialer pr. indbygger mod 17,8 tons i EU. DI vil afskaffe emballageafgiften, når producentansvaret for emballage træder i kraft i 2025, og have Miljøstyrelsen til at bygge ét affaldsdatasystem til ca. 50 mio. kr. DI ønsker også ensartet indsamling og sortering i hele EU og 250 mio. kr. til hver sin satsning på genanvendelse af plast og tekstiler. I byggeriet vil DI have lovkrav om selektiv nedrivning af større bygninger.' },
      { id: 'NY329', title: 'Undersøgelse om madspild: Særligt yngre danskere og børnefamilier har madspildsudfordringer', org: 'Landbrug & Fødevarer', year: 2024, type: 'Analyse', temaer: ['Analyser og undersøgelser', 'Kommunikation'], img: 'img/04d6f94c26e739f713c9064eef47669e.jpg', url: 'https://lf.dk/media/vlzhnovk/undersoegelse-om-madspild_dec-24.pdf', res: 'Spørgeundersøgelse fra Landbrug & Fødevarer, hvor 41 % af danskerne smider mad ud mindst én gang om ugen. Madspildet er størst blandt yngre og i børnefamilier.', long: 'Norstat spurgte i oktober 2024 1.512 danskere mellem 18 og 80 år om madspild for Landbrug & Fødevarer. 32 % undgår altid madspild og 51 % ofte, men 41 % smider mad ud mindst ugentligt, oftest brød (34 %) og rå grøntsager (31 %). Blandt børnefamilier gælder det 57 % mod 36 % i husstande uden børn hjemme, og blandt de under 40 år er det 50 %. Hyppigste årsager er, at maden er blevet dårlig (46 %) eller ikke bruges helt (38 %). Madplaner sikrer ikke mindre spild, fordi ugen og appetitten er svære at forudsige. Kendskabet til, hvad sidste anvendelsesdato betyder, er begrænset, og 73 % ville spise maden efter datoen, hvis den virkede i orden.' },
      { id: 'NY330', title: 'Leaching of problematic substances during storage of WEEE', org: 'Miljøstyrelsen', year: 2023, type: 'Rapport', temaer: ['Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/ec25a5a454c9769c650f9dcfc789f9d1.jpg', url: 'https://www2.mst.dk/Udgiv/publications/2023/02/978-87-7038-482-7.pdf', res: 'Undersøgelse af, hvilke stoffer der vaskes ud af elaffald, som opbevares udendørs. Kvalitetskravet for PFAS blev overskredet i flere prøver fra småt elektronik og skærme.', long: 'Danish Waste Solutions har for Miljøstyrelsen testet udvaskning fra småt elektronik, skærme og kølemøbler, der blev vandet med 40 mm om ugen og til sidst 160 mm for at efterligne opbevaring uden overdækning. Eluaterne er holdt op mod kvalitetskrav ved afløb til overfladevand og til kloak. Udvaskningen af bl.a. cadmium, kviksølv, PCB og flere ftalater var uproblematisk, mens arsen, bly, tin, zink og organiske tinforbindelser kan være problematiske. Forsøg i 2022 viste, at summen af 22 PFAS oversteg 0,1 μg/l i halvdelen af prøverne fra småt elektronik, men i ingen fra kølemøbler. Kravet for summen af 4 PFAS blev overskredet i alle prøver.' },
      { id: 'NY331', title: 'Sæt gang i repair cafeer i landsbyer & landdistrikter: Manual til kommuner', org: 'Lejre Kommune', year: 2022, type: 'Vejledning', temaer: ['Direkte genbrug', 'Cirkulær økonomi'], img: 'img/23f4c028e51b2a9d63ce03c75349b81f.jpg', url: 'https://www.lejre.dk/Media/638641603094705650/manual_repair_cafe_final.pdf', res: 'Manual fra Lejre Kommune om at starte repair cafeer i landsbyer. I 2021 kom der fem cafeer, som holdt 31 arrangementer og reparerede godt 250 kilo af borgernes ting.', long: 'Lejre Kommune testede sammen med Repair Cafe Danmark og konsulentvirksomheden Naboskab og med støtte fra Bolig- og Planstyrelsens Landdistriktspulje, om repair cafeer kan slå rod i mindre samfund. Kommunen tog en understøttende rolle med opsøgende kontakt, infomøder, hjælp til kommunikation og refusion af udgifter på 2.000-5.000 kr. pr. café, mens borgerne selv drev cafeerne. Fra august til december 2021 blev der holdt 31 repair cafeer, og fire af de fem kører videre. Manualen giver råd om opstart, lokaler, værktøj og hensyn til lokale reparatører. Projektet mener, at repair cafeer kan gebyrfinansieres som forberedelse til genbrug.' },
      { id: 'NY332', title: 'Ressource- og Affaldsplan 2030. Kortlægningsrapport', org: 'Københavns Kommune', year: 2024, type: 'Rapport', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Økonomi'], img: 'img/2c3a857961ddab1d0fcd2f78cc65752b.jpg', url: 'https://www.kk.dk/sites/default/files/agenda/4c2ace22-b3ad-4eae-8a00-7fea405ffd51/c9f94d92-06ad-4320-8c91-e6022246f487-bilag-8_0.pdf', res: 'Københavns Kommunes kortlægning til Ressource- og Affaldsplan 2030 med affaldsmængder for 2017-2022, prognose til 2036 og mål om at løfte reel genanvendelse fra 33 % til 60 %.', long: 'Kortlægningen er datagrundlaget for planen for 2025-2030 og bygger på kommunens egne data og Miljøstyrelsens Affaldsdatasystem. I 2021 var der 481.000 ton affald i kommunen, og 49 % gik til genanvendelse. Genanvendelsen af husholdningsaffald var 41,2 % i 2022 og 43,2 % i 2023. Med sorteringsanlæg til restaffald og planens indsatser ventes den reelle genanvendelse af husholdnings- og husholdningslignende affald at stige fra 32,9 % i 2022 til 60 % i 2030. De midlertidige udgifter til planen ventes at blive ca. 470 mio. kr., svarende til 285 kr. om året pr. husstand i fem år, og de varige driftsudgifter ventes at stige med 75 mio. kr. årligt.' },
      { id: 'NY333', title: 'Tilskud til borgeres reparationer af produkter som klimatiltag', org: 'Aalborg Universitet', year: 2023, type: 'Notat', temaer: ['Direkte genbrug', 'Cirkulær økonomi', 'Klima'], img: 'img/741ecce20b8f750793194c30a30a9877.jpg', url: 'https://vbn.aau.dk/ws/files/572590404/Sammenligning_af_nationale_reparationsordninger_-_notat_-_nov_2023.pdf', res: 'Aalborg Universitet sammenligner tilskud og fradrag for reparation i Østrig, Thüringen, Frankrig og Sverige. Østrigs og Thüringens ordninger bruges meget, mest til mobiltelefoner.', long: 'Michael Søgaard Jørgensen skrev notatet i november 2023, hvor flere aktører havde foreslået et dansk reparationsfradrag. Ordningerne sammenlignes ud fra syv spørgsmål om bl.a. kompensation og finansiering. Østrig og Thüringen refunderer halvdelen af udgiften op til 200 og 100 euro, Frankrig giver tilskud fra producentbetalte fonde, og Sverige har lavere moms og fradrag for lønudgifter. I Østrig blev ordningen brugt over 500.000 gange fra april 2022 til medio 2023, oftest til mobiltelefoner. Længere levetid for borgernes elektronik frem for genanvendelse kan ifølge notatet give en klimagevinst på ca. 500.000 ton CO2e om året.' },
      { id: 'NY334', title: 'Bilag til Affaldsplan 2025 for Roskilde Kommune', org: 'Roskilde Kommune', year: 2025, type: 'Rapport', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/956c80f2bc8ea74c528637c229a72b75.jpg', url: 'https://www.roskilde.dk/media/pzyd32dn/bilag-til-affaldsplan-2025-2030-roskilde-kommune.pdf', res: 'Bilag til Roskilde Kommunes affaldsplan 2025 med kortlægning og prognose til 2036. Den reelle genanvendelse af husholdningsaffald uden have- og byggeaffald var 58 % i 2023.', long: 'Bilaget udgør kortlægnings- og planlægningsdelen af Roskilde Kommunes affaldsplan og rummer også en evaluering af planen fra 2015 og en miljøscreening. I 2023 kom der 71.340 tons affald fra husholdningerne, svarende til 789 kg pr. indbygger. Efter den gamle opgørelse blev 60 % indsamlet til genanvendelse, mens den reelle genanvendelse af husholdningsaffald uden have- og byggeaffald er beregnet til 58 %. Alle 10 fraktioner er indsamlet siden 2022, og der ventes ingen nye ordninger frem mod 2030. Affaldshåndteringen kostede 144,9 mio. kr. i 2023, og det brændbare affald går indtil videre til ARGOs kraftvarmeværk i Roskilde.' },
      { id: 'NY335', title: 'Bilag til affaldsplan 2023-2034', org: 'Greve Kommune', year: 2022, type: 'Rapport', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Reel genanvendelse'], img: 'img/ddfb6eb0077efb668cd05fbcff8df47d.jpg', url: 'https://greve.dk/media/0v2ocvui/bilag-til-affaldsplan-2023-2034.pdf', res: 'Bilaget til Greve Kommunes affaldsplan 2023-2034 rummer kortlægning og prognoser. Husholdningerne afleverede 41.902 tons affald i 2021, og 76,2 % gik til genanvendelse.', long: 'Greve Kommune har samlet affaldsplanens lovpligtige kortlægning og planlægningsdel i dette bilag sammen med status for planen 2014-2024 og en miljøscreening. Tallene for husholdninger er fra 2021 og for erhverv fra 2020, og de kommer fra KLAR Forsyning og Affaldsdatasystemet. Uden have- og byggeaffald skønnes den reelle genanvendelse til 52,25 %. Erhvervsaffaldet var 177.493 tons, mest jord, og 86 % gik til genanvendelse. Husholdningsaffald til forbrænding fremskrives fra 9.622 tons i 2021 til 11.934 tons i 2034, og ARGOs anlæg i Roskilde har kapacitet til det. Nye deponiceller på Audebo til ca. 25 mio. kr. ventes ikke at påvirke gebyrerne.' },
      { id: 'NY336', title: 'Bilag til Ressource- og Affaldsplan 2022-2033. Kortlægning af affaldsmængder', org: 'Hvidovre Kommune', year: 2023, type: 'Rapport', temaer: ['Affaldsplaner/regulativer og strategi', 'Data, statistikker og nøgletal', 'Afsætning og behandling'], img: 'img/d5270ba931ae4f8a2320910f84282a7b.jpg', url: 'https://www.hvidovre.dk/Media/638630471576782793/bilag-til-affaldsplan-2022-2033%20(1).pdf', res: 'Hvidovre Kommunes kortlægning til affaldsplanen 2022-2033 beskriver ordninger, anlæg, mængder og økonomi. Den reelle genanvendelse af husholdningsaffald var ca. 49 % i 2020.', long: 'Bilaget er kortlægningsdelen af Hvidovre Kommunes Ressource- og Affaldsplan 2022-2033, som kommunalbestyrelsen godkendte 28. marts 2023. Det gennemgår ordninger og modtageanlæg, affaldsmængder fra husholdninger, virksomheder og genbrugspladsen, en evaluering af planen for 2014-2018 og prognoser. Kommunen regner med at sende ca. 12.000 tons forbrændingsegnet affald om året til ARC, og deponiet AV Miljø ventes at have plads til udgangen af 2034. En restaffaldsanalyse fra 2020 i 200 etageboliger og 200 haveboliger viste, at madaffald udgjorde 32 % og 21 % af restaffaldet. Kommunen vil bruge informationskampagner til at øge sorteringen.' },
      { id: 'NY337', title: 'Bekendtgørelse om affald', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2026, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Affaldsplaner/regulativer og strategi', 'Hente- og bringeordninger'], img: 'img/e1bc9b776ddbc424b445544861417952.jpg', url: 'https://www.retsinformation.dk/api/pdf/257178', res: 'BEK nr. 810 af 22. september 2026 fastsætter kommunernes pligter til affaldsplaner og indsamlingsordninger og virksomhedernes sortering. Den gælder fra 8. november 2026.', long: 'Bekendtgørelsen fra Klima-, Energi- og Forsyningsministeriet afløser BEK nr. 1749 fra 2024. Kommunerne skal vedtage en 12-årig affaldsplan, som revideres mindst hvert 6. år, og have henteordninger for madaffald, papir, pap, glas, metal, plast, mad- og drikkekartoner, farligt affald, tekstil og restaffald. I sommerhusområder og på ikke-brofaste øer med under 200 indbyggere må flere ordninger være bringeordninger. Plast, som ikke overdrages til producenterne, skal have mindst 60 % reel genanvendelse. Virksomheder skal sortere husholdningslignende affald efter husholdningernes sorteringskriterier, og forbrændingsanlæg skal lave modtagekontrol.' },
      { id: 'NY338', title: 'Bekendtgørelse om affaldsregulativer, -gebyrer og -aktører m.v.', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2024, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Affaldsplaner/regulativer og strategi', 'Økonomi'], img: 'img/bdc3ea306fc3b3dfad12a49b388e9d17.jpg', url: 'https://www.retsinformation.dk/api/pdf/246903', res: 'Bekendtgørelsen fastsætter reglerne for kommunernes affaldsregulativer og affaldsgebyrer og for kommunal indsamling og behandling af erhvervsaffald. Gælder fra 1. januar 2025.', long: 'Klima-, Energi- og Forsyningsministeriet udstedte BEK nr. 1743 den 30. december 2024. Den trådte i kraft 1. januar 2025 og afløste bekendtgørelse nr. 539 fra maj 2024. Kommunerne skal bruge standardregulativerne i bilag 1 og 2 og indberette regulativerne til den nationale regulativdatabase. Gebyrreglerne kræver et gebyrblad og gebyrer pr. ordning, som alene dækker omkostningerne, og regulerer virksomheders betaling på genbrugspladser pr. besøg eller abonnement. Den regulerer også prisen for kommunal indsamling af erhvervsaffald og den årlige indberetning af forbrændingskapacitet.' },
      { id: 'NY339', title: 'Bekendtgørelse af lov om miljøbeskyttelse', org: 'Miljøministeriet', year: 2026, type: 'Rapport', temaer: ['Lovgivning og afgørelser', 'Udvidet producentansvar', 'Affaldsplaner/regulativer og strategi'], img: 'img/b21bf1c16a9996bc88bf9492695a8b33.jpg', url: 'https://www.retsinformation.dk/api/pdf/257515', res: 'Lovbekendtgørelse nr. 842 af 11. september 2026 samler den gældende miljøbeskyttelseslov, herunder kapitel 6 om affald og kapitel 2 c om udvidet producentansvar.', long: 'Miljøministeriet samler her miljøbeskyttelsesloven med ændringerne fra december 2025 og marts 2026. Efter kapitel 6 står kommunalbestyrelsen for håndteringen af affald, fastsætter regulativer for affaldsordningerne og udarbejder en affaldsplan. Udgifterne dækkes af gebyrer med et særskilt gebyr for hver ordning. Kapitel 2 c rummer reglerne om udvidet producentansvar for bl.a. emballage, elektronik, batterier og engangsplast. Loven giver hjemmel til regler om selektiv nedrivning og pålægger kommunerne at udbyde behandlingen af forbrændingsegnet affald. Enkelte ændringer fra 2022 træder først i kraft 1. januar 2027 og er ikke indarbejdet.' },
      { id: 'NY340', title: 'Elektronikaffaldsbekendtgørelsen, BEK nr. 942 af 20/06/2025', org: 'Miljø- og Ligestillingsministeriet', year: 2025, type: 'Lovforslag', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Hente- og bringeordninger'], img: 'img/726fa64f566f04b6f0159f1757fea043.jpg', url: 'https://www.retsinformation.dk/api/pdf/249485', res: 'Elektronikaffaldsbekendtgørelsen fra 2025 fastlægger producentansvaret for elektronik og kommunernes pligt til at indsamle husholdningernes elektronikaffald i seks fraktioner.', long: 'Bekendtgørelsen fra Miljø- og Ligestillingsministeriet trådte i kraft 1. juli 2025 og afløser BEK nr. 1566 af 19. december 2022. Producenterne skal for egen regning tage affaldet tilbage, og Dansk Producentansvar fordeler hvert år mængderne fra de kommunale indsamlingssteder. Kommunen skal sortere affaldet i seks fraktioner, fx skærme og lyskilder, og registrere sine indsamlingssteder en måned før de oprettes eller nedlægges. Efter bilag 9 skal producenten som udgangspunkt hente senest to hverdage efter en anmodning. Sker det ikke inden fire timer efter en påmindelse, kan kommunen bestille nødafhentning og kræve udgifterne dækket.' },
      { id: 'NY341', title: 'Bekendtgørelse om Affaldsdatasystemet', org: 'Miljø- og Ligestillingsministeriet', year: 2025, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Data, statistikker og nøgletal'], img: 'img/5721bd68935be47615b64c832686fb3f.jpg', url: 'https://www.retsinformation.dk/api/pdf/252084', res: 'Bekendtgørelsen fastsætter, hvem der skal indberette affaldsdata til Affaldsdatasystemet, og hvordan. Den gælder fra 1. januar 2026 og afløser bekendtgørelsen fra 2021.', long: 'BEK nr. 1465 af 28. november 2025 gælder for virksomheder, der indsamler eller behandler affald. De skal indberette mængder i ton via ads.mst.dk senest 1. februar for det foregående år. Affald, som genbrugspladser modtager, skal ikke indberettes, medmindre det slutbehandles på pladsen, fx ved kompostering af haveaffald. Kommunen indberettes som affaldsproducent for husholdningsaffald fra kommunale ordninger, og kommunalbestyrelsen kan rette data for virksomheder i kommunen fra 2. februar til 30. marts. For farligt affald gælder krav om supplerende oplysninger og om registre hos transportører og mæglere. Overtrædelser kan straffes med bøde.' },
      { id: 'NY342', title: 'Bekendtgørelse om håndtering af affald og materialer fra bygge- og nedrivningsarbejde', org: 'Miljøministeriet', year: 2024, type: 'Afgørelse', temaer: ['Byggeaffald', 'Lovgivning og afgørelser'], img: 'img/70b7a00952be5c639fd6ebaebd9d7c4e.jpg', url: 'https://www.retsinformation.dk/api/pdf/243016', res: 'Bekendtgørelsen kræver affaldsanmeldelse og miljøscreening ved byggearbejder og selektiv nedrivning ved større nedrivninger, så problematiske stoffer bliver sorteret fra.', long: 'BEK nr. 496 af 21. maj 2024 er udstedt af Miljøministeriet efter miljøbeskyttelsesloven og trådte i kraft 1. juli 2024. Ved byggearbejder med mere end 1 ton affald skal bygherren lave en miljøscreening og anmelde affaldet til kommunen, før arbejdet går i gang. Fra 1. juli 2025 skal nedrivning af mindst 250 m2 etageareal ske selektivt efter en standardiseret nedrivningsplan, der sendes til kommunen senest tre uger før start. Bygherren skal udpege en miljø- og ressourcekoordinator, og kun nedrivningsvirksomheder autoriseret af Miljøstyrelsen må udføre arbejdet. Kommunen fører tilsyn og kan opkræve gebyr for at behandle planen.' },
      { id: 'NY343', title: 'Bekendtgørelse om supplerende bestemmelser til forordning om emballage og emballageaffald', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2026, type: 'Lovforslag', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/77a0bdec0f693ac4dedff97536ab2515.jpg', url: 'https://www.retsinformation.dk/eli/lta/2026/851/pdf', res: 'Bekendtgørelse nr. 851 fra 2026 supplerer EU\'s emballageforordning med danske regler om producentansvar, bl.a. for kommunernes overdragelse af emballageaffald til producenterne.', long: 'Klima-, Energi- og Forsyningsministeriet udstedte bekendtgørelsen 28. september 2026. Den træder i kraft 15. oktober 2026 og afløser bekendtgørelse nr. 1146 fra 2025. Reglerne supplerer forordning (EU) 2025/40 og handler bl.a. om producentregister, indberetning, producentansvarsorganisationer og tilsyn. Dansk Producentansvar tildeler hvert andet år producenterne kommunalt indsamlede fraktioner som pap, plast, glas og metal. Kommunen skal sikre høj reel genanvendelse af affald, den selv behandler, og opkræve særskilte gebyrer for emballageordningerne hos producenterne. Bilag 5 sætter fx emballageandelen i plast fra henteordninger til 51 %.' },
      { id: 'NY344', title: 'Bekendtgørelse om udvidet producentansvar for visse engangsplastprodukter', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2026, type: 'Lovforslag', temaer: ['Udvidet producentansvar', 'Lovgivning og afgørelser'], img: 'img/d776a381597fc2a1968a234fbb28fd3e.jpg', url: 'https://www.retsinformation.dk/eli/lta/2026/852/pdf', res: 'Bekendtgørelse nr. 852 af 2026 pålægger producenter af bl.a. fødevarebeholdere, vådservietter, balloner og tobaksfiltre at betale for oprydning af henkastet affald.', long: 'Bekendtgørelsen gennemfører dele af EU\'s engangsplastdirektiv og træder i kraft 15. oktober 2026, hvor den afløser bekendtgørelse nr. 882 fra 2025. Den dækker otte produktkategorier, bl.a. drikkebægre og letvægtsplastbæreposer. Producenterne skal registrere sig hos Dansk Producentansvar for 1.000 kr. og indberette mængder hvert kvartal. Det kvartalsvise gebyr til Energistyrelsen dækker kommunal og statslig oprydning af henkastet affald, indsamling fra offentlige affaldsbeholdere, oplysning, data og administration. Gebyret justeres mindst hvert tredje år ud fra affaldsanalyser. Grove overtrædelser kan give fængsel i op til 2 år.' },
      { id: 'NY345', title: 'Bekendtgørelse om supplerende bestemmelser til forordning om batterier og udtjente batterier', org: 'Miljø- og Ligestillingsministeriet', year: 2025, type: 'Notat', temaer: ['Lovgivning og afgørelser', 'Udvidet producentansvar'], img: 'img/ac31d2562f125da5f0299a7f037781aa.jpg', url: 'https://www.retsinformation.dk/eli/lta/2025/986/pdf', res: 'Bekendtgørelse nr. 986 af 20. juni 2025 supplerer EU\'s batteriforordning med danske regler om producentansvar, registrering, gebyrer og indsamling af udtjente batterier.', long: 'Bekendtgørelsen trådte i kraft 18. august 2025 og ophævede to bekendtgørelser om batterier fra 2015. Miljøstyrelsen er kompetent myndighed, og Dansk Producentansvar fører producentregistret. Producenter af bærbare batterier og batterier til lette transportmidler skal være med i en godkendt producentansvarsorganisation. Indsamlingssteder må kun tage imod udtjente batterier med skriftlig kontrakt med en producent eller organisation. Registrering koster 1.000 kr., og første indberetning skal ske senest 30. juni 2026. Bidragene til organisationerne gradueres efter designkriterier med 10 % tillæg for hvert kriterie, batteriet ikke opfylder.' },
      { id: 'NY346', title: 'Forordning (EU) 2023/1542 om batterier og udtjente batterier', org: 'Europa-Parlamentet og Rådet', year: 2023, type: 'Afgørelse', temaer: ['Lovgivning og afgørelser', 'Udvidet producentansvar'], img: 'img/304b5c565e89d30c5ecee6be12fe6175.jpg', url: 'http://publications.europa.eu/resource/cellar/d0065c31-2ce3-11ee-95a2-01aa75ed71a1.0003.01/DOC_1', res: 'EU\'s batteriforordning fastsætter fælles regler for batterier fra design til affald. Producenterne skal indsamle 63 % af de bærbare batterier i 2027 og 73 % i 2030.', long: 'Forordningen fra juli 2023 afløser batteridirektivet og gælder direkte i alle medlemsstater. Den dækker alt fra farlige stoffer og CO2-fodaftryk til batteripas og affaldshåndtering. Reglerne om udtjente batterier gælder fra 18. august 2025. Producenterne skal sørge for gratis indsamling, og offentlige affaldsmyndigheder kan oprette indsamlingssteder og overdrage batterierne til producenterne. Indsamlingsmålet for batterier til lette transportmidler er 51 % i 2028 og 61 % i 2031. Litiumbatterier skal genanvendes med en effektivitet på 65 % i 2025 og 70 % i 2030. Fra februar 2027 skal bærbare batterier i produkter kunne udskiftes af brugeren.' },
      { id: 'NY347', title: 'Bekendtgørelse om deponeringsanlæg', org: 'Miljø- og Fødevareministeriet', year: 2019, type: 'Afgørelse', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling'], img: 'img/ca4df1af784af3905a02426c4ab3211e.jpg', url: 'https://www.retsinformation.dk/api/pdf/210692', res: 'Bekendtgørelsen fastsætter regler for godkendelse, drift, modtagekontrol, nedlukning og efterbehandling af deponeringsanlæg og gennemfører EU\'s deponeringsdirektiv i dansk ret.', long: 'Bekendtgørelse nr. 1253 af 21. november 2019 trådte i kraft 1. januar 2020 og blev ændret i 2021. Den inddeler affaldet i inert, mineralsk, blandet og farligt affald og deler anlæggene i klasser efter bl.a. kystnærhed. Deponering skal følge anlæggets positivliste, og affaldsproducenten skal sikre en grundlæggende karakterisering. Ved hver modtagelse skal anlægget kontrollere, at affaldet er sorteret og ikke indeholder forbrændingsegnet eller genanvendeligt affald. Fra 1. januar 2023 må blandet affald ikke deponeres på ikke-kystnære anlæg. Godkendelsen skal kræve sikkerhed for nedlukning og en efterbehandling på som udgangspunkt 30 år.' },
      { id: 'NY348', title: 'Bekendtgørelse om Affaldsregistret', org: 'Klima-, Energi- og Forsyningsministeriet', year: 2025, type: 'Lovforslag', temaer: ['Lovgivning og afgørelser', 'Erhverv'], img: 'img/9253440ab42502d759753b9d7a594a0b.jpg', url: 'https://www.retsinformation.dk/api/pdf/251287', res: 'Bekendtgørelse nr. 1066 af 26. august 2025 om Affaldsregistret. Den fastlægger, hvilke affaldsvirksomheder der skal registreres hos Energistyrelsen, og regler for gebyr og tilsyn.', long: 'Bekendtgørelsen fra Klima-, Energi- og Forsyningsministeriet trådte i kraft 1. oktober 2025 og afløser bekendtgørelse nr. 939 fra 2022. Genanvendelsesanlæg med sorteret erhvervsaffald, indsamlingsvirksomheder, transportører, mæglere, forhandlere og visse kommunale behandlingsanlæg skal være registreret, og de fleste må først gå i gang efter registreringen. Indsamlingsvirksomheder skal have mindst én leder med indsamlerbevis. Tilmelding sker digitalt pr. p-nummer, ændringer meldes inden 14 dage, og der betales et årligt gebyr for højst fire produktionsenheder. Drift uden korrekt registrering straffes med bøde.' },
      { id: 'NY349', title: 'Webinar #1 for kommuner om styrket affaldstilsyn: Implementering og gebyrfinansiering', org: 'Miljøstyrelsen', year: 2024, type: 'Oplæg', temaer: ['Erhverv', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/d87c337a6aaa86e56663085e4ca0e226.jpg', url: 'https://mst.dk/media/ub1djtyk/webinar-1-07102004-implementering-og-gebyrfinansiering.pdf', res: 'Miljøstyrelsens slides fra første webinar for kommuner om det styrkede affaldstilsyn fra 2025. De handler om de to faser i indkøringen og om, hvordan tilsynet gebyrfinansieres.', long: 'Webinaret 7. oktober 2024 bygger på den politiske aftale fra august 2022 og en ny bekendtgørelse om affaldstilsyn med ikrafttræden 1. januar 2025. Miljøstyrelsen skal føre ca. 24.000 administrative tilsyn om året, mens kommunerne skal stå for de fleste fysiske tilsyn, ca. 4.800 nye og ca. 9.000 sammen med miljøtilsyn. I 2025 udpeges virksomhederne først via modtagekontrol på forbrændingsanlæg og puljer fra styrelsen og fra august ud fra de administrative tilsyn. Tilsynene skal være 100 % gebyrfinansierede efter forureneren betaler-princippet. Kommunen vælger selv fast takst eller timepris og må regne overhead og transporttid med i gebyret.' },
      { id: 'NY350', title: 'De fysiske affaldstilsyn og tilbagemeldinger til Miljøstyrelsen', org: 'Miljøstyrelsen', year: 2024, type: 'Oplæg', temaer: ['Lovgivning og afgørelser', 'Erhverv'], img: 'img/7200a2a511ec2f2cb632d3a02e996038.jpg', url: 'https://mst.dk/media/l2clsdeo/webinar-3-18112024-de-fysiske-affaldstilsyn-og-tilbagemeldinger-til-miljoestyrelsen.pdf', res: 'Miljøstyrelsen viser i slides fra et webinar i november 2024, hvordan kommunerne fra 2025 skal udføre fysiske affaldstilsyn hos virksomheder og melde resultatet tilbage.', long: 'Webinaret 18. november 2024 var det tredje for kommunerne om det styrkede affaldstilsyn, som bygger på den politiske klimaplan for affald fra august 2022. Miljøstyrelsen skal fra 2025 udføre ca. 24.000 administrative tilsyn om året og udpege ca. 4.800 virksomheder til fysisk tilsyn, som kommunerne for det meste står for. Præsentationen gennemgår forløbet fra udpegning og varsling til dialog, henstilling, indskærpelse, påbud og gebyr, og tilsynet skal i første omgang være vejledende. Senest en måned efter afsluttet tilsyn skal tilsynsmyndigheden indberette generelle oplysninger, udfaldet og eventuelle fejl i Miljøstyrelsens affaldsdata.' },
      { id: 'NY351', title: 'Webinar for kommuner: Bygge- og anlægsaffald', org: 'Miljøstyrelsen', year: 2025, type: 'Oplæg', temaer: ['Byggeaffald', 'Lovgivning og afgørelser', 'Erhverv'], img: 'img/2312fe9bc1f1c29346e3dd38b72e6818.jpg', url: 'https://mst.dk/media/xcphdd0s/webinar-5-11062025-bygge-og-anlaegsaffald.pdf', res: 'Slides fra Miljøstyrelsens webinar i juni 2025 om affaldstilsyn på byggepladser. De gennemgår reglerne om sortering og selektiv nedrivning, og Odense Kommune deler erfaringer.', long: 'Miljøstyrelsen holdt webinaret for kommunerne 11. juni 2025. Præsentationen gennemgår puljerne af affaldstilsyn i 2025, hvor byggeri og nedrivning er et tema, og muligheden for § 8-tilsyn, når puljen er brugt op. Byggepladser skal ikke have P-nummer, så tilsynet rettes mod de virksomheder, der arbejder på pladsen. Fra 1. juli 2025 skal nedrivning af mindst 250 m2 etageareal ske selektivt, og affaldet skal sorteres på stedet. Odense Kommunes affaldsteam anbefaler bl.a. dialog, fotodokumentation og henstillinger ved første tilsyn. Miljøstyrelsen fik i de første fire måneder ca. 60 ansøgninger og henvendelser om klassificering af byggeaffald.' },
      { id: 'NY352', title: 'Webinar for kommuner: Opsamling på tidligere webinarer om styrket affaldstilsyn', org: 'Miljøstyrelsen', year: 2025, type: 'Oplæg', temaer: ['Erhverv', 'Lovgivning og afgørelser'], img: 'img/4cba24fc0fcc41cd815e9f021b8d55f0.jpg', url: 'https://mst.dk/media/4jyl0rtr/webinar-6-23092025-opsamlende-webinar.pdf', res: 'Miljøstyrelsens slides fra et webinar for kommuner om det styrkede affaldstilsyn med virksomheder, der startede i 2025, og om hvordan de fysiske tilsyn udføres og indberettes.', long: 'Præsentationen fra 23. september 2025 samler op på Miljøstyrelsens webinarer om det styrkede affaldstilsyn. Hvert år udvælges 24.000 af ca. 360.000 produktionsenheder til administrativt tilsyn, 60 % via en risikomodel med data fra Affaldsdatasystemet. Kommunerne udfører de fleste af de ca. 4.800 fysiske affaldstilsyn og ca. 9.000 tilsyn sammen med miljøtilsyn, og tilsynene er fuldt gebyrfinansieret. Forbrændingsanlæg skal kontrollere mindst 5 % af læssene hver uge, og fra juli 2025 skal emballeret erhvervsaffald til forbrænding være i klare sække. Et udpeget tilsyn skal gennemføres inden for seks måneder og indberettes senest en måned efter.' },
      { id: 'NY353', title: 'En styrket modtagekontrol', org: 'Miljøstyrelsen', year: 2025, type: 'Oplæg', temaer: ['Lovgivning og afgørelser', 'Erhverv', 'Afsætning og behandling'], img: 'img/18811f0ec342f425a3aa2a6d7842a9dd.jpg', url: 'https://mst.dk/media/alccrwct/sat-praesentation-til-webinar-om-modtagekontrollen-27-02-2025_version-02.pdf', res: 'Slides fra Miljøstyrelsens webinar i februar 2025 om den nye modtagekontrol, hvor forbrændingsanlæg skal afvise og indberette læs med for meget genanvendeligt affald.', long: 'Miljøstyrelsen gennemgik på webinaret den 27. februar 2025 det styrkede affaldstilsyn og reglerne i affaldsbekendtgørelsens nye kapitel 7, der trådte i kraft 1. januar 2025. Forbrændingsanlæggene skal hver uge kontrollere mindst 5 % af de modtagne læs visuelt og afvise læs med mere end et ikke uvæsentligt omfang affald egnet til materialenyttiggørelse. Afvisninger indberettes med fotos til Miljøstyrelsen senest den 5. i den følgende måned. Fra juli 2025 skal emballeret erhvervsaffald afleveres i klare plastsække. Billedeksempler viser både læs med en høj andel af fx plast eller pap og læs, hvor andelen er svær at vurdere.' },
      { id: 'NY354', title: 'Ny affaldsdatabekendtgørelse 1. januar 2026. Webinar for affaldsselskaber og kommuner', org: 'Miljøstyrelsen', year: 2025, type: 'Oplæg', temaer: ['Data, statistikker og nøgletal', 'Lovgivning og afgørelser'], img: 'img/5ce399dac0fb4a4ff7f90f2750f5b46a.jpg', url: 'https://mst.dk/media/ecedw4mv/webinar-om-ny-affaldsdatabekendtgoerelse_for-kommuner-og-affaldsselskaber_291025.pdf', res: 'Slides fra Miljøstyrelsens webinar 29. oktober 2025 om den nye affaldsdatabekendtgørelse. Fristen for indberetning til Affaldsdatasystemet rykkes frem til 1. februar.', long: 'Miljøstyrelsen gennemgik for kommuner og affaldsselskaber den nye affaldsdatabekendtgørelse, der ifølge styrelsen træder i kraft 1. januar 2026. Indberetningsfristen flyttes fra 1. marts til 1. februar, så data for 2025 skal indberettes inden 1. februar 2026. Kommunerne kan validere og rette data om aktører i egen kommune fra 1. februar til 30. marts, og affaldsproducenter kan tjekke deres data i Mit Affaldsoverblik. Affaldsfraktionskoderne (H/E) bliver opdateret. En præcisering af indberetningspligten for husholdningsaffald blev taget ud efter høringen, men Miljøstyrelsen mener fortsat, at kommunernes indsamling er indberetningspligtig.' },
      { id: 'NY355', title: 'Erfaringer med sortering af dansk husholdningsplast og fejlsortering', org: 'ReSource Denmark', year: 2026, type: 'Oplæg', temaer: ['Sorteringskvalitet', 'Afsætning og behandling', 'Reel genanvendelse'], img: 'img/023b7b8adeacc89833d35d4a1cb2ac45.jpg', url: 'https://plast.dk/wp-content/uploads/2026/05/LOOP-praesentation-Resource-29.-april-2026.pdf', res: 'Sorteringsanlægget ReSource Denmark udsorterer ca. 90 % af den sorterbare plast fra danske husholdninger, men fejlsortering sender alt for meget til forbrænding.', long: 'Flemming Horn Nielsen fra ReSource Denmark (Viridor) holdt oplægget på LOOP den 29. april 2026. Anlægget modtager ca. 2.000 tons plast om ugen fra 80 lastbiler, og for første gang håndterer Danmark selv al sin husholdningsplast i første led. Den reelle genanvendelse er over 60 %, men alt for meget går til forbrænding på grund af fejlsortering. Af det fejlsorterede er 40 % pap, papir og karton. Høj fugt, især om vinteren og i baller lagret udendørs, skader genanvendelsen, og store metalemner giver problemer, hvor plast og metal deler kammer. Kommunerne bedes finde ud af, hvor forureningen sker, for det kan ikke kun være hos borgerne.' },
      { id: 'NY356', title: 'Kan det betale sig at kildesortere plast fra husholdninger', org: 'DTU Sustain', year: 2026, type: 'Oplæg', temaer: ['Reel genanvendelse', 'Afsætning og behandling'], img: 'img/101215484efaa3739d047106a789f51a.jpg', url: 'https://plast.dk/wp-content/uploads/2026/05/LOOP-Plastindustrien-Anders-Damgaard.pdf', res: 'Debatoplæg fra DTU Sustain om plast fra kildesortering og fra sortering af restaffald. Konklusionen er, at sortering af restaffald kan supplere, men ikke erstatte kildesortering.', long: 'Anders Damgaard, lektor ved DTU Sustain, holdt oplægget på LOOP Forum 2026 i april. Slidene sammenligner de to systemer med tal fra Emballagestatistikken 2023 og et studie fra 2026 om udsortering fra restaffald og spørger, hvad man gør, når procenterne ikke kan sammenlignes. Sortering af restaffald giver mindre rene og blandede 2D- og 3D-strømme med risiko for at blande polymerer. Oplægget peger også på lovkrav til kemisk sammensætning, som er strenge for fødevareemballage og legetøj, og spørger, hvem der sikrer en aftager til plasten fra restaffald, og hvem der betaler for anlæggene.' },
      { id: 'NY357', title: 'Kan det betale sig at kildesortere plast fra husholdninger? Er der kvalitetsforskel?', org: 'Norion Consult', year: 2026, type: 'Oplæg', temaer: ['Analyser og undersøgelser', 'Reel genanvendelse', 'Afsætning og behandling'], img: 'img/90671244040e44defc1a2853dcbdb58b.jpg', url: 'https://plast.dk/wp-content/uploads/2026/05/Praesentation-LOOP-Norion.pdf', res: 'Norion Consult sammenholder 14 studier af plast fra kildesortering og centralsortering. Kildesortering giver oftest bedst kvalitet, mens økonomi og klimaeffekt er usikre.', long: 'Aske Nydam Guldberg fra Norion Consult holdt oplægget den 28. april 2026. Han gennemgår 14 studier af kvaliteten af genanvendt plast fra kildesortering og centralsortering på fem parametre, bl.a. kemisk forurening (NIAS). De store analyser fra 2019-2022 antog samme pris og kvalitet for begge sorteringer, og det holder sandsynligvis ikke længere. Siden er plastmarkedet i EU gået i gulvet, og der kildesorteres bedre end ventet. De fleste data peger på bedre kvalitet ved kildesortering, og med et risikoperspektiv er konklusionen klar. Økonomisk er det usikkert, hvad der er bedst, men han gætter på, at centralsortering stadig er billigst.' },
      { id: 'NY358', title: 'Separate end-of-life textile collection, sorting and solutions: learnings from Finland', org: 'Lounais-Suomen Jätehuolto', year: 2023, type: 'Oplæg', temaer: ['Tekstil', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/761b2bc0333386f36e629466be875c8c.jpg', url: 'https://mst.dk/media/0p4d1234/separate-end-of-life-textile-collection-sorting-and-solutions-learning-from-finland-by-anna-garton.pdf', res: 'Det finske affaldsselskab LSJH fortæller om særskilt indsamling af tekstilaffald, som har været krav i Finland siden 2023. Manuel forsortering er en forudsætning for kvaliteten.', long: 'Anna Garton fra Lounais-Suomen Jätehuolto, der ejes af 18 kommuner i Sydvestfinland, fortæller om landets kommunale model. 25 affaldsselskaber dækker 95 % af befolkningen og indsamler og forsorterer lokalt, mens LSJH kvalitetssorterer og sælger råvarer til industrien. Netværket voksede fra 2,3 mio. indbyggere og 399 ton behandlet tekstil i 2020 til 4,5 mio. og 743 ton i 2022, og indsamlingen lå på 0,35 kg pr. person. Erfaringerne er, at automatisk sortering ikke kan erstatte manuel forsortering, og at der endnu mangler et etableret marked for materialerne. Et sorteringsanlæg til 10.000 ton om året og 20-25 mio. euro er i spil til 2025-2026.' },
      { id: 'NY359', title: 'What can we learn from the textiles in the waste bin', org: 'Aalborg Universitet', year: 2023, type: 'Oplæg', temaer: ['Tekstil', 'Analyser og undersøgelser', 'Direkte genbrug'], img: 'img/b737c59d598eeba23323c6d2ae1cbcea.jpg', url: 'https://mst.dk/media/mdvgrktt/what-can-we-learn-from-the-textiles-in-the-waste-bin-and-why-is-waste-management-not-a-sufficient-solution-to-overconsumption-by-nynne-noerup.pdf', res: 'Oplæg fra Aalborg Universitet om tekstiler i restaffald og småt brændbart. Der smides i snit 6,2 kg tekstiler ud pr. borger, og 77-83 % kunne genbruges eller genanvendes.', long: 'Nynne Nørup fra Aalborg Universitet holdt oplægget 26. oktober 2023 og viser resultater fra sine sorteringsanalyser, publiceret i 2018 og 2019. Restaffaldet indeholdt 1,4 % tøj og 0,6 % boligtekstiler, og småt brændbart 4,5 % tøj og 2,5 % boligtekstiler. Det svarer til 6,2 kg pr. borger, eller lidt over 40 % af det årlige forbrug af tøj og boligtekstiler. Mellem 65 og 69 % af tekstilerne kunne genbruges og 12-16 % genanvendes, så lidt over 27 % af det årlige forbrug kunne spares. Hun konkluderer, at affaldshåndtering ikke løser overforbruget, da systemet er lineært og vægter mængde over kvalitet.' },
      { id: 'NY360', title: 'Reuse and resale of textiles: how we do it at Kierrätyskeskus Oy', org: 'Kierrätyskeskus', year: 2024, type: 'Oplæg', temaer: ['Tekstil', 'Direkte genbrug'], img: 'img/7877c1398b766c0e8366682234d9a0ea.jpg', url: 'https://mst.dk/media/uzpdusbk/reuse-and-resale-of-textiles_how-we-do-it-at-kierraetyskeskus-by-anu-hakala.pdf', res: 'Genbrugscentret Kierrätyskeskus i Helsinki-området viser, hvordan det sorterer og sælger brugte tekstiler. I 2023 gik 84 % af ca. 850.000 kg tekstiler til genbrug.', long: 'Anu Hakala fra Kierrätyskeskus holdt oplægget på Nordic Textile Collaboration i marts 2024. Den almennyttige virksomhed fra 1990 har 13 genbrugsbutikker i hovedstadsområdet og en webshop. Alle tekstildonationer går gennem et sorterings- og logistikcenter i Espoo, der behandler ca. 16.000 kg om ugen. I 2023 blev 42 % af tekstilerne solgt og 42 % givet væk gratis, mens 16 % gik til energiudnyttelse og genanvendelse. Intet blev eksporteret. Butikkerne sælger ca. 7.200 tekstiler om ugen. Upcycling og håndplukkede kollektioner fylder lidt, og tøj sælger dårligt online på grund af konkurrencen.' },
      { id: 'NY361', title: 'Temadag om selskabsgørelse', org: 'KL', year: 2023, type: 'Oplæg', temaer: ['Ledelse', 'Lovgivning og afgørelser', 'Økonomi'], img: 'img/e002fd40efb3dad2091220af76cafd72.jpg', url: 'https://cirkulaer.dk/files/media/document/03%20KL%20selskabsg%C3%B8relse.pdf', res: 'KL’s oplæg fra en temadag om selskabsgørelse. KL mener, at selskabsgørelse af alle kommunale affaldsydelser er at skyde gråspurve med kanoner og vil blive dyrt for borgerne.', long: 'Chefkonsulent Anders Christiansen fra KL holdt oplægget på en temadag. Præsentationen viser forløbet fra klimaplanen i juni 2020 og den opfølgende aftale fra august 2022, der lægger op til at selskabsgøre genanvendelsesanlæg, forbrænding og kommunernes affaldsydelser, mens deponier skal undersøges nærmere. KL er enig i, at konkurrenceforvridningen skal løses, men mener, at en momsrefusionsordning var bedre og ville sænke gebyret. Oplægget lister åbne spørgsmål, fx hvilke ydelser der er omfattet, og hvem der skal lave regulativer og affaldsplan og opkræve gebyrer. Det nævner også, at 63 anlæg har søgt dispensation hos Forsyningstilsynet.' },
      { id: 'NY362', title: 'Selskabsgørelse af affaldsydelser. Hvad siger Dansk Affaldsforening?', org: 'Brancheforeningen Cirkulær', year: 2023, type: 'Oplæg', temaer: ['Lovgivning og afgørelser', 'Ledelse', 'Økonomi'], img: 'img/11a2a656f1c61a5dd6ef9b53f05f8114.jpg', url: 'https://cirkulaer.dk/files/media/document/04%20Dansk%20Affaldsforening%20selskabsg%C3%B8relse.pdf', res: 'Dansk Affaldsforenings oplæg om den aftalte selskabsgørelse af kommunale affaldsydelser, som skal gøre indsamlingen momspligtig. Det omtaler også prisloftet på affaldsgebyrerne.', long: 'Dansk Affaldsforenings slides gennemgår aftalen fra august 2022 om selskabsgørelse, som skal gøre kommunal affaldsindsamling momspligtig, efter at Landsskatteretten i oktober 2020 afgjorde, at kommunerne ikke må opkræve moms på affaldsydelser. Ordningen skulle træde i kraft i 2024 og kan omfatte 48 kommuner og 18 kommunale fællesskaber. Driftsansvar og kundeforhold flyttes til et selskab, mens myndighedsopgaven bliver i kommunen. Oplægget nævner også kodeks for god selskabsledelse og opfølgningsaftalen, hvor Forsyningstilsynet fra 2025 skal føre tilsyn med gebyrerne og udmelde prislofter efter en overgang på to år.' },
      { id: 'NY363', title: 'Nyt om affald: Webinar den 11. maj 2023', org: 'Advokatfirmaet Energi & Miljø', year: 2023, type: 'Oplæg', temaer: ['Lovgivning og afgørelser', 'Afsætning og behandling', 'Udvidet producentansvar'], img: 'img/cdbb50ccfa2ba4acc197f41aa357680e.jpg', url: 'https://energiogmiljo.dk/wp-content/uploads/2023/05/11-05-2022-morgenmoede-og-webinar-nyt-om-affald-samlet-v-10-maj-2023-003.pdf', res: 'Slides fra Advokatfirmaet Energi & Miljøs webinar i maj 2023 om lovforslag L 115 om affaldsforbrænding, afhændelse af kommunale anlæg, prisloft for affaldsvarme og producentansvar.', long: 'Oplægget gennemgår L 115 fra 26. april 2023, der foreslår forbrændingsanlæg udskilt i selskaber senest 1. januar 2025 og udbud af kommunalt indsamlet forbrændingsegnet affald med kontrakt senest 1. juli 2025. Kommunerne skal afhænde selskaber med anlæg til materialenyttiggørelse senest 1. januar 2027, og prisloftet for affaldsvarme er 83 kr. pr. GJ i 2023 og ventes omkring 74 kr. i 2024. Blandt nyhederne er Miljøstyrelsens præcisering af, at kommunen frit kan vælge husstandsindsamling eller husstandsnær indsamling som henteordning. Et notat til Dansk Affaldsforening vurderer foreløbigt, at L 115 i enkelte tilfælde kan udgøre ekspropriation.' },
      { id: 'NY364', title: 'Juridiske nyheder på affaldsområdet. Webinar den 14. december 2023', org: 'Advokatfirmaet Energi & Miljø', year: 2023, type: 'Oplæg', temaer: ['Lovgivning og afgørelser', 'Byggeaffald', 'Økonomi'], img: 'img/8a80e5c6f3dc5705d86f96238377dc83.jpg', url: 'https://energiogmiljo.dk/wp-content/uploads/2023/12/morgenmoede-affald-endelig.pdf', res: 'Slides fra Energi & Miljøs webinar i december 2023 om bl.a. prisloft for affaldsvarme, blokmodregning, selskabsgørelse, kommunale lånegarantier og selektiv nedrivning.', long: 'Advokatfirmaet Energi & Miljø gennemgik på et webinar 14. december 2023 nyt på affaldsområdet. Prisloftet for affaldsvarme er 114 kr./GJ i 2024, mens et nyt VE-prisloft på anslået 70-73 kr./GJ er udskudt. Slides viser, hvornår omstruktureringer kan udløse modregning i bloktilskuddet, og at lovprogrammet 2023-2024 ikke rummer selskabsgørelse af affaldsområdet. Lovforslaget om selektiv nedrivning skal give hjemmel til krav om nedrivningsplaner og autoriserede nedrivningsvirksomheder, bl.a. ved fjernelse af mindst 250 m2 etageareal. Sidst omtales Skattestyrelsens styresignal om, at kommuner ikke skal opkræve moms på renovationsydelser.' },
      { id: 'NY365', title: 'Circular construction in Europe: Handbook for local and regional governments', org: 'ICLEI', year: 2023, type: 'Vejledning', temaer: ['Byggeaffald', 'Cirkulær økonomi', 'Udbud og kravspecifikationer'], img: 'img/83aca47a4da762862d869a0d5b6dfcdb.jpg', url: 'https://rucforsk.ruc.dk/ws/files/97775882/City-Loops-Circular-Construction-handbook.pdf', res: 'Håndbog fra EU-projektet CityLoops om, hvordan kommuner kan gøre byggeri og nedrivning mere cirkulært, med erfaringer fra bl.a. Roskilde og Høje-Taastrup.', long: 'ICLEI har skrevet håndbogen med bidrag fra bl.a. Roskilde Universitet og Region Hovedstaden. Den bygger på CityLoops, hvor syv europæiske byer i fire år afprøvede over 30 nye værktøjer til bygge- og anlægsaffald inkl. jord og til bioaffald. Kapitel 3 følger værdikæden fra byplanlægning over kortlægning før nedrivning og selektiv nedrivning til markeder for genbrugsmaterialer og nyt byggeri. Høje-Taastrup bygger det gamle rådhus om til boliger i stedet for at rive det ned og sparer ca. 20.000 ton naturressourcer og 2.000 ton CO2. Roskilde har lavet en guide til lokal genanvendelse af beton med krav, der kan bruges direkte i udbud.' },
      { id: 'NY366', title: 'Re-Plastic: Framework conditions and industrial adaptation of the EPR-scheme in Denmark', org: 'Roskilde Universitet', year: 2024, type: 'Rapport', temaer: ['Udvidet producentansvar', 'Afsætning og behandling', 'Cirkulær økonomi'], img: 'img/5735cfa3c4c1a90dee157b015d80b659.jpg', url: 'https://rucforsk.ruc.dk/ws/files/107002582/FINAL_Re-Plastic_Innovation_Fund_Rikke_Lyb_k_2024.pdf', res: 'Forskningsrapport fra Roskilde Universitet om producentansvar for plastemballage i Danmark. Den anbefaler én kollektiv ordning og ensartet sortering af plast i kommunerne.', long: 'Rikke Lybæk skrev rapporten i januar 2024 i Re-Plastic-projektet, støttet af Innovationsfonden. Den gennemgår dansk affaldsregulering siden 1973 og erfaringer med producentansvar i andre EU-lande og bygger på casestudier hos Damifo, Færch og Gibo. Ifølge rapporten genanvendes kun 17,2 % af plastemballagen fra danske husholdninger. Producentansvaret bør samles i én kollektiv ordning under Dansk Producent Ansvar, og ecodesign og gebyrmodulering skal fremme mere miljøvenlige produkter. Virksomhederne efterspørger ensartede regler og renere plast, og Danmark mangler kapacitet til at sortere og oparbejde plast, især til fødevareemballage.' },
      { id: 'NY367', title: 'Caretakers as mediators in household waste separation', org: 'Aarhus Universitet', year: 2021, type: 'Analyse', temaer: ['Etageboliger', 'Sorteringskvalitet'], img: 'img/c6aa073ada7a91f902be5685a6a1cf3c.jpg', url: 'https://pure.au.dk/ws/files/443552017/Caretakers_JEPP_greenOA-Pure.pdf', res: 'Videnskabelig artikel om viceværternes rolle i affaldssortering i københavnske etageboliger. De eftersorterer fejl og flytter beholdere, så nye ordninger fungerer i hverdagen.', long: 'Lars Kjerulf Petersen fra Aarhus Universitet bygger artiklen på 19 interviews med 22 viceværter fra to projekter i København i 2015 og 2017, suppleret med beboerinterviews og spørgeskemaer. I en beboerundersøgelse er 87 % enige i, at affaldet skal genanvendes, og de fleste viceværter vurderer, at ca. 80 % af beboerne sorterer korrekt det meste af tiden. Viceværterne flytter fulde beholdere og eftersorterer synlige fejl, mens skakter og Longopac-poser giver tungt og uhygiejnisk arbejde. Nogle irettesætter beboere direkte. Konklusionen er, at viceværter især stabiliserer og forankrer nye ordninger lokalt frem for at drive forandringen.' },
      { id: 'NY368', title: 'Cirkulær økonomi i lokalsamfund: Inspiration til cirkulære samfund', org: 'Aalborg Universitet', year: 2025, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Direkte genbrug'], img: 'img/d4347e5f47c48d7a526b969af03aed1f.jpg', url: 'https://vbn.aau.dk/ws/files/791373768/2025_Cirkul_r_konomi_i_lokalsamfund_AAU.pdf', res: 'Inspirationshæfte fra projektet Cirkulær Ø om lokale genbrugs- og deleordninger på småøerne. Det opfordrer kommuner og affaldsselskaber til at samarbejde med lokalsamfundene.', long: 'Forskere fra Aalborg Universitet undersøgte i 2022-2024 cirkulære initiativer på småøerne sammen med bl.a. Genskabet på Orø og Fællesskabet Fanø. En screening af bl.a. de 27 øer i Sammenslutningen af Danske Småøer viser færre sorteringsmuligheder på øerne end i andre lokalsamfund. Genskabet på Orø henter ting fra en container på Fors\' genbrugsplads, driver genbrugsbutik og værksteder og udlåner billigt festudstyr. Foreningen er meget afhængig af enkeltpersoner og har svært ved at skaffe finansiering. Forfatterne mener, at selskabsgørelse og snævre effektivitetsmål gør det svært for affaldsselskaber at støtte sådanne initiativer.' },
      { id: 'NY369', title: 'Analyse af transport af containere fra genbrugspladser', org: 'Aarhus Universitet', year: 2020, type: 'Analyse', temaer: ['Genbrugspladser', 'Teknologi', 'Analyser og undersøgelser'], img: 'img/4b540cf9974ac6ac9216a4c7ac2aab3d.jpg', url: 'https://pure.au.dk/ws/files/199735349/Analyse_af_transport_af_containere_fra_genbrugspladser_generel.pdf', res: 'Aarhus Universitet har regnet på fleksibel returnering af containere fra genbrugspladser. Det sparer i gennemsnit 8,2 % af de kørte km og en rute i ca. 10 % af tilfældene.', long: 'Sanne Wøhlk fra Aarhus Universitet sammenligner i analysen fra oktober 2020 to måder at køre containere fra genbrugspladser på. I den faste model kommer hver container tilbage til samme plads, i den fleksible kan containere af samme type byttes rundt. Data kommer fra fire områder med 8-24 genbrugspladser og 8-18 modtageanlæg, i alt 989 datasæt, og en optimeringsalgoritme med 8 timers arbejdsdag er kørt 25 gange pr. scenarie. Fleksibel returnering sparede en rute i 104 af de 989 datasæt og i gennemsnit 8,2 % af de kørte km, mest når der var få containere. Med færre containertyper steg besparelsen kun lidt, til 8,8 og 9,4 %.' },
      { id: 'NY370', title: 'A.L.I.C.E. in Waste Wonderland', org: 'Aalborg Universitet', year: 2026, type: 'Analyse', temaer: ['Genbrugspladser', 'Direkte genbrug', 'Byggeaffald'], img: 'img/5f8acf8c0e468624b5aa16fdea355a72.jpg', url: 'https://vbn.aau.dk/ws/files/837799470/ALICE_in_Waste_Wonderland_EMSS4_Thesis.pdf', res: 'Speciale fra Aalborg Universitet om genbrug af byggematerialer fra Nordværks genbrugspladser. Potentialet afhænger mere af organisering og aftagere end af selve materialerne.', long: 'Tre studerende fra Aalborg Universitet har sammen med Nordværk undersøgt, hvordan affald fra genbrugspladserne i Aalborg Kommune kan forberedes til genbrug som byggematerialer. Med Action Design Research blev værktøjet ALICE udviklet gennem interview, feltarbejde på to genbrugspladser, workshops og en affaldsanalyse. I en prøve på 8.160 kg indendørs træ var 360 kg egnet til direkte genbrug og 240 kg til forberedelse til genbrug. Ledelsen vægter aftagere og dokumentation, mens driftspersonalet peger på borgeradfærd, tid, plads og sikkerhed. Genbrugsvejlederne mangler rammer til at deltage, og forfatterne anbefaler afgrænsede forsøg.' },
      { id: 'NY371', title: 'Waste Prevention in Danish Municipalities', org: 'Aalborg Universitet', year: 2024, type: 'Analyse', temaer: ['Cirkulær økonomi', 'Affaldsplaner/regulativer og strategi', 'Direkte genbrug'], img: 'img/f5cafeee5f90a6ed5f58e5c8167f62d4.jpg', url: 'https://vbn.aau.dk/ws/files/680680818/Emily_Rose_Lloyd_Krasuski_SusCi_4_Master_s_Thesis_2024.pdf', res: 'Speciale fra Aalborg Universitet, der kortlægger danske kommuners tiltag for affaldsforebyggelse og finder, at dansk affaldspolitik prioriterer genanvendelse over forebyggelse.', long: 'Emily Rose Lloyd Krasuski har i specialet fra Sustainable Cities (marts 2024) kortlagt kommunale tiltag for affaldsforebyggelse ud fra desk research, klimahandlingskortet fra DN, Gate 21 og AAU og interview med Frederiksberg, Gentofte, Albertslund og Rødovre kommuner samt Vestforbrænding. De fleste tiltag bremser ressourcestrømmen, fx repair cafeer og byttestationer, mens dansk og EU-politik især satser på genanvendelse. Kommunerne kan primært fremme forebyggelse gennem genbrug og kommunikation. Som løsninger diskuterer specialet et ændret affaldshierarki og et strammere producentansvar suppleret med en juridisk ramme for produkter.' },
      { id: 'NY372', title: 'Waste Prevention from a municipal perspective - a case study of Hjørring Municipality', org: 'Aalborg Universitet', year: 2023, type: 'Analyse', temaer: ['Direkte genbrug', 'Tekstil', 'Cirkulær økonomi'], img: 'img/acd6b12e1dc2cff0d2c97ea072ab3aec.jpg', url: 'https://vbn.aau.dk/ws/files/538655972/Anne_Louise_Koch_EMSS6_student_nr._20283442_title_Waste_Prevention_from_a_municipal_perspective_a_case_study_of_Hjorring_Municipality_.pdf', res: 'Kandidatspeciale om, hvad Hjørring Kommune kan gøre for at forebygge affald. Kommunen kan sætte noget i gang for tøj, mens regler og økonomi spænder ben for store hvidevarer.', long: 'Specialet er skrevet på Aalborg Universitet i 2023 med Hjørring Kommune som case. Det gennemgår EU\'s og Danmarks regler for affaldsforebyggelse og bruger tøj og store hvidevarer som eksempler. Aktørerne blev fundet ved en brainstorm med kommunen, og fem blev interviewet, blandt andre Repair Café Danmark og Nordværk. Kommunerne har ikke pligt til affaldsforebyggelse og må ikke betale for den med affaldsgebyret. For tøj foreslås en Repair Café, årlige arrangementer med folkeskoler, samarbejde med velgørende organisationer og mere information. For hvidevarer står reglerne i vejen, og lov nr. 898 forhindrer Nordværk i selv at reparere dem.' },
      { id: 'NY373', title: 'Circular Communities in Holbæk Municipality', org: 'Aalborg Universitet', year: 2026, type: 'Rapport', temaer: ['Cirkulær økonomi', 'Direkte genbrug'], img: 'img/6968b7ea932190d55b1f256504e8fcf8.jpg', url: 'https://vbn.aau.dk/ws/files/841365835/Master_Thesis_Circular_Communities_in_Holbak_Municipality_04_06_2026.pdf', res: 'Kandidatspeciale fra Aalborg Universitet om tre lokale fællesskaber for genbrug og forebyggelse i Holbæk. Kommunen og Fors kan støtte dem mere aktivt, fx med netværk og tilskud.', long: 'Specialet er skrevet på Sustainable Cities ved Aalborg Universitet i 2026. Det undersøger Repair Cafe Holbæk, Ét Grønt Holbæk og Genskabet på Orø ud fra interviews med frivillige og med medarbejdere i kommunen og Fors samt feltobservationer. Fællesskaberne kan fremme genbrug og forebyggelse, men de har brug for ressourcer og netværk for at blive stabile. Affaldssystemet er bygget op om genanvendelse og forbrænding, og det gør det svært for kommunen at støtte dem. Specialet anbefaler kommunen og Fors en mere opsøgende rolle med netværk, tilskud til lokale initiativer, reparationscaféer på genbrugspladserne og samarbejde med andre kommuner.' },
      { id: 'NY374', title: 'Sorting of Food Waste in Households on Bornholm', org: 'Aalborg Universitet', year: 2022, type: 'Analyse', temaer: ['Sorteringskvalitet', 'Hente- og bringeordninger', 'Afsætning og behandling'], img: 'img/773209b54fbacfa274a86cd50c8f4403.jpg', url: 'https://vbn.aau.dk/ws/files/475236124/Sorting_of_food_waste_in_households_on_Bornholm.pdf', res: 'Kandidatspeciale fra Aalborg Universitet om, hvordan BOFA kan hjælpe husholdninger på Bornholm med at sortere madaffald. Jo mere der sorteres til biogas, jo bedre for miljøet.', long: 'Tre studerende fra Sustainable Design har i 2022 i samarbejde med BOFA kombineret praksisteori og etnografiske metoder med en livscyklusvurdering. Fem husstande i Bo42 i Rønne testede sorteringssæt, og 178 borgere svarede på et spørgeskema. Af dem sorterede 66,3 % ikke madaffald, og 57,3 % følte sig ikke klar til den nye ordning, især på grund af manglende information. Livscyklusvurderingen af ca. 3.000 ton madaffald om året viser, at sortering til biogas giver den bedste miljøprofil, også med transport væk fra øen. Anbefalingerne til BOFA spænder fra inspirationskatalog og trækvogne til bedre information og inddragelse af husstandene.' },
      { id: 'NY375', title: 'Circularity in the Danish WEEE Management System', org: 'Aalborg Universitet', year: 2022, type: 'Rapport', temaer: ['Direkte genbrug', 'Udvidet producentansvar', 'Cirkulær økonomi'], img: 'img/f7d984c7e4e70f45c952f48ff58fe087.jpg', url: 'https://vbn.aau.dk/ws/files/473470131/Thesis_WEEE_IdzerdaSybren.pdf', res: 'Kandidatspeciale fra Aalborg Universitet om, hvorfor elektronikaffald i Danmark næsten altid genanvendes frem for at blive genbrugt, og hvordan forberedelse til genbrug kan øges.', long: 'Sybren Idzerda skrev specialet i 2022 på baggrund af 20 fagartikler og interview med forskere, Dansk Producentansvar, affaldsselskabet AVV og Nilfisk. Danske tal fra 2015 viser, at kun 0,2 % af det indsamlede elektronikaffald blev genbrugt, mens 83,9 % blev genanvendt. Barriererne er bl.a. dybe containere på kommunernes pladser, hvor udstyret ofte ødelægges, en fastlåsning til genanvendelsesteknologi, svage økonomiske incitamenter og lav tillid til brugte produkter. Hovedanbefalingen er et samlet netværk af genbrugscentre efter forbillede af De Kringwinkel i Flandern, suppleret af miljøgraduerede gebyrer og mærkning af produkterne.' },
      { id: 'NY376', title: 'High-Resolution Mapping of the Nordic Plastic Cycle', org: 'Syddansk Universitet', year: 2025, type: 'Analyse', temaer: ['Reel genanvendelse', 'Afsætning og behandling', 'Data, statistikker og nøgletal'], img: 'img/4dee4d610c21679b39fd5ebfa0dec3ed.jpg', url: 'https://findresearcher.sdu.dk/ws/files/302460026/acssusresmgt.pdf', res: 'Forskere fra bl.a. Syddansk Universitet har kortlagt plaststrømmene i Norden 1978-2020. Under 6 % af plastaffaldet genanvendes, og kapaciteten bør udvides kraftigt frem mod 2050.', long: 'Artiklen i ACS Sustainable Resource Management bygger på en dynamisk materialestrømsmodel for 14 polymergrupper i de fem nordiske lande. I 2020 var der ca. 1.100 kg plast i brug pr. indbygger, importen oversteg langt egenproduktionen, og over 70 % af det affald, landene selv behandlede, blev brændt. Danmark havde 890.000 tons plastaffald, og i hele regionen blev 3,7 mio. tons ikke genanvendt. Øget mekanisk genanvendelse kan dække 27 % af efterspørgslen i 2050, men kræver ca. 6,7 gange den nuværende kapacitet. Kemisk genanvendelse kan teoretisk give yderligere 22 %, men regionen mangler industri og har brug for internationalt samarbejde.' },
      { id: 'NY377', title: 'Miljøvurdering og emballageflows for e-handlen i Danmark', org: 'Miljøstyrelsen', year: 2023, type: 'Analyse', temaer: ['Klima', 'Analyser og undersøgelser', 'Cirkulær økonomi'], img: 'img/e21ee75f409f9f4f6471f20efc2b6b65.jpg', url: 'https://www2.mst.dk/Udgiv/publikationer/2023/01/978-87-7038-474-2.pdf', res: 'NIRAS og Econet anslår for Miljøstyrelsen, at dansk e-handel bruger ca. 33.000 ton forsendelsesemballage og fyld om året. Materialevalg og mængde betyder mest for klimaet.', long: 'Kortlægningen bygger på Dansk Erhvervs tal for 170 mio. e-handler med fysiske varer i 2021, 11 interviews, to workshops og egne vejninger fordelt på 14 produktkategorier. Mængden fordeler sig på ca. 28.000 ton pap, 2.000 ton papir og 3.000 ton plast, men tallet hviler på et spinkelt datagrundlag. En miljøvurdering af to cases viser, at transporten fylder langt mindre i klimaaftrykket end emballagen. Papirposer er at foretrække frem for plastposer, og genbrugspapkasser frem for engangspapkasser. Tre scenarier anslår besparelser på 529 til 960 ton CO2e, fx 840 ton ved at skifte plastposer til papirposer for tøj og sko.' },
      { id: 'NY378', title: 'Fyldningsgrad for beholdere til Restaffald, 2026', org: 'Ballerup Kommune', year: 2026, type: 'Analyse', temaer: ['Haveboliger/parcelhuse', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/467a96eeda61c0b3a922f0614fdbdae2.jpg', url: 'https://dagsorden.ballerup.dk/vis/pdf/bilag/d9a21304-c7e4-4210-88b2-fdcb5ea49825', res: 'Econet har målt restaffaldet i villaernes beholdere i Ballerup efter skiftet til tømning hver 14. dag. I gennemsnit bruges 72 af 144 liter, og 99 % af villaerne har plads nok.', long: 'Ballerup Kommune fik Econet til at gentage målingen fra 2023 for at se, om tømning hver 14. dag giver villaerne plads nok til restaffald. Restaffaldsrummet på 144 liter i den todelte 240 liters beholder blev målt på tømmedagen hos 194 villaer i Ballerup, Måløv og Skovlunde. Vægtet efter kommunens husstande er behovet 72 liter pr. tømning, svarende til 36 liter om ugen mod 47 liter i 2023, et fald på 23 %. Kun én beholder var overfyldt, mens 14 % var fyldte, ofte med bleer. Econet vurderer, at frekvensen er tilstrækkelig, og foreslår, at kommunen overvejer at tilbyde en 390 liters beholder på fire hjul af hensyn til arbejdsmiljøet.' },
      { id: 'NY379', title: 'Fyldningsgrad for beholdere til Restaffald, 2023. Ballerup Kommune', org: 'Ballerup Kommune', year: 2023, type: 'Analyse', temaer: ['Haveboliger/parcelhuse', 'Hente- og bringeordninger', 'Analyser og undersøgelser'], img: 'img/60f06daf8285513d1e6beec848ca2bb1.jpg', url: 'https://dagsorden.ballerup.dk/vis/pdf/bilag/1932da31-937d-4ed4-b873-e10fbbdcd742', res: 'Måling hos 189 villaer i Ballerup viser, at husstandene ved ugetømning i snit bruger 50 af de 144 liter til restaffald, og at 77 % kunne klare sig med tømning hver 14. dag.', long: 'Econet målte i foråret 2023 for Ballerup Kommune fyldningsgraden i restaffaldsrummet hos 198 villaer i Ballerup, Måløv og Skovlunde, efter at kommunen havde uddelt beholdere til pap. De fleste har en todelt 240 liters beholder med 144 liter til restaffald. Den gennemsnitlige fyldningsgrad var 0,35, og 8 % af villaerne havde en tom beholder. Husstande med en eller to personer brugte ca. 35 liter om ugen, større husstande 71-72 liter. Econet anbefaler tømning hver 14. dag, så den ekstra plads ikke fyldes med pap, haveaffald og andet, der kan sorteres, og en ekstra beholder til dem, der mangler plads.' },
      { id: 'NY380', title: 'Analyse af restaffald fra to sommerhusområder', org: 'Hjørring Kommune', year: 2021, type: 'Analyse', temaer: ['Sommerhuse og kolonihaver', 'Sorteringskvalitet', 'Hente- og bringeordninger'], img: 'img/f8029ef25812cca2a7ad638a7e44366c.jpg', url: 'https://dagsordener.hjoerring.dk/vis/pdf/bilag/7152d989-73b6-45ce-b29c-ed3da3b8f020', res: 'Econet sorterede restaffald fra sommerhuse i Lønstrup og Tversted. Ved de nedgravede fællesløsninger kunne 45 % have været sorteret fra, mod 35 % ved husstandsbeholderne.', long: 'Hjørring Kommune ville vide, hvilket affaldssystem der får folk i sommerhusområder til at sortere mest. Econet sorterede derfor i august 2021 stikprøver på 396 kg restaffald fra Lønstrup, hvor der er nedgravede affaldsøer med fem fraktioner, og 326 kg fra Tversted, hvor hvert hus har to todelte beholdere. Madaffald var den største genanvendelige fraktion med ca. 30 % i Lønstrup og 23 % i Tversted, og tørre genanvendelige fraktioner udgjorde ca. 14 % mod 10 %. Til gengæld lå der mere glas i restaffaldet i Tversted, hvor glas ikke hentes ved huset. Econet peger på afstanden til beholderne som en mulig forklaring.' },
      { id: 'NY381', title: 'Affald fra énfamilieboliger før og under forsøg med øget kildesortering i Gundsømagle, Roskilde', org: 'Roskilde Kommune', year: 2021, type: 'Evaluering', temaer: ['Hente- og bringeordninger', 'Haveboliger/parcelhuse', 'Sorteringskvalitet'], img: 'img/c62da705e5f2ce63bcea0b670fe5d7bf.jpg', url: 'https://dagsordener.roskilde.dk/vis/pdf/bilag/6fff5e46-7dca-4385-91de-1c70c8c4d152', res: 'Econet undersøgte for Roskilde Kommune affald fra 203 husstande i Gundsømagle før og under et forsøg med ti fraktioner. Restaffaldet faldt fra 4,1 til 3,6 kg pr. husstand om ugen.', long: 'Forsøget kørte i 2020 og gav borgerne nye ordninger for pap, tekstiler, plast samt mad- og drikkekartoner. Econet analyserede affaldet og målte, hvor fyldte beholderne var, mens borgernes erfaringer blev indsamlet gennem 17 interview og to fokusgrupper. Den samlede indsamlede mængde steg fra 10,3 til 12 kg pr. husstand om ugen. Plast og kartoner havde en renhed på 80 %, men kun omkring halvdelen af plasten blev sorteret fra restaffaldet. Papir og pap med tekstiler i poser krævede cirka dobbelt så stor kapacitet som før, og beholderne blev overfyldt. Borgerne var generelt tilfredse, og bekymringen for plads til beholderne faldt.' },
      { id: 'NY383', title: 'Redegørelse for beregning af reel genanvendelse på kommunalt niveau, 2024', org: 'Energistyrelsen', year: 2026, type: 'Notat', temaer: ['Reel genanvendelse', 'Data, statistikker og nøgletal'], img: '', url: 'https://mst.dk/media/kttmspdb/til-as2024-_bilag-8_-energistyrelsen-opgoerelse-af-reel-genanvendelse.docx', res: 'Notatet forklarer, hvordan Energistyrelsen opgør reel genanvendelse pr. kommune. I 2024 blev 46 % af husholdnings- og husholdningslignende affald reelt genanvendt på landsplan.', long: 'Notatet er bilag 8 til Affaldsstatistik 2024 og skal gøre det muligt for kommunerne selv at gennemse Energistyrelsens tal. Modellen er udviklet med COWI og bygger på Affaldsdatasystemet. Mængder indsamlet til genanvendelse ganges med nationale slutbehandlingsrater baseret på over 350 genanvendelsesanlæg. I 2024 var der 4,53 mio. ton husholdnings- og husholdningslignende affald. 60 % blev indsamlet til genanvendelse, og 2,09 mio. ton eller 46 % blev reelt genanvendt mod et mål på 55 % i 2025. Da alle kommuner regnes med samme nationale rater, kalder Energistyrelsen de kommunale tal relativt usikre. Kommunerne kan rette fejl i indberetningerne.' },
      { id: 'NY384', title: 'Dansk Producentansvar. Årsrapport 2025', org: 'Dansk Producentansvar', year: 2026, type: 'Rapport', temaer: ['Udvidet producentansvar', 'Data, statistikker og nøgletal', 'Lovgivning og afgørelser'], img: 'img/f967a670c68d53fea90c236338b65468.jpg', url: 'https://producentansvar.dk/wp-content/uploads/2026/06/dpa-aarsrapport-2025.pdf', res: 'DPA\'s årsrapport for 2025 viser, at over 10.000 producenter nu er registreret, især på grund af emballage. Den har tal for markedsførte og indsamlede mængder til og med 2024.', long: 'Dansk Producentansvar (DPA) er delegeret myndighed for producentansvaret på biler, batterier, elektronik, emballage, engangsplast og fiskeredskaber. I 2025 steg antallet af registrerede producenter fra 6.402 til over 10.000, især på grund af emballage. Statistikken går til 2024, hvor 212.428 ton elektronik blev markedsført og 71.500 ton indsamlet, mens tallene for batterier var 78.675 og 17.680 ton. Der blev markedsført 794.901 ton emballage. Den første tildeling af emballageaffald blev lavet i 2025 ud fra budgetterede mængder. DPA\'s indtægter steg fra 19,6 til 106,1 mio. kr., og i 2026 kommer en ny model for gebyrer.' },
      { id: 'NY385', title: 'Faldværn på genbrugsstationer. Kortlægning af erfaringer 2024', org: 'Reno Djurs', year: 2024, type: 'Notat', temaer: ['Genbrugspladser', 'Ledelse', 'Lovgivning og afgørelser'], img: 'img/8af89569fdfcdcdda0568ddf3dbb194e.jpg', url: 'https://renodjurs.dk/sites/default/files/2024-12/Bilag%2025.2_Faldv%C3%A6rn%20p%C3%A5%20genbrugsstationer.pdf', res: 'JHN Processor har for Reno Djurs spurgt 12 kommuner og affaldsselskaber om værn ved nedsænkede containerområder på genbrugsstationer. Otte har værn helt eller delvist.', long: 'JHN Processor skrev notatet for Reno Djurs, efter at to kunder i 2024 faldt ned til containerniveauet på selskabets genbrugsstationer. Det bygger på telefoninterviews i efteråret 2024 med 12 kommuner og affaldsselskaber. Der er ikke et lovkrav om værn, men Arbejdstilsynet kan give påbud, og byggemyndigheden kan kræve værn. Otte har værn helt eller delvist, oftest af hensyn til sikkerheden. Hvor der ikke er værn, stikker containeren typisk op over kanten som barriere. Kunderne ser værn som en forringelse, fordi affaldet skal løftes. Ingen med værn har haft faldulykker over det, og FM Larsen anbefaler værn støbt i beton på nye pladser.' },
      { id: 'NY386', title: 'Tilfredshedsundersøgelse. Vejen Kommunes genbrugspladser i Brørup, Rødding og Vejen 2022', org: 'Vejen Kommune', year: 2022, type: 'Analyse', temaer: ['Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/a479d736e6282b7fb6b4b824567a8f80.jpg', url: 'https://dagsordener.vejen.dk/vis/pdf/bilag/8d967979-436f-4c35-a681-0cb1b353e60b', res: 'JHN Processor har spurgt 1.287 kunder på Vejen Kommunes tre genbrugspladser om deres tilfredshed i 2022. Langt de fleste er tilfredse, og kun køreafstanden ligger under 90 %.', long: 'Vejen Kommune har målt kundernes tilfredshed med genbrugspladserne i Brørup, Rødding og Vejen siden 2014, og JHN Processor stod for målingen i 2022. Interviewere delte spørgeskemaer ud på pladserne 15.-22. maj, og 1.287 kunder svarede, heraf 1.213 private husstande og 74 virksomheder. For ni ud af ti forhold, fx åbningstider og personalets vejledning, var 96-99 % tilfredse eller meget tilfredse. Køreafstanden fik 89 %. På den nye plads i Vejen steg tilfredsheden med indretningen 23,8 procentpoint fra 2019, mens køreafstanden faldt 6,3 procentpoint, hvilket kan skyldes pladsens nye placering i byens sydøstlige del.' },
      { id: 'NY387', title: 'Årsberetning 2023. Indsamling af affald i Næstved Kommune', org: 'Næstved Kommune', year: 2024, type: 'Rapport', temaer: ['Data, statistikker og nøgletal', 'Hente- og bringeordninger', 'Reel genanvendelse'], img: 'img/fe6bc9fab4f62616c793455967c9e571.jpg', url: 'https://dagsordener.naestved.dk/vis/pdf/bilag/3ceb1fdf-5d59-430b-9197-a8e28d7b4a54', res: 'Næstved Kommunes årsberetning for 2023 samler drift, statistik, økonomi og klima for affaldsindsamlingen. Den reelle genanvendelse af husholdningsaffald var 48,4 %.', long: 'Årsberetningen fra Næstved Kommune dækker 2023, hvor der blev hentet affald ved 43.517 boliger med 1,71 mio. tømninger og et budget på 128,0 mio. kr. Fra husstandene kom 22.529 ton, og halvdelen gik til genanvendelse. Genbrugspladserne modtog 42.470 ton, hvoraf 83 % gik til genanvendelse. Den reelle genanvendelse af husholdningsaffald var 48,4 % mod pejlemærket på 50 %, og 53,7 % med haveaffald, men tallene er kun vejledende. I sommerhusområdet blev sække skiftet ud med beholdere, og fra 2024 kører Verdis med el- og biodieselbiler, der udleder op til 95 % mindre CO2 end under den tidligere kontrakt.' },
      { id: 'NY388', title: 'Genbrugsanalyse af genbrugsmaterialer. Hedensted Kommune 2024', org: 'Hedensted Kommune', year: 2024, type: 'Analyse', temaer: ['Direkte genbrug', 'Genbrugspladser', 'Analyser og undersøgelser'], img: 'img/ef217ef46eb42a8acd04f569ca902726.jpg', url: 'https://www.hedensted.dk/Agenda/GetFile?filePath=/dagsorden/Udvalget_for_Teknik_/05-03-2025/Dagsorden(ID93)/Bilag/Punkt_40_Bilag_1_Bilag%201%20Stikproeveanalyse%20Direkte%20Genbrug.pdf', res: 'Ud fra stikprøver i Gi’ og Ta’ containerne på Remmerslund Genbrugsstation anslås det direkte genbrug til 31,5 tons i juli-december 2024 og ca. 61,7 tons ved et helt års drift.', long: 'JHN Processor har for Hedensted Kommune vejet og kategoriseret de genstande, der blev hentet fra Gi’ og Ta’ containerne i pilotprojektet på Remmerslund Genbrugsstation. Otte stikprøvedage i august og november 2024 er skaleret op med tællertal og ugegennemsnit til 31,5 tons fra juli til december. Heraf tog kunderne 14,8 tons fra Ta’ containeren og Y’s Men 13,5 tons fra Gi’ containeren, mens andre kunder tog 3,3 tons fra Gi’ containeren, selv om det ikke er tilladt. Tilbehør til boligen udgør 35 % af det, kunderne tager. Rapporten vurderer, at mere plads og flere genbrugsstationer med ordningen kan øge mængderne markant.' },
      { id: 'NY389', title: 'Kortlægning af genbrugelige hårde hvidevarer indsamlet som WEEE på kommunale genbrugspladser', org: 'Elretur', year: 2021, type: 'Analyse', temaer: ['Direkte genbrug', 'Genbrugspladser', 'Udvidet producentansvar'], img: 'img/9d899e93fe0bc2d993dd35ff869cf30c.jpg', url: 'https://elretur.dk/wp-content/uploads/2021/11/2021-0921-Sammenfatning-til-Kortlaegning-af-genbrugelige-haarde-hvidevarer-indsamlet-som-WEEE-paa-genbrugspladser-.pdf', res: 'Econet har for Elretur gennemgået knap 2.000 hårde hvidevarer og frys/køl-produkter fra genbrugspladser. Når de fejlsorterede regnes fra, kunne 7,8 % forberedes til genbrug.', long: 'Sammenfatningen er skrevet af Ole Kaysen fra Econet som intern rapport for Elretur i september 2021. Produkter fra 45 containere, i alt 92 ton, blev tømt manuelt og vurderet visuelt på modtagepladser i Odense, Roskilde, Aalborg og Aarhus. Af 1.981 produkter blev 79 % kasseret, 14 % var fejlsorteret og 7 % kunne forberedes til genbrug. Regnes de fejlsorterede fra, bliver andelen 7,8 %, som er kortlægningens hovedresultat. Alder over seks år og afklippede strømkabler forklarer 58 % af kassationerne. I 12 containere var over 5 % af vægten fejlsorteret. Et genbrugeligt produkt er ikke nødvendigvis salgbart.' },
      { id: 'NY390', title: 'Life Cycle Assessment of Packaging Materials in relation to Extended Producer Responsibility', org: 'Miljøstyrelsen', year: 2023, type: 'Analyse', temaer: ['Klima', 'Cirkulær økonomi', 'Udvidet producentansvar'], img: 'img/6574f3e73a586381e87182a4f4753f9e.jpg', url: 'https://backend.orbit.dtu.dk/ws/files/356990132/2825823.pdf', res: 'DTU har for Miljøstyrelsen lavet en livscyklusvurdering af emballage i 11 materialer. Genbrug giver den største klimagevinst for alle materialer, og forbrænding er dårligst.', long: 'Fire forskere fra DTU lavede i februar 2023 analysen som internt beslutningsgrundlag for Miljøstyrelsens arbejde med producentansvar for emballage. Genbrug og genanvendelse i flere cyklusser sammenlignes med forbrænding for emballage af fossil plast, PLA, aluminium, stål, papir, karton, bølgepap og glas. Modellen er lavet i EASETECH med 1.000 Monte Carlo-simuleringer og 2 til 50 cyklusser alt efter type. Genbrug giver størst klimabesparelse for alle materialer, mest for aluminium og stål, og genanvendelse er næstbedst. For de fleste materialer kan få genbrug være dårligere end mange genanvendelser, så antallet af cyklusser bør dokumenteres.' },
      { id: 'NY391', title: 'Tømning efter behov: Opskalering til hele Glostrup kommune', org: 'Aarhus Universitet', year: 2021, type: 'Analyse', temaer: ['Hente- og bringeordninger', 'Teknologi', 'Analyser og undersøgelser'], img: '', url: 'https://pure.au.dk/ws/files/216222605/Rapport_om_fors_g_med_t_mning_efter_behov.docx', res: 'Et forsøg med 53 husstande i Glostrup er skaleret op til hele kommunen. Tømning efter behov giver færre tømninger, men 1,6 til 5,7 gange så meget kørsel som fast tømning.', long: 'Sanne Wøhlk fra Aarhus Universitet har i april 2021 skaleret et forsøg op, hvor 53 husstande i Glostrup i et halvt år selv bestilte tømning via en app eller en skyder på beholderen. Forsøget blev gennemført af Vestforbrændingen, Glostrup Forsyning og Urbaser. Tre modeller for behovstømning er simuleret over 81 uger og sammenlignet med fast tømning. Borgerne bestilte sjældnere end i dag, så kun 63-73 % af beholderne skal tømmes pr. uge. Stjernekørsel øger dog kørslen 1,6 til 2,0 gange for dagrenovation og op til 5,7 gange for glas og metal. Om de sparede tømninger opvejer den ekstra kørsel, skal en fagekspert vurdere.' }
    ]);
    // Søgetekst med små bogstaver, beregnet én gang pr. dokument
