          const clean = t.replace(/\s*\S*…$/, '').replace(/[\s,:–-]+$/, '');
          const title = note(t) ? (short === 'Affaldsplan' ? short : 'Affaldsplan ' + short.toLowerCase()) : (/^\d{4}-\d{4}/.test(t) ? 'Affaldsplan ' + t : clean);
          const first = out.length === 0;
