    // Husker hvor man kom fra, så brødkrummen og tilbage-knappen fører til samme sted i listen
    const openDoc = (d) => () => nav({ view: 'doc', docId: d.id, from: st.view === 'doc' ? st.from : { serie: st.serie || '', y: sy() } })();
