    GROUPS.forEach((g) => F[g.key].forEach((x) => activeChips.push({ label: x, aria: 'Fjern filteret ' + x, remove: toggleIn(g.state, x) })));

    // Genveje over listen: ord, der passer på en kommune eller et selskab, viser de nyeste faste dokumenter,
